/********************************************************
*ADASEventType                                          *
********************************************************/
int ASN1_Print_ADASEventType(ADASEventType *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(*value)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("ADASEventType", "nowarning", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("ADASEventType", "bus", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("ADASEventType", "car", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("ADASEventType", "truck", 3)) < 0) return ret; break;
	case 4: if ((ret = ASN1_Print_ENUMERATED("ADASEventType", "motors", 4)) < 0) return ret; break;
	case 5: if ((ret = ASN1_Print_ENUMERATED("ADASEventType", "special", 5)) < 0) return ret; break;
	case 6: if ((ret = ASN1_Print_ENUMERATED("ADASEventType", "bicycle", 6)) < 0) return ret; break;
	case 7: if ((ret = ASN1_Print_ENUMERATED("ADASEventType", "pedestrian", 7)) < 0) return ret; break;
	case 8: if ((ret = ASN1_Print_ENUMERATED("ADASEventType", "pothole", 8)) < 0) return ret; break;
	case 9: if ((ret = ASN1_Print_ENUMERATED("ADASEventType", "rubbercon", 9)) < 0) return ret; break;
	case 10: if ((ret = ASN1_Print_ENUMERATED("ADASEventType", "ldwsLeft", 10)) < 0) return ret; break;
	case 11: if ((ret = ASN1_Print_ENUMERATED("ADASEventType", "ldwsRight", 11)) < 0) return ret; break;
	case 12: if ((ret = ASN1_Print_ENUMERATED("ADASEventType", "ldwsWarning", 12)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	return ret;
}
int ASN1_CHECK_ADASEventType(ADASEventType *value)
{
	unsigned char checkinfo_ADASEventType[] = {0x0D,0x00,0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08,0x09,0x0A,0x0B,0x0C,0x00 };
	int ret = 0;
	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32 *)value, checkinfo_ADASEventType)) < 0) return ret;
	return ret;
}
int ASN1_BER_Data_Enc_ADASEventType(ASN1WorkSpace *workspace, ADASEventType *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_BER_Enc_ENUMERATED(workspace, (ASNINT32 *)value, tagFlag)) < 0) return ret;
	return ret;
}
int ASN1_BER_Enc_ADASEventType(ASN1WorkSpace *workspace, ADASEventType *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_ADASEventType(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_ADASEventType(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
int ASN1_BER_Data_Dec_ADASEventType(ASN1WorkSpace *workspace, ADASEventType *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	if ((ret = ASN1_BER_Dec_ENUMERATED(workspace, (ASNINT32*)value, len, tagFlag)) < 0) return ret;
	return ret;
}
int ASN1_BER_Dec_ADASEventType(ASN1WorkSpace *workspace, ADASEventType *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_ADASEventType(workspace, value, length, tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_ADASEventType(value)) < 0) return ret;
	return ret;
}
int ASN1_PER_Align_Data_Enc_ADASEventType(ASN1WorkSpace *workspace, ADASEventType *value)
{
	struct Asn1ConsInfo consinfo_ADASEventType = { ASN1_CONST64(0), ASN1_CONST64(12), NULL, 1, CONS, 0, 0 };
	int ret = 0;
	ASNINT32 ui_ADASEventType;
	switch(*value)
	{
	case ADASEventType_nowarning: ui_ADASEventType = 0; consinfo_ADASEventType.enumextbit = 0; break;
	case ADASEventType_bus: ui_ADASEventType = 1; consinfo_ADASEventType.enumextbit = 0; break;
	case ADASEventType_car: ui_ADASEventType = 2; consinfo_ADASEventType.enumextbit = 0; break;
	case ADASEventType_truck: ui_ADASEventType = 3; consinfo_ADASEventType.enumextbit = 0; break;
	case ADASEventType_motors: ui_ADASEventType = 4; consinfo_ADASEventType.enumextbit = 0; break;
	case ADASEventType_special: ui_ADASEventType = 5; consinfo_ADASEventType.enumextbit = 0; break;
	case ADASEventType_bicycle: ui_ADASEventType = 6; consinfo_ADASEventType.enumextbit = 0; break;
	case ADASEventType_pedestrian: ui_ADASEventType = 7; consinfo_ADASEventType.enumextbit = 0; break;
	case ADASEventType_pothole: ui_ADASEventType = 8; consinfo_ADASEventType.enumextbit = 0; break;
	case ADASEventType_rubbercon: ui_ADASEventType = 9; consinfo_ADASEventType.enumextbit = 0; break;
	case ADASEventType_ldwsLeft: ui_ADASEventType = 10; consinfo_ADASEventType.enumextbit = 0; break;
	case ADASEventType_ldwsRight: ui_ADASEventType = 11; consinfo_ADASEventType.enumextbit = 0; break;
	case ADASEventType_ldwsWarning: ui_ADASEventType = 12; consinfo_ADASEventType.enumextbit = 0; break;
	default: ui_ADASEventType = *value; consinfo_ADASEventType.enumextbit = 1; break;
	}
	if ((ret = ASN1_PER_Align_Enc_ENUMERATED(workspace, ui_ADASEventType, &consinfo_ADASEventType)) < 0) return ret;
	return ret;
}
int ASN1_PER_Align_Enc_ADASEventType(ASN1WorkSpace *workspace, ADASEventType *value)
{ // ASN1_PER_Extern_Encode 
	int ret = 0;
	if ((ret = ASN1_CHECK_ADASEventType(value)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Data_Enc_ADASEventType(workspace,value)) < 0) return ret;
	return ret;
}
int ASN1_PER_Align_Data_Dec_ADASEventType(ASN1WorkSpace *workspace, ADASEventType *value)
{
	struct Asn1ConsInfo consinfo_ADASEventType = { ASN1_CONST64(0), ASN1_CONST64(12), NULL, 1, CONS, 0, 0 };
	int ret = 0;
	ASNINT32 ui_ADASEventType;
	if ((ret = ASN1_PER_Align_Dec_ENUMERATED(workspace, &ui_ADASEventType, &consinfo_ADASEventType)) < 0) return ret;
	if (consinfo_ADASEventType.enumextbit == 0)
	{
		switch(ui_ADASEventType)
		{
		case 0: *value = ADASEventType_nowarning; break;
		case 1: *value = ADASEventType_bus; break;
		case 2: *value = ADASEventType_car; break;
		case 3: *value = ADASEventType_truck; break;
		case 4: *value = ADASEventType_motors; break;
		case 5: *value = ADASEventType_special; break;
		case 6: *value = ADASEventType_bicycle; break;
		case 7: *value = ADASEventType_pedestrian; break;
		case 8: *value = ADASEventType_pothole; break;
		case 9: *value = ADASEventType_rubbercon; break;
		case 10: *value = ADASEventType_ldwsLeft; break;
		case 11: *value = ADASEventType_ldwsRight; break;
		case 12: *value = ADASEventType_ldwsWarning; break;
		default: break;
		}
	}
	else
	{
		switch(ui_ADASEventType)
		{
		default: *value = ui_ADASEventType; break;
		}
	}
	return ret;
}
int ASN1_PER_Align_Dec_ADASEventType(ASN1WorkSpace *workspace, ADASEventType *value)
{
	int ret = 0;
	if ((ret = ASN1_PER_Align_Data_Dec_ADASEventType(workspace,value)) < 0) return ret;
	if ((ret = ASN1_CHECK_ADASEventType(value)) < 0) return ret;
	return ret;
}
