		case 1: *value = LightbarInUse_notInUse; break;
		case 2: *value = LightbarInUse_inUse; break;
		case 3: *value = LightbarInUse_yellowCautionLights; break;
		case 4: *value = LightbarInUse_schooldBusLights; break;
