{
	int ret = 0;
	if ((ret = ASN1_CHECK_TransmissionState(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_TransmissionState(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
