{
	struct Asn1ConsInfo consinfo_TransmissionState = { ASN1_CONST64(0), ASN1_CONST64(7), NULL, 0, CONS, 0, 0 };
	int ret = 0;
	ASNINT32 ui_TransmissionState;
	switch(*value)
	{
	case TransmissionState_neutral: ui_TransmissionState = 0; consinfo_TransmissionState.enumextbit = 0; break;
	case TransmissionState_park: ui_TransmissionState = 1; consinfo_TransmissionState.enumextbit = 0; break;
	case TransmissionState_forwardGears: ui_TransmissionState = 2; consinfo_TransmissionState.enumextbit = 0; break;
	case TransmissionState_reverseGears: ui_TransmissionState = 3; consinfo_TransmissionState.enumextbit = 0; break;
	case TransmissionState_reserved1: ui_TransmissionState = 4; consinfo_TransmissionState.enumextbit = 0; break;
	case TransmissionState_reserved2: ui_TransmissionState = 5; consinfo_TransmissionState.enumextbit = 0; break;
	case TransmissionState_reserved3: ui_TransmissionState = 6; consinfo_TransmissionState.enumextbit = 0; break;
	case TransmissionState_unavailable: ui_TransmissionState = 7; consinfo_TransmissionState.enumextbit = 0; break;
	default: ui_TransmissionState = *value; consinfo_TransmissionState.enumextbit = 0; break;
	}
	if ((ret = ASN1_PER_Align_Enc_ENUMERATED(workspace, ui_TransmissionState, &consinfo_TransmissionState)) < 0) return ret;
	return ret;
}
