/********************************************************
*AdvisorySpeedType                                      *
********************************************************/
int ASN1_Print_AdvisorySpeedType(AdvisorySpeedType *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(*value)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("AdvisorySpeedType", "none", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("AdvisorySpeedType", "greenwave", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("AdvisorySpeedType", "ecoDrive", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("AdvisorySpeedType", "transit", 3)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	return ret;
}
int ASN1_CHECK_AdvisorySpeedType(AdvisorySpeedType *value)
{
	unsigned char checkinfo_AdvisorySpeedType[] = {0x04,0x00,0x01,0x02,0x03,0x00 };
	int ret = 0;
	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32 *)value, checkinfo_AdvisorySpeedType)) < 0) return ret;
	return ret;
}
int ASN1_BER_Data_Enc_AdvisorySpeedType(ASN1WorkSpace *workspace, AdvisorySpeedType *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_BER_Enc_ENUMERATED(workspace, (ASNINT32 *)value, tagFlag)) < 0) return ret;
	return ret;
}
int ASN1_BER_Enc_AdvisorySpeedType(ASN1WorkSpace *workspace, AdvisorySpeedType *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_AdvisorySpeedType(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_AdvisorySpeedType(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
int ASN1_BER_Data_Dec_AdvisorySpeedType(ASN1WorkSpace *workspace, AdvisorySpeedType *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	if ((ret = ASN1_BER_Dec_ENUMERATED(workspace, (ASNINT32*)value, len, tagFlag)) < 0) return ret;
	return ret;
}
int ASN1_BER_Dec_AdvisorySpeedType(ASN1WorkSpace *workspace, AdvisorySpeedType *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_AdvisorySpeedType(workspace, value, length, tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_AdvisorySpeedType(value)) < 0) return ret;
	return ret;
}
int ASN1_PER_Align_Data_Enc_AdvisorySpeedType(ASN1WorkSpace *workspace, AdvisorySpeedType *value)
{
	struct Asn1ConsInfo consinfo_AdvisorySpeedType = { ASN1_CONST64(0), ASN1_CONST64(3), NULL, 1, CONS, 0, 0 };
	int ret = 0;
	ASNINT32 ui_AdvisorySpeedType;
	switch(*value)
	{
	case AdvisorySpeedType_none: ui_AdvisorySpeedType = 0; consinfo_AdvisorySpeedType.enumextbit = 0; break;
	case AdvisorySpeedType_greenwave: ui_AdvisorySpeedType = 1; consinfo_AdvisorySpeedType.enumextbit = 0; break;
	case AdvisorySpeedType_ecoDrive: ui_AdvisorySpeedType = 2; consinfo_AdvisorySpeedType.enumextbit = 0; break;
	case AdvisorySpeedType_transit: ui_AdvisorySpeedType = 3; consinfo_AdvisorySpeedType.enumextbit = 0; break;
	default: ui_AdvisorySpeedType = *value; consinfo_AdvisorySpeedType.enumextbit = 1; break;
	}
	if ((ret = ASN1_PER_Align_Enc_ENUMERATED(workspace, ui_AdvisorySpeedType, &consinfo_AdvisorySpeedType)) < 0) return ret;
	return ret;
}
int ASN1_PER_Align_Enc_AdvisorySpeedType(ASN1WorkSpace *workspace, AdvisorySpeedType *value)
{ // ASN1_PER_Extern_Encode 
	int ret = 0;
	if ((ret = ASN1_CHECK_AdvisorySpeedType(value)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Data_Enc_AdvisorySpeedType(workspace,value)) < 0) return ret;
	return ret;
}
