{
	struct Asn1ConsInfo consinfo_AdvisorySpeedType = { ASN1_CONST64(0), ASN1_CONST64(3), NULL, 1, CONS, 0, 0 };
	int ret = 0;
	ASNINT32 ui_AdvisorySpeedType;
	if ((ret = ASN1_PER_Align_Dec_ENUMERATED(workspace, &ui_AdvisorySpeedType, &consinfo_AdvisorySpeedType)) < 0) return ret;
	if (consinfo_AdvisorySpeedType.enumextbit == 0)
	{
		switch(ui_AdvisorySpeedType)
		{
		case 0: *value = AdvisorySpeedType_none; break;
		case 1: *value = AdvisorySpeedType_greenwave; break;
		case 2: *value = AdvisorySpeedType_ecoDrive; break;
		case 3: *value = AdvisorySpeedType_transit; break;
		default: break;
		}
	}
	else
	{
		switch(ui_AdvisorySpeedType)
		{
		default: *value = ui_AdvisorySpeedType; break;
		}
	}
	return ret;
}
