/********************************************************
*RainSensor                                             *
********************************************************/
int ASN1_Print_RainSensor(RainSensor *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(*value)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("RainSensor", "none", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("RainSensor", "lightMist", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("RainSensor", "heavyMist", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("RainSensor", "lightRainOrDrizzle", 3)) < 0) return ret; break;
	case 4: if ((ret = ASN1_Print_ENUMERATED("RainSensor", "rain", 4)) < 0) return ret; break;
	case 5: if ((ret = ASN1_Print_ENUMERATED("RainSensor", "moderateRain", 5)) < 0) return ret; break;
	case 6: if ((ret = ASN1_Print_ENUMERATED("RainSensor", "heavyRain", 6)) < 0) return ret; break;
	case 7: if ((ret = ASN1_Print_ENUMERATED("RainSensor", "heavyDownpour", 7)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	return ret;
}
int ASN1_CHECK_RainSensor(RainSensor *value)
{
	unsigned char checkinfo_RainSensor[] = {0x08,0x00,0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x00 };
	int ret = 0;
	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32 *)value, checkinfo_RainSensor)) < 0) return ret;
	return ret;
}
int ASN1_BER_Data_Enc_RainSensor(ASN1WorkSpace *workspace, RainSensor *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_BER_Enc_ENUMERATED(workspace, (ASNINT32 *)value, tagFlag)) < 0) return ret;
	return ret;
}
int ASN1_BER_Enc_RainSensor(ASN1WorkSpace *workspace, RainSensor *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_RainSensor(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_RainSensor(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
int ASN1_BER_Data_Dec_RainSensor(ASN1WorkSpace *workspace, RainSensor *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	if ((ret = ASN1_BER_Dec_ENUMERATED(workspace, (ASNINT32*)value, len, tagFlag)) < 0) return ret;
	return ret;
}
int ASN1_BER_Dec_RainSensor(ASN1WorkSpace *workspace, RainSensor *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_RainSensor(workspace, value, length, tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_RainSensor(value)) < 0) return ret;
	return ret;
}
int ASN1_PER_Align_Data_Enc_RainSensor(ASN1WorkSpace *workspace, RainSensor *value)
{
	struct Asn1ConsInfo consinfo_RainSensor = { ASN1_CONST64(0), ASN1_CONST64(7), NULL, 0, CONS, 0, 0 };
	int ret = 0;
	ASNINT32 ui_RainSensor;
	switch(*value)
	{
	case RainSensor_none: ui_RainSensor = 0; consinfo_RainSensor.enumextbit = 0; break;
	case RainSensor_lightMist: ui_RainSensor = 1; consinfo_RainSensor.enumextbit = 0; break;
	case RainSensor_heavyMist: ui_RainSensor = 2; consinfo_RainSensor.enumextbit = 0; break;
	case RainSensor_lightRainOrDrizzle: ui_RainSensor = 3; consinfo_RainSensor.enumextbit = 0; break;
	case RainSensor_rain: ui_RainSensor = 4; consinfo_RainSensor.enumextbit = 0; break;
	case RainSensor_moderateRain: ui_RainSensor = 5; consinfo_RainSensor.enumextbit = 0; break;
	case RainSensor_heavyRain: ui_RainSensor = 6; consinfo_RainSensor.enumextbit = 0; break;
	case RainSensor_heavyDownpour: ui_RainSensor = 7; consinfo_RainSensor.enumextbit = 0; break;
	default: ui_RainSensor = *value; consinfo_RainSensor.enumextbit = 0; break;
	}
	if ((ret = ASN1_PER_Align_Enc_ENUMERATED(workspace, ui_RainSensor, &consinfo_RainSensor)) < 0) return ret;
	return ret;
}
