extern int ASN1_BER_Data_Dec_SemiMajorAxisAccuracy(ASN1WorkSpace *workspace, SemiMajorAxisAccuracy *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_SemiMinorAxisAccuracy(ASN1WorkSpace *workspace, SemiMinorAxisAccuracy *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_SemiMajorAxisOrientation(ASN1WorkSpace *workspace, SemiMajorAxisOrientation *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_PositionalAccuracy(ASN1WorkSpace *workspace, PositionalAccuracy *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_SemiMajorAxisAccuracy(workspace, &value->semiMajor, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_SemiMinorAxisAccuracy(workspace, &value->semiMinor, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_SemiMajorAxisOrientation(workspace, &value->orientation, len, ASN1IMPL)) < 0) return ret;
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_PositionalAccuracy(PositionalAccuracy *value);
extern int ASN1_BER_Data_Dec_PositionalAccuracy(ASN1WorkSpace *workspace, PositionalAccuracy *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_PositionalAccuracy(ASN1WorkSpace *workspace, PositionalAccuracy *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_PositionalAccuracy(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_PositionalAccuracy(value)) < 0) return ret;
	return ret;
}
