int ASN1_Print_AccelerationSet4Way(AccelerationSet4Way *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("AccelerationSet4Way");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("Acceleration", &(value->lon))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("Acceleration", &(value->lat))) < 0) return ret;
	if (value->DEF_AccelerationSet4Way_vert == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("VerticalAcceleration", &(value->vert))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("YawRate", &(value->yaw))) < 0) return ret;
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
