int ASN1_CHECK_AccelerationSet4Way(AccelerationSet4Way *value)
{
	int ret = 0;

	unsigned char checkinfo_lon[] = { 
		0x02,0x82,0xF8,0x30,0x82,0x07,0xD1,0x00
	};
	unsigned char checkinfo_lat[] = { 
		0x02,0x82,0xF8,0x30,0x82,0x07,0xD1,0x00
	};
	unsigned char checkinfo_vert[] = { 
		0x02,0x81,0x81,0x7F,0x00
	};
	unsigned char checkinfo_yaw[] = { 
		0x02,0x82,0x80,0x01,0x82,0x7F,0xFF,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->lon), checkinfo_lon)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->lat), checkinfo_lat)) < 0) return ret;
	if (value->DEF_AccelerationSet4Way_vert == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->vert), checkinfo_vert)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_INTEGER(&(value->yaw), checkinfo_yaw)) < 0) return ret;
	return ret;
}
