	if ((ret = ASN1_BER_Data_Enc_Acceleration(workspace, &(value->lon), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_Acceleration(workspace, &(value->lat), ASN1IMPL)) < 0) return ret;
