int ASN1_Print_BrakeSystemStatus(BrakeSystemStatus *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("BrakeSystemStatus");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BITSTRING("BrakeAppliedStatus", &(value->wheelBrakes))) < 0) return ret;
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->traction)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("TractionControlStatus", "unavailable", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("TractionControlStatus", "off", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("TractionControlStatus", "on", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("TractionControlStatus", "engaged", 3)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->abs)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("AntiLockBrakeStatus", "unavailable", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("AntiLockBrakeStatus", "off", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("AntiLockBrakeStatus", "on", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("AntiLockBrakeStatus", "engaged", 3)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->scs)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("StabilityControlStatus", "unavailable", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("StabilityControlStatus", "off", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("StabilityControlStatus", "on", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("StabilityControlStatus", "engaged", 3)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->brakeBoost)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("BrakeBoostApplied", "unavailable", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("BrakeBoostApplied", "off", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("BrakeBoostApplied", "on", 2)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->auxBrakes)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("AuxiliaryBrakeStatus", "unavailable", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("AuxiliaryBrakeStatus", "off", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("AuxiliaryBrakeStatus", "on", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("AuxiliaryBrakeStatus", "reserved", 3)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
