int ASN1_CHECK_BrakeSystemStatus(BrakeSystemStatus *value)
{
	int ret = 0;

	unsigned char checkinfo_wheelBrakes[] = { 
		0x02,0x05,0x05,0x00
	};
	unsigned char checkinfo_traction[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_abs[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_scs[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_brakeBoost[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_auxBrakes[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_BITSTRING(&(value->wheelBrakes), checkinfo_wheelBrakes)) < 0) return ret;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->traction), checkinfo_traction)) < 0) return ret;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->abs), checkinfo_abs)) < 0) return ret;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->scs), checkinfo_scs)) < 0) return ret;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->brakeBoost), checkinfo_brakeBoost)) < 0) return ret;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->auxBrakes), checkinfo_auxBrakes)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Enc_BrakeAppliedStatus(ASN1WorkSpace *workspace, BrakeAppliedStatus *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_TractionControlStatus(ASN1WorkSpace *workspace, TractionControlStatus *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_AntiLockBrakeStatus(ASN1WorkSpace *workspace, AntiLockBrakeStatus *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_StabilityControlStatus(ASN1WorkSpace *workspace, StabilityControlStatus *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_BrakeBoostApplied(ASN1WorkSpace *workspace, BrakeBoostApplied *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_AuxiliaryBrakeStatus(ASN1WorkSpace *workspace, AuxiliaryBrakeStatus *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_BrakeSystemStatus(ASN1WorkSpace *workspace, BrakeSystemStatus *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_BrakeAppliedStatus(workspace, &(value->wheelBrakes), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_TractionControlStatus(workspace, &(value->traction), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_AntiLockBrakeStatus(workspace, &(value->abs), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_StabilityControlStatus(workspace, &(value->scs), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 4)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_BrakeBoostApplied(workspace, &(value->brakeBoost), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 5)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_AuxiliaryBrakeStatus(workspace, &(value->auxBrakes), ASN1IMPL)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
