extern int ASN1_BER_Data_Dec_BrakeAppliedStatus(ASN1WorkSpace *workspace, BrakeAppliedStatus *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_TractionControlStatus(ASN1WorkSpace *workspace, TractionControlStatus *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_AntiLockBrakeStatus(ASN1WorkSpace *workspace, AntiLockBrakeStatus *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_StabilityControlStatus(ASN1WorkSpace *workspace, StabilityControlStatus *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_BrakeBoostApplied(ASN1WorkSpace *workspace, BrakeBoostApplied *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_AuxiliaryBrakeStatus(ASN1WorkSpace *workspace, AuxiliaryBrakeStatus *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_BrakeSystemStatus(ASN1WorkSpace *workspace, BrakeSystemStatus *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_BrakeAppliedStatus(workspace, &value->wheelBrakes, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_TractionControlStatus(workspace, &value->traction, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_AntiLockBrakeStatus(workspace, &value->abs, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_StabilityControlStatus(workspace, &value->scs, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 4)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_BrakeBoostApplied(workspace, &value->brakeBoost, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 5)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_AuxiliaryBrakeStatus(workspace, &value->auxBrakes, len, ASN1IMPL)) < 0) return ret;
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_BrakeSystemStatus(BrakeSystemStatus *value);
extern int ASN1_BER_Data_Dec_BrakeSystemStatus(ASN1WorkSpace *workspace, BrakeSystemStatus *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_BrakeSystemStatus(ASN1WorkSpace *workspace, BrakeSystemStatus *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_BrakeSystemStatus(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_BrakeSystemStatus(value)) < 0) return ret;
	return ret;
}
int ASN1_PER_Align_Data_Enc_BrakeSystemStatus(ASN1WorkSpace *workspace, BrakeSystemStatus *value)
{
	int ret = 0;
	ASNINT32 ui_traction;
	ASNINT32 ui_abs;
	ASNINT32 ui_scs;
	ASNINT32 ui_brakeBoost;
	ASNINT32 ui_auxBrakes;
	struct Asn1ConsInfo consinfo_wheelBrakes = { ASN1_CONST64(5), ASN1_CONST64(5), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_traction = { ASN1_CONST64(0), ASN1_CONST64(3), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_abs = { ASN1_CONST64(0), ASN1_CONST64(3), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_scs = { ASN1_CONST64(0), ASN1_CONST64(3), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_brakeBoost = { ASN1_CONST64(0), ASN1_CONST64(2), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_auxBrakes = { ASN1_CONST64(0), ASN1_CONST64(3), NULL, 0, CONS, 0, 0 };

	if ((ret = ASN1_PER_Align_Enc_BITSTRING(workspace, &(value->wheelBrakes), &consinfo_wheelBrakes)) < 0) return ret;
	switch(value->traction)
	{
	case TractionControlStatus_unavailable: ui_traction = 0; consinfo_traction.enumextbit = 0; break;
	case TractionControlStatus_off: ui_traction = 1; consinfo_traction.enumextbit = 0; break;
	case TractionControlStatus_on: ui_traction = 2; consinfo_traction.enumextbit = 0; break;
	case TractionControlStatus_engaged: ui_traction = 3; consinfo_traction.enumextbit = 0; break;
	default: ui_traction = value->traction; consinfo_traction.enumextbit = 0;break;
	}
	if ((ret = ASN1_PER_Align_Enc_ENUMERATED(workspace, ui_traction, &consinfo_traction)) < 0) return ret;
	switch(value->abs)
	{
	case AntiLockBrakeStatus_unavailable: ui_abs = 0; consinfo_abs.enumextbit = 0; break;
	case AntiLockBrakeStatus_off: ui_abs = 1; consinfo_abs.enumextbit = 0; break;
	case AntiLockBrakeStatus_on: ui_abs = 2; consinfo_abs.enumextbit = 0; break;
	case AntiLockBrakeStatus_engaged: ui_abs = 3; consinfo_abs.enumextbit = 0; break;
	default: ui_abs = value->abs; consinfo_abs.enumextbit = 0;break;
	}
	if ((ret = ASN1_PER_Align_Enc_ENUMERATED(workspace, ui_abs, &consinfo_abs)) < 0) return ret;
	switch(value->scs)
	{
	case StabilityControlStatus_unavailable: ui_scs = 0; consinfo_scs.enumextbit = 0; break;
	case StabilityControlStatus_off: ui_scs = 1; consinfo_scs.enumextbit = 0; break;
	case StabilityControlStatus_on: ui_scs = 2; consinfo_scs.enumextbit = 0; break;
	case StabilityControlStatus_engaged: ui_scs = 3; consinfo_scs.enumextbit = 0; break;
	default: ui_scs = value->scs; consinfo_scs.enumextbit = 0;break;
	}
	if ((ret = ASN1_PER_Align_Enc_ENUMERATED(workspace, ui_scs, &consinfo_scs)) < 0) return ret;
	switch(value->brakeBoost)
	{
	case BrakeBoostApplied_unavailable: ui_brakeBoost = 0; consinfo_brakeBoost.enumextbit = 0; break;
	case BrakeBoostApplied_off: ui_brakeBoost = 1; consinfo_brakeBoost.enumextbit = 0; break;
	case BrakeBoostApplied_on: ui_brakeBoost = 2; consinfo_brakeBoost.enumextbit = 0; break;
	default: ui_brakeBoost = value->brakeBoost; consinfo_brakeBoost.enumextbit = 0;break;
	}
	if ((ret = ASN1_PER_Align_Enc_ENUMERATED(workspace, ui_brakeBoost, &consinfo_brakeBoost)) < 0) return ret;
	switch(value->auxBrakes)
	{
	case AuxiliaryBrakeStatus_unavailable: ui_auxBrakes = 0; consinfo_auxBrakes.enumextbit = 0; break;
	case AuxiliaryBrakeStatus_off: ui_auxBrakes = 1; consinfo_auxBrakes.enumextbit = 0; break;
	case AuxiliaryBrakeStatus_on: ui_auxBrakes = 2; consinfo_auxBrakes.enumextbit = 0; break;
	case AuxiliaryBrakeStatus_reserved: ui_auxBrakes = 3; consinfo_auxBrakes.enumextbit = 0; break;
	default: ui_auxBrakes = value->auxBrakes; consinfo_auxBrakes.enumextbit = 0;break;
	}
	if ((ret = ASN1_PER_Align_Enc_ENUMERATED(workspace, ui_auxBrakes, &consinfo_auxBrakes)) < 0) return ret;
	return ret;
}
