int ASN1_CHECK_VehicleSize(VehicleSize *value)
{
	int ret = 0;

	unsigned char checkinfo_width[] = { 
		0x02,0x00,0x82,0x03,0xFF,0x00
	};
	unsigned char checkinfo_length[] = { 
		0x02,0x00,0x82,0x0F,0xFF,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->width), checkinfo_width)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->length), checkinfo_length)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Enc_VehicleWidth(ASN1WorkSpace *workspace, VehicleWidth *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_VehicleLength(ASN1WorkSpace *workspace, VehicleLength *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_VehicleSize(ASN1WorkSpace *workspace, VehicleSize *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_VehicleWidth(workspace, &(value->width), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_VehicleLength(workspace, &(value->length), ASN1IMPL)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_VehicleSize(VehicleSize *value);
extern int ASN1_BER_Data_Enc_VehicleSize(ASN1WorkSpace *workspace, VehicleSize *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_VehicleSize(ASN1WorkSpace *workspace, VehicleSize *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_VehicleSize(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_VehicleSize(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_VehicleWidth(ASN1WorkSpace *workspace, VehicleWidth *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_VehicleLength(ASN1WorkSpace *workspace, VehicleLength *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_VehicleSize(ASN1WorkSpace *workspace, VehicleSize *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_VehicleWidth(workspace, &value->width, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_VehicleLength(workspace, &value->length, len, ASN1IMPL)) < 0) return ret;
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_VehicleSize(VehicleSize *value);
extern int ASN1_BER_Data_Dec_VehicleSize(ASN1WorkSpace *workspace, VehicleSize *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_VehicleSize(ASN1WorkSpace *workspace, VehicleSize *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_VehicleSize(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_VehicleSize(value)) < 0) return ret;
	return ret;
}
