	struct Asn1ConsInfo consinfo_length = { ASN1_CONST64(0), ASN1_CONST64(4095), NULL, 0, CONS, 0, 0 };

	if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->width), &consinfo_width)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->length), &consinfo_length)) < 0) return ret;
