/********************************************************
*BSMcoreData                                            *
********************************************************/
int ASN1_Print_BSMcoreData(BSMcoreData *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("BSMcoreData");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("MsgCount", &(value->msgCnt))) < 0) return ret;
	// Type OCTET STRING
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_OCTETSTRING("TemporaryID", &(value->id), tab_value + 1)) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("DSecond", &(value->secMark))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("Latitude", &(value->lat))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("Longitude", &(value->lon))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("Elevation", &(value->elev))) < 0) return ret;
	// Type Reference PositionalAccuracy
	if (Compare_Letter(tab_value, "accuracy")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("accuracy = ");
	}
	if ((ret = ASN1_Print_PositionalAccuracy((PositionalAccuracy *)value->accuracy, tab_value + 1)) < 0) return ret;
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->transmission)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "neutral", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "park", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "forwardGears", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "reverseGears", 3)) < 0) return ret; break;
	case 4: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "reserved1", 4)) < 0) return ret; break;
	case 5: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "reserved2", 5)) < 0) return ret; break;
	case 6: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "reserved3", 6)) < 0) return ret; break;
	case 7: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "unavailable", 7)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("Speed", &(value->speed))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("Heading", &(value->heading))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("SteeringWheelAngle", &(value->angle))) < 0) return ret;
	// Type Reference AccelerationSet4Way
	if (Compare_Letter(tab_value, "accelSet")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("accelSet = ");
	}
	if ((ret = ASN1_Print_AccelerationSet4Way((AccelerationSet4Way *)value->accelSet, tab_value + 1)) < 0) return ret;
	// Type Reference BrakeSystemStatus
	if (Compare_Letter(tab_value, "brakes")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("brakes = ");
	}
	if ((ret = ASN1_Print_BrakeSystemStatus((BrakeSystemStatus *)value->brakes, tab_value + 1)) < 0) return ret;
	// Type Reference VehicleSize
	if (Compare_Letter(tab_value, "size")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("size = ");
	}
	if ((ret = ASN1_Print_VehicleSize((VehicleSize *)value->size, tab_value + 1)) < 0) return ret;
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
