int ASN1_CHECK_PartIIcontent(PartIIcontent *value)
{
	int ret = 0;

	unsigned char checkinfo_partII_Id[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_partII_Value[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->partII_Id), checkinfo_partII_Id)) < 0) return ret;
	if ((ret = ASN1_CHECK_OpenType(&(value->partII_Value), checkinfo_partII_Value)) < 0) return ret;
	return ret;
}
int ASN1_BER_Data_Enc_PartIIcontent(ASN1WorkSpace *workspace, PartIIcontent *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_INTEGER(workspace, &(value->partII_Id), ASN1EXPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_OpenType(workspace, &(value->partII_Value), ASN1IMPL)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_PartIIcontent(PartIIcontent *value);
extern int ASN1_BER_Data_Enc_PartIIcontent(ASN1WorkSpace *workspace, PartIIcontent *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_PartIIcontent(ASN1WorkSpace *workspace, PartIIcontent *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_PartIIcontent(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_PartIIcontent(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
int ASN1_BER_Data_Dec_PartIIcontent(ASN1WorkSpace *workspace, PartIIcontent *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_Dec_INTEGER(workspace, &value->partII_Id, len, ASN1EXPL)) < 0) return ret;
	if ((ret = ASN1_BER_Dec_OpenType(workspace, &value->partII_Value, len, ASN1IMPL)) < 0) return ret;
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_PartIIcontent(PartIIcontent *value);
extern int ASN1_BER_Data_Dec_PartIIcontent(ASN1WorkSpace *workspace, PartIIcontent *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_PartIIcontent(ASN1WorkSpace *workspace, PartIIcontent *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_PartIIcontent(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_PartIIcontent(value)) < 0) return ret;
	return ret;
}
