/********************************************************
*RegionalExtension                                      *
********************************************************/
int ASN1_Print_RegionalExtension(RegionalExtension *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("RegionalExtension");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("REG_EXT_ID_AND_TYPE_id", &(value->regionId))) < 0) return ret;
	// Type ANY
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_OpenType("REG_EXT_ID_AND_TYPE_Type", &(value->regExtValue), tab_value + 1)) < 0) return ret;
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_RegionalExtension_regionId(ASN1WorkSpace *workspace, RegionalExtension *value, INTEGER user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if ((ret = ASN1_SET_INTEGER(workspace, &value->regionId, user_value)) < 0) return ret;
	return ret;
}
int ASN1_SET_RegionalExtension_regExtValue(ASN1WorkSpace *workspace, RegionalExtension *value, ASNUINT8 *user_value, ASNUINT32 user_value_length)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if ((ret = ASN1_SET_OpenType(workspace, &value->regExtValue, user_value, user_value_length)) < 0) return ret;
	return ret;
}
int ASN1_GET_RegionalExtension_regionId(ASN1WorkSpace *workspace, RegionalExtension *value, INTEGER *user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if ((ret = ASN1_GET_INTEGER(workspace, &value->regionId, user_value)) < 0) return ret;
	return ret;
}
int ASN1_GET_RegionalExtension_regExtValue(ASN1WorkSpace *workspace, RegionalExtension *value, ASNUINT8 **user_value, ASNUINT32 *user_value_length)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if ((ret = ASN1_GET_OpenType(workspace, &value->regExtValue, user_value, user_value_length)) < 0) return ret;
	return ret;
}
int ASN1_CHECK_RegionalExtension(RegionalExtension *value)
{
	int ret = 0;

	unsigned char checkinfo_regionId[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_regExtValue[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->regionId), checkinfo_regionId)) < 0) return ret;
	if ((ret = ASN1_CHECK_OpenType(&(value->regExtValue), checkinfo_regExtValue)) < 0) return ret;
	return ret;
}
int ASN1_BER_Data_Enc_RegionalExtension(ASN1WorkSpace *workspace, RegionalExtension *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_INTEGER(workspace, &(value->regionId), ASN1EXPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_OpenType(workspace, &(value->regExtValue), ASN1IMPL)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_RegionalExtension(RegionalExtension *value);
extern int ASN1_BER_Data_Enc_RegionalExtension(ASN1WorkSpace *workspace, RegionalExtension *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_RegionalExtension(ASN1WorkSpace *workspace, RegionalExtension *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_RegionalExtension(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_RegionalExtension(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
int ASN1_BER_Data_Dec_RegionalExtension(ASN1WorkSpace *workspace, RegionalExtension *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_Dec_INTEGER(workspace, &value->regionId, len, ASN1EXPL)) < 0) return ret;
	if ((ret = ASN1_BER_Dec_OpenType(workspace, &value->regExtValue, len, ASN1IMPL)) < 0) return ret;
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
