/********************************************************
*BasicSafetyMessage_regional                            *
********************************************************/
int ASN1_Print_BasicSafetyMessage_regional(BasicSafetyMessage_regional *value, int tab_value)
{
	int ret = 0;
	int count;
	ASN1ListNode *pnode;
	if (value == NULL) return -1;
	count = value->count;
	pnode = value->head->next;
	// SEQUENCE OF : default
	ASN1_Print_SEQ_OF(" ");
	while(count) {
		// Type Reference RegionalExtension
		ASN_Print_TAB(tab_value + 1);
		if ((ret = ASN1_Print_RegionalExtension((RegionalExtension *)pnode->data, tab_value + 1)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}

	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
extern int ASN1_CHECK_RegionalExtension(RegionalExtension *value);
int ASN1_CHECK_BasicSafetyMessage_regional(BasicSafetyMessage_regional *value)
{
	int ret = 0;

	unsigned char checkinfo_BasicSafetyMessage_regional[] = { 
		0x02,0x01,0x04,0x00
	};
	unsigned char checkinfo_BasicSafetyMessage_regional_pdata[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	int count;
	ASN1ListNode* pnode;
	if (value == NULL) return -1;
	if (value->head == NULL) return -1;
	if (value->count < 0) return -1;
	pnode = value->head->next;
	count = value->count;
	while (count) {
		if ((ret = ASN1_CHECK_RegionalExtension(pnode->data)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}
	return ret;
}
