/********************************************************
*IntersectionReferenceID                                *
********************************************************/
int ASN1_Print_IntersectionReferenceID(IntersectionReferenceID *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("IntersectionReferenceID");
	if (value->DEF_IntersectionReferenceID_region == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("RoadRegulatorID", &(value->region))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("IntersectionID", &(value->id))) < 0) return ret;
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_IntersectionReferenceID_region(ASN1WorkSpace *workspace, IntersectionReferenceID *value, INTEGER user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	value->DEF_IntersectionReferenceID_region = 1;
	if ((ret = ASN1_SET_INTEGER(workspace, &value->region, user_value)) < 0) return ret;
	return ret;
}
int ASN1_SET_IntersectionReferenceID_id(ASN1WorkSpace *workspace, IntersectionReferenceID *value, INTEGER user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if ((ret = ASN1_SET_INTEGER(workspace, &value->id, user_value)) < 0) return ret;
	return ret;
}
int ASN1_GET_IntersectionReferenceID_region(ASN1WorkSpace *workspace, IntersectionReferenceID *value, INTEGER *user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if (value->DEF_IntersectionReferenceID_region == 1)
	{
		if ((ret = ASN1_GET_INTEGER(workspace, &value->region, user_value)) < 0) return ret;
	}
	else return -2;
	return ret;
}
int ASN1_GET_IntersectionReferenceID_id(ASN1WorkSpace *workspace, IntersectionReferenceID *value, INTEGER *user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if ((ret = ASN1_GET_INTEGER(workspace, &value->id, user_value)) < 0) return ret;
	return ret;
}
int ASN1_CHECK_IntersectionReferenceID(IntersectionReferenceID *value)
{
	int ret = 0;

	unsigned char checkinfo_region[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};
	unsigned char checkinfo_id[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_IntersectionReferenceID_region == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->region), checkinfo_region)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_INTEGER(&(value->id), checkinfo_id)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Enc_RoadRegulatorID(ASN1WorkSpace *workspace, RoadRegulatorID *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_IntersectionID(ASN1WorkSpace *workspace, IntersectionID *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_IntersectionReferenceID(ASN1WorkSpace *workspace, IntersectionReferenceID *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if (value->DEF_IntersectionReferenceID_region == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_RoadRegulatorID(workspace, &(value->region), ASN1IMPL)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_IntersectionID(workspace, &(value->id), ASN1IMPL)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_IntersectionReferenceID(IntersectionReferenceID *value);
extern int ASN1_BER_Data_Enc_IntersectionReferenceID(ASN1WorkSpace *workspace, IntersectionReferenceID *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_IntersectionReferenceID(ASN1WorkSpace *workspace, IntersectionReferenceID *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_IntersectionReferenceID(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_IntersectionReferenceID(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_RoadRegulatorID(ASN1WorkSpace *workspace, RoadRegulatorID *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_IntersectionID(ASN1WorkSpace *workspace, IntersectionID *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_IntersectionReferenceID(ASN1WorkSpace *workspace, IntersectionReferenceID *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 0))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_RoadRegulatorID(workspace, &value->region, len, ASN1IMPL)) < 0) return ret;
		value->DEF_IntersectionReferenceID_region = 1;
	}
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_IntersectionID(workspace, &value->id, len, ASN1IMPL)) < 0) return ret;
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_IntersectionReferenceID(IntersectionReferenceID *value);
extern int ASN1_BER_Data_Dec_IntersectionReferenceID(ASN1WorkSpace *workspace, IntersectionReferenceID *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_IntersectionReferenceID(ASN1WorkSpace *workspace, IntersectionReferenceID *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_IntersectionReferenceID(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_IntersectionReferenceID(value)) < 0) return ret;
	return ret;
}
int ASN1_PER_Align_Data_Enc_IntersectionReferenceID(ASN1WorkSpace *workspace, IntersectionReferenceID *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_region = { ASN1_CONST64(0), ASN1_CONST64(65535), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_id = { ASN1_CONST64(0), ASN1_CONST64(65535), NULL, 0, CONS, 0, 0 };

	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_IntersectionReferenceID_region == 1 ? 1 : 0) )) < 0) return ret;
	if (value->DEF_IntersectionReferenceID_region == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->region), &consinfo_region)) < 0) return ret;
	}
	if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->id), &consinfo_id)) < 0) return ret;
	return ret;
}
