/********************************************************
*AdvisorySpeed                                          *
********************************************************/
int ASN1_Print_AdvisorySpeed(AdvisorySpeed *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("AdvisorySpeed");
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->type)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("AdvisorySpeedType", "none", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("AdvisorySpeedType", "greenwave", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("AdvisorySpeedType", "ecoDrive", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("AdvisorySpeedType", "transit", 3)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	if (value->DEF_AdvisorySpeed_speed == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("SpeedAdvice", &(value->speed))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_AdvisorySpeed_confidence == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->confidence)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("SpeedConfidence", "unavailable", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("SpeedConfidence", "prec100ms", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("SpeedConfidence", "prec10ms", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("SpeedConfidence", "prec5ms", 3)) < 0) return ret; break;
		case 4: if ((ret = ASN1_Print_ENUMERATED("SpeedConfidence", "prec1ms", 4)) < 0) return ret; break;
		case 5: if ((ret = ASN1_Print_ENUMERATED("SpeedConfidence", "prec0-1ms", 5)) < 0) return ret; break;
		case 6: if ((ret = ASN1_Print_ENUMERATED("SpeedConfidence", "prec0-05ms", 6)) < 0) return ret; break;
		case 7: if ((ret = ASN1_Print_ENUMERATED("SpeedConfidence", "prec0-01ms", 7)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	if (value->DEF_AdvisorySpeed_distance == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("ZoneLength", &(value->distance))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_AdvisorySpeed_class == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("RestrictionClassID", &(value->class))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_AdvisorySpeed_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference AdvisorySpeed_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_AdvisorySpeed_regional((AdvisorySpeed_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
