extern int ASN1_PER_UNAlign_Data_Enc_AdvisorySpeed_regional(ASN1WorkSpace *workspace, AdvisorySpeed_regional *value);
int ASN1_PER_UNAlign_Data_Enc_AdvisorySpeed(ASN1WorkSpace *workspace, AdvisorySpeed *value)
{
	int ret = 0;
	ASNINT32 ui_type;
	ASNINT32 ui_confidence;
	struct Asn1ConsInfo consinfo_type = { ASN1_CONST64(0), ASN1_CONST64(3), NULL, 1, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_speed = { ASN1_CONST64(0), ASN1_CONST64(500), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_confidence = { ASN1_CONST64(0), ASN1_CONST64(7), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_distance = { ASN1_CONST64(0), ASN1_CONST64(10000), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_class = { ASN1_CONST64(0), ASN1_CONST64(255), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNINT32 all_bit;
	ASNUINT16 all_pointer;
	if ((ret = ASN1_PER_Enc_extbit(workspace, value->E)) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_AdvisorySpeed_speed == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_AdvisorySpeed_confidence == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_AdvisorySpeed_distance == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_AdvisorySpeed_class == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_AdvisorySpeed_regional == 1 ? 1 : 0) )) < 0) return ret;
	switch(value->type)
	{
	case AdvisorySpeedType_none: ui_type = 0; consinfo_type.enumextbit = 0; break;
	case AdvisorySpeedType_greenwave: ui_type = 1; consinfo_type.enumextbit = 0; break;
	case AdvisorySpeedType_ecoDrive: ui_type = 2; consinfo_type.enumextbit = 0; break;
	case AdvisorySpeedType_transit: ui_type = 3; consinfo_type.enumextbit = 0; break;
	default: ui_type = value->type; consinfo_type.enumextbit = 1;break;
	}
	if ((ret = ASN1_PER_UNAlign_Enc_ENUMERATED(workspace, ui_type, &consinfo_type)) < 0) return ret;
	if (value->DEF_AdvisorySpeed_speed == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_INTEGER(workspace, &(value->speed), &consinfo_speed)) < 0) return ret;
	}
	if (value->DEF_AdvisorySpeed_confidence == 1)
	{
		switch(value->confidence)
		{
		case SpeedConfidence_unavailable: ui_confidence = 0; consinfo_confidence.enumextbit = 0; break;
		case SpeedConfidence_prec100ms: ui_confidence = 1; consinfo_confidence.enumextbit = 0; break;
		case SpeedConfidence_prec10ms: ui_confidence = 2; consinfo_confidence.enumextbit = 0; break;
		case SpeedConfidence_prec5ms: ui_confidence = 3; consinfo_confidence.enumextbit = 0; break;
		case SpeedConfidence_prec1ms: ui_confidence = 4; consinfo_confidence.enumextbit = 0; break;
		case SpeedConfidence_prec0_1ms: ui_confidence = 5; consinfo_confidence.enumextbit = 0; break;
		case SpeedConfidence_prec0_05ms: ui_confidence = 6; consinfo_confidence.enumextbit = 0; break;
		case SpeedConfidence_prec0_01ms: ui_confidence = 7; consinfo_confidence.enumextbit = 0; break;
		default: ui_confidence = value->confidence; consinfo_confidence.enumextbit = 0;break;
		}
		if ((ret = ASN1_PER_UNAlign_Enc_ENUMERATED(workspace, ui_confidence, &consinfo_confidence)) < 0) return ret;
	}
	if (value->DEF_AdvisorySpeed_distance == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_INTEGER(workspace, &(value->distance), &consinfo_distance)) < 0) return ret;
	}
	if (value->DEF_AdvisorySpeed_class == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_INTEGER(workspace, &(value->class), &consinfo_class)) < 0) return ret;
	}
	if (value->DEF_AdvisorySpeed_regional == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_AdvisorySpeed_regional(workspace, &(value->regional))) < 0) return ret;
	}
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, UNALIGN, 0);
	}
	return ret;
}
