/********************************************************
*MovementEvent                                          *
********************************************************/
int ASN1_Print_MovementEvent(MovementEvent *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("MovementEvent");
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->eventState)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("MovementPhaseState", "unavailable", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("MovementPhaseState", "dark", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("MovementPhaseState", "stop-Then-Proceed", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("MovementPhaseState", "stop-And-Remain", 3)) < 0) return ret; break;
	case 4: if ((ret = ASN1_Print_ENUMERATED("MovementPhaseState", "pre-Movement", 4)) < 0) return ret; break;
	case 5: if ((ret = ASN1_Print_ENUMERATED("MovementPhaseState", "permissive-Movement-Allowed", 5)) < 0) return ret; break;
	case 6: if ((ret = ASN1_Print_ENUMERATED("MovementPhaseState", "protected-Movement-Allowed", 6)) < 0) return ret; break;
	case 7: if ((ret = ASN1_Print_ENUMERATED("MovementPhaseState", "permissive-clearance", 7)) < 0) return ret; break;
	case 8: if ((ret = ASN1_Print_ENUMERATED("MovementPhaseState", "protected-clearance", 8)) < 0) return ret; break;
	case 9: if ((ret = ASN1_Print_ENUMERATED("MovementPhaseState", "caution-Conflicting-Traffic", 9)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	if (value->DEF_MovementEvent_timing == 1)
	{ /*OPTIONAL start */
		// Type Reference TimeChangeDetails
		if (Compare_Letter(tab_value, "timing")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("timing = ");
		}
		if ((ret = ASN1_Print_TimeChangeDetails((TimeChangeDetails *)value->timing, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MovementEvent_speeds == 1)
	{ /*OPTIONAL start */
		// Type Reference AdvisorySpeedList
		if (Compare_Letter(tab_value, "speeds")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("speeds = ");
		}
		if ((ret = ASN1_Print_AdvisorySpeedList((AdvisorySpeedList *)&(value->speeds), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MovementEvent_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference MovementEvent_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_MovementEvent_regional((MovementEvent_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
