int ASN1_Print_ConnectionManeuverAssist(ConnectionManeuverAssist *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("ConnectionManeuverAssist");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("LaneConnectionID", &(value->connectionID))) < 0) return ret;
	if (value->DEF_ConnectionManeuverAssist_queueLength == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("ZoneLength", &(value->queueLength))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ConnectionManeuverAssist_availableStorageLength == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("ZoneLength", &(value->availableStorageLength))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ConnectionManeuverAssist_waitOnStop == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BOOLEAN("WaitOnStopline", &(value->waitOnStop))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ConnectionManeuverAssist_pedBicycleDetect == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BOOLEAN("PedestrianBicycleDetect", &(value->pedBicycleDetect))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ConnectionManeuverAssist_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference ConnectionManeuverAssist_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_ConnectionManeuverAssist_regional((ConnectionManeuverAssist_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
