int ASN1_Print_ManeuverAssistList(ManeuverAssistList *value, int tab_value)
{
	int ret = 0;
	int count;
	ASN1ListNode *pnode;
	if (value == NULL) return -1;
	count = value->count;
	pnode = value->head->next;
	// SEQUENCE OF : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ_OF("ManeuverAssistList");
	while(count) {
		// Type Reference ConnectionManeuverAssist
		ASN_Print_TAB(tab_value + 1);
		if ((ret = ASN1_Print_ConnectionManeuverAssist((ConnectionManeuverAssist *)pnode->data, tab_value + 1)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}

	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
extern int ASN1_CHECK_ConnectionManeuverAssist(ConnectionManeuverAssist *value);
int ASN1_CHECK_ManeuverAssistList(ManeuverAssistList *value)
{
	int ret = 0;

	unsigned char checkinfo_ManeuverAssistList[] = { 
		0x02,0x01,0x10,0x00
	};
	unsigned char checkinfo_ManeuverAssistList_pdata[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	int count;
	ASN1ListNode* pnode;
	if (value == NULL) return -1;
	if (value->head == NULL) return -1;
	if (value->count < 0) return -1;
	pnode = value->head->next;
	count = value->count;
	while (count) {
		if ((ret = ASN1_CHECK_ConnectionManeuverAssist(pnode->data)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}
	return ret;
}
