/********************************************************
*MovementState_regional                                 *
********************************************************/
int ASN1_Print_MovementState_regional(MovementState_regional *value, int tab_value)
{
	int ret = 0;
	int count;
	ASN1ListNode *pnode;
	if (value == NULL) return -1;
	count = value->count;
	pnode = value->head->next;
	// SEQUENCE OF : default
	ASN1_Print_SEQ_OF(" ");
	while(count) {
		// Type Reference RegionalExtension
		ASN_Print_TAB(tab_value + 1);
		if ((ret = ASN1_Print_RegionalExtension((RegionalExtension *)pnode->data, tab_value + 1)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}

	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
extern int ASN1_CHECK_RegionalExtension(RegionalExtension *value);
int ASN1_CHECK_MovementState_regional(MovementState_regional *value)
{
	int ret = 0;

	unsigned char checkinfo_MovementState_regional[] = { 
		0x02,0x01,0x04,0x00
	};
	unsigned char checkinfo_MovementState_regional_pdata[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	int count;
	ASN1ListNode* pnode;
	if (value == NULL) return -1;
	if (value->head == NULL) return -1;
	if (value->count < 0) return -1;
	pnode = value->head->next;
	count = value->count;
	while (count) {
		if ((ret = ASN1_CHECK_RegionalExtension(pnode->data)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}
	return ret;
}
extern int ASN1_BER_Data_Enc_RegionalExtension(ASN1WorkSpace *workspace, RegionalExtension *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_MovementState_regional(ASN1WorkSpace *workspace, MovementState_regional *value, ASN1TagType tagFlag)
{
	int ret = 0;
	ASN1ListNode *pnode;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	pnode = value->head->next;
	while (NULL != pnode)
	{
		if ((ret = ASN1_BER_Data_Enc_RegionalExtension(workspace, pnode->data, ASN1EXPL)) < 0) return ret;
		pnode = pnode->next;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_MovementState_regional(MovementState_regional *value);
extern int ASN1_BER_Data_Enc_MovementState_regional(ASN1WorkSpace *workspace, MovementState_regional *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_MovementState_regional(ASN1WorkSpace *workspace, MovementState_regional *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_MovementState_regional(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_MovementState_regional(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_RegionalExtension(ASN1WorkSpace *workspace, RegionalExtension *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_MovementState_regional(ASN1WorkSpace *workspace, MovementState_regional *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	RegionalExtension *pdata;
	ASNUINT8 *p = workspace->buffer.current;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	if ((ret = ASN1_Creat_Init_List(workspace, value)) < 0) return ret;
	while (ASN1_BER_Dec_Isloop(workspace, p, length))
	{
		pdata = (RegionalExtension *)mpool_malloc(GetMemPool(workspace), sizeof(RegionalExtension));
		memset(pdata, 0, sizeof(RegionalExtension));
		if ((ret = ASN1_BER_Data_Dec_RegionalExtension(workspace, pdata, len, ASN1EXPL)) < 0) return ret;
		if ((ret = ASN1_Insert_Node(workspace, value,(void*)pdata)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_MovementState_regional(MovementState_regional *value);
extern int ASN1_BER_Data_Dec_MovementState_regional(ASN1WorkSpace *workspace, MovementState_regional *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_MovementState_regional(ASN1WorkSpace *workspace, MovementState_regional *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_MovementState_regional(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_MovementState_regional(value)) < 0) return ret;
	return ret;
}
