int ASN1_Print_IntersectionState(IntersectionState *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("IntersectionState");
	if (value->DEF_IntersectionState_name == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_IA5String("DescriptiveName", &(value->name))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Reference IntersectionReferenceID
	if (Compare_Letter(tab_value, "id")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("id = ");
	}
	if ((ret = ASN1_Print_IntersectionReferenceID((IntersectionReferenceID *)value->id, tab_value + 1)) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("MsgCount", &(value->revision))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BITSTRING("IntersectionStatusObject", &(value->status))) < 0) return ret;
	if (value->DEF_IntersectionState_moy == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("MinuteOfTheYear", &(value->moy))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_IntersectionState_timeStamp == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DSecond", &(value->timeStamp))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_IntersectionState_enabledLanes == 1)
	{ /*OPTIONAL start */
		// Type Reference EnabledLaneList
		if (Compare_Letter(tab_value, "enabledLanes")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("enabledLanes = ");
		}
		if ((ret = ASN1_Print_EnabledLaneList((EnabledLaneList *)&(value->enabledLanes), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	// Type Reference MovementList
	if (Compare_Letter(tab_value, "states")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("states = ");
	}
	if ((ret = ASN1_Print_MovementList((MovementList *)&(value->states), tab_value + 1)) < 0) return ret;
	if (value->DEF_IntersectionState_maneuverAssistList == 1)
	{ /*OPTIONAL start */
		// Type Reference ManeuverAssistList
		if (Compare_Letter(tab_value, "maneuverAssistList")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("maneuverAssistList = ");
		}
		if ((ret = ASN1_Print_ManeuverAssistList((ManeuverAssistList *)&(value->maneuverAssistList), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_IntersectionState_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference IntersectionState_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_IntersectionState_regional((IntersectionState_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
