extern int ASN1_CHECK_IntersectionReferenceID(IntersectionReferenceID *value);
extern int ASN1_CHECK_EnabledLaneList(EnabledLaneList *value);
extern int ASN1_CHECK_MovementList(MovementList *value);
extern int ASN1_CHECK_ManeuverAssistList(ManeuverAssistList *value);
extern int ASN1_CHECK_IntersectionState_regional(IntersectionState_regional *value);
int ASN1_CHECK_IntersectionState(IntersectionState *value)
{
	int ret = 0;

	unsigned char checkinfo_name[] = { 
		0x02,0x01,0x3F,0x00
	};
	unsigned char checkinfo_id[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_revision[] = { 
		0x02,0x00,0x7F,0x00
	};
	unsigned char checkinfo_status[] = { 
		0x02,0x10,0x10,0x00
	};
	unsigned char checkinfo_moy[] = { 
		0x02,0x00,0x83,0x08,0x0A,0xC0,0x00
	};
	unsigned char checkinfo_timeStamp[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};
	unsigned char checkinfo_enabledLanes[] = { 
		0x02,0x01,0x10,0x00
	};
	unsigned char checkinfo_states[] = { 
		0x02,0x01,0x82,0x00,0xFF,0x00
	};
	unsigned char checkinfo_maneuverAssistList[] = { 
		0x02,0x01,0x10,0x00
	};
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_IntersectionState_name == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_IA5String(&(value->name), checkinfo_name)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_IntersectionReferenceID(value->id)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->revision), checkinfo_revision)) < 0) return ret;
	if ((ret = ASN1_CHECK_BITSTRING(&(value->status), checkinfo_status)) < 0) return ret;
	if (value->DEF_IntersectionState_moy == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->moy), checkinfo_moy)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_IntersectionState_timeStamp == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->timeStamp), checkinfo_timeStamp)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_IntersectionState_enabledLanes == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_EnabledLaneList(&(value->enabledLanes))) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_MovementList(&(value->states))) < 0) return ret;
	if (value->DEF_IntersectionState_maneuverAssistList == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ManeuverAssistList(&(value->maneuverAssistList))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_IntersectionState_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_IntersectionState_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
