		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_ManeuverAssistList(workspace, &value->maneuverAssistList, len, ASN1IMPL)) < 0) return ret;
