int ASN1_PER_UNAlign_Data_Enc_IntersectionState(ASN1WorkSpace *workspace, IntersectionState *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_name = { ASN1_CONST64(1), ASN1_CONST64(63), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_id = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_revision = { ASN1_CONST64(0), ASN1_CONST64(127), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_status = { ASN1_CONST64(16), ASN1_CONST64(16), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_moy = { ASN1_CONST64(0), ASN1_CONST64(527040), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_timeStamp = { ASN1_CONST64(0), ASN1_CONST64(65535), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_enabledLanes = { ASN1_CONST64(1), ASN1_CONST64(16), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_states = { ASN1_CONST64(1), ASN1_CONST64(255), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_maneuverAssistList = { ASN1_CONST64(1), ASN1_CONST64(16), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNINT32 all_bit;
	ASNUINT16 all_pointer;
	if ((ret = ASN1_PER_Enc_extbit(workspace, value->E)) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_IntersectionState_name == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_IntersectionState_moy == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_IntersectionState_timeStamp == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_IntersectionState_enabledLanes == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_IntersectionState_maneuverAssistList == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_IntersectionState_regional == 1 ? 1 : 0) )) < 0) return ret;
	if (value->DEF_IntersectionState_name == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_IA5String(workspace, &(value->name), &consinfo_name)) < 0) return ret;
	}
	if ((ret = ASN1_PER_UNAlign_Enc_IntersectionReferenceID(workspace, value->id)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Enc_INTEGER(workspace, &(value->revision), &consinfo_revision)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Enc_BITSTRING(workspace, &(value->status), &consinfo_status)) < 0) return ret;
	if (value->DEF_IntersectionState_moy == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_INTEGER(workspace, &(value->moy), &consinfo_moy)) < 0) return ret;
	}
	if (value->DEF_IntersectionState_timeStamp == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_INTEGER(workspace, &(value->timeStamp), &consinfo_timeStamp)) < 0) return ret;
	}
	if (value->DEF_IntersectionState_enabledLanes == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_EnabledLaneList(workspace, &(value->enabledLanes))) < 0) return ret;
	}
	if ((ret = ASN1_PER_UNAlign_Enc_MovementList(workspace, &(value->states))) < 0) return ret;
	if (value->DEF_IntersectionState_maneuverAssistList == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_ManeuverAssistList(workspace, &(value->maneuverAssistList))) < 0) return ret;
	}
	if (value->DEF_IntersectionState_regional == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_IntersectionState_regional(workspace, &(value->regional))) < 0) return ret;
	}
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, UNALIGN, 0);
	}
	return ret;
}
