int ASN1_BER_Dec_IntersectionStateList(ASN1WorkSpace *workspace, IntersectionStateList *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_IntersectionStateList(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_IntersectionStateList(value)) < 0) return ret;
	return ret;
}
