/********************************************************
*SPAT                                                   *
********************************************************/
int ASN1_Print_SPAT(SPAT *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("SPAT");
	if (value->DEF_SPAT_timeStamp == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("MinuteOfTheYear", &(value->timeStamp))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SPAT_name == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_IA5String("DescriptiveName", &(value->name))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Reference IntersectionStateList
	if (Compare_Letter(tab_value, "intersections")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("intersections = ");
	}
	if ((ret = ASN1_Print_IntersectionStateList((IntersectionStateList *)&(value->intersections), tab_value + 1)) < 0) return ret;
	if (value->DEF_SPAT_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference SPAT_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_SPAT_regional((SPAT_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_SPAT_timeStamp(ASN1WorkSpace *workspace, SPAT *value, INTEGER user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	value->DEF_SPAT_timeStamp = 1;
	if ((ret = ASN1_SET_INTEGER(workspace, &value->timeStamp, user_value)) < 0) return ret;
	return ret;
}
int ASN1_SET_SPAT_name(ASN1WorkSpace *workspace, SPAT *value, ASNUINT8 *user_value, ASNUINT32 user_value_length)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->DEF_SPAT_name = 1;
	if ((ret = ASN1_SET_IA5String(workspace, &value->name, user_value, user_value_length)) < 0) return ret;
	return ret;
}
int ASN1_SET_SPAT_intersections(ASN1WorkSpace *workspace, SPAT *value, IntersectionStateList *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	memmove(&value->intersections, user_value, sizeof(IntersectionStateList));
	return ret;
}
int ASN1_SET_SPAT_regional(ASN1WorkSpace *workspace, SPAT *value, SPAT_regional *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->DEF_SPAT_regional = 1;
	memmove(&value->regional, user_value, sizeof(SPAT_regional));
	return ret;
}
int ASN1_GET_SPAT_timeStamp(ASN1WorkSpace *workspace, SPAT *value, INTEGER *user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if (value->DEF_SPAT_timeStamp == 1)
	{
		if ((ret = ASN1_GET_INTEGER(workspace, &value->timeStamp, user_value)) < 0) return ret;
	}
	else return -2;
	return ret;
}
int ASN1_GET_SPAT_name(ASN1WorkSpace *workspace, SPAT *value, ASNUINT8 **user_value, ASNUINT32 *user_value_length)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if (value->DEF_SPAT_name == 1)
	{
		if ((ret = ASN1_GET_IA5String(workspace, &value->name, user_value, user_value_length)) < 0) return ret;
	}
	else return -2;
	return ret;
}
int ASN1_GET_SPAT_intersections(ASN1WorkSpace *workspace, SPAT *value, IntersectionStateList **user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	*user_value = &value->intersections;
	return ret;
}
int ASN1_GET_SPAT_regional(ASN1WorkSpace *workspace, SPAT *value, SPAT_regional **user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if (value->DEF_SPAT_regional == 1)
	{
		*user_value = &value->regional;
	}
	else return -2;
	return ret;
}
extern int ASN1_CHECK_IntersectionStateList(IntersectionStateList *value);
extern int ASN1_CHECK_SPAT_regional(SPAT_regional *value);
int ASN1_CHECK_SPAT(SPAT *value)
{
	int ret = 0;

	unsigned char checkinfo_timeStamp[] = { 
		0x02,0x00,0x83,0x08,0x0A,0xC0,0x00
	};
	unsigned char checkinfo_name[] = { 
		0x02,0x01,0x3F,0x00
	};
	unsigned char checkinfo_intersections[] = { 
		0x02,0x01,0x20,0x00
	};
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_SPAT_timeStamp == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->timeStamp), checkinfo_timeStamp)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SPAT_name == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_IA5String(&(value->name), checkinfo_name)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_IntersectionStateList(&(value->intersections))) < 0) return ret;
	if (value->DEF_SPAT_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_SPAT_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_MinuteOfTheYear(ASN1WorkSpace *workspace, MinuteOfTheYear *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_DescriptiveName(ASN1WorkSpace *workspace, DescriptiveName *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_IntersectionStateList(ASN1WorkSpace *workspace, IntersectionStateList *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_SPAT_regional(ASN1WorkSpace *workspace, SPAT_regional *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_SPAT(ASN1WorkSpace *workspace, SPAT *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if (value->DEF_SPAT_timeStamp == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_MinuteOfTheYear(workspace, &(value->timeStamp), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_SPAT_name == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_DescriptiveName(workspace, &(value->name), ASN1IMPL)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_IntersectionStateList(workspace, &(value->intersections), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (value->DEF_SPAT_regional == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 16)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_SPAT_regional(workspace, &(value->regional), ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_SPAT(SPAT *value);
extern int ASN1_BER_Data_Enc_SPAT(ASN1WorkSpace *workspace, SPAT *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_SPAT(ASN1WorkSpace *workspace, SPAT *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_SPAT(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_SPAT(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_MinuteOfTheYear(ASN1WorkSpace *workspace, MinuteOfTheYear *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_DescriptiveName(ASN1WorkSpace *workspace, DescriptiveName *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_IntersectionStateList(ASN1WorkSpace *workspace, IntersectionStateList *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_SPAT_regional(ASN1WorkSpace *workspace, SPAT_regional *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_SPAT(ASN1WorkSpace *workspace, SPAT *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 0))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_MinuteOfTheYear(workspace, &value->timeStamp, len, ASN1IMPL)) < 0) return ret;
		value->DEF_SPAT_timeStamp = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 1))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_DescriptiveName(workspace, &value->name, len, ASN1IMPL)) < 0) return ret;
		value->DEF_SPAT_name = 1;
	}
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_IntersectionStateList(workspace, &value->intersections, len, ASN1IMPL)) < 0) return ret;
	if (IfFixedLength(len) == -1)
	{
		if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_CONS | 16))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_SPAT_regional(workspace, &value->regional, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->DEF_SPAT_regional = 1;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_SPAT(SPAT *value);
extern int ASN1_BER_Data_Dec_SPAT(ASN1WorkSpace *workspace, SPAT *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_SPAT(ASN1WorkSpace *workspace, SPAT *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_SPAT(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_SPAT(value)) < 0) return ret;
	return ret;
}
extern int ASN1_PER_Align_Data_Enc_IntersectionStateList(ASN1WorkSpace *workspace, IntersectionStateList *value);
extern int ASN1_PER_Align_Data_Enc_SPAT_regional(ASN1WorkSpace *workspace, SPAT_regional *value);
int ASN1_PER_Align_Data_Enc_SPAT(ASN1WorkSpace *workspace, SPAT *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_timeStamp = { ASN1_CONST64(0), ASN1_CONST64(527040), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_name = { ASN1_CONST64(1), ASN1_CONST64(63), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_intersections = { ASN1_CONST64(1), ASN1_CONST64(32), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNINT32 all_bit;
	ASNUINT16 all_pointer;
	if ((ret = ASN1_PER_Enc_extbit(workspace, value->E)) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_SPAT_timeStamp == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_SPAT_name == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_SPAT_regional == 1 ? 1 : 0) )) < 0) return ret;
	if (value->DEF_SPAT_timeStamp == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->timeStamp), &consinfo_timeStamp)) < 0) return ret;
	}
	if (value->DEF_SPAT_name == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_IA5String(workspace, &(value->name), &consinfo_name)) < 0) return ret;
	}
	if ((ret = ASN1_PER_Align_Enc_IntersectionStateList(workspace, &(value->intersections))) < 0) return ret;
	if (value->DEF_SPAT_regional == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_SPAT_regional(workspace, &(value->regional))) < 0) return ret;
	}
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, ALIGN, 0);
	}
	return ret;
}
extern int ASN1_CHECK_SPAT(SPAT *value);
extern int ASN1_PER_Align_Data_Enc_SPAT(ASN1WorkSpace *workspace, SPAT *value);
int ASN1_PER_Align_Enc_SPAT(ASN1WorkSpace *workspace, SPAT *value)
{ // ASN1_PER_Extern_Encode 
	int ret = 0;
	if ((ret = ASN1_CHECK_SPAT(value)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Data_Enc_SPAT(workspace,value)) < 0) return ret;
	return ret;
}
extern int ASN1_PER_Align_Data_Dec_IntersectionStateList(ASN1WorkSpace *workspace, IntersectionStateList *value);
extern int ASN1_PER_Align_Data_Dec_SPAT_regional(ASN1WorkSpace *workspace, SPAT_regional *value);
int ASN1_PER_Align_Data_Dec_SPAT(ASN1WorkSpace *workspace, SPAT *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_timeStamp = { ASN1_CONST64(0), ASN1_CONST64(527040), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_name = { ASN1_CONST64(1), ASN1_CONST64(63), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_intersections = { ASN1_CONST64(1), ASN1_CONST64(32), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNBOOL extbit_SPAT;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_SPAT)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 3, &_optvalue)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_SPAT_timeStamp = 1;
		if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->timeStamp), &consinfo_timeStamp)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_SPAT_name = 1;
		if ((ret = ASN1_PER_Align_Dec_IA5String(workspace, &(value->name), &consinfo_name)) < 0) return ret;
	}
	if ((ret = ASN1_PER_Align_Dec_IntersectionStateList(workspace, &(value->intersections))) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 3) == 1)
	{
		value->DEF_SPAT_regional = 1;
		if ((ret = ASN1_PER_Align_Dec_SPAT_regional(workspace, &(value->regional))) < 0) return ret;
	}
	if (extbit_SPAT == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, ALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, ALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
extern int ASN1_CHECK_SPAT(SPAT *value);
extern int ASN1_PER_Align_Data_Dec_SPAT(ASN1WorkSpace *workspace, SPAT *value);
int ASN1_PER_Align_Dec_SPAT(ASN1WorkSpace *workspace, SPAT *value)
{
	int ret = 0;
	if ((ret = ASN1_PER_Align_Data_Dec_SPAT(workspace,value)) < 0) return ret;
	if ((ret = ASN1_CHECK_SPAT(value)) < 0) return ret;
	return ret;
}
