extern int ASN1_PER_Align_Data_Dec_RegionalExtension(ASN1WorkSpace *workspace, RegionalExtension *value);
int ASN1_PER_Align_Data_Dec_Position3D_regional(ASN1WorkSpace *workspace, Position3D_regional *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_Position3D_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_Position3D_regional_pdata = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	ASNINT32 loop_set = 1;
	ASNINT32 process_length = 0;
	ASNINT32 i = 0;
	RegionalExtension *pdata;
	if ((ret = ASN1_Creat_Init_List(workspace, value)) < 0) return ret;
	while(loop_set)
	{
		loop_set = ASN1_PER_Align_Dec_Set_Seq_Of_Length(workspace, &process_length, &consinfo_Position3D_regional);
		for (i = 0; i < process_length; i++)
		{
			if ((pdata = (RegionalExtension *)mpool_calloc(GetMemPool(workspace), sizeof(RegionalExtension), 1)) == NULL) return -1;
			if ((ret = ASN1_PER_Align_Dec_RegionalExtension(workspace, pdata)) < 0) return ret;
			if ((ret = ASN1_Insert_Node(workspace, value, (void *)pdata)) < 0) return ret;
		}
	}

	return ret;
}
