extern int ASN1_PER_UNAlign_Data_Enc_Position3D_regional(ASN1WorkSpace *workspace, Position3D_regional *value);
int ASN1_PER_UNAlign_Data_Enc_Position3D(ASN1WorkSpace *workspace, Position3D *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_lat = { ASN1_CONST64(-900000000), ASN1_CONST64(900000001), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_lon = { ASN1_CONST64(-1799999999), ASN1_CONST64(1800000001), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_elevation = { ASN1_CONST64(-4096), ASN1_CONST64(61439), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNINT32 all_bit;
	ASNUINT16 all_pointer;
	if ((ret = ASN1_PER_Enc_extbit(workspace, value->E)) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_Position3D_elevation == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_Position3D_regional == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Enc_INTEGER(workspace, &(value->lat), &consinfo_lat)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Enc_INTEGER(workspace, &(value->lon), &consinfo_lon)) < 0) return ret;
	if (value->DEF_Position3D_elevation == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_INTEGER(workspace, &(value->elevation), &consinfo_elevation)) < 0) return ret;
	}
	if (value->DEF_Position3D_regional == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_Position3D_regional(workspace, &(value->regional))) < 0) return ret;
	}
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, UNALIGN, 0);
	}
	return ret;
}
extern int ASN1_CHECK_Position3D(Position3D *value);
extern int ASN1_PER_UNAlign_Data_Enc_Position3D(ASN1WorkSpace *workspace, Position3D *value);
int ASN1_PER_UNAlign_Enc_Position3D(ASN1WorkSpace *workspace, Position3D *value)
{ // ASN1_PER_Extern_Encode 
	int ret = 0;
	if ((ret = ASN1_CHECK_Position3D(value)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Data_Enc_Position3D(workspace,value)) < 0) return ret;
	return ret;
}
extern int ASN1_PER_UNAlign_Data_Dec_Position3D_regional(ASN1WorkSpace *workspace, Position3D_regional *value);
int ASN1_PER_UNAlign_Data_Dec_Position3D(ASN1WorkSpace *workspace, Position3D *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_lat = { ASN1_CONST64(-900000000), ASN1_CONST64(900000001), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_lon = { ASN1_CONST64(-1799999999), ASN1_CONST64(1800000001), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_elevation = { ASN1_CONST64(-4096), ASN1_CONST64(61439), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNBOOL extbit_Position3D;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_Position3D)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 2, &_optvalue)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->lat), &consinfo_lat)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->lon), &consinfo_lon)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_Position3D_elevation = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->elevation), &consinfo_elevation)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_Position3D_regional = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_Position3D_regional(workspace, &(value->regional))) < 0) return ret;
	}
	if (extbit_Position3D == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, UNALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, UNALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
extern int ASN1_CHECK_Position3D(Position3D *value);
extern int ASN1_PER_UNAlign_Data_Dec_Position3D(ASN1WorkSpace *workspace, Position3D *value);
int ASN1_PER_UNAlign_Dec_Position3D(ASN1WorkSpace *workspace, Position3D *value)
{
	int ret = 0;
	if ((ret = ASN1_PER_UNAlign_Data_Dec_Position3D(workspace,value)) < 0) return ret;
	if ((ret = ASN1_CHECK_Position3D(value)) < 0) return ret;
	return ret;
}

