int ASN1_CHECK_RegulatorySpeedLimit(RegulatorySpeedLimit *value)
{
	int ret = 0;

	unsigned char checkinfo_type[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_speed[] = { 
		0x02,0x00,0x82,0x1F,0xFF,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->type), checkinfo_type)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->speed), checkinfo_speed)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Enc_SpeedLimitType(ASN1WorkSpace *workspace, SpeedLimitType *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_Velocity(ASN1WorkSpace *workspace, Velocity *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_RegulatorySpeedLimit(ASN1WorkSpace *workspace, RegulatorySpeedLimit *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_SpeedLimitType(workspace, &(value->type), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_Velocity(workspace, &(value->speed), ASN1IMPL)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_RegulatorySpeedLimit(RegulatorySpeedLimit *value);
extern int ASN1_BER_Data_Enc_RegulatorySpeedLimit(ASN1WorkSpace *workspace, RegulatorySpeedLimit *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_RegulatorySpeedLimit(ASN1WorkSpace *workspace, RegulatorySpeedLimit *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_RegulatorySpeedLimit(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_RegulatorySpeedLimit(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_SpeedLimitType(ASN1WorkSpace *workspace, SpeedLimitType *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_Velocity(ASN1WorkSpace *workspace, Velocity *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_RegulatorySpeedLimit(ASN1WorkSpace *workspace, RegulatorySpeedLimit *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_SpeedLimitType(workspace, &value->type, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_Velocity(workspace, &value->speed, len, ASN1IMPL)) < 0) return ret;
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_RegulatorySpeedLimit(RegulatorySpeedLimit *value);
extern int ASN1_BER_Data_Dec_RegulatorySpeedLimit(ASN1WorkSpace *workspace, RegulatorySpeedLimit *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_RegulatorySpeedLimit(ASN1WorkSpace *workspace, RegulatorySpeedLimit *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_RegulatorySpeedLimit(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_RegulatorySpeedLimit(value)) < 0) return ret;
	return ret;
}
