	case SpeedLimitType_vehicleNightMaxSpeed: ui_type = 6; consinfo_type.enumextbit = 0; break;
	case SpeedLimitType_truckMinSpeed: ui_type = 7; consinfo_type.enumextbit = 0; break;
	case SpeedLimitType_truckMaxSpeed: ui_type = 8; consinfo_type.enumextbit = 0; break;
