/********************************************************
*LaneTypeAttributes                                     *
********************************************************/
int ASN1_Print_LaneTypeAttributes(LaneTypeAttributes *value, int tab_value)
{
	int ret = 0;
	// CHOICE : t->tempIdentifier is Upper Letter
	ASN1_Print_CHOICE("LaneTypeAttributes");
	if (value == NULL) return -1;
	switch (value->M) {
	case DEF_LaneTypeAttributes_vehicle:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("LaneAttributes_Vehicle", &value->elements.vehicle)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_LaneTypeAttributes_crosswalk:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("LaneAttributes_Crosswalk", &value->elements.crosswalk)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_LaneTypeAttributes_bikeLane:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("LaneAttributes_Bike", &value->elements.bikeLane)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_LaneTypeAttributes_sidewalk:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("LaneAttributes_Sidewalk", &value->elements.sidewalk)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_LaneTypeAttributes_median:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("LaneAttributes_Barrier", &value->elements.median)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_LaneTypeAttributes_striping:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("LaneAttributes_Striping", &value->elements.striping)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_LaneTypeAttributes_trackedVehicle:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("LaneAttributes_TrackedVehicle", &value->elements.trackedVehicle)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_LaneTypeAttributes_parking:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("LaneAttributes_Parking", &value->elements.parking)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	default: return -1;
}
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
