int ASN1_Print_LaneAttributes(LaneAttributes *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("LaneAttributes");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BITSTRING("LaneDirection", &(value->directionalUse))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BITSTRING("LaneSharing", &(value->sharedWith))) < 0) return ret;
	// Type Reference LaneTypeAttributes
	if (Compare_Letter(tab_value, "laneType")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("laneType = ");
	}
	if ((ret = ASN1_Print_LaneTypeAttributes((LaneTypeAttributes *)value->laneType, tab_value + 1)) < 0) return ret;
	if (value->DEF_LaneAttributes_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference RegionalExtension
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_RegionalExtension((RegionalExtension *)value->regional, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
