{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if (value->DEF_LaneAttributes_regional == 1)
	{
		*user_value = value->regional;
	}
	else return -2;
	return ret;
}
extern int ASN1_CHECK_LaneTypeAttributes(LaneTypeAttributes *value);
extern int ASN1_CHECK_RegionalExtension(RegionalExtension *value);
int ASN1_CHECK_LaneAttributes(LaneAttributes *value)
{
	int ret = 0;

	unsigned char checkinfo_directionalUse[] = { 
		0x02,0x02,0x02,0x00
	};
	unsigned char checkinfo_sharedWith[] = { 
		0x02,0x0A,0x0A,0x00
	};
	unsigned char checkinfo_laneType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_regional[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_BITSTRING(&(value->directionalUse), checkinfo_directionalUse)) < 0) return ret;
	if ((ret = ASN1_CHECK_BITSTRING(&(value->sharedWith), checkinfo_sharedWith)) < 0) return ret;
	if ((ret = ASN1_CHECK_LaneTypeAttributes(value->laneType)) < 0) return ret;
	if (value->DEF_LaneAttributes_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_RegionalExtension(value->regional)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_LaneDirection(ASN1WorkSpace *workspace, LaneDirection *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_LaneSharing(ASN1WorkSpace *workspace, LaneSharing *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_LaneTypeAttributes(ASN1WorkSpace *workspace, LaneTypeAttributes *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_RegionalExtension(ASN1WorkSpace *workspace, RegionalExtension *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_LaneAttributes(ASN1WorkSpace *workspace, LaneAttributes *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_LaneDirection(workspace, &(value->directionalUse), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_LaneSharing(workspace, &(value->sharedWith), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_LaneTypeAttributes(workspace, value->laneType, ASN1EXPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (value->DEF_LaneAttributes_regional == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 3)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_RegionalExtension(workspace, value->regional, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_LaneAttributes(LaneAttributes *value);
extern int ASN1_BER_Data_Enc_LaneAttributes(ASN1WorkSpace *workspace, LaneAttributes *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_LaneAttributes(ASN1WorkSpace *workspace, LaneAttributes *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_LaneAttributes(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_LaneAttributes(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_LaneDirection(ASN1WorkSpace *workspace, LaneDirection *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_LaneSharing(ASN1WorkSpace *workspace, LaneSharing *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_LaneTypeAttributes(ASN1WorkSpace *workspace, LaneTypeAttributes *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_RegionalExtension(ASN1WorkSpace *workspace, RegionalExtension *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_LaneAttributes(ASN1WorkSpace *workspace, LaneAttributes *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	value->laneType = (LaneTypeAttributes *)mpool_malloc(workspace->Pmemory, sizeof(LaneTypeAttributes));
	memset(value->laneType, 0, sizeof(LaneTypeAttributes));
	value->regional = (RegionalExtension *)mpool_malloc(workspace->Pmemory, sizeof(RegionalExtension));
	memset(value->regional, 0, sizeof(RegionalExtension));
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_LaneDirection(workspace, &value->directionalUse, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_LaneSharing(workspace, &value->sharedWith, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_LaneTypeAttributes(workspace, value->laneType, len, ASN1EXPL)) < 0) return ret;
	if (IfFixedLength(len) == -1)
	{
		if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_CONS | 3))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 3)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_RegionalExtension(workspace, value->regional, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->DEF_LaneAttributes_regional = 1;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_LaneAttributes(LaneAttributes *value);
extern int ASN1_BER_Data_Dec_LaneAttributes(ASN1WorkSpace *workspace, LaneAttributes *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_LaneAttributes(ASN1WorkSpace *workspace, LaneAttributes *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_LaneAttributes(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_LaneAttributes(value)) < 0) return ret;
	return ret;
}
