int ASN1_Print_LaneDataAttribute(LaneDataAttribute *value, int tab_value)
{
	int ret = 0;
	// CHOICE : t->tempIdentifier is Upper Letter
	ASN1_Print_CHOICE("LaneDataAttribute");
	if (value == NULL) return -1;
	switch (value->M) {
	case DEF_LaneDataAttribute_pathEndPointAngle:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DeltaAngle", &value->elements.pathEndPointAngle)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_LaneDataAttribute_laneCrownPointCenter:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("RoadwayCrownAngle", &value->elements.laneCrownPointCenter)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_LaneDataAttribute_laneCrownPointLeft:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("RoadwayCrownAngle", &value->elements.laneCrownPointLeft)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_LaneDataAttribute_laneCrownPointRight:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("RoadwayCrownAngle", &value->elements.laneCrownPointRight)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_LaneDataAttribute_laneAngle:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("MergeDivergeNodeAngle", &value->elements.laneAngle)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_LaneDataAttribute_speedLimits:
		// Type Reference SpeedLimitList
		if (Compare_Letter(tab_value, "speedLimits")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("speedLimits = ");
		}
		if ((ret = ASN1_Print_SpeedLimitList((SpeedLimitList *)&value->elements.speedLimits, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_LaneDataAttribute_regional:
		// Type Reference LaneDataAttribute_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_LaneDataAttribute_regional((LaneDataAttribute_regional *)&value->elements.regional, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	default: return -1;
}
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
