/********************************************************
*NodeXY                                                 *
********************************************************/
int ASN1_Print_NodeXY(NodeXY *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("NodeXY");
	// Type Reference NodeOffsetPointXY
	if (Compare_Letter(tab_value, "delta")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("delta = ");
	}
	if ((ret = ASN1_Print_NodeOffsetPointXY((NodeOffsetPointXY *)value->delta, tab_value + 1)) < 0) return ret;
	if (value->DEF_NodeXY_attributes == 1)
	{ /*OPTIONAL start */
		// Type Reference NodeAttributeSetXY
		if (Compare_Letter(tab_value, "attributes")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("attributes = ");
		}
		if ((ret = ASN1_Print_NodeAttributeSetXY((NodeAttributeSetXY *)value->attributes, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_NodeXY_delta(ASN1WorkSpace *workspace, NodeXY *value, NodeOffsetPointXY *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->delta = (NodeOffsetPointXY *)mpool_malloc(workspace->Pmemory, sizeof(NodeOffsetPointXY));
	memset(value->delta, 0, sizeof(NodeOffsetPointXY));
	memmove(value->delta, user_value, sizeof(NodeOffsetPointXY));
	return ret;
}
int ASN1_SET_NodeXY_attributes(ASN1WorkSpace *workspace, NodeXY *value, NodeAttributeSetXY *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->attributes = (NodeAttributeSetXY *)mpool_malloc(workspace->Pmemory, sizeof(NodeAttributeSetXY));
	memset(value->attributes, 0, sizeof(NodeAttributeSetXY));
	value->DEF_NodeXY_attributes = 1;
	memmove(value->attributes, user_value, sizeof(NodeAttributeSetXY));
	return ret;
}
int ASN1_GET_NodeXY_delta(ASN1WorkSpace *workspace, NodeXY *value, NodeOffsetPointXY **user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	*user_value = value->delta;
	return ret;
}
int ASN1_GET_NodeXY_attributes(ASN1WorkSpace *workspace, NodeXY *value, NodeAttributeSetXY **user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if (value->DEF_NodeXY_attributes == 1)
	{
		*user_value = value->attributes;
	}
	else return -2;
	return ret;
}
extern int ASN1_CHECK_NodeOffsetPointXY(NodeOffsetPointXY *value);
extern int ASN1_CHECK_NodeAttributeSetXY(NodeAttributeSetXY *value);
int ASN1_CHECK_NodeXY(NodeXY *value)
{
	int ret = 0;

	unsigned char checkinfo_delta[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_attributes[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_NodeOffsetPointXY(value->delta)) < 0) return ret;
	if (value->DEF_NodeXY_attributes == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_NodeAttributeSetXY(value->attributes)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
