int ASN1_BER_Data_Enc_NodeXY(ASN1WorkSpace *workspace, NodeXY *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_NodeOffsetPointXY(workspace, value->delta, ASN1EXPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (value->DEF_NodeXY_attributes == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_NodeAttributeSetXY(workspace, value->attributes, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
