int ASN1_Print_ComputedLane(ComputedLane *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("ComputedLane");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("LaneID", &(value->referenceLaneId))) < 0) return ret;
	// Type Reference ComputedLane_offsetXaxis
	if (Compare_Letter(tab_value, "offsetXaxis")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("offsetXaxis = ");
	}
	if ((ret = ASN1_Print_ComputedLane_offsetXaxis((ComputedLane_offsetXaxis *)value->offsetXaxis, tab_value + 1)) < 0) return ret;
	// Type Reference ComputedLane_offsetYaxis
	if (Compare_Letter(tab_value, "offsetYaxis")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("offsetYaxis = ");
	}
	if ((ret = ASN1_Print_ComputedLane_offsetYaxis((ComputedLane_offsetYaxis *)value->offsetYaxis, tab_value + 1)) < 0) return ret;
	if (value->DEF_ComputedLane_rotateXY == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("Angle", &(value->rotateXY))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ComputedLane_scaleXaxis == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("Scale_B12", &(value->scaleXaxis))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ComputedLane_scaleYaxis == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("Scale_B12", &(value->scaleYaxis))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ComputedLane_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference ComputedLane_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_ComputedLane_regional((ComputedLane_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
