extern int ASN1_CHECK_ComputedLane_offsetXaxis(ComputedLane_offsetXaxis *value);
extern int ASN1_CHECK_ComputedLane_offsetYaxis(ComputedLane_offsetYaxis *value);
extern int ASN1_CHECK_ComputedLane_regional(ComputedLane_regional *value);
int ASN1_CHECK_ComputedLane(ComputedLane *value)
{
	int ret = 0;

	unsigned char checkinfo_referenceLaneId[] = { 
		0x02,0x00,0x82,0x00,0xFF,0x00
	};
	unsigned char checkinfo_offsetXaxis[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_offsetYaxis[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_rotateXY[] = { 
		0x02,0x00,0x82,0x70,0x80,0x00
	};
	unsigned char checkinfo_scaleXaxis[] = { 
		0x02,0x82,0xF8,0x00,0x82,0x07,0xFF,0x00
	};
	unsigned char checkinfo_scaleYaxis[] = { 
		0x02,0x82,0xF8,0x00,0x82,0x07,0xFF,0x00
	};
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->referenceLaneId), checkinfo_referenceLaneId)) < 0) return ret;
	if ((ret = ASN1_CHECK_ComputedLane_offsetXaxis(value->offsetXaxis)) < 0) return ret;
	if ((ret = ASN1_CHECK_ComputedLane_offsetYaxis(value->offsetYaxis)) < 0) return ret;
	if (value->DEF_ComputedLane_rotateXY == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->rotateXY), checkinfo_rotateXY)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ComputedLane_scaleXaxis == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->scaleXaxis), checkinfo_scaleXaxis)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ComputedLane_scaleYaxis == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->scaleYaxis), checkinfo_scaleYaxis)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ComputedLane_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ComputedLane_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
