extern int ASN1_BER_Data_Enc_ComputedLane_offsetXaxis(ASN1WorkSpace *workspace, ComputedLane_offsetXaxis *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_ComputedLane_offsetYaxis(ASN1WorkSpace *workspace, ComputedLane_offsetYaxis *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_Angle(ASN1WorkSpace *workspace, Angle *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_Scale_B12(ASN1WorkSpace *workspace, Scale_B12 *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_Scale_B12(ASN1WorkSpace *workspace, Scale_B12 *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_ComputedLane_regional(ASN1WorkSpace *workspace, ComputedLane_regional *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_ComputedLane(ASN1WorkSpace *workspace, ComputedLane *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_LaneID(workspace, &(value->referenceLaneId), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_ComputedLane_offsetXaxis(workspace, value->offsetXaxis, ASN1EXPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_ComputedLane_offsetYaxis(workspace, value->offsetYaxis, ASN1EXPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (value->DEF_ComputedLane_rotateXY == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_Angle(workspace, &(value->rotateXY), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_ComputedLane_scaleXaxis == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 4)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_Scale_B12(workspace, &(value->scaleXaxis), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_ComputedLane_scaleYaxis == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 5)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_Scale_B12(workspace, &(value->scaleYaxis), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_ComputedLane_regional == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 16)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_ComputedLane_regional(workspace, &(value->regional), ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_ComputedLane(ComputedLane *value);
extern int ASN1_BER_Data_Enc_ComputedLane(ASN1WorkSpace *workspace, ComputedLane *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_ComputedLane(ASN1WorkSpace *workspace, ComputedLane *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_ComputedLane(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_ComputedLane(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_LaneID(ASN1WorkSpace *workspace, LaneID *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_ComputedLane_offsetXaxis(ASN1WorkSpace *workspace, ComputedLane_offsetXaxis *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_ComputedLane_offsetYaxis(ASN1WorkSpace *workspace, ComputedLane_offsetYaxis *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_Angle(ASN1WorkSpace *workspace, Angle *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_Scale_B12(ASN1WorkSpace *workspace, Scale_B12 *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_Scale_B12(ASN1WorkSpace *workspace, Scale_B12 *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_ComputedLane_regional(ASN1WorkSpace *workspace, ComputedLane_regional *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_ComputedLane(ASN1WorkSpace *workspace, ComputedLane *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	value->offsetXaxis = (ComputedLane_offsetXaxis *)mpool_malloc(workspace->Pmemory, sizeof(ComputedLane_offsetXaxis));
	memset(value->offsetXaxis, 0, sizeof(ComputedLane_offsetXaxis));
	value->offsetYaxis = (ComputedLane_offsetYaxis *)mpool_malloc(workspace->Pmemory, sizeof(ComputedLane_offsetYaxis));
	memset(value->offsetYaxis, 0, sizeof(ComputedLane_offsetYaxis));
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_LaneID(workspace, &value->referenceLaneId, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_ComputedLane_offsetXaxis(workspace, value->offsetXaxis, len, ASN1EXPL)) < 0) return ret;
	if (IfFixedLength(len) == -1)
	{
		if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
	}
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_ComputedLane_offsetYaxis(workspace, value->offsetYaxis, len, ASN1EXPL)) < 0) return ret;
	if (IfFixedLength(len) == -1)
	{
		if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 3))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_Angle(workspace, &value->rotateXY, len, ASN1IMPL)) < 0) return ret;
		value->DEF_ComputedLane_rotateXY = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 4))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 4)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_Scale_B12(workspace, &value->scaleXaxis, len, ASN1IMPL)) < 0) return ret;
		value->DEF_ComputedLane_scaleXaxis = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 5))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 5)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_Scale_B12(workspace, &value->scaleYaxis, len, ASN1IMPL)) < 0) return ret;
		value->DEF_ComputedLane_scaleYaxis = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_CONS | 16))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_ComputedLane_regional(workspace, &value->regional, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->DEF_ComputedLane_regional = 1;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_ComputedLane(ComputedLane *value);
extern int ASN1_BER_Data_Dec_ComputedLane(ASN1WorkSpace *workspace, ComputedLane *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_ComputedLane(ASN1WorkSpace *workspace, ComputedLane *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_ComputedLane(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_ComputedLane(value)) < 0) return ret;
	return ret;
}
