/********************************************************
*NodeListXY                                             *
********************************************************/
int ASN1_Print_NodeListXY(NodeListXY *value, int tab_value)
{
	int ret = 0;
	// CHOICE : t->tempIdentifier is Upper Letter
	ASN1_Print_CHOICE("NodeListXY");
	if (value == NULL) return -1;
	switch (value->M) {
	case DEF_NodeListXY_nodes:
		// Type Reference NodeSetXY
		if (Compare_Letter(tab_value, "nodes")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("nodes = ");
		}
		if ((ret = ASN1_Print_NodeSetXY((NodeSetXY *)&value->elements.nodes, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_NodeListXY_computed:
		// Type Reference ComputedLane
		if (Compare_Letter(tab_value, "computed")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("computed = ");
		}
		if ((ret = ASN1_Print_ComputedLane((ComputedLane *)value->elements.computed, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	default: return -1;
}
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_NodeListXY_nodes(ASN1WorkSpace *workspace, NodeListXY *value, NodeSetXY *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->M = DEF_NodeListXY_nodes;
	memmove(&value->elements.nodes, user_value, sizeof(NodeSetXY));
	return ret;
}
int ASN1_SET_NodeListXY_computed(ASN1WorkSpace *workspace, NodeListXY *value, ComputedLane *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->elements.computed = (ComputedLane *)mpool_malloc(workspace->Pmemory, sizeof(ComputedLane));
	memset(value->elements.computed, 0, sizeof(ComputedLane));
	value->M = DEF_NodeListXY_computed;
	memmove(value->elements.computed, user_value, sizeof(ComputedLane));
	return ret;
}
int ASN1_GET_NodeListXY_nodes(ASN1WorkSpace *workspace, NodeListXY *value, NodeSetXY **user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if (value->M == DEF_NodeListXY_nodes)
	{
		*user_value = &value->elements.nodes;
	}
	else return -2;
	return ret;
}
int ASN1_GET_NodeListXY_computed(ASN1WorkSpace *workspace, NodeListXY *value, ComputedLane **user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if (value->M == DEF_NodeListXY_computed)
	{
		*user_value = value->elements.computed;
	}
	else return -2;
	return ret;
}
extern int ASN1_CHECK_NodeSetXY(NodeSetXY *value);
extern int ASN1_CHECK_ComputedLane(ComputedLane *value);
int ASN1_CHECK_NodeListXY(NodeListXY *value)
{
	int ret = 0;

	unsigned char checkinfo_nodes[] = { 
		0x02,0x02,0x3F,0x00
	};
	unsigned char checkinfo_computed[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	switch (value->M)
	{
	case DEF_NodeListXY_nodes:
		if ((ret = ASN1_CHECK_NodeSetXY(&value->elements.nodes)) < 0) return ret;
		break;
	case DEF_NodeListXY_computed:
		if ((ret = ASN1_CHECK_ComputedLane(value->elements.computed)) < 0) return ret;
		break;
	default: break;
	}
	return ret;
}
extern int ASN1_BER_Data_Enc_NodeSetXY(ASN1WorkSpace *workspace, NodeSetXY *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_ComputedLane(ASN1WorkSpace *workspace, ComputedLane *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_NodeListXY(ASN1WorkSpace *workspace, NodeListXY *value, ASN1TagType tagFlag)
{
	int ret = 0;
	switch(value->M)
	{
	case DEF_NodeListXY_nodes:
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_NodeSetXY(workspace, &(value->elements.nodes), ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
		break;
	case DEF_NodeListXY_computed:
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_ComputedLane(workspace, value->elements.computed, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
		break;
	}
	return ret;
}
