int ASN1_BER_Data_Dec_NodeListXY(ASN1WorkSpace *workspace, NodeListXY *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	value->M = 0;
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	switch(tag)
	{
	case ITS_ASN_CONT | ITS_ASN_CONS | 0:
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_NodeSetXY(workspace, &value->elements.nodes, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->M = DEF_NodeListXY_nodes;
		break;
	case ITS_ASN_CONT | ITS_ASN_CONS | 1:
		value->elements.computed = (ComputedLane *)mpool_malloc(workspace->Pmemory, sizeof(ComputedLane));
		memset(value->elements.computed, 0, sizeof(ComputedLane));
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_ComputedLane(workspace, value->elements.computed, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->M = DEF_NodeListXY_computed;
		break;
	}
	return ret;
}
