/********************************************************
*ConnectingLane                                         *
********************************************************/
int ASN1_Print_ConnectingLane(ConnectingLane *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("ConnectingLane");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("LaneID", &(value->lane))) < 0) return ret;
	if (value->DEF_ConnectingLane_maneuver == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("AllowedManeuvers", &(value->maneuver))) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_ConnectingLane_lane(ASN1WorkSpace *workspace, ConnectingLane *value, INTEGER user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if ((ret = ASN1_SET_INTEGER(workspace, &value->lane, user_value)) < 0) return ret;
	return ret;
}
int ASN1_SET_ConnectingLane_maneuver(ASN1WorkSpace *workspace, ConnectingLane *value, ASNUINT8 *user_value, ASNUINT32L user_value_length)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->DEF_ConnectingLane_maneuver = 1;
	if ((ret = ASN1_SET_BITSTRING(workspace, &value->maneuver, user_value, user_value_length)) < 0) return ret;
	return ret;
}
int ASN1_GET_ConnectingLane_lane(ASN1WorkSpace *workspace, ConnectingLane *value, INTEGER *user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if ((ret = ASN1_GET_INTEGER(workspace, &value->lane, user_value)) < 0) return ret;
	return ret;
}
int ASN1_GET_ConnectingLane_maneuver(ASN1WorkSpace *workspace, ConnectingLane *value, ASNUINT8 **user_value, ASNUINT32L *user_value_length)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if (value->DEF_ConnectingLane_maneuver == 1)
	{
		if ((ret = ASN1_GET_BITSTRING(workspace, &value->maneuver, user_value, user_value_length)) < 0) return ret;
	}
	else return -2;
	return ret;
}
int ASN1_CHECK_ConnectingLane(ConnectingLane *value)
{
	int ret = 0;

	unsigned char checkinfo_lane[] = { 
		0x02,0x00,0x82,0x00,0xFF,0x00
	};
	unsigned char checkinfo_maneuver[] = { 
		0x02,0x0C,0x0C,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->lane), checkinfo_lane)) < 0) return ret;
	if (value->DEF_ConnectingLane_maneuver == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BITSTRING(&(value->maneuver), checkinfo_maneuver)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_LaneID(ASN1WorkSpace *workspace, LaneID *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_AllowedManeuvers(ASN1WorkSpace *workspace, AllowedManeuvers *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_LaneID(workspace, &(value->lane), ASN1IMPL)) < 0) return ret;
	if (value->DEF_ConnectingLane_maneuver == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_AllowedManeuvers(workspace, &(value->maneuver), ASN1IMPL)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_ConnectingLane(ConnectingLane *value);
extern int ASN1_BER_Data_Enc_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_ConnectingLane(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_ConnectingLane(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_LaneID(ASN1WorkSpace *workspace, LaneID *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_AllowedManeuvers(ASN1WorkSpace *workspace, AllowedManeuvers *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_LaneID(workspace, &value->lane, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 1))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_AllowedManeuvers(workspace, &value->maneuver, len, ASN1IMPL)) < 0) return ret;
		value->DEF_ConnectingLane_maneuver = 1;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_ConnectingLane(ConnectingLane *value);
extern int ASN1_BER_Data_Dec_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_ConnectingLane(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_ConnectingLane(value)) < 0) return ret;
	return ret;
}
int ASN1_PER_Align_Data_Enc_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_lane = { ASN1_CONST64(0), ASN1_CONST64(255), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_maneuver = { ASN1_CONST64(12), ASN1_CONST64(12), NULL, 0, CONS, 0, 0 };

	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_ConnectingLane_maneuver == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->lane), &consinfo_lane)) < 0) return ret;
	if (value->DEF_ConnectingLane_maneuver == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_BITSTRING(workspace, &(value->maneuver), &consinfo_maneuver)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_ConnectingLane(ConnectingLane *value);
extern int ASN1_PER_Align_Data_Enc_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value);
int ASN1_PER_Align_Enc_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value)
{ // ASN1_PER_Extern_Encode 
	int ret = 0;
	if ((ret = ASN1_CHECK_ConnectingLane(value)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Data_Enc_ConnectingLane(workspace,value)) < 0) return ret;
	return ret;
}
int ASN1_PER_Align_Data_Dec_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_lane = { ASN1_CONST64(0), ASN1_CONST64(255), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_maneuver = { ASN1_CONST64(12), ASN1_CONST64(12), NULL, 0, CONS, 0, 0 };

	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 1, &_optvalue)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->lane), &consinfo_lane)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_ConnectingLane_maneuver = 1;
		if ((ret = ASN1_PER_Align_Dec_BITSTRING(workspace, &(value->maneuver), &consinfo_maneuver)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_ConnectingLane(ConnectingLane *value);
extern int ASN1_PER_Align_Data_Dec_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value);
int ASN1_PER_Align_Dec_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value)
{
	int ret = 0;
	if ((ret = ASN1_PER_Align_Data_Dec_ConnectingLane(workspace,value)) < 0) return ret;
	if ((ret = ASN1_CHECK_ConnectingLane(value)) < 0) return ret;
	return ret;
}
int ASN1_PER_UNAlign_Data_Enc_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_lane = { ASN1_CONST64(0), ASN1_CONST64(255), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_maneuver = { ASN1_CONST64(12), ASN1_CONST64(12), NULL, 0, CONS, 0, 0 };

	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_ConnectingLane_maneuver == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Enc_INTEGER(workspace, &(value->lane), &consinfo_lane)) < 0) return ret;
	if (value->DEF_ConnectingLane_maneuver == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_BITSTRING(workspace, &(value->maneuver), &consinfo_maneuver)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_ConnectingLane(ConnectingLane *value);
extern int ASN1_PER_UNAlign_Data_Enc_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value);
int ASN1_PER_UNAlign_Enc_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value)
{ // ASN1_PER_Extern_Encode 
	int ret = 0;
	if ((ret = ASN1_CHECK_ConnectingLane(value)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Data_Enc_ConnectingLane(workspace,value)) < 0) return ret;
	return ret;
}
int ASN1_PER_UNAlign_Data_Dec_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_lane = { ASN1_CONST64(0), ASN1_CONST64(255), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_maneuver = { ASN1_CONST64(12), ASN1_CONST64(12), NULL, 0, CONS, 0, 0 };

	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 1, &_optvalue)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->lane), &consinfo_lane)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_ConnectingLane_maneuver = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_BITSTRING(workspace, &(value->maneuver), &consinfo_maneuver)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_ConnectingLane(ConnectingLane *value);
extern int ASN1_PER_UNAlign_Data_Dec_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value);
int ASN1_PER_UNAlign_Dec_ConnectingLane(ASN1WorkSpace *workspace, ConnectingLane *value)
{
	int ret = 0;
	if ((ret = ASN1_PER_UNAlign_Data_Dec_ConnectingLane(workspace,value)) < 0) return ret;
	if ((ret = ASN1_CHECK_ConnectingLane(value)) < 0) return ret;
	return ret;
}

