int ASN1_Print_Connection(Connection *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("Connection");
	// Type Reference ConnectingLane
	if (Compare_Letter(tab_value, "connectingLane")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("connectingLane = ");
	}
	if ((ret = ASN1_Print_ConnectingLane((ConnectingLane *)value->connectingLane, tab_value + 1)) < 0) return ret;
	if (value->DEF_Connection_remoteIntersection == 1)
	{ /*OPTIONAL start */
		// Type Reference IntersectionReferenceID
		if (Compare_Letter(tab_value, "remoteIntersection")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("remoteIntersection = ");
		}
		if ((ret = ASN1_Print_IntersectionReferenceID((IntersectionReferenceID *)value->remoteIntersection, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_Connection_signalGroup == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("SignalGroupID", &(value->signalGroup))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_Connection_userClass == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("RestrictionClassID", &(value->userClass))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_Connection_connectionID == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("LaneConnectionID", &(value->connectionID))) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
