/********************************************************
*ConnectsToList                                         *
********************************************************/
int ASN1_Print_ConnectsToList(ConnectsToList *value, int tab_value)
{
	int ret = 0;
	int count;
	ASN1ListNode *pnode;
	if (value == NULL) return -1;
	count = value->count;
	pnode = value->head->next;
	// SEQUENCE OF : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ_OF("ConnectsToList");
	while(count) {
		// Type Reference Connection
		ASN_Print_TAB(tab_value + 1);
		if ((ret = ASN1_Print_Connection((Connection *)pnode->data, tab_value + 1)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}

	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
extern int ASN1_CHECK_Connection(Connection *value);
int ASN1_CHECK_ConnectsToList(ConnectsToList *value)
{
	int ret = 0;

	unsigned char checkinfo_ConnectsToList[] = { 
		0x02,0x01,0x10,0x00
	};
	unsigned char checkinfo_ConnectsToList_pdata[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	int count;
	ASN1ListNode* pnode;
	if (value == NULL) return -1;
	if (value->head == NULL) return -1;
	if (value->count < 0) return -1;
	pnode = value->head->next;
	count = value->count;
	while (count) {
		if ((ret = ASN1_CHECK_Connection(pnode->data)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}
	return ret;
}
extern int ASN1_BER_Data_Enc_Connection(ASN1WorkSpace *workspace, Connection *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_ConnectsToList(ASN1WorkSpace *workspace, ConnectsToList *value, ASN1TagType tagFlag)
{
	int ret = 0;
	ASN1ListNode *pnode;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	pnode = value->head->next;
	while (NULL != pnode)
	{
		if ((ret = ASN1_BER_Data_Enc_Connection(workspace, pnode->data, ASN1EXPL)) < 0) return ret;
		pnode = pnode->next;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_ConnectsToList(ConnectsToList *value);
extern int ASN1_BER_Data_Enc_ConnectsToList(ASN1WorkSpace *workspace, ConnectsToList *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_ConnectsToList(ASN1WorkSpace *workspace, ConnectsToList *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_ConnectsToList(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_ConnectsToList(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_Connection(ASN1WorkSpace *workspace, Connection *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_ConnectsToList(ASN1WorkSpace *workspace, ConnectsToList *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	Connection *pdata;
	ASNUINT8 *p = workspace->buffer.current;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	if ((ret = ASN1_Creat_Init_List(workspace, value)) < 0) return ret;
	while (ASN1_BER_Dec_Isloop(workspace, p, length))
	{
		pdata = (Connection *)mpool_malloc(GetMemPool(workspace), sizeof(Connection));
		memset(pdata, 0, sizeof(Connection));
		if ((ret = ASN1_BER_Data_Dec_Connection(workspace, pdata, len, ASN1EXPL)) < 0) return ret;
		if ((ret = ASN1_Insert_Node(workspace, value,(void*)pdata)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_ConnectsToList(ConnectsToList *value);
extern int ASN1_BER_Data_Dec_ConnectsToList(ASN1WorkSpace *workspace, ConnectsToList *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_ConnectsToList(ASN1WorkSpace *workspace, ConnectsToList *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_ConnectsToList(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_ConnectsToList(value)) < 0) return ret;
	return ret;
}
