int ASN1_Print_GenericLane(GenericLane *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("GenericLane");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("LaneID", &(value->laneID))) < 0) return ret;
	if (value->DEF_GenericLane_name == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_IA5String("DescriptiveName", &(value->name))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_GenericLane_ingressApproach == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("ApproachID", &(value->ingressApproach))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_GenericLane_egressApproach == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("ApproachID", &(value->egressApproach))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Reference LaneAttributes
	if (Compare_Letter(tab_value, "laneAttributes")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("laneAttributes = ");
	}
	if ((ret = ASN1_Print_LaneAttributes((LaneAttributes *)value->laneAttributes, tab_value + 1)) < 0) return ret;
	if (value->DEF_GenericLane_maneuvers == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("AllowedManeuvers", &(value->maneuvers))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Reference NodeListXY
	if (Compare_Letter(tab_value, "nodeList")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("nodeList = ");
	}
	if ((ret = ASN1_Print_NodeListXY((NodeListXY *)value->nodeList, tab_value + 1)) < 0) return ret;
	if (value->DEF_GenericLane_connectsTo == 1)
	{ /*OPTIONAL start */
		// Type Reference ConnectsToList
		if (Compare_Letter(tab_value, "connectsTo")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("connectsTo = ");
		}
		if ((ret = ASN1_Print_ConnectsToList((ConnectsToList *)&(value->connectsTo), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_GenericLane_overlays == 1)
	{ /*OPTIONAL start */
		// Type Reference OverlayLaneList
		if (Compare_Letter(tab_value, "overlays")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("overlays = ");
		}
		if ((ret = ASN1_Print_OverlayLaneList((OverlayLaneList *)&(value->overlays), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_GenericLane_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference GenericLane_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_GenericLane_regional((GenericLane_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
