extern int ASN1_PER_UNAlign_Data_Dec_LaneAttributes(ASN1WorkSpace *workspace, LaneAttributes *value);
extern int ASN1_PER_UNAlign_Data_Dec_NodeListXY(ASN1WorkSpace *workspace, NodeListXY *value);
extern int ASN1_PER_UNAlign_Data_Dec_ConnectsToList(ASN1WorkSpace *workspace, ConnectsToList *value);
extern int ASN1_PER_UNAlign_Data_Dec_OverlayLaneList(ASN1WorkSpace *workspace, OverlayLaneList *value);
extern int ASN1_PER_UNAlign_Data_Dec_GenericLane_regional(ASN1WorkSpace *workspace, GenericLane_regional *value);
int ASN1_PER_UNAlign_Data_Dec_GenericLane(ASN1WorkSpace *workspace, GenericLane *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_laneID = { ASN1_CONST64(0), ASN1_CONST64(255), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_name = { ASN1_CONST64(1), ASN1_CONST64(63), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_ingressApproach = { ASN1_CONST64(0), ASN1_CONST64(15), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_egressApproach = { ASN1_CONST64(0), ASN1_CONST64(15), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_laneAttributes = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_maneuvers = { ASN1_CONST64(12), ASN1_CONST64(12), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_nodeList = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_connectsTo = { ASN1_CONST64(1), ASN1_CONST64(16), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_overlays = { ASN1_CONST64(1), ASN1_CONST64(5), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNBOOL extbit_GenericLane;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_GenericLane)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 7, &_optvalue)) < 0) return ret;
	value->laneAttributes = (LaneAttributes *)mpool_malloc(workspace->Pmemory, sizeof(LaneAttributes));
	memset(value->laneAttributes, 0, sizeof(LaneAttributes));
	value->nodeList = (NodeListXY *)mpool_malloc(workspace->Pmemory, sizeof(NodeListXY));
	memset(value->nodeList, 0, sizeof(NodeListXY));
	if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->laneID), &consinfo_laneID)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_GenericLane_name = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_IA5String(workspace, &(value->name), &consinfo_name)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_GenericLane_ingressApproach = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->ingressApproach), &consinfo_ingressApproach)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 3) == 1)
	{
		value->DEF_GenericLane_egressApproach = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->egressApproach), &consinfo_egressApproach)) < 0) return ret;
	}
	if ((ret = ASN1_PER_UNAlign_Dec_LaneAttributes(workspace, value->laneAttributes)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 4) == 1)
	{
		value->DEF_GenericLane_maneuvers = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_BITSTRING(workspace, &(value->maneuvers), &consinfo_maneuvers)) < 0) return ret;
	}
	if ((ret = ASN1_PER_UNAlign_Dec_NodeListXY(workspace, value->nodeList)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 5) == 1)
	{
		value->DEF_GenericLane_connectsTo = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_ConnectsToList(workspace, &(value->connectsTo))) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 6) == 1)
	{
		value->DEF_GenericLane_overlays = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_OverlayLaneList(workspace, &(value->overlays))) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 7) == 1)
	{
		value->DEF_GenericLane_regional = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_GenericLane_regional(workspace, &(value->regional))) < 0) return ret;
	}
	if (extbit_GenericLane == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, UNALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, UNALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
