int ASN1_Print_IntersectionGeometry(IntersectionGeometry *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("IntersectionGeometry");
	if (value->DEF_IntersectionGeometry_name == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_IA5String("DescriptiveName", &(value->name))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Reference IntersectionReferenceID
	if (Compare_Letter(tab_value, "id")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("id = ");
	}
	if ((ret = ASN1_Print_IntersectionReferenceID((IntersectionReferenceID *)value->id, tab_value + 1)) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("MsgCount", &(value->revision))) < 0) return ret;
	// Type Reference Position3D
	if (Compare_Letter(tab_value, "refPoint")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("refPoint = ");
	}
	if ((ret = ASN1_Print_Position3D((Position3D *)value->refPoint, tab_value + 1)) < 0) return ret;
	if (value->DEF_IntersectionGeometry_laneWidth == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("LaneWidth", &(value->laneWidth))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_IntersectionGeometry_speedLimits == 1)
	{ /*OPTIONAL start */
		// Type Reference SpeedLimitList
		if (Compare_Letter(tab_value, "speedLimits")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("speedLimits = ");
		}
		if ((ret = ASN1_Print_SpeedLimitList((SpeedLimitList *)&(value->speedLimits), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	// Type Reference LaneList
	if (Compare_Letter(tab_value, "laneSet")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("laneSet = ");
	}
	if ((ret = ASN1_Print_LaneList((LaneList *)&(value->laneSet), tab_value + 1)) < 0) return ret;
	if (value->DEF_IntersectionGeometry_preemptPriorityData == 1)
	{ /*OPTIONAL start */
		// Type Reference PreemptPriorityList
		if (Compare_Letter(tab_value, "preemptPriorityData")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("preemptPriorityData = ");
		}
		if ((ret = ASN1_Print_PreemptPriorityList((PreemptPriorityList *)&(value->preemptPriorityData), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_IntersectionGeometry_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference IntersectionGeometry_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_IntersectionGeometry_regional((IntersectionGeometry_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
