int ASN1_PER_UNAlign_Data_Dec_IntersectionGeometry(ASN1WorkSpace *workspace, IntersectionGeometry *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_name = { ASN1_CONST64(1), ASN1_CONST64(63), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_id = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_revision = { ASN1_CONST64(0), ASN1_CONST64(127), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_refPoint = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_laneWidth = { ASN1_CONST64(0), ASN1_CONST64(32767), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_speedLimits = { ASN1_CONST64(1), ASN1_CONST64(9), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_laneSet = { ASN1_CONST64(1), ASN1_CONST64(255), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_preemptPriorityData = { ASN1_CONST64(1), ASN1_CONST64(32), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNBOOL extbit_IntersectionGeometry;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_IntersectionGeometry)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 5, &_optvalue)) < 0) return ret;
	value->id = (IntersectionReferenceID *)mpool_malloc(workspace->Pmemory, sizeof(IntersectionReferenceID));
	memset(value->id, 0, sizeof(IntersectionReferenceID));
	value->refPoint = (Position3D *)mpool_malloc(workspace->Pmemory, sizeof(Position3D));
	memset(value->refPoint, 0, sizeof(Position3D));
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_IntersectionGeometry_name = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_IA5String(workspace, &(value->name), &consinfo_name)) < 0) return ret;
	}
	if ((ret = ASN1_PER_UNAlign_Dec_IntersectionReferenceID(workspace, value->id)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->revision), &consinfo_revision)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Dec_Position3D(workspace, value->refPoint)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_IntersectionGeometry_laneWidth = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->laneWidth), &consinfo_laneWidth)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 3) == 1)
	{
		value->DEF_IntersectionGeometry_speedLimits = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_SpeedLimitList(workspace, &(value->speedLimits))) < 0) return ret;
	}
	if ((ret = ASN1_PER_UNAlign_Dec_LaneList(workspace, &(value->laneSet))) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 4) == 1)
	{
		value->DEF_IntersectionGeometry_preemptPriorityData = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_PreemptPriorityList(workspace, &(value->preemptPriorityData))) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 5) == 1)
	{
		value->DEF_IntersectionGeometry_regional = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_IntersectionGeometry_regional(workspace, &(value->regional))) < 0) return ret;
	}
	if (extbit_IntersectionGeometry == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, UNALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, UNALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
