extern int ASN1_BER_Data_Dec_IntersectionGeometry(ASN1WorkSpace *workspace, IntersectionGeometry *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_IntersectionGeometryList(ASN1WorkSpace *workspace, IntersectionGeometryList *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	IntersectionGeometry *pdata;
	ASNUINT8 *p = workspace->buffer.current;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	if ((ret = ASN1_Creat_Init_List(workspace, value)) < 0) return ret;
	while (ASN1_BER_Dec_Isloop(workspace, p, length))
	{
		pdata = (IntersectionGeometry *)mpool_malloc(GetMemPool(workspace), sizeof(IntersectionGeometry));
		memset(pdata, 0, sizeof(IntersectionGeometry));
		if ((ret = ASN1_BER_Data_Dec_IntersectionGeometry(workspace, pdata, len, ASN1EXPL)) < 0) return ret;
		if ((ret = ASN1_Insert_Node(workspace, value,(void*)pdata)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
