{
	int ret = 0;
	if (value == NULL) return -1;
	if ((ret = ASN1_SET_INTEGER(workspace, &value->id, user_value)) < 0) return ret;
	return ret;
}
int ASN1_GET_RoadSegmentReferenceID_region(ASN1WorkSpace *workspace, RoadSegmentReferenceID *value, INTEGER *user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if (value->DEF_RoadSegmentReferenceID_region == 1)
	{
		if ((ret = ASN1_GET_INTEGER(workspace, &value->region, user_value)) < 0) return ret;
	}
	else return -2;
	return ret;
}
