int ASN1_Print_RoadLaneSetList(RoadLaneSetList *value, int tab_value)
{
	int ret = 0;
	int count;
	ASN1ListNode *pnode;
	if (value == NULL) return -1;
	count = value->count;
	pnode = value->head->next;
	// SEQUENCE OF : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ_OF("RoadLaneSetList");
	while(count) {
		// Type Reference GenericLane
		ASN_Print_TAB(tab_value + 1);
		if ((ret = ASN1_Print_GenericLane((GenericLane *)pnode->data, tab_value + 1)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}

	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
extern int ASN1_CHECK_GenericLane(GenericLane *value);
int ASN1_CHECK_RoadLaneSetList(RoadLaneSetList *value)
{
	int ret = 0;

	unsigned char checkinfo_RoadLaneSetList[] = { 
		0x02,0x01,0x82,0x00,0xFF,0x00
	};
	unsigned char checkinfo_RoadLaneSetList_pdata[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	int count;
	ASN1ListNode* pnode;
	if (value == NULL) return -1;
	if (value->head == NULL) return -1;
	if (value->count < 0) return -1;
	pnode = value->head->next;
	count = value->count;
	while (count) {
		if ((ret = ASN1_CHECK_GenericLane(pnode->data)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}
	return ret;
}
