int ASN1_PER_Align_Data_Enc_RoadSegment_regional(ASN1WorkSpace *workspace, RoadSegment_regional *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_RoadSegment_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_RoadSegment_regional_pdata = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	ASNINT32 loop_set = 1;
	ASNINT32 all_length = value->count;
	ASNINT32 process_length = 0;
	ASNINT32 i = 0;
	ASN1ListNode *pnode = value->head->next;
	while(loop_set)
	{
		loop_set = ASN1_PER_Align_Enc_Set_Seq_Of_Length(workspace, &all_length, &process_length, &consinfo_RoadSegment_regional);
		for(i = 0; i < process_length; i++)
		{
			if ((ret = ASN1_PER_Align_Enc_RegionalExtension(workspace, pnode->data)) < 0) return ret;
			pnode = pnode->next;
		}
	}
	if (value->count != 0 && value->count % 16384 == 0)
	{
		if ((ret = ASN1_PER_Align_WirteBuffer(workspace)) < 0) return ret;
	}
	return ret;
}
