/********************************************************
*RoadSegment                                            *
********************************************************/
int ASN1_Print_RoadSegment(RoadSegment *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("RoadSegment");
	if (value->DEF_RoadSegment_name == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_IA5String("DescriptiveName", &(value->name))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Reference RoadSegmentReferenceID
	if (Compare_Letter(tab_value, "id")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("id = ");
	}
	if ((ret = ASN1_Print_RoadSegmentReferenceID((RoadSegmentReferenceID *)value->id, tab_value + 1)) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("MsgCount", &(value->revision))) < 0) return ret;
	// Type Reference Position3D
	if (Compare_Letter(tab_value, "refPoint")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("refPoint = ");
	}
	if ((ret = ASN1_Print_Position3D((Position3D *)value->refPoint, tab_value + 1)) < 0) return ret;
	if (value->DEF_RoadSegment_laneWidth == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("LaneWidth", &(value->laneWidth))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSegment_speedLimits == 1)
	{ /*OPTIONAL start */
		// Type Reference SpeedLimitList
		if (Compare_Letter(tab_value, "speedLimits")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("speedLimits = ");
		}
		if ((ret = ASN1_Print_SpeedLimitList((SpeedLimitList *)&(value->speedLimits), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	// Type Reference RoadLaneSetList
	if (Compare_Letter(tab_value, "roadLaneSet")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("roadLaneSet = ");
	}
	if ((ret = ASN1_Print_RoadLaneSetList((RoadLaneSetList *)&(value->roadLaneSet), tab_value + 1)) < 0) return ret;
	if (value->DEF_RoadSegment_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference RoadSegment_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_RoadSegment_regional((RoadSegment_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
