/********************************************************
*RestrictionUserType                                    *
********************************************************/
int ASN1_Print_RestrictionUserType(RestrictionUserType *value, int tab_value)
{
	int ret = 0;
	// CHOICE : t->tempIdentifier is Upper Letter
	ASN1_Print_CHOICE("RestrictionUserType");
	if (value == NULL) return -1;
	switch (value->M) {
	case DEF_RestrictionUserType_basicType:
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->elements.basicType)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("RestrictionAppliesTo", "none", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("RestrictionAppliesTo", "equippedTransit", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("RestrictionAppliesTo", "equippedTaxis", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("RestrictionAppliesTo", "equippedOther", 3)) < 0) return ret; break;
		case 4: if ((ret = ASN1_Print_ENUMERATED("RestrictionAppliesTo", "emissionCompliant", 4)) < 0) return ret; break;
		case 5: if ((ret = ASN1_Print_ENUMERATED("RestrictionAppliesTo", "equippedBicycle", 5)) < 0) return ret; break;
		case 6: if ((ret = ASN1_Print_ENUMERATED("RestrictionAppliesTo", "weightCompliant", 6)) < 0) return ret; break;
		case 7: if ((ret = ASN1_Print_ENUMERATED("RestrictionAppliesTo", "heightCompliant", 7)) < 0) return ret; break;
		case 8: if ((ret = ASN1_Print_ENUMERATED("RestrictionAppliesTo", "pedestrians", 8)) < 0) return ret; break;
		case 9: if ((ret = ASN1_Print_ENUMERATED("RestrictionAppliesTo", "slowMovingPersons", 9)) < 0) return ret; break;
		case 10: if ((ret = ASN1_Print_ENUMERATED("RestrictionAppliesTo", "wheelchairUsers", 10)) < 0) return ret; break;
		case 11: if ((ret = ASN1_Print_ENUMERATED("RestrictionAppliesTo", "visualDisabilities", 11)) < 0) return ret; break;
		case 12: if ((ret = ASN1_Print_ENUMERATED("RestrictionAppliesTo", "audioDisabilities", 12)) < 0) return ret; break;
		case 13: if ((ret = ASN1_Print_ENUMERATED("RestrictionAppliesTo", "otherUnknownDisabilities", 13)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
		if (ret != 0) return -1;
		break;
	case DEF_RestrictionUserType_regional:
		// Type Reference RestrictionUserType_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_RestrictionUserType_regional((RestrictionUserType_regional *)&value->elements.regional, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	default: return -1;
}
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_RestrictionUserType_basicType(ASN1WorkSpace *workspace, RestrictionUserType *value, ENUMERATED user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	value->M = DEF_RestrictionUserType_basicType;
	if ((ret = ASN1_SET_ENUMERATED(workspace, (ASNINT32*)&value->elements.basicType, user_value)) < 0) return ret;
	return ret;
}
int ASN1_SET_RestrictionUserType_regional(ASN1WorkSpace *workspace, RestrictionUserType *value, RestrictionUserType_regional *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->M = DEF_RestrictionUserType_regional;
	memmove(&value->elements.regional, user_value, sizeof(RestrictionUserType_regional));
	return ret;
}
int ASN1_GET_RestrictionUserType_basicType(ASN1WorkSpace *workspace, RestrictionUserType *value, ENUMERATED *user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if (value->M == DEF_RestrictionUserType_basicType)
	{
		if ((ret = ASN1_GET_ENUMERATED(workspace, (ASNINT32*)&value->elements.basicType, user_value)) < 0) return ret;
	}
	else return -2;
	return ret;
}
int ASN1_GET_RestrictionUserType_regional(ASN1WorkSpace *workspace, RestrictionUserType *value, RestrictionUserType_regional **user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if (value->M == DEF_RestrictionUserType_regional)
	{
		*user_value = &value->elements.regional;
	}
	else return -2;
	return ret;
}
extern int ASN1_CHECK_RestrictionUserType_regional(RestrictionUserType_regional *value);
int ASN1_CHECK_RestrictionUserType(RestrictionUserType *value)
{
	int ret = 0;

	unsigned char checkinfo_basicType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	switch (value->M)
	{
	case DEF_RestrictionUserType_basicType:
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&value->elements.basicType, checkinfo_basicType)) < 0) return ret;
		break;
	case DEF_RestrictionUserType_regional:
		if ((ret = ASN1_CHECK_RestrictionUserType_regional(&value->elements.regional)) < 0) return ret;
		break;
	default: break;
	}
	return ret;
}
