int ASN1_BER_Data_Enc_RestrictionUserType(ASN1WorkSpace *workspace, RestrictionUserType *value, ASN1TagType tagFlag)
{
	int ret = 0;
	switch(value->M)
	{
	case DEF_RestrictionUserType_basicType:
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_RestrictionAppliesTo(workspace, &(value->elements.basicType), ASN1IMPL)) < 0) return ret;
		break;
	case DEF_RestrictionUserType_regional:
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_RestrictionUserType_regional(workspace, &(value->elements.regional), ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
		break;
	}
	return ret;
}
