extern int ASN1_BER_Data_Dec_RestrictionAppliesTo(ASN1WorkSpace *workspace, RestrictionAppliesTo *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_RestrictionUserType_regional(ASN1WorkSpace *workspace, RestrictionUserType_regional *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_RestrictionUserType(ASN1WorkSpace *workspace, RestrictionUserType *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	value->M = 0;
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	switch(tag)
	{
	case ITS_ASN_CONT | ITS_ASN_PRIM | 0:
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_RestrictionAppliesTo(workspace, &value->elements.basicType, len, ASN1IMPL)) < 0) return ret;
		value->M = DEF_RestrictionUserType_basicType;
		break;
	case ITS_ASN_UNIV | ITS_ASN_CONS | 16:
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_RestrictionUserType_regional(workspace, &value->elements.regional, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->M = DEF_RestrictionUserType_regional;
		break;
	}
	return ret;
}
