/********************************************************
*RestrictionUserTypeList                                *
********************************************************/
int ASN1_Print_RestrictionUserTypeList(RestrictionUserTypeList *value, int tab_value)
{
	int ret = 0;
	int count;
	ASN1ListNode *pnode;
	if (value == NULL) return -1;
	count = value->count;
	pnode = value->head->next;
	// SEQUENCE OF : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ_OF("RestrictionUserTypeList");
	while(count) {
		// Type Reference RestrictionUserType
		ASN_Print_TAB(tab_value + 1);
		if ((ret = ASN1_Print_RestrictionUserType((RestrictionUserType *)pnode->data, tab_value + 1)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}

	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
extern int ASN1_CHECK_RestrictionUserType(RestrictionUserType *value);
int ASN1_CHECK_RestrictionUserTypeList(RestrictionUserTypeList *value)
{
	int ret = 0;

	unsigned char checkinfo_RestrictionUserTypeList[] = { 
		0x02,0x01,0x10,0x00
	};
	unsigned char checkinfo_RestrictionUserTypeList_pdata[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	int count;
	ASN1ListNode* pnode;
	if (value == NULL) return -1;
	if (value->head == NULL) return -1;
	if (value->count < 0) return -1;
	pnode = value->head->next;
	count = value->count;
	while (count) {
		if ((ret = ASN1_CHECK_RestrictionUserType(pnode->data)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}
	return ret;
}
