/********************************************************
*MapData                                                *
********************************************************/
int ASN1_Print_MapData(MapData *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("MapData");
	if (value->DEF_MapData_timeStamp == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("MinuteOfTheYear", &(value->timeStamp))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("MsgCount", &(value->msgIssueRevision))) < 0) return ret;
	if (value->DEF_MapData_layerType == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->layerType)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("LayerType", "none", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("LayerType", "mixedContent", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("LayerType", "generalMapData", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("LayerType", "intersectionData", 3)) < 0) return ret; break;
		case 4: if ((ret = ASN1_Print_ENUMERATED("LayerType", "curveData", 4)) < 0) return ret; break;
		case 5: if ((ret = ASN1_Print_ENUMERATED("LayerType", "roadwaySectionData", 5)) < 0) return ret; break;
		case 6: if ((ret = ASN1_Print_ENUMERATED("LayerType", "parkingAreaData", 6)) < 0) return ret; break;
		case 7: if ((ret = ASN1_Print_ENUMERATED("LayerType", "sharedLaneData", 7)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	if (value->DEF_MapData_layerID == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("LayerID", &(value->layerID))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MapData_intersections == 1)
	{ /*OPTIONAL start */
		// Type Reference IntersectionGeometryList
		if (Compare_Letter(tab_value, "intersections")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("intersections = ");
		}
		if ((ret = ASN1_Print_IntersectionGeometryList((IntersectionGeometryList *)&(value->intersections), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MapData_roadSegments == 1)
	{ /*OPTIONAL start */
		// Type Reference RoadSegmentList
		if (Compare_Letter(tab_value, "roadSegments")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("roadSegments = ");
		}
		if ((ret = ASN1_Print_RoadSegmentList((RoadSegmentList *)&(value->roadSegments), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MapData_dataParameters == 1)
	{ /*OPTIONAL start */
		// Type Reference DataParameters
		if (Compare_Letter(tab_value, "dataParameters")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("dataParameters = ");
		}
		if ((ret = ASN1_Print_DataParameters((DataParameters *)value->dataParameters, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MapData_restrictionList == 1)
	{ /*OPTIONAL start */
		// Type Reference RestrictionClassList
		if (Compare_Letter(tab_value, "restrictionList")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("restrictionList = ");
		}
		if ((ret = ASN1_Print_RestrictionClassList((RestrictionClassList *)&(value->restrictionList), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MapData_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference MapData_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_MapData_regional((MapData_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
