extern int ASN1_CHECK_IntersectionGeometryList(IntersectionGeometryList *value);
extern int ASN1_CHECK_RoadSegmentList(RoadSegmentList *value);
extern int ASN1_CHECK_DataParameters(DataParameters *value);
extern int ASN1_CHECK_RestrictionClassList(RestrictionClassList *value);
extern int ASN1_CHECK_MapData_regional(MapData_regional *value);
int ASN1_CHECK_MapData(MapData *value)
{
	int ret = 0;

	unsigned char checkinfo_timeStamp[] = { 
		0x02,0x00,0x83,0x08,0x0A,0xC0,0x00
	};
	unsigned char checkinfo_msgIssueRevision[] = { 
		0x02,0x00,0x7F,0x00
	};
	unsigned char checkinfo_layerType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_layerID[] = { 
		0x02,0x00,0x64,0x00
	};
	unsigned char checkinfo_intersections[] = { 
		0x02,0x01,0x20,0x00
	};
	unsigned char checkinfo_roadSegments[] = { 
		0x02,0x01,0x20,0x00
	};
	unsigned char checkinfo_dataParameters[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_restrictionList[] = { 
		0x02,0x01,0x82,0x00,0xFE,0x00
	};
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_MapData_timeStamp == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->timeStamp), checkinfo_timeStamp)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_INTEGER(&(value->msgIssueRevision), checkinfo_msgIssueRevision)) < 0) return ret;
	if (value->DEF_MapData_layerType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->layerType), checkinfo_layerType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MapData_layerID == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->layerID), checkinfo_layerID)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MapData_intersections == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_IntersectionGeometryList(&(value->intersections))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MapData_roadSegments == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_RoadSegmentList(&(value->roadSegments))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MapData_dataParameters == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_DataParameters(value->dataParameters)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MapData_restrictionList == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_RestrictionClassList(&(value->restrictionList))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MapData_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_MapData_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_MinuteOfTheYear(ASN1WorkSpace *workspace, MinuteOfTheYear *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_MsgCount(ASN1WorkSpace *workspace, MsgCount *value, ASN1TagType tagFlag);
