int ASN1_Print_DDateTime(DDateTime *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("DDateTime");
	if (value->DEF_DDateTime_year == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DYear", &(value->year))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DDateTime_month == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DMonth", &(value->month))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DDateTime_day == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DDay", &(value->day))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DDateTime_hour == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DHour", &(value->hour))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DDateTime_minute == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DMinute", &(value->minute))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DDateTime_second == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DSecond", &(value->second))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DDateTime_offset == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DOffset", &(value->offset))) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
