int ASN1_PER_UNAlign_Data_Dec_DDateTime(ASN1WorkSpace *workspace, DDateTime *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_year = { ASN1_CONST64(0), ASN1_CONST64(4095), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_month = { ASN1_CONST64(0), ASN1_CONST64(12), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_day = { ASN1_CONST64(0), ASN1_CONST64(31), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_hour = { ASN1_CONST64(0), ASN1_CONST64(31), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_minute = { ASN1_CONST64(0), ASN1_CONST64(60), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_second = { ASN1_CONST64(0), ASN1_CONST64(65535), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_offset = { ASN1_CONST64(-840), ASN1_CONST64(840), NULL, 0, CONS, 0, 0 };

	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 7, &_optvalue)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_DDateTime_year = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->year), &consinfo_year)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_DDateTime_month = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->month), &consinfo_month)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 3) == 1)
	{
		value->DEF_DDateTime_day = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->day), &consinfo_day)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 4) == 1)
	{
		value->DEF_DDateTime_hour = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->hour), &consinfo_hour)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 5) == 1)
	{
		value->DEF_DDateTime_minute = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->minute), &consinfo_minute)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 6) == 1)
	{
		value->DEF_DDateTime_second = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->second), &consinfo_second)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 7) == 1)
	{
		value->DEF_DDateTime_offset = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->offset), &consinfo_offset)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_DDateTime(DDateTime *value);
extern int ASN1_PER_UNAlign_Data_Dec_DDateTime(ASN1WorkSpace *workspace, DDateTime *value);
int ASN1_PER_UNAlign_Dec_DDateTime(ASN1WorkSpace *workspace, DDateTime *value)
{
	int ret = 0;
	if ((ret = ASN1_PER_UNAlign_Data_Dec_DDateTime(workspace,value)) < 0) return ret;
	if ((ret = ASN1_CHECK_DDateTime(value)) < 0) return ret;
	return ret;
}

/********************************************************
*TrafficLightStatus                                     *
********************************************************/
int ASN1_Print_TrafficLightStatus(TrafficLightStatus *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("TrafficLightStatus");
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->trafficLightType)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("TrafficLightType", "reserved", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("TrafficLightType", "straight", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("TrafficLightType", "left-turn", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("TrafficLightType", "pedestrian", 3)) < 0) return ret; break;
	case 4: if ((ret = ASN1_Print_ENUMERATED("TrafficLightType", "bicycle", 4)) < 0) return ret; break;
	case 5: if ((ret = ASN1_Print_ENUMERATED("TrafficLightType", "right-turn", 5)) < 0) return ret; break;
	case 6: if ((ret = ASN1_Print_ENUMERATED("TrafficLightType", "bus", 6)) < 0) return ret; break;
	case 7: if ((ret = ASN1_Print_ENUMERATED("TrafficLightType", "u-turn", 7)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->consecutiveTrafficLight)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("ConsecutiveTrafficLight", "none", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("ConsecutiveTrafficLight", "first", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("ConsecutiveTrafficLight", "second", 2)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->trafficLightIntervalType)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("TrafficLightIntervalType", "static", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("TrafficLightIntervalType", "variable", 1)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BOOLEAN("PedestrianCall", &(value->pedestrianCall))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BOOLEAN("ActuatedInterval", &(value->actuatedinterval))) < 0) return ret;
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->permissiveNonProtected)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("PermissiveNonProtected", "none", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("PermissiveNonProtected", "permissive", 1)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->lightingStatus)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("TrafficLightingStatus", "off", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("TrafficLightingStatus", "red-on", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("TrafficLightingStatus", "yellow-on", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("TrafficLightingStatus", "green-on", 3)) < 0) return ret; break;
	case 4: if ((ret = ASN1_Print_ENUMERATED("TrafficLightingStatus", "red-blinking", 4)) < 0) return ret; break;
	case 5: if ((ret = ASN1_Print_ENUMERATED("TrafficLightingStatus", "yellow-blinking", 5)) < 0) return ret; break;
	case 6: if ((ret = ASN1_Print_ENUMERATED("TrafficLightingStatus", "green-blinking", 6)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("TimeInSecond_B8", &(value->maxIntervalLength))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("TimeInSecond_B8", &(value->remainingTime))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("TrafficLightDirectionCode", &(value->directionCode))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BOOLEAN("ReservedBit", &(value->reserved))) < 0) return ret;
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
