int ASN1_CHECK_TrafficLightStatus(TrafficLightStatus *value)
{
	int ret = 0;

	unsigned char checkinfo_trafficLightType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_consecutiveTrafficLight[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_trafficLightIntervalType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_pedestrianCall[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_actuatedinterval[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_permissiveNonProtected[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_lightingStatus[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_maxIntervalLength[] = { 
		0x02,0x00,0x82,0x00,0xFF,0x00
	};
	unsigned char checkinfo_remainingTime[] = { 
		0x02,0x00,0x82,0x00,0xFF,0x00
	};
	unsigned char checkinfo_directionCode[] = { 
		0x02,0x00,0x82,0x01,0x67,0x00
	};
	unsigned char checkinfo_reserved[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->trafficLightType), checkinfo_trafficLightType)) < 0) return ret;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->consecutiveTrafficLight), checkinfo_consecutiveTrafficLight)) < 0) return ret;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->trafficLightIntervalType), checkinfo_trafficLightIntervalType)) < 0) return ret;
	if ((ret = ASN1_CHECK_BOOLEAN(&(value->pedestrianCall), checkinfo_pedestrianCall)) < 0) return ret;
	if ((ret = ASN1_CHECK_BOOLEAN(&(value->actuatedinterval), checkinfo_actuatedinterval)) < 0) return ret;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->permissiveNonProtected), checkinfo_permissiveNonProtected)) < 0) return ret;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->lightingStatus), checkinfo_lightingStatus)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->maxIntervalLength), checkinfo_maxIntervalLength)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->remainingTime), checkinfo_remainingTime)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->directionCode), checkinfo_directionCode)) < 0) return ret;
	if ((ret = ASN1_CHECK_BOOLEAN(&(value->reserved), checkinfo_reserved)) < 0) return ret;
	return ret;
}
