extern int ASN1_BER_Data_Enc_ConsecutiveTrafficLight(ASN1WorkSpace *workspace, ConsecutiveTrafficLight *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_TrafficLightIntervalType(ASN1WorkSpace *workspace, TrafficLightIntervalType *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_PedestrianCall(ASN1WorkSpace *workspace, PedestrianCall *value, ASN1TagType tagFlag);
