int ASN1_Print_TLS(TLS *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("TLS");
	// Type Reference TrafficLightID
	if (Compare_Letter(tab_value, "trafficLightID")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("trafficLightID = ");
	}
	if ((ret = ASN1_Print_TrafficLightID((TrafficLightID *)value->trafficLightID, tab_value + 1)) < 0) return ret;
	if (value->DEF_TLS_lon == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("Longitude", &(value->lon))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TLS_lat == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("Latitude", &(value->lat))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BITSTRING("TrafficLightOperationStatus", &(value->operationStatus))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BITSTRING("TrafficLightControllerStatus", &(value->controllerStatus))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("TimeInSecond_B16", &(value->cyclecounter))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("TimeInSecond_B16", &(value->cycletime))) < 0) return ret;
	// Type Reference DDateTime
	if (Compare_Letter(tab_value, "currentTime")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("currentTime = ");
	}
	if ((ret = ASN1_Print_DDateTime((DDateTime *)value->currentTime, tab_value + 1)) < 0) return ret;
	// Type Reference TrafficLightStatusList
	if (Compare_Letter(tab_value, "trafficLightStatus")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("trafficLightStatus = ");
	}
	if ((ret = ASN1_Print_TrafficLightStatusList((TrafficLightStatusList *)&(value->trafficLightStatus), tab_value + 1)) < 0) return ret;
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
