extern int ASN1_CHECK_NMEAcorrections_regional(NMEAcorrections_regional *value);
int ASN1_CHECK_NMEAcorrections(NMEAcorrections *value)
{
	int ret = 0;

	unsigned char checkinfo_timeStamp[] = { 
		0x02,0x00,0x83,0x08,0x0A,0xC0,0x00
	};
	unsigned char checkinfo_rev[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_msg[] = { 
		0x02,0x00,0x82,0x7F,0xFF,0x00
	};
	unsigned char checkinfo_wdCount[] = { 
		0x02,0x00,0x82,0x03,0xFF,0x00
	};
	unsigned char checkinfo_payload[] = { 
		0x02,0x01,0x82,0x03,0xFF,0x00
	};
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_NMEAcorrections_timeStamp == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->timeStamp), checkinfo_timeStamp)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_NMEAcorrections_rev == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->rev), checkinfo_rev)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_NMEAcorrections_msg == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->msg), checkinfo_msg)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_NMEAcorrections_wdCount == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->wdCount), checkinfo_wdCount)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_OCTETSTRING(&(value->payload), checkinfo_payload)) < 0) return ret;
	if (value->DEF_NMEAcorrections_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_NMEAcorrections_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_MinuteOfTheYear(ASN1WorkSpace *workspace, MinuteOfTheYear *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_NMEA_Revision(ASN1WorkSpace *workspace, NMEA_Revision *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_NMEA_MsgType(ASN1WorkSpace *workspace, NMEA_MsgType *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_ObjectCount(ASN1WorkSpace *workspace, ObjectCount *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_NMEA_Payload(ASN1WorkSpace *workspace, NMEA_Payload *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_NMEAcorrections_regional(ASN1WorkSpace *workspace, NMEAcorrections_regional *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_NMEAcorrections(ASN1WorkSpace *workspace, NMEAcorrections *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if (value->DEF_NMEAcorrections_timeStamp == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_MinuteOfTheYear(workspace, &(value->timeStamp), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_NMEAcorrections_rev == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_NMEA_Revision(workspace, &(value->rev), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_NMEAcorrections_msg == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_NMEA_MsgType(workspace, &(value->msg), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_NMEAcorrections_wdCount == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_ObjectCount(workspace, &(value->wdCount), ASN1IMPL)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 4)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_NMEA_Payload(workspace, &(value->payload), ASN1IMPL)) < 0) return ret;
	if (value->DEF_NMEAcorrections_regional == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 16)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_NMEAcorrections_regional(workspace, &(value->regional), ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
