extern int ASN1_PER_Align_Data_Dec_NMEAcorrections_regional(ASN1WorkSpace *workspace, NMEAcorrections_regional *value);
int ASN1_PER_Align_Data_Dec_NMEAcorrections(ASN1WorkSpace *workspace, NMEAcorrections *value)
{
	int ret = 0;
	ASNINT32 ui_rev;
	struct Asn1ConsInfo consinfo_timeStamp = { ASN1_CONST64(0), ASN1_CONST64(527040), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_rev = { ASN1_CONST64(0), ASN1_CONST64(6), NULL, 1, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_msg = { ASN1_CONST64(0), ASN1_CONST64(32767), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_wdCount = { ASN1_CONST64(0), ASN1_CONST64(1023), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_payload = { ASN1_CONST64(1), ASN1_CONST64(1023), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNBOOL extbit_NMEAcorrections;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_NMEAcorrections)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 5, &_optvalue)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_NMEAcorrections_timeStamp = 1;
		if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->timeStamp), &consinfo_timeStamp)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_NMEAcorrections_rev = 1;
		if ((ret = ASN1_PER_Align_Dec_ENUMERATED(workspace, &ui_rev, &consinfo_rev)) < 0) return ret;
		if (consinfo_rev.enumextbit == 0)
		{
			switch(ui_rev)
			{
			case 0: value->rev = NMEA_Revision_unknown; break;
			case 1: value->rev = NMEA_Revision_reserved; break;
			case 2: value->rev = NMEA_Revision_rev1; break;
			case 3: value->rev = NMEA_Revision_rev2; break;
			case 4: value->rev = NMEA_Revision_rev3; break;
			case 5: value->rev = NMEA_Revision_rev4; break;
			case 6: value->rev = NMEA_Revision_rev5; break;
			default: break;
			}
		}
		else
		{
			switch(ui_rev)
			{
			default: value->rev = ui_rev; break;
			}
		}
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 3) == 1)
	{
		value->DEF_NMEAcorrections_msg = 1;
		if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->msg), &consinfo_msg)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 4) == 1)
	{
		value->DEF_NMEAcorrections_wdCount = 1;
		if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->wdCount), &consinfo_wdCount)) < 0) return ret;
	}
	if ((ret = ASN1_PER_Align_Dec_OCTETSTRING(workspace, &(value->payload), &consinfo_payload)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 5) == 1)
	{
		value->DEF_NMEAcorrections_regional = 1;
		if ((ret = ASN1_PER_Align_Dec_NMEAcorrections_regional(workspace, &(value->regional))) < 0) return ret;
	}
	if (extbit_NMEAcorrections == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, ALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, ALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
extern int ASN1_CHECK_NMEAcorrections(NMEAcorrections *value);
extern int ASN1_PER_Align_Data_Dec_NMEAcorrections(ASN1WorkSpace *workspace, NMEAcorrections *value);
int ASN1_PER_Align_Dec_NMEAcorrections(ASN1WorkSpace *workspace, NMEAcorrections *value)
{
	int ret = 0;
	if ((ret = ASN1_PER_Align_Data_Dec_NMEAcorrections(workspace,value)) < 0) return ret;
	if ((ret = ASN1_CHECK_NMEAcorrections(value)) < 0) return ret;
	return ret;
}
extern int ASN1_PER_UNAlign_Data_Enc_NMEAcorrections_regional(ASN1WorkSpace *workspace, NMEAcorrections_regional *value);
int ASN1_PER_UNAlign_Data_Enc_NMEAcorrections(ASN1WorkSpace *workspace, NMEAcorrections *value)
{
	int ret = 0;
	ASNINT32 ui_rev;
	struct Asn1ConsInfo consinfo_timeStamp = { ASN1_CONST64(0), ASN1_CONST64(527040), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_rev = { ASN1_CONST64(0), ASN1_CONST64(6), NULL, 1, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_msg = { ASN1_CONST64(0), ASN1_CONST64(32767), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_wdCount = { ASN1_CONST64(0), ASN1_CONST64(1023), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_payload = { ASN1_CONST64(1), ASN1_CONST64(1023), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNINT32 all_bit;
	ASNUINT16 all_pointer;
	if ((ret = ASN1_PER_Enc_extbit(workspace, value->E)) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_NMEAcorrections_timeStamp == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_NMEAcorrections_rev == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_NMEAcorrections_msg == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_NMEAcorrections_wdCount == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_NMEAcorrections_regional == 1 ? 1 : 0) )) < 0) return ret;
	if (value->DEF_NMEAcorrections_timeStamp == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_INTEGER(workspace, &(value->timeStamp), &consinfo_timeStamp)) < 0) return ret;
	}
	if (value->DEF_NMEAcorrections_rev == 1)
	{
		switch(value->rev)
		{
		case NMEA_Revision_unknown: ui_rev = 0; consinfo_rev.enumextbit = 0; break;
		case NMEA_Revision_reserved: ui_rev = 1; consinfo_rev.enumextbit = 0; break;
		case NMEA_Revision_rev1: ui_rev = 2; consinfo_rev.enumextbit = 0; break;
		case NMEA_Revision_rev2: ui_rev = 3; consinfo_rev.enumextbit = 0; break;
		case NMEA_Revision_rev3: ui_rev = 4; consinfo_rev.enumextbit = 0; break;
		case NMEA_Revision_rev4: ui_rev = 5; consinfo_rev.enumextbit = 0; break;
		case NMEA_Revision_rev5: ui_rev = 6; consinfo_rev.enumextbit = 0; break;
		default: ui_rev = value->rev; consinfo_rev.enumextbit = 1;break;
		}
		if ((ret = ASN1_PER_UNAlign_Enc_ENUMERATED(workspace, ui_rev, &consinfo_rev)) < 0) return ret;
	}
	if (value->DEF_NMEAcorrections_msg == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_INTEGER(workspace, &(value->msg), &consinfo_msg)) < 0) return ret;
	}
	if (value->DEF_NMEAcorrections_wdCount == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_INTEGER(workspace, &(value->wdCount), &consinfo_wdCount)) < 0) return ret;
	}
	if ((ret = ASN1_PER_UNAlign_Enc_OCTETSTRING(workspace, &(value->payload), &consinfo_payload)) < 0) return ret;
	if (value->DEF_NMEAcorrections_regional == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_NMEAcorrections_regional(workspace, &(value->regional))) < 0) return ret;
	}
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, UNALIGN, 0);
	}
	return ret;
}
extern int ASN1_CHECK_NMEAcorrections(NMEAcorrections *value);
extern int ASN1_PER_UNAlign_Data_Enc_NMEAcorrections(ASN1WorkSpace *workspace, NMEAcorrections *value);
int ASN1_PER_UNAlign_Enc_NMEAcorrections(ASN1WorkSpace *workspace, NMEAcorrections *value)
{ // ASN1_PER_Extern_Encode 
	int ret = 0;
	if ((ret = ASN1_CHECK_NMEAcorrections(value)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Data_Enc_NMEAcorrections(workspace,value)) < 0) return ret;
	return ret;
}
extern int ASN1_PER_UNAlign_Data_Dec_NMEAcorrections_regional(ASN1WorkSpace *workspace, NMEAcorrections_regional *value);
int ASN1_PER_UNAlign_Data_Dec_NMEAcorrections(ASN1WorkSpace *workspace, NMEAcorrections *value)
{
	int ret = 0;
	ASNINT32 ui_rev;
	struct Asn1ConsInfo consinfo_timeStamp = { ASN1_CONST64(0), ASN1_CONST64(527040), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_rev = { ASN1_CONST64(0), ASN1_CONST64(6), NULL, 1, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_msg = { ASN1_CONST64(0), ASN1_CONST64(32767), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_wdCount = { ASN1_CONST64(0), ASN1_CONST64(1023), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_payload = { ASN1_CONST64(1), ASN1_CONST64(1023), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNBOOL extbit_NMEAcorrections;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_NMEAcorrections)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 5, &_optvalue)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_NMEAcorrections_timeStamp = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->timeStamp), &consinfo_timeStamp)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_NMEAcorrections_rev = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_ENUMERATED(workspace, &ui_rev, &consinfo_rev)) < 0) return ret;
		if (consinfo_rev.enumextbit == 0)
		{
			switch(ui_rev)
			{
			case 0: value->rev = NMEA_Revision_unknown; break;
			case 1: value->rev = NMEA_Revision_reserved; break;
			case 2: value->rev = NMEA_Revision_rev1; break;
			case 3: value->rev = NMEA_Revision_rev2; break;
			case 4: value->rev = NMEA_Revision_rev3; break;
			case 5: value->rev = NMEA_Revision_rev4; break;
			case 6: value->rev = NMEA_Revision_rev5; break;
			default: break;
			}
		}
		else
		{
			switch(ui_rev)
			{
			default: value->rev = ui_rev; break;
			}
		}
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 3) == 1)
	{
		value->DEF_NMEAcorrections_msg = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->msg), &consinfo_msg)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 4) == 1)
	{
		value->DEF_NMEAcorrections_wdCount = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->wdCount), &consinfo_wdCount)) < 0) return ret;
	}
	if ((ret = ASN1_PER_UNAlign_Dec_OCTETSTRING(workspace, &(value->payload), &consinfo_payload)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 5) == 1)
	{
		value->DEF_NMEAcorrections_regional = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_NMEAcorrections_regional(workspace, &(value->regional))) < 0) return ret;
	}
	if (extbit_NMEAcorrections == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, UNALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, UNALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
extern int ASN1_CHECK_NMEAcorrections(NMEAcorrections *value);
extern int ASN1_PER_UNAlign_Data_Dec_NMEAcorrections(ASN1WorkSpace *workspace, NMEAcorrections *value);
int ASN1_PER_UNAlign_Dec_NMEAcorrections(ASN1WorkSpace *workspace, NMEAcorrections *value)
{
	int ret = 0;
	if ((ret = ASN1_PER_UNAlign_Data_Dec_NMEAcorrections(workspace,value)) < 0) return ret;
	if ((ret = ASN1_CHECK_NMEAcorrections(value)) < 0) return ret;
	return ret;
}

/********************************************************
*TransmissionAndSpeed                                   *
********************************************************/
int ASN1_Print_TransmissionAndSpeed(TransmissionAndSpeed *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("TransmissionAndSpeed");
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->transmisson)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "neutral", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "park", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "forwardGears", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "reverseGears", 3)) < 0) return ret; break;
	case 4: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "reserved1", 4)) < 0) return ret; break;
	case 5: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "reserved2", 5)) < 0) return ret; break;
	case 6: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "reserved3", 6)) < 0) return ret; break;
	case 7: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "unavailable", 7)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("Velocity", &(value->speed))) < 0) return ret;
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
