int ASN1_CHECK_TransmissionAndSpeed(TransmissionAndSpeed *value)
{
	int ret = 0;

	unsigned char checkinfo_transmisson[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_speed[] = { 
		0x02,0x00,0x82,0x1F,0xFF,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->transmisson), checkinfo_transmisson)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->speed), checkinfo_speed)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Enc_TransmissionState(ASN1WorkSpace *workspace, TransmissionState *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_Velocity(ASN1WorkSpace *workspace, Velocity *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_TransmissionAndSpeed(ASN1WorkSpace *workspace, TransmissionAndSpeed *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_TransmissionState(workspace, &(value->transmisson), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_Velocity(workspace, &(value->speed), ASN1IMPL)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_TransmissionAndSpeed(TransmissionAndSpeed *value);
extern int ASN1_BER_Data_Enc_TransmissionAndSpeed(ASN1WorkSpace *workspace, TransmissionAndSpeed *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_TransmissionAndSpeed(ASN1WorkSpace *workspace, TransmissionAndSpeed *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_TransmissionAndSpeed(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_TransmissionAndSpeed(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_TransmissionState(ASN1WorkSpace *workspace, TransmissionState *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_Velocity(ASN1WorkSpace *workspace, Velocity *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_TransmissionAndSpeed(ASN1WorkSpace *workspace, TransmissionAndSpeed *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_TransmissionState(workspace, &value->transmisson, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_Velocity(workspace, &value->speed, len, ASN1IMPL)) < 0) return ret;
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_TransmissionAndSpeed(TransmissionAndSpeed *value);
extern int ASN1_BER_Data_Dec_TransmissionAndSpeed(ASN1WorkSpace *workspace, TransmissionAndSpeed *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_TransmissionAndSpeed(ASN1WorkSpace *workspace, TransmissionAndSpeed *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_TransmissionAndSpeed(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_TransmissionAndSpeed(value)) < 0) return ret;
	return ret;
}
int ASN1_PER_Align_Data_Enc_TransmissionAndSpeed(ASN1WorkSpace *workspace, TransmissionAndSpeed *value)
{
	int ret = 0;
	ASNINT32 ui_transmisson;
	struct Asn1ConsInfo consinfo_transmisson = { ASN1_CONST64(0), ASN1_CONST64(7), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_speed = { ASN1_CONST64(0), ASN1_CONST64(8191), NULL, 0, CONS, 0, 0 };

	switch(value->transmisson)
	{
	case TransmissionState_neutral: ui_transmisson = 0; consinfo_transmisson.enumextbit = 0; break;
	case TransmissionState_park: ui_transmisson = 1; consinfo_transmisson.enumextbit = 0; break;
	case TransmissionState_forwardGears: ui_transmisson = 2; consinfo_transmisson.enumextbit = 0; break;
	case TransmissionState_reverseGears: ui_transmisson = 3; consinfo_transmisson.enumextbit = 0; break;
	case TransmissionState_reserved1: ui_transmisson = 4; consinfo_transmisson.enumextbit = 0; break;
	case TransmissionState_reserved2: ui_transmisson = 5; consinfo_transmisson.enumextbit = 0; break;
	case TransmissionState_reserved3: ui_transmisson = 6; consinfo_transmisson.enumextbit = 0; break;
	case TransmissionState_unavailable: ui_transmisson = 7; consinfo_transmisson.enumextbit = 0; break;
	default: ui_transmisson = value->transmisson; consinfo_transmisson.enumextbit = 0;break;
	}
	if ((ret = ASN1_PER_Align_Enc_ENUMERATED(workspace, ui_transmisson, &consinfo_transmisson)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->speed), &consinfo_speed)) < 0) return ret;
	return ret;
}
extern int ASN1_CHECK_TransmissionAndSpeed(TransmissionAndSpeed *value);
extern int ASN1_PER_Align_Data_Enc_TransmissionAndSpeed(ASN1WorkSpace *workspace, TransmissionAndSpeed *value);
int ASN1_PER_Align_Enc_TransmissionAndSpeed(ASN1WorkSpace *workspace, TransmissionAndSpeed *value)
{ // ASN1_PER_Extern_Encode 
	int ret = 0;
	if ((ret = ASN1_CHECK_TransmissionAndSpeed(value)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Data_Enc_TransmissionAndSpeed(workspace,value)) < 0) return ret;
	return ret;
}
int ASN1_PER_Align_Data_Dec_TransmissionAndSpeed(ASN1WorkSpace *workspace, TransmissionAndSpeed *value)
{
	int ret = 0;
	ASNINT32 ui_transmisson;
	struct Asn1ConsInfo consinfo_transmisson = { ASN1_CONST64(0), ASN1_CONST64(7), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_speed = { ASN1_CONST64(0), ASN1_CONST64(8191), NULL, 0, CONS, 0, 0 };

	if ((ret = ASN1_PER_Align_Dec_ENUMERATED(workspace, &ui_transmisson, &consinfo_transmisson)) < 0) return ret;
	if (consinfo_transmisson.enumextbit == 0)
	{
		switch(ui_transmisson)
		{
		case 0: value->transmisson = TransmissionState_neutral; break;
		case 1: value->transmisson = TransmissionState_park; break;
		case 2: value->transmisson = TransmissionState_forwardGears; break;
		case 3: value->transmisson = TransmissionState_reverseGears; break;
		case 4: value->transmisson = TransmissionState_reserved1; break;
		case 5: value->transmisson = TransmissionState_reserved2; break;
		case 6: value->transmisson = TransmissionState_reserved3; break;
		case 7: value->transmisson = TransmissionState_unavailable; break;
		default: value->transmisson = ui_transmisson; break;
		}
	}
	if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->speed), &consinfo_speed)) < 0) return ret;
	return ret;
}
extern int ASN1_CHECK_TransmissionAndSpeed(TransmissionAndSpeed *value);
extern int ASN1_PER_Align_Data_Dec_TransmissionAndSpeed(ASN1WorkSpace *workspace, TransmissionAndSpeed *value);
int ASN1_PER_Align_Dec_TransmissionAndSpeed(ASN1WorkSpace *workspace, TransmissionAndSpeed *value)
{
	int ret = 0;
	if ((ret = ASN1_PER_Align_Data_Dec_TransmissionAndSpeed(workspace,value)) < 0) return ret;
	if ((ret = ASN1_CHECK_TransmissionAndSpeed(value)) < 0) return ret;
	return ret;
}
int ASN1_PER_UNAlign_Data_Enc_TransmissionAndSpeed(ASN1WorkSpace *workspace, TransmissionAndSpeed *value)
{
	int ret = 0;
	ASNINT32 ui_transmisson;
	struct Asn1ConsInfo consinfo_transmisson = { ASN1_CONST64(0), ASN1_CONST64(7), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_speed = { ASN1_CONST64(0), ASN1_CONST64(8191), NULL, 0, CONS, 0, 0 };

	switch(value->transmisson)
	{
	case TransmissionState_neutral: ui_transmisson = 0; consinfo_transmisson.enumextbit = 0; break;
	case TransmissionState_park: ui_transmisson = 1; consinfo_transmisson.enumextbit = 0; break;
	case TransmissionState_forwardGears: ui_transmisson = 2; consinfo_transmisson.enumextbit = 0; break;
	case TransmissionState_reverseGears: ui_transmisson = 3; consinfo_transmisson.enumextbit = 0; break;
	case TransmissionState_reserved1: ui_transmisson = 4; consinfo_transmisson.enumextbit = 0; break;
	case TransmissionState_reserved2: ui_transmisson = 5; consinfo_transmisson.enumextbit = 0; break;
	case TransmissionState_reserved3: ui_transmisson = 6; consinfo_transmisson.enumextbit = 0; break;
	case TransmissionState_unavailable: ui_transmisson = 7; consinfo_transmisson.enumextbit = 0; break;
	default: ui_transmisson = value->transmisson; consinfo_transmisson.enumextbit = 0;break;
	}
	if ((ret = ASN1_PER_UNAlign_Enc_ENUMERATED(workspace, ui_transmisson, &consinfo_transmisson)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Enc_INTEGER(workspace, &(value->speed), &consinfo_speed)) < 0) return ret;
	return ret;
}
