extern int ASN1_PER_UNAlign_Data_Dec_TransmissionAndSpeed(ASN1WorkSpace *workspace, TransmissionAndSpeed *value);
int ASN1_PER_UNAlign_Dec_TransmissionAndSpeed(ASN1WorkSpace *workspace, TransmissionAndSpeed *value)
{
	int ret = 0;
	if ((ret = ASN1_PER_UNAlign_Data_Dec_TransmissionAndSpeed(workspace,value)) < 0) return ret;
	if ((ret = ASN1_CHECK_TransmissionAndSpeed(value)) < 0) return ret;
	return ret;
}

