int ASN1_CHECK_PositionConfidenceSet(PositionConfidenceSet *value)
{
	int ret = 0;

	unsigned char checkinfo_pos[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_elevation[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->pos), checkinfo_pos)) < 0) return ret;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->elevation), checkinfo_elevation)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Enc_PositionConfidence(ASN1WorkSpace *workspace, PositionConfidence *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_ElevationConfidence(ASN1WorkSpace *workspace, ElevationConfidence *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_PositionConfidenceSet(ASN1WorkSpace *workspace, PositionConfidenceSet *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_PositionConfidence(workspace, &(value->pos), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_ElevationConfidence(workspace, &(value->elevation), ASN1IMPL)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_PositionConfidenceSet(PositionConfidenceSet *value);
extern int ASN1_BER_Data_Enc_PositionConfidenceSet(ASN1WorkSpace *workspace, PositionConfidenceSet *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_PositionConfidenceSet(ASN1WorkSpace *workspace, PositionConfidenceSet *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_PositionConfidenceSet(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_PositionConfidenceSet(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_PositionConfidence(ASN1WorkSpace *workspace, PositionConfidence *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_ElevationConfidence(ASN1WorkSpace *workspace, ElevationConfidence *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_PositionConfidenceSet(ASN1WorkSpace *workspace, PositionConfidenceSet *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_PositionConfidence(workspace, &value->pos, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_ElevationConfidence(workspace, &value->elevation, len, ASN1IMPL)) < 0) return ret;
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_PositionConfidenceSet(PositionConfidenceSet *value);
extern int ASN1_BER_Data_Dec_PositionConfidenceSet(ASN1WorkSpace *workspace, PositionConfidenceSet *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_PositionConfidenceSet(ASN1WorkSpace *workspace, PositionConfidenceSet *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_PositionConfidenceSet(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_PositionConfidenceSet(value)) < 0) return ret;
	return ret;
}
