int ASN1_PER_UNAlign_Data_Dec_PositionConfidenceSet(ASN1WorkSpace *workspace, PositionConfidenceSet *value)
{
	int ret = 0;
	ASNINT32 ui_pos;
	ASNINT32 ui_elevation;
	struct Asn1ConsInfo consinfo_pos = { ASN1_CONST64(0), ASN1_CONST64(15), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_elevation = { ASN1_CONST64(0), ASN1_CONST64(15), NULL, 0, CONS, 0, 0 };

	if ((ret = ASN1_PER_UNAlign_Dec_ENUMERATED(workspace, &ui_pos, &consinfo_pos)) < 0) return ret;
	if (consinfo_pos.enumextbit == 0)
	{
		switch(ui_pos)
		{
		case 0: value->pos = PositionConfidence_unavailable; break;
		case 1: value->pos = PositionConfidence_a500m; break;
		case 2: value->pos = PositionConfidence_a200m; break;
		case 3: value->pos = PositionConfidence_a100m; break;
		case 4: value->pos = PositionConfidence_a50m; break;
		case 5: value->pos = PositionConfidence_a20m; break;
		case 6: value->pos = PositionConfidence_a10m; break;
		case 7: value->pos = PositionConfidence_a5m; break;
		case 8: value->pos = PositionConfidence_a2m; break;
		case 9: value->pos = PositionConfidence_a1m; break;
		case 10: value->pos = PositionConfidence_a50cm; break;
		case 11: value->pos = PositionConfidence_a20cm; break;
		case 12: value->pos = PositionConfidence_a10cm; break;
		case 13: value->pos = PositionConfidence_a5cm; break;
		case 14: value->pos = PositionConfidence_a2cm; break;
		case 15: value->pos = PositionConfidence_a1cm; break;
		default: value->pos = ui_pos; break;
		}
	}
	if ((ret = ASN1_PER_UNAlign_Dec_ENUMERATED(workspace, &ui_elevation, &consinfo_elevation)) < 0) return ret;
	if (consinfo_elevation.enumextbit == 0)
	{
		switch(ui_elevation)
		{
		case 0: value->elevation = ElevationConfidence_unavailable; break;
		case 1: value->elevation = ElevationConfidence_elev_500_00; break;
		case 2: value->elevation = ElevationConfidence_elev_200_00; break;
		case 3: value->elevation = ElevationConfidence_elev_100_00; break;
		case 4: value->elevation = ElevationConfidence_elev_050_00; break;
		case 5: value->elevation = ElevationConfidence_elev_020_00; break;
		case 6: value->elevation = ElevationConfidence_elev_010_00; break;
		case 7: value->elevation = ElevationConfidence_elev_005_00; break;
		case 8: value->elevation = ElevationConfidence_elev_002_00; break;
		case 9: value->elevation = ElevationConfidence_elev_001_00; break;
		case 10: value->elevation = ElevationConfidence_elev_000_50; break;
		case 11: value->elevation = ElevationConfidence_elev_000_20; break;
		case 12: value->elevation = ElevationConfidence_elev_000_10; break;
		case 13: value->elevation = ElevationConfidence_elev_000_05; break;
		case 14: value->elevation = ElevationConfidence_elev_000_02; break;
		case 15: value->elevation = ElevationConfidence_elev_000_01; break;
		default: value->elevation = ui_elevation; break;
		}
	}
	return ret;
}
