extern int ASN1_BER_Data_Enc_HeadingConfidence(ASN1WorkSpace *workspace, HeadingConfidence *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_SpeedConfidence(ASN1WorkSpace *workspace, SpeedConfidence *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_ThrottleConfidence(ASN1WorkSpace *workspace, ThrottleConfidence *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_SpeedandHeadingandThrottleConfidence(ASN1WorkSpace *workspace, SpeedandHeadingandThrottleConfidence *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_HeadingConfidence(workspace, &(value->heading), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_SpeedConfidence(workspace, &(value->speed), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_ThrottleConfidence(workspace, &(value->throttle), ASN1IMPL)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
