extern int ASN1_BER_Data_Dec_SpeedandHeadingandThrottleConfidence(ASN1WorkSpace *workspace, SpeedandHeadingandThrottleConfidence *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_SpeedandHeadingandThrottleConfidence(ASN1WorkSpace *workspace, SpeedandHeadingandThrottleConfidence *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_SpeedandHeadingandThrottleConfidence(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_SpeedandHeadingandThrottleConfidence(value)) < 0) return ret;
	return ret;
}
