int ASN1_PER_Align_Data_Dec_SpeedandHeadingandThrottleConfidence(ASN1WorkSpace *workspace, SpeedandHeadingandThrottleConfidence *value)
{
	int ret = 0;
	ASNINT32 ui_heading;
	ASNINT32 ui_speed;
	ASNINT32 ui_throttle;
	struct Asn1ConsInfo consinfo_heading = { ASN1_CONST64(0), ASN1_CONST64(7), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_speed = { ASN1_CONST64(0), ASN1_CONST64(7), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_throttle = { ASN1_CONST64(0), ASN1_CONST64(3), NULL, 0, CONS, 0, 0 };

	if ((ret = ASN1_PER_Align_Dec_ENUMERATED(workspace, &ui_heading, &consinfo_heading)) < 0) return ret;
	if (consinfo_heading.enumextbit == 0)
	{
		switch(ui_heading)
		{
		case 0: value->heading = HeadingConfidence_unavailable; break;
		case 1: value->heading = HeadingConfidence_prec10deg; break;
		case 2: value->heading = HeadingConfidence_prec05deg; break;
		case 3: value->heading = HeadingConfidence_prec01deg; break;
		case 4: value->heading = HeadingConfidence_prec0_1deg; break;
		case 5: value->heading = HeadingConfidence_prec0_05deg; break;
		case 6: value->heading = HeadingConfidence_prec0_01deg; break;
		case 7: value->heading = HeadingConfidence_prec0_0125deg; break;
		default: value->heading = ui_heading; break;
		}
	}
	if ((ret = ASN1_PER_Align_Dec_ENUMERATED(workspace, &ui_speed, &consinfo_speed)) < 0) return ret;
	if (consinfo_speed.enumextbit == 0)
	{
		switch(ui_speed)
		{
		case 0: value->speed = SpeedConfidence_unavailable; break;
		case 1: value->speed = SpeedConfidence_prec100ms; break;
		case 2: value->speed = SpeedConfidence_prec10ms; break;
		case 3: value->speed = SpeedConfidence_prec5ms; break;
		case 4: value->speed = SpeedConfidence_prec1ms; break;
		case 5: value->speed = SpeedConfidence_prec0_1ms; break;
		case 6: value->speed = SpeedConfidence_prec0_05ms; break;
		case 7: value->speed = SpeedConfidence_prec0_01ms; break;
		default: value->speed = ui_speed; break;
		}
	}
	if ((ret = ASN1_PER_Align_Dec_ENUMERATED(workspace, &ui_throttle, &consinfo_throttle)) < 0) return ret;
	if (consinfo_throttle.enumextbit == 0)
	{
		switch(ui_throttle)
		{
		case 0: value->throttle = ThrottleConfidence_unavailable; break;
		case 1: value->throttle = ThrottleConfidence_prec10percent; break;
		case 2: value->throttle = ThrottleConfidence_prec1percent; break;
		case 3: value->throttle = ThrottleConfidence_prec0_5percent; break;
		default: value->throttle = ui_throttle; break;
		}
	}
	return ret;
}
