		case 20: if ((ret = ASN1_Print_ENUMERATED("TimeConfidence", "time-000-000-02", 20)) < 0) return ret; break;
		case 21: if ((ret = ASN1_Print_ENUMERATED("TimeConfidence", "time-000-000-01", 21)) < 0) return ret; break;
		case 22: if ((ret = ASN1_Print_ENUMERATED("TimeConfidence", "time-000-000-005", 22)) < 0) return ret; break;
		case 23: if ((ret = ASN1_Print_ENUMERATED("TimeConfidence", "time-000-000-002", 23)) < 0) return ret; break;
		case 24: if ((ret = ASN1_Print_ENUMERATED("TimeConfidence", "time-000-000-001", 24)) < 0) return ret; break;
		case 25: if ((ret = ASN1_Print_ENUMERATED("TimeConfidence", "time-000-000-000-5", 25)) < 0) return ret; break;
