		case 30: if ((ret = ASN1_Print_ENUMERATED("TimeConfidence", "time-000-000-000-01", 30)) < 0) return ret; break;
		case 31: if ((ret = ASN1_Print_ENUMERATED("TimeConfidence", "time-000-000-000-005", 31)) < 0) return ret; break;
		case 32: if ((ret = ASN1_Print_ENUMERATED("TimeConfidence", "time-000-000-000-002", 32)) < 0) return ret; break;
		case 33: if ((ret = ASN1_Print_ENUMERATED("TimeConfidence", "time-000-000-000-001", 33)) < 0) return ret; break;
