extern int ASN1_CHECK_TransmissionAndSpeed(TransmissionAndSpeed *value);
extern int ASN1_CHECK_PositionalAccuracy(PositionalAccuracy *value);
extern int ASN1_CHECK_PositionConfidenceSet(PositionConfidenceSet *value);
extern int ASN1_CHECK_SpeedandHeadingandThrottleConfidence(SpeedandHeadingandThrottleConfidence *value);
int ASN1_CHECK_FullPositionVector(FullPositionVector *value)
{
	int ret = 0;

	unsigned char checkinfo_utcTime[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_lon[] = { 
		0x02,0x84,0x94,0xB6,0x2E,0x01,0x84,0x6B,0x49,0xD2,0x01,0x00
	};
	unsigned char checkinfo_lat[] = { 
		0x02,0x84,0xCA,0x5B,0x17,0x00,0x84,0x35,0xA4,0xE9,0x01,0x00
	};
	unsigned char checkinfo_elevation[] = { 
		0x02,0x82,0xF0,0x00,0x83,0x00,0xEF,0xFF,0x00
	};
	unsigned char checkinfo_heading[] = { 
		0x02,0x00,0x82,0x70,0x80,0x00
	};
	unsigned char checkinfo_speed[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_posAccuracy[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_timeConfidence[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_posConfidence[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_speedConfidence[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if (value->DEF_FullPositionVector_utcTime == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_DDateTime(value->utcTime)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_INTEGER(&(value->lon), checkinfo_lon)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->lat), checkinfo_lat)) < 0) return ret;
	if (value->DEF_FullPositionVector_elevation == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->elevation), checkinfo_elevation)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_FullPositionVector_heading == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->heading), checkinfo_heading)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_FullPositionVector_speed == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_TransmissionAndSpeed(value->speed)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_FullPositionVector_posAccuracy == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_PositionalAccuracy(value->posAccuracy)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_FullPositionVector_timeConfidence == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->timeConfidence), checkinfo_timeConfidence)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_FullPositionVector_posConfidence == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_PositionConfidenceSet(value->posConfidence)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_FullPositionVector_speedConfidence == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_SpeedandHeadingandThrottleConfidence(value->speedConfidence)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
