	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 4)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_Heading(workspace, &(value->heading), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_FullPositionVector_speed == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 5)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_TransmissionAndSpeed(workspace, value->speed, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_FullPositionVector_posAccuracy == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 6)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_PositionalAccuracy(workspace, value->posAccuracy, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_FullPositionVector_timeConfidence == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 7)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_TimeConfidence(workspace, &(value->timeConfidence), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_FullPositionVector_posConfidence == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 8)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_PositionConfidenceSet(workspace, value->posConfidence, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_FullPositionVector_speedConfidence == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 9)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_SpeedandHeadingandThrottleConfidence(workspace, value->speedConfidence, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
