/********************************************************
*RTCMheader                                             *
********************************************************/
int ASN1_Print_RTCMheader(RTCMheader *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("RTCMheader");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BITSTRING("GNSSstatus", &(value->status))) < 0) return ret;
	// Type Reference AntennaOffsetSet
	if (Compare_Letter(tab_value, "offsetSet")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("offsetSet = ");
	}
	if ((ret = ASN1_Print_AntennaOffsetSet((AntennaOffsetSet *)value->offsetSet, tab_value + 1)) < 0) return ret;
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_RTCMheader_status(ASN1WorkSpace *workspace, RTCMheader *value, ASNUINT8 *user_value, ASNUINT32L user_value_length)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if ((ret = ASN1_SET_BITSTRING(workspace, &value->status, user_value, user_value_length)) < 0) return ret;
	return ret;
}
int ASN1_SET_RTCMheader_offsetSet(ASN1WorkSpace *workspace, RTCMheader *value, AntennaOffsetSet *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->offsetSet = (AntennaOffsetSet *)mpool_malloc(workspace->Pmemory, sizeof(AntennaOffsetSet));
	memset(value->offsetSet, 0, sizeof(AntennaOffsetSet));
	memmove(value->offsetSet, user_value, sizeof(AntennaOffsetSet));
	return ret;
}
int ASN1_GET_RTCMheader_status(ASN1WorkSpace *workspace, RTCMheader *value, ASNUINT8 **user_value, ASNUINT32L *user_value_length)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if ((ret = ASN1_GET_BITSTRING(workspace, &value->status, user_value, user_value_length)) < 0) return ret;
	return ret;
}
int ASN1_GET_RTCMheader_offsetSet(ASN1WorkSpace *workspace, RTCMheader *value, AntennaOffsetSet **user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	*user_value = value->offsetSet;
	return ret;
}
extern int ASN1_CHECK_AntennaOffsetSet(AntennaOffsetSet *value);
int ASN1_CHECK_RTCMheader(RTCMheader *value)
{
	int ret = 0;

	unsigned char checkinfo_status[] = { 
		0x02,0x08,0x08,0x00
	};
	unsigned char checkinfo_offsetSet[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_BITSTRING(&(value->status), checkinfo_status)) < 0) return ret;
	if ((ret = ASN1_CHECK_AntennaOffsetSet(value->offsetSet)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Enc_GNSSstatus(ASN1WorkSpace *workspace, GNSSstatus *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_AntennaOffsetSet(ASN1WorkSpace *workspace, AntennaOffsetSet *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_RTCMheader(ASN1WorkSpace *workspace, RTCMheader *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_GNSSstatus(workspace, &(value->status), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_AntennaOffsetSet(workspace, value->offsetSet, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
