{
	int ret = 0;
	if ((ret = ASN1_CHECK_RTCMmessageList(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_RTCMmessageList(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_RTCMmessage(ASN1WorkSpace *workspace, RTCMmessage *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_RTCMmessageList(ASN1WorkSpace *workspace, RTCMmessageList *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	RTCMmessage *pdata;
	ASNUINT8 *p = workspace->buffer.current;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	if ((ret = ASN1_Creat_Init_List(workspace, value)) < 0) return ret;
	while (ASN1_BER_Dec_Isloop(workspace, p, length))
	{
		pdata = (RTCMmessage *)mpool_malloc(GetMemPool(workspace), sizeof(RTCMmessage));
		memset(pdata, 0, sizeof(RTCMmessage));
		if ((ret = ASN1_BER_Data_Dec_RTCMmessage(workspace, pdata, len, ASN1EXPL)) < 0) return ret;
		if ((ret = ASN1_Insert_Node(workspace, value,(void*)pdata)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_RTCMmessageList(RTCMmessageList *value);
extern int ASN1_BER_Data_Dec_RTCMmessageList(ASN1WorkSpace *workspace, RTCMmessageList *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_RTCMmessageList(ASN1WorkSpace *workspace, RTCMmessageList *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_RTCMmessageList(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_RTCMmessageList(value)) < 0) return ret;
	return ret;
}
int ASN1_PER_Align_Data_Enc_RTCMmessageList(ASN1WorkSpace *workspace, RTCMmessageList *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_RTCMmessageList = { ASN1_CONST64(1), ASN1_CONST64(5), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_RTCMmessageList_pdata = { ASN1_CONST64(1), ASN1_CONST64(1023), NULL, 0, CONS, 0, 0 };
	ASNINT32 loop_set = 1;
	ASNINT32 all_length = value->count;
	ASNINT32 process_length = 0;
	ASNINT32 i = 0;
	ASN1ListNode *pnode = value->head->next;
	while(loop_set)
	{
		loop_set = ASN1_PER_Align_Enc_Set_Seq_Of_Length(workspace, &all_length, &process_length, &consinfo_RTCMmessageList);
		for(i = 0; i < process_length; i++)
		{
			if ((ret = ASN1_PER_Align_Enc_RTCMmessage(workspace, pnode->data)) < 0) return ret;
			pnode = pnode->next;
		}
	}
	if (value->count != 0 && value->count % 16384 == 0)
	{
		if ((ret = ASN1_PER_Align_WirteBuffer(workspace)) < 0) return ret;
	}
	return ret;
}
