extern int ASN1_PER_UNAlign_Data_Enc_RegionalExtension(ASN1WorkSpace *workspace, RegionalExtension *value);
int ASN1_PER_UNAlign_Data_Enc_RTCMcorrections_regional(ASN1WorkSpace *workspace, RTCMcorrections_regional *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_RTCMcorrections_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_RTCMcorrections_regional_pdata = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	ASNINT32 loop_set = 1;
	ASNINT32 all_length = value->count;
	ASNINT32 process_length = 0;
	ASNINT32 i = 0;
	ASN1ListNode *pnode = value->head->next;
	while(loop_set)
	{
		loop_set = ASN1_PER_UNAlign_Enc_Set_Seq_Of_Length(workspace, &all_length, &process_length, &consinfo_RTCMcorrections_regional);
		for(i = 0; i < process_length; i++)
		{
			if ((ret = ASN1_PER_UNAlign_Enc_RegionalExtension(workspace, pnode->data)) < 0) return ret;
			pnode = pnode->next;
		}
	}
	if (value->count != 0 && value->count % 16384 == 0)
	{
		if ((ret = ASN1_PER_UNAlign_WirteBuffer(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_RTCMcorrections_regional(RTCMcorrections_regional *value);
extern int ASN1_PER_UNAlign_Data_Enc_RTCMcorrections_regional(ASN1WorkSpace *workspace, RTCMcorrections_regional *value);
int ASN1_PER_UNAlign_Enc_RTCMcorrections_regional(ASN1WorkSpace *workspace, RTCMcorrections_regional *value)
{ // ASN1_PER_Extern_Encode 
	int ret = 0;
	if ((ret = ASN1_CHECK_RTCMcorrections_regional(value)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Data_Enc_RTCMcorrections_regional(workspace,value)) < 0) return ret;
	return ret;
}
extern int ASN1_PER_UNAlign_Data_Dec_RegionalExtension(ASN1WorkSpace *workspace, RegionalExtension *value);
int ASN1_PER_UNAlign_Data_Dec_RTCMcorrections_regional(ASN1WorkSpace *workspace, RTCMcorrections_regional *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_RTCMcorrections_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_RTCMcorrections_regional_pdata = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	ASNINT32 loop_set = 1;
	ASNINT32 process_length = 0;
	ASNINT32 i = 0;
	RegionalExtension *pdata;
	if ((ret = ASN1_Creat_Init_List(workspace, value)) < 0) return ret;
	while(loop_set)
	{
		loop_set = ASN1_PER_UNAlign_Dec_Set_Seq_Of_Length(workspace, &process_length, &consinfo_RTCMcorrections_regional);
		for (i = 0; i < process_length; i++)
		{
			if ((pdata = (RegionalExtension *)mpool_calloc(GetMemPool(workspace), sizeof(RegionalExtension), 1)) == NULL) return -1;
			if ((ret = ASN1_PER_UNAlign_Dec_RegionalExtension(workspace, pdata)) < 0) return ret;
			if ((ret = ASN1_Insert_Node(workspace, value, (void *)pdata)) < 0) return ret;
		}
	}

	return ret;
}
