int ASN1_Print_VehicleID(VehicleID *value, int tab_value)
{
	int ret = 0;
	// CHOICE : t->tempIdentifier is Upper Letter
	ASN1_Print_CHOICE("VehicleID");
	if (value == NULL) return -1;
	switch (value->M) {
	case DEF_VehicleID_entityID:
		// Type OCTET STRING
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_OCTETSTRING("TemporaryID", &value->elements.entityID, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_VehicleID_stationID:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("StationID", &value->elements.stationID)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	default: return -1;
}
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
