int ASN1_CHECK_VehicleID(VehicleID *value)
{
	int ret = 0;

	unsigned char checkinfo_entityID[] = { 
		0x02,0x04,0x04,0x00
	};
	unsigned char checkinfo_stationID[] = { 
		0x02,0x00,0x85,0x00,0xFF,0xFF,0xFF,0xFF,0x00
	};

	if (value == NULL) return -1;
	switch (value->M)
	{
	case DEF_VehicleID_entityID:
		if ((ret = ASN1_CHECK_OCTETSTRING(&value->elements.entityID, checkinfo_entityID)) < 0) return ret;
		break;
	case DEF_VehicleID_stationID:
		if ((ret = ASN1_CHECK_INTEGER(&value->elements.stationID, checkinfo_stationID)) < 0) return ret;
		break;
	default: break;
	}
	return ret;
}
extern int ASN1_BER_Data_Enc_TemporaryID(ASN1WorkSpace *workspace, TemporaryID *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_StationID(ASN1WorkSpace *workspace, StationID *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_VehicleID(ASN1WorkSpace *workspace, VehicleID *value, ASN1TagType tagFlag)
{
	int ret = 0;
	switch(value->M)
	{
	case DEF_VehicleID_entityID:
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_TemporaryID(workspace, &(value->elements.entityID), ASN1IMPL)) < 0) return ret;
		break;
	case DEF_VehicleID_stationID:
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_StationID(workspace, &(value->elements.stationID), ASN1IMPL)) < 0) return ret;
		break;
	}
	return ret;
}
