extern int ASN1_BER_Data_Dec_TemporaryID(ASN1WorkSpace *workspace, TemporaryID *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_StationID(ASN1WorkSpace *workspace, StationID *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_VehicleID(ASN1WorkSpace *workspace, VehicleID *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	value->M = 0;
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	switch(tag)
	{
	case ITS_ASN_CONT | ITS_ASN_PRIM | 0:
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_TemporaryID(workspace, &value->elements.entityID, len, ASN1IMPL)) < 0) return ret;
		value->M = DEF_VehicleID_entityID;
		break;
	case ITS_ASN_CONT | ITS_ASN_PRIM | 1:
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_StationID(workspace, &value->elements.stationID, len, ASN1IMPL)) < 0) return ret;
		value->M = DEF_VehicleID_stationID;
		break;
	}
	return ret;
}
extern int ASN1_CHECK_VehicleID(VehicleID *value);
extern int ASN1_BER_Data_Dec_VehicleID(ASN1WorkSpace *workspace, VehicleID *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_VehicleID(ASN1WorkSpace *workspace, VehicleID *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_VehicleID(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_VehicleID(value)) < 0) return ret;
	return ret;
}
