extern int ASN1_CHECK_VehicleID(VehicleID *value);
extern int ASN1_CHECK_VehicleIdent_vehicleClass(VehicleIdent_vehicleClass *value);
int ASN1_CHECK_VehicleIdent(VehicleIdent *value)
{
	int ret = 0;

	unsigned char checkinfo_name[] = { 
		0x02,0x01,0x3F,0x00
	};
	unsigned char checkinfo_vin[] = { 
		0x02,0x01,0x11,0x00
	};
	unsigned char checkinfo_ownerCode[] = { 
		0x02,0x01,0x20,0x00
	};
	unsigned char checkinfo_id[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_vehicleType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_vehicleClass[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if (value->DEF_VehicleIdent_name == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_IA5String(&(value->name), checkinfo_name)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleIdent_vin == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_OCTETSTRING(&(value->vin), checkinfo_vin)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleIdent_ownerCode == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_IA5String(&(value->ownerCode), checkinfo_ownerCode)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleIdent_id == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_VehicleID(value->id)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleIdent_vehicleType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->vehicleType), checkinfo_vehicleType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleIdent_vehicleClass == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_VehicleIdent_vehicleClass(value->vehicleClass)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_DescriptiveName(ASN1WorkSpace *workspace, DescriptiveName *value, ASN1TagType tagFlag);
