int ASN1_BER_Dec_VehicleClassification_regional(ASN1WorkSpace *workspace, VehicleClassification_regional *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_VehicleClassification_regional(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_VehicleClassification_regional(value)) < 0) return ret;
	return ret;
}
