int ASN1_CHECK_VehicleClassification(VehicleClassification *value)
{
	int ret = 0;

	unsigned char checkinfo_keyType[] = { 
		0x02,0x00,0x82,0x00,0xFF,0x00
	};
	unsigned char checkinfo_role[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_iso3883[] = { 
		0x02,0x00,0x64,0x00
	};
	unsigned char checkinfo_hpmsType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_vehicleType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_responseEquip[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_responderType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_fuelType[] = { 
		0x02,0x00,0x0F,0x00
	};
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_VehicleClassification_keyType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->keyType), checkinfo_keyType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleClassification_role == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->role), checkinfo_role)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleClassification_iso3883 == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->iso3883), checkinfo_iso3883)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleClassification_hpmsType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->hpmsType), checkinfo_hpmsType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleClassification_vehicleType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->vehicleType), checkinfo_vehicleType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleClassification_responseEquip == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->responseEquip), checkinfo_responseEquip)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleClassification_responderType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->responderType), checkinfo_responderType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleClassification_fuelType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->fuelType), checkinfo_fuelType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleClassification_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_VehicleClassification_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
