/********************************************************
*PathHistoryPoint                                       *
********************************************************/
int ASN1_Print_PathHistoryPoint(PathHistoryPoint *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("PathHistoryPoint");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("OffsetLL_B18", &(value->latOffset))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("OffsetLL_B18", &(value->lonOffset))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("VertOffset_B12", &(value->elevationOffset))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("TimeOffset", &(value->timeOffset))) < 0) return ret;
	if (value->DEF_PathHistoryPoint_speed == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("Speed", &(value->speed))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PathHistoryPoint_posAccuracy == 1)
	{ /*OPTIONAL start */
		// Type Reference PositionalAccuracy
		if (Compare_Letter(tab_value, "posAccuracy")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("posAccuracy = ");
		}
		if ((ret = ASN1_Print_PositionalAccuracy((PositionalAccuracy *)value->posAccuracy, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PathHistoryPoint_heading == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("CoarseHeading", &(value->heading))) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
