extern int ASN1_PER_Align_Data_Dec_PathHistoryPointList(ASN1WorkSpace *workspace, PathHistoryPointList *value);
int ASN1_PER_Align_Data_Dec_PathHistory(ASN1WorkSpace *workspace, PathHistory *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_initialPosition = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_currGNSSstatus = { ASN1_CONST64(8), ASN1_CONST64(8), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_crumbData = { ASN1_CONST64(1), ASN1_CONST64(23), NULL, 0, CONS, 0, 0 };

	ASNBOOL extbit_PathHistory;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_PathHistory)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 2, &_optvalue)) < 0) return ret;
	value->initialPosition = (FullPositionVector *)mpool_malloc(workspace->Pmemory, sizeof(FullPositionVector));
	memset(value->initialPosition, 0, sizeof(FullPositionVector));
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_PathHistory_initialPosition = 1;
		if ((ret = ASN1_PER_Align_Dec_FullPositionVector(workspace, value->initialPosition)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_PathHistory_currGNSSstatus = 1;
		if ((ret = ASN1_PER_Align_Dec_BITSTRING(workspace, &(value->currGNSSstatus), &consinfo_currGNSSstatus)) < 0) return ret;
	}
	if ((ret = ASN1_PER_Align_Dec_PathHistoryPointList(workspace, &(value->crumbData))) < 0) return ret;
	if (extbit_PathHistory == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, ALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, ALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
