int ASN1_CHECK_PathPrediction(PathPrediction *value)
{
	int ret = 0;

	unsigned char checkinfo_radiusOfCurve[] = { 
		0x02,0x82,0x80,0x01,0x82,0x7F,0xFF,0x00
	};
	unsigned char checkinfo_confidence[] = { 
		0x02,0x00,0x82,0x00,0xC8,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->radiusOfCurve), checkinfo_radiusOfCurve)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->confidence), checkinfo_confidence)) < 0) return ret;
	return ret;
}
