extern int ASN1_BER_Data_Enc_Confidence(ASN1WorkSpace *workspace, Confidence *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_PathPrediction(ASN1WorkSpace *workspace, PathPrediction *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_RadiusOfCurvature(workspace, &(value->radiusOfCurve), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_Confidence(workspace, &(value->confidence), ASN1IMPL)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
