int ASN1_Print_VehicleSafetyExtensions(VehicleSafetyExtensions *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("VehicleSafetyExtensions");
	if (value->DEF_VehicleSafetyExtensions_events == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("VehicleEventFlags", &(value->events))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleSafetyExtensions_pathHistory == 1)
	{ /*OPTIONAL start */
		// Type Reference PathHistory
		if (Compare_Letter(tab_value, "pathHistory")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("pathHistory = ");
		}
		if ((ret = ASN1_Print_PathHistory((PathHistory *)value->pathHistory, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleSafetyExtensions_pathPrediction == 1)
	{ /*OPTIONAL start */
		// Type Reference PathPrediction
		if (Compare_Letter(tab_value, "pathPrediction")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("pathPrediction = ");
		}
		if ((ret = ASN1_Print_PathPrediction((PathPrediction *)value->pathPrediction, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleSafetyExtensions_lights == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("ExteriorLights", &(value->lights))) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
