int ASN1_CHECK_VehicleSafetyExtensions(VehicleSafetyExtensions *value)
{
	int ret = 0;

	unsigned char checkinfo_events[] = { 
		0x02,0x0D,0x0D,0xCC,0x00
	};
	unsigned char checkinfo_pathHistory[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_pathPrediction[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_lights[] = { 
		0x02,0x09,0x09,0xCC,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_VehicleSafetyExtensions_events == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BITSTRING(&(value->events), checkinfo_events)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleSafetyExtensions_pathHistory == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_PathHistory(value->pathHistory)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleSafetyExtensions_pathPrediction == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_PathPrediction(value->pathPrediction)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleSafetyExtensions_lights == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BITSTRING(&(value->lights), checkinfo_lights)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
