int ASN1_PER_UNAlign_Data_Enc_VehicleSafetyExtensions(ASN1WorkSpace *workspace, VehicleSafetyExtensions *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_events = { ASN1_CONST64(13), ASN1_CONST64(13), NULL, 1, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_pathHistory = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_pathPrediction = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_lights = { ASN1_CONST64(9), ASN1_CONST64(9), NULL, 1, CONS, 0, 0 };

	ASNINT32 all_bit;
	ASNUINT16 all_pointer;
	if ((ret = ASN1_PER_Enc_extbit(workspace, value->E)) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_VehicleSafetyExtensions_events == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_VehicleSafetyExtensions_pathHistory == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_VehicleSafetyExtensions_pathPrediction == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_VehicleSafetyExtensions_lights == 1 ? 1 : 0) )) < 0) return ret;
	if (value->DEF_VehicleSafetyExtensions_events == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_BITSTRING(workspace, &(value->events), &consinfo_events)) < 0) return ret;
	}
	if (value->DEF_VehicleSafetyExtensions_pathHistory == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_PathHistory(workspace, value->pathHistory)) < 0) return ret;
	}
	if (value->DEF_VehicleSafetyExtensions_pathPrediction == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_PathPrediction(workspace, value->pathPrediction)) < 0) return ret;
	}
	if (value->DEF_VehicleSafetyExtensions_lights == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_BITSTRING(workspace, &(value->lights), &consinfo_lights)) < 0) return ret;
	}
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, UNALIGN, 0);
	}
	return ret;
}
