extern int ASN1_PER_UNAlign_Data_Dec_PathHistory(ASN1WorkSpace *workspace, PathHistory *value);
extern int ASN1_PER_UNAlign_Data_Dec_PathPrediction(ASN1WorkSpace *workspace, PathPrediction *value);
int ASN1_PER_UNAlign_Data_Dec_VehicleSafetyExtensions(ASN1WorkSpace *workspace, VehicleSafetyExtensions *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_events = { ASN1_CONST64(13), ASN1_CONST64(13), NULL, 1, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_pathHistory = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_pathPrediction = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_lights = { ASN1_CONST64(9), ASN1_CONST64(9), NULL, 1, CONS, 0, 0 };

	ASNBOOL extbit_VehicleSafetyExtensions;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_VehicleSafetyExtensions)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 4, &_optvalue)) < 0) return ret;
	value->pathHistory = (PathHistory *)mpool_malloc(workspace->Pmemory, sizeof(PathHistory));
	memset(value->pathHistory, 0, sizeof(PathHistory));
	value->pathPrediction = (PathPrediction *)mpool_malloc(workspace->Pmemory, sizeof(PathPrediction));
	memset(value->pathPrediction, 0, sizeof(PathPrediction));
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_VehicleSafetyExtensions_events = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_BITSTRING(workspace, &(value->events), &consinfo_events)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_VehicleSafetyExtensions_pathHistory = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_PathHistory(workspace, value->pathHistory)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 3) == 1)
	{
		value->DEF_VehicleSafetyExtensions_pathPrediction = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_PathPrediction(workspace, value->pathPrediction)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 4) == 1)
	{
		value->DEF_VehicleSafetyExtensions_lights = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_BITSTRING(workspace, &(value->lights), &consinfo_lights)) < 0) return ret;
	}
	if (extbit_VehicleSafetyExtensions == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, UNALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, UNALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
extern int ASN1_CHECK_VehicleSafetyExtensions(VehicleSafetyExtensions *value);
extern int ASN1_PER_UNAlign_Data_Dec_VehicleSafetyExtensions(ASN1WorkSpace *workspace, VehicleSafetyExtensions *value);
