int ASN1_Print_WiperSet(WiperSet *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("WiperSet");
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->statusFront)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("WiperStatus", "unavailable", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("WiperStatus", "off", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("WiperStatus", "intermittent", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("WiperStatus", "low", 3)) < 0) return ret; break;
	case 4: if ((ret = ASN1_Print_ENUMERATED("WiperStatus", "high", 4)) < 0) return ret; break;
	case 5: if ((ret = ASN1_Print_ENUMERATED("WiperStatus", "washerInUse", 5)) < 0) return ret; break;
	case 6: if ((ret = ASN1_Print_ENUMERATED("WiperStatus", "automaticPresent", 6)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("WiperRate", &(value->rateFront))) < 0) return ret;
	if (value->DEF_WiperSet_statusRear == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->statusRear)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("WiperStatus", "unavailable", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("WiperStatus", "off", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("WiperStatus", "intermittent", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("WiperStatus", "low", 3)) < 0) return ret; break;
		case 4: if ((ret = ASN1_Print_ENUMERATED("WiperStatus", "high", 4)) < 0) return ret; break;
		case 5: if ((ret = ASN1_Print_ENUMERATED("WiperStatus", "washerInUse", 5)) < 0) return ret; break;
		case 6: if ((ret = ASN1_Print_ENUMERATED("WiperStatus", "automaticPresent", 6)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	if (value->DEF_WiperSet_rateRear == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("WiperRate", &(value->rateRear))) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
