int ASN1_CHECK_WiperSet(WiperSet *value)
{
	int ret = 0;

	unsigned char checkinfo_statusFront[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_rateFront[] = { 
		0x02,0x00,0x7F,0x00
	};
	unsigned char checkinfo_statusRear[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_rateRear[] = { 
		0x02,0x00,0x7F,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->statusFront), checkinfo_statusFront)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->rateFront), checkinfo_rateFront)) < 0) return ret;
	if (value->DEF_WiperSet_statusRear == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->statusRear), checkinfo_statusRear)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_WiperSet_rateRear == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->rateRear), checkinfo_rateRear)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
