int ASN1_CHECK_VehicleStatus_steering(VehicleStatus_steering *value)
{
	int ret = 0;

	unsigned char checkinfo_angle[] = { 
		0x02,0x81,0x82,0x7F,0x00
	};
	unsigned char checkinfo_confidence[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_rate[] = { 
		0x02,0x81,0x81,0x7F,0x00
	};
	unsigned char checkinfo_wheels[] = { 
		0x02,0x82,0xFF,0x80,0x7F,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->angle), checkinfo_angle)) < 0) return ret;
	if (value->DEF_VehicleStatus_steering_confidence == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->confidence), checkinfo_confidence)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_steering_rate == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->rate), checkinfo_rate)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_steering_wheels == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->wheels), checkinfo_wheels)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_SteeringWheelAngle(ASN1WorkSpace *workspace, SteeringWheelAngle *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_SteeringWheelAngleConfidence(ASN1WorkSpace *workspace, SteeringWheelAngleConfidence *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_SteeringWheelAngleRateOfChange(ASN1WorkSpace *workspace, SteeringWheelAngleRateOfChange *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_DrivingWheelAngle(ASN1WorkSpace *workspace, DrivingWheelAngle *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_VehicleStatus_steering(ASN1WorkSpace *workspace, VehicleStatus_steering *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_SteeringWheelAngle(workspace, &(value->angle), ASN1IMPL)) < 0) return ret;
	if (value->DEF_VehicleStatus_steering_confidence == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_SteeringWheelAngleConfidence(workspace, &(value->confidence), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_VehicleStatus_steering_rate == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_SteeringWheelAngleRateOfChange(workspace, &(value->rate), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_VehicleStatus_steering_wheels == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_DrivingWheelAngle(workspace, &(value->wheels), ASN1IMPL)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
