	if (value->DEF_VehicleStatus_steering_wheels == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->wheels), &consinfo_wheels)) < 0) return ret;
	}
	return ret;
