extern int ASN1_BER_Data_Dec_YawRateConfidence(ASN1WorkSpace *workspace, YawRateConfidence *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_AccelerationConfidence(ASN1WorkSpace *workspace, AccelerationConfidence *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_SteeringWheelAngleConfidence(ASN1WorkSpace *workspace, SteeringWheelAngleConfidence *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_AccelSteerYawRateConfidence(ASN1WorkSpace *workspace, AccelSteerYawRateConfidence *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_YawRateConfidence(workspace, &value->yawRate, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_AccelerationConfidence(workspace, &value->acceleration, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_SteeringWheelAngleConfidence(workspace, &value->steeringWheelAngle, len, ASN1IMPL)) < 0) return ret;
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
