extern int ASN1_CHECK_AccelSteerYawRateConfidence(AccelSteerYawRateConfidence *value);
extern int ASN1_CHECK_SpeedandHeadingandThrottleConfidence(SpeedandHeadingandThrottleConfidence *value);
extern int ASN1_CHECK_PositionConfidenceSet(PositionConfidenceSet *value);
int ASN1_CHECK_ConfidenceSet(ConfidenceSet *value)
{
	int ret = 0;

	unsigned char checkinfo_accelConfidence[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_speedConfidence[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_timeConfidence[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_posConfidence[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_steerConfidence[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_headingConfidence[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_throttleConfidence[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if (value->DEF_ConfidenceSet_accelConfidence == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_AccelSteerYawRateConfidence(value->accelConfidence)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ConfidenceSet_speedConfidence == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_SpeedandHeadingandThrottleConfidence(value->speedConfidence)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ConfidenceSet_timeConfidence == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->timeConfidence), checkinfo_timeConfidence)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ConfidenceSet_posConfidence == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_PositionConfidenceSet(value->posConfidence)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ConfidenceSet_steerConfidence == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->steerConfidence), checkinfo_steerConfidence)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ConfidenceSet_headingConfidence == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->headingConfidence), checkinfo_headingConfidence)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ConfidenceSet_throttleConfidence == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->throttleConfidence), checkinfo_throttleConfidence)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_AccelSteerYawRateConfidence(ASN1WorkSpace *workspace, AccelSteerYawRateConfidence *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_SpeedandHeadingandThrottleConfidence(ASN1WorkSpace *workspace, SpeedandHeadingandThrottleConfidence *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_TimeConfidence(ASN1WorkSpace *workspace, TimeConfidence *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_PositionConfidenceSet(ASN1WorkSpace *workspace, PositionConfidenceSet *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_SteeringWheelAngleConfidence(ASN1WorkSpace *workspace, SteeringWheelAngleConfidence *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_HeadingConfidence(ASN1WorkSpace *workspace, HeadingConfidence *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_ThrottleConfidence(ASN1WorkSpace *workspace, ThrottleConfidence *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_ConfidenceSet(ASN1WorkSpace *workspace, ConfidenceSet *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if (value->DEF_ConfidenceSet_accelConfidence == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_AccelSteerYawRateConfidence(workspace, value->accelConfidence, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_ConfidenceSet_speedConfidence == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_SpeedandHeadingandThrottleConfidence(workspace, value->speedConfidence, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_ConfidenceSet_timeConfidence == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_TimeConfidence(workspace, &(value->timeConfidence), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_ConfidenceSet_posConfidence == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 3)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_PositionConfidenceSet(workspace, value->posConfidence, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_ConfidenceSet_steerConfidence == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 4)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_SteeringWheelAngleConfidence(workspace, &(value->steerConfidence), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_ConfidenceSet_headingConfidence == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 5)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_HeadingConfidence(workspace, &(value->headingConfidence), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_ConfidenceSet_throttleConfidence == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 6)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_ThrottleConfidence(workspace, &(value->throttleConfidence), ASN1IMPL)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_ConfidenceSet(ConfidenceSet *value);
extern int ASN1_BER_Data_Enc_ConfidenceSet(ASN1WorkSpace *workspace, ConfidenceSet *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_ConfidenceSet(ASN1WorkSpace *workspace, ConfidenceSet *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_ConfidenceSet(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_ConfidenceSet(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
