int ASN1_Print_VehicleStatus_accelSets(VehicleStatus_accelSets *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : default
	ASN1_Print_SEQ(" ");
	if (value->DEF_VehicleStatus_accelSets_accel4way == 1)
	{ /*OPTIONAL start */
		// Type Reference AccelerationSet4Way
		if (Compare_Letter(tab_value, "accel4way")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("accel4way = ");
		}
		if ((ret = ASN1_Print_AccelerationSet4Way((AccelerationSet4Way *)value->accel4way, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_accelSets_vertAccelThres == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("VerticalAccelerationThreshold", &(value->vertAccelThres))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_accelSets_yawRateCon == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->yawRateCon)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("YawRateConfidence", "unavailable", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("YawRateConfidence", "degSec-100-00", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("YawRateConfidence", "degSec-010-00", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("YawRateConfidence", "degSec-005-00", 3)) < 0) return ret; break;
		case 4: if ((ret = ASN1_Print_ENUMERATED("YawRateConfidence", "degSec-001-00", 4)) < 0) return ret; break;
		case 5: if ((ret = ASN1_Print_ENUMERATED("YawRateConfidence", "degSec-000-10", 5)) < 0) return ret; break;
		case 6: if ((ret = ASN1_Print_ENUMERATED("YawRateConfidence", "degSec-000-05", 6)) < 0) return ret; break;
		case 7: if ((ret = ASN1_Print_ENUMERATED("YawRateConfidence", "degSec-000-01", 7)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_accelSets_hozAccelCon == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->hozAccelCon)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("AccelerationConfidence", "unavailable", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("AccelerationConfidence", "accl-100-00", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("AccelerationConfidence", "accl-010-00", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("AccelerationConfidence", "accl-005-00", 3)) < 0) return ret; break;
		case 4: if ((ret = ASN1_Print_ENUMERATED("AccelerationConfidence", "accl-001-00", 4)) < 0) return ret; break;
		case 5: if ((ret = ASN1_Print_ENUMERATED("AccelerationConfidence", "accl-000-10", 5)) < 0) return ret; break;
		case 6: if ((ret = ASN1_Print_ENUMERATED("AccelerationConfidence", "accl-000-05", 6)) < 0) return ret; break;
		case 7: if ((ret = ASN1_Print_ENUMERATED("AccelerationConfidence", "accl-000-01", 7)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_accelSets_confidenceSet == 1)
	{ /*OPTIONAL start */
		// Type Reference ConfidenceSet
		if (Compare_Letter(tab_value, "confidenceSet")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("confidenceSet = ");
		}
		if ((ret = ASN1_Print_ConfidenceSet((ConfidenceSet *)value->confidenceSet, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
