int ASN1_Print_VehicleStatus_object(VehicleStatus_object *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : default
	ASN1_Print_SEQ(" ");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("ObstacleDistance", &(value->obDist))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("Angle", &(value->obDirect))) < 0) return ret;
	// Type Reference DDateTime
	if (Compare_Letter(tab_value, "dateTime")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("dateTime = ");
	}
	if ((ret = ASN1_Print_DDateTime((DDateTime *)value->dateTime, tab_value + 1)) < 0) return ret;
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
