extern int ASN1_CHECK_DDateTime(DDateTime *value);
int ASN1_CHECK_VehicleStatus_object(VehicleStatus_object *value)
{
	int ret = 0;

	unsigned char checkinfo_obDist[] = { 
		0x02,0x00,0x82,0x7F,0xFF,0x00
	};
	unsigned char checkinfo_obDirect[] = { 
		0x02,0x00,0x82,0x70,0x80,0x00
	};
	unsigned char checkinfo_dateTime[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->obDist), checkinfo_obDist)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->obDirect), checkinfo_obDirect)) < 0) return ret;
	if ((ret = ASN1_CHECK_DDateTime(value->dateTime)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Enc_ObstacleDistance(ASN1WorkSpace *workspace, ObstacleDistance *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_Angle(ASN1WorkSpace *workspace, Angle *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_DDateTime(ASN1WorkSpace *workspace, DDateTime *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_VehicleStatus_object(ASN1WorkSpace *workspace, VehicleStatus_object *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_ObstacleDistance(workspace, &(value->obDist), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_Angle(workspace, &(value->obDirect), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_DDateTime(workspace, value->dateTime, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_VehicleStatus_object(VehicleStatus_object *value);
extern int ASN1_BER_Data_Enc_VehicleStatus_object(ASN1WorkSpace *workspace, VehicleStatus_object *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_VehicleStatus_object(ASN1WorkSpace *workspace, VehicleStatus_object *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_VehicleStatus_object(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_VehicleStatus_object(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_ObstacleDistance(ASN1WorkSpace *workspace, ObstacleDistance *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_Angle(ASN1WorkSpace *workspace, Angle *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_DDateTime(ASN1WorkSpace *workspace, DDateTime *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_VehicleStatus_object(ASN1WorkSpace *workspace, VehicleStatus_object *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT8 *_cpointer;
	value->dateTime = (DDateTime *)mpool_malloc(workspace->Pmemory, sizeof(DDateTime));
	memset(value->dateTime, 0, sizeof(DDateTime));
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_ObstacleDistance(workspace, &value->obDist, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_Angle(workspace, &value->obDirect, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_DDateTime(workspace, value->dateTime, len, ASN1IMPL)) < 0) return ret;
	if (IfFixedLength(len) == -1)
	{
		if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_VehicleStatus_object(VehicleStatus_object *value);
extern int ASN1_BER_Data_Dec_VehicleStatus_object(ASN1WorkSpace *workspace, VehicleStatus_object *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_VehicleStatus_object(ASN1WorkSpace *workspace, VehicleStatus_object *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_VehicleStatus_object(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_VehicleStatus_object(value)) < 0) return ret;
	return ret;
}
