/********************************************************
*VehicleStatus_vehicleData                              *
********************************************************/
int ASN1_Print_VehicleStatus_vehicleData(VehicleStatus_vehicleData *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : default
	ASN1_Print_SEQ(" ");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("VehicleHeight", &(value->height))) < 0) return ret;
	// Type Reference BumperHeights
	if (Compare_Letter(tab_value, "bumpers")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("bumpers = ");
	}
	if ((ret = ASN1_Print_BumperHeights((BumperHeights *)value->bumpers, tab_value + 1)) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("VehicleMass", &(value->mass))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("TrailerWeight", &(value->trailerWeight))) < 0) return ret;
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->type)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("VehicleType", "none", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("VehicleType", "unknown", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("VehicleType", "special", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("VehicleType", "moto", 3)) < 0) return ret; break;
	case 4: if ((ret = ASN1_Print_ENUMERATED("VehicleType", "car", 4)) < 0) return ret; break;
	case 5: if ((ret = ASN1_Print_ENUMERATED("VehicleType", "carOther", 5)) < 0) return ret; break;
	case 6: if ((ret = ASN1_Print_ENUMERATED("VehicleType", "bus", 6)) < 0) return ret; break;
	case 7: if ((ret = ASN1_Print_ENUMERATED("VehicleType", "axleCnt2", 7)) < 0) return ret; break;
	case 8: if ((ret = ASN1_Print_ENUMERATED("VehicleType", "axleCnt3", 8)) < 0) return ret; break;
	case 9: if ((ret = ASN1_Print_ENUMERATED("VehicleType", "axleCnt4", 9)) < 0) return ret; break;
	case 10: if ((ret = ASN1_Print_ENUMERATED("VehicleType", "axleCnt4Trailer", 10)) < 0) return ret; break;
	case 11: if ((ret = ASN1_Print_ENUMERATED("VehicleType", "axleCnt5Trailer", 11)) < 0) return ret; break;
	case 12: if ((ret = ASN1_Print_ENUMERATED("VehicleType", "axleCnt6Trailer", 12)) < 0) return ret; break;
	case 13: if ((ret = ASN1_Print_ENUMERATED("VehicleType", "axleCnt5MultiTrailer", 13)) < 0) return ret; break;
	case 14: if ((ret = ASN1_Print_ENUMERATED("VehicleType", "axleCnt6MultiTrailer", 14)) < 0) return ret; break;
	case 15: if ((ret = ASN1_Print_ENUMERATED("VehicleType", "axleCnt7MultiTrailer", 15)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
