/********************************************************
*TireData                                               *
********************************************************/
int ASN1_Print_TireData(TireData *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("TireData");
	if (value->DEF_TireData_location == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("TireLocation", &(value->location))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TireData_pressure == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("TirePressure", &(value->pressure))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TireData_temp == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("TireTemp", &(value->temp))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TireData_wheelSensorStatus == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->wheelSensorStatus)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("WheelSensorStatus", "off", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("WheelSensorStatus", "on", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("WheelSensorStatus", "notDefined", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("WheelSensorStatus", "notSupported", 3)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	if (value->DEF_TireData_wheelEndElectFault == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->wheelEndElectFault)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("WheelEndElectFault", "isOk", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("WheelEndElectFault", "isNotDefined", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("WheelEndElectFault", "isError", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("WheelEndElectFault", "isNotSupported", 3)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	if (value->DEF_TireData_leakageRate == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("TireLeakageRate", &(value->leakageRate))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TireData_detection == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->detection)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("TirePressureThresholdDetection", "noData", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("TirePressureThresholdDetection", "overPressure", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("TirePressureThresholdDetection", "noWarningPressure", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("TirePressureThresholdDetection", "underPressure", 3)) < 0) return ret; break;
		case 4: if ((ret = ASN1_Print_ENUMERATED("TirePressureThresholdDetection", "extremeUnderPressure", 4)) < 0) return ret; break;
		case 5: if ((ret = ASN1_Print_ENUMERATED("TirePressureThresholdDetection", "undefined", 5)) < 0) return ret; break;
		case 6: if ((ret = ASN1_Print_ENUMERATED("TirePressureThresholdDetection", "errorIndicator", 6)) < 0) return ret; break;
		case 7: if ((ret = ASN1_Print_ENUMERATED("TirePressureThresholdDetection", "notAvailable", 7)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
