int ASN1_CHECK_TireData(TireData *value)
{
	int ret = 0;

	unsigned char checkinfo_location[] = { 
		0x02,0x00,0x82,0x00,0xFF,0x00
	};
	unsigned char checkinfo_pressure[] = { 
		0x02,0x00,0x82,0x00,0xFA,0x00
	};
	unsigned char checkinfo_temp[] = { 
		0x02,0x82,0xDD,0xE0,0x83,0x00,0xD8,0xDF,0x00
	};
	unsigned char checkinfo_wheelSensorStatus[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_wheelEndElectFault[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_leakageRate[] = { 
		0x02,0x00,0x83,0x00,0xFA,0xFF,0x00
	};
	unsigned char checkinfo_detection[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if (value->DEF_TireData_location == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->location), checkinfo_location)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TireData_pressure == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->pressure), checkinfo_pressure)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TireData_temp == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->temp), checkinfo_temp)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TireData_wheelSensorStatus == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->wheelSensorStatus), checkinfo_wheelSensorStatus)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TireData_wheelEndElectFault == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->wheelEndElectFault), checkinfo_wheelEndElectFault)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TireData_leakageRate == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->leakageRate), checkinfo_leakageRate)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TireData_detection == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->detection), checkinfo_detection)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
