extern int ASN1_BER_Data_Enc_TireTemp(ASN1WorkSpace *workspace, TireTemp *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_WheelSensorStatus(ASN1WorkSpace *workspace, WheelSensorStatus *value, ASN1TagType tagFlag);
