extern int ASN1_BER_Data_Enc_TireLeakageRate(ASN1WorkSpace *workspace, TireLeakageRate *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_TirePressureThresholdDetection(ASN1WorkSpace *workspace, TirePressureThresholdDetection *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_TireData(ASN1WorkSpace *workspace, TireData *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if (value->DEF_TireData_location == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_TireLocation(workspace, &(value->location), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_TireData_pressure == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_TirePressure(workspace, &(value->pressure), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_TireData_temp == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_TireTemp(workspace, &(value->temp), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_TireData_wheelSensorStatus == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_WheelSensorStatus(workspace, &(value->wheelSensorStatus), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_TireData_wheelEndElectFault == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 4)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_WheelEndElectFault(workspace, &(value->wheelEndElectFault), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_TireData_leakageRate == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 5)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_TireLeakageRate(workspace, &(value->leakageRate), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_TireData_detection == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 6)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_TirePressureThresholdDetection(workspace, &(value->detection), ASN1IMPL)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
