extern int ASN1_BER_Data_Dec_TireLocation(ASN1WorkSpace *workspace, TireLocation *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_TirePressure(ASN1WorkSpace *workspace, TirePressure *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_TireTemp(ASN1WorkSpace *workspace, TireTemp *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_WheelSensorStatus(ASN1WorkSpace *workspace, WheelSensorStatus *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_WheelEndElectFault(ASN1WorkSpace *workspace, WheelEndElectFault *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_TireLeakageRate(ASN1WorkSpace *workspace, TireLeakageRate *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_TirePressureThresholdDetection(ASN1WorkSpace *workspace, TirePressureThresholdDetection *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_TireData(ASN1WorkSpace *workspace, TireData *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 0))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_TireLocation(workspace, &value->location, len, ASN1IMPL)) < 0) return ret;
		value->DEF_TireData_location = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 1))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_TirePressure(workspace, &value->pressure, len, ASN1IMPL)) < 0) return ret;
		value->DEF_TireData_pressure = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 2))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_TireTemp(workspace, &value->temp, len, ASN1IMPL)) < 0) return ret;
		value->DEF_TireData_temp = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 3))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_WheelSensorStatus(workspace, &value->wheelSensorStatus, len, ASN1IMPL)) < 0) return ret;
		value->DEF_TireData_wheelSensorStatus = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 4))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 4)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_WheelEndElectFault(workspace, &value->wheelEndElectFault, len, ASN1IMPL)) < 0) return ret;
		value->DEF_TireData_wheelEndElectFault = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 5))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 5)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_TireLeakageRate(workspace, &value->leakageRate, len, ASN1IMPL)) < 0) return ret;
		value->DEF_TireData_leakageRate = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 6))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 6)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_TirePressureThresholdDetection(workspace, &value->detection, len, ASN1IMPL)) < 0) return ret;
		value->DEF_TireData_detection = 1;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_TireData(TireData *value);
extern int ASN1_BER_Data_Dec_TireData(ASN1WorkSpace *workspace, TireData *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_TireData(ASN1WorkSpace *workspace, TireData *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_TireData(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_TireData(value)) < 0) return ret;
	return ret;
}
int ASN1_PER_Align_Data_Enc_TireData(ASN1WorkSpace *workspace, TireData *value)
{
	int ret = 0;
	ASNINT32 ui_wheelSensorStatus;
	ASNINT32 ui_wheelEndElectFault;
	ASNINT32 ui_detection;
	struct Asn1ConsInfo consinfo_location = { ASN1_CONST64(0), ASN1_CONST64(255), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_pressure = { ASN1_CONST64(0), ASN1_CONST64(250), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_temp = { ASN1_CONST64(-8736), ASN1_CONST64(55519), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_wheelSensorStatus = { ASN1_CONST64(0), ASN1_CONST64(3), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_wheelEndElectFault = { ASN1_CONST64(0), ASN1_CONST64(3), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_leakageRate = { ASN1_CONST64(0), ASN1_CONST64(64255), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_detection = { ASN1_CONST64(0), ASN1_CONST64(7), NULL, 0, CONS, 0, 0 };

	ASNINT32 all_bit;
	ASNUINT16 all_pointer;
	if ((ret = ASN1_PER_Enc_extbit(workspace, value->E)) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_TireData_location == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_TireData_pressure == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_TireData_temp == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_TireData_wheelSensorStatus == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_TireData_wheelEndElectFault == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_TireData_leakageRate == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_TireData_detection == 1 ? 1 : 0) )) < 0) return ret;
	if (value->DEF_TireData_location == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->location), &consinfo_location)) < 0) return ret;
	}
	if (value->DEF_TireData_pressure == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->pressure), &consinfo_pressure)) < 0) return ret;
	}
	if (value->DEF_TireData_temp == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->temp), &consinfo_temp)) < 0) return ret;
	}
	if (value->DEF_TireData_wheelSensorStatus == 1)
	{
		switch(value->wheelSensorStatus)
		{
		case WheelSensorStatus_off: ui_wheelSensorStatus = 0; consinfo_wheelSensorStatus.enumextbit = 0; break;
		case WheelSensorStatus_on: ui_wheelSensorStatus = 1; consinfo_wheelSensorStatus.enumextbit = 0; break;
		case WheelSensorStatus_notDefined: ui_wheelSensorStatus = 2; consinfo_wheelSensorStatus.enumextbit = 0; break;
		case WheelSensorStatus_notSupported: ui_wheelSensorStatus = 3; consinfo_wheelSensorStatus.enumextbit = 0; break;
		default: ui_wheelSensorStatus = value->wheelSensorStatus; consinfo_wheelSensorStatus.enumextbit = 0;break;
		}
		if ((ret = ASN1_PER_Align_Enc_ENUMERATED(workspace, ui_wheelSensorStatus, &consinfo_wheelSensorStatus)) < 0) return ret;
	}
	if (value->DEF_TireData_wheelEndElectFault == 1)
	{
		switch(value->wheelEndElectFault)
		{
		case WheelEndElectFault_isOk: ui_wheelEndElectFault = 0; consinfo_wheelEndElectFault.enumextbit = 0; break;
		case WheelEndElectFault_isNotDefined: ui_wheelEndElectFault = 1; consinfo_wheelEndElectFault.enumextbit = 0; break;
		case WheelEndElectFault_isError: ui_wheelEndElectFault = 2; consinfo_wheelEndElectFault.enumextbit = 0; break;
		case WheelEndElectFault_isNotSupported: ui_wheelEndElectFault = 3; consinfo_wheelEndElectFault.enumextbit = 0; break;
		default: ui_wheelEndElectFault = value->wheelEndElectFault; consinfo_wheelEndElectFault.enumextbit = 0;break;
		}
		if ((ret = ASN1_PER_Align_Enc_ENUMERATED(workspace, ui_wheelEndElectFault, &consinfo_wheelEndElectFault)) < 0) return ret;
	}
	if (value->DEF_TireData_leakageRate == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->leakageRate), &consinfo_leakageRate)) < 0) return ret;
	}
	if (value->DEF_TireData_detection == 1)
	{
		switch(value->detection)
		{
		case TirePressureThresholdDetection_noData: ui_detection = 0; consinfo_detection.enumextbit = 0; break;
		case TirePressureThresholdDetection_overPressure: ui_detection = 1; consinfo_detection.enumextbit = 0; break;
		case TirePressureThresholdDetection_noWarningPressure: ui_detection = 2; consinfo_detection.enumextbit = 0; break;
		case TirePressureThresholdDetection_underPressure: ui_detection = 3; consinfo_detection.enumextbit = 0; break;
		case TirePressureThresholdDetection_extremeUnderPressure: ui_detection = 4; consinfo_detection.enumextbit = 0; break;
		case TirePressureThresholdDetection_undefined: ui_detection = 5; consinfo_detection.enumextbit = 0; break;
		case TirePressureThresholdDetection_errorIndicator: ui_detection = 6; consinfo_detection.enumextbit = 0; break;
		case TirePressureThresholdDetection_notAvailable: ui_detection = 7; consinfo_detection.enumextbit = 0; break;
		default: ui_detection = value->detection; consinfo_detection.enumextbit = 0;break;
		}
		if ((ret = ASN1_PER_Align_Enc_ENUMERATED(workspace, ui_detection, &consinfo_detection)) < 0) return ret;
	}
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, ALIGN, 0);
	}
	return ret;
}
