int ASN1_PER_Align_Data_Enc_AxleWeightSet(ASN1WorkSpace *workspace, AxleWeightSet *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_location = { ASN1_CONST64(0), ASN1_CONST64(255), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_weight = { ASN1_CONST64(0), ASN1_CONST64(64255), NULL, 0, CONS, 0, 0 };

	ASNINT32 all_bit;
	ASNUINT16 all_pointer;
	if ((ret = ASN1_PER_Enc_extbit(workspace, value->E)) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_AxleWeightSet_location == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_AxleWeightSet_weight == 1 ? 1 : 0) )) < 0) return ret;
	if (value->DEF_AxleWeightSet_location == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->location), &consinfo_location)) < 0) return ret;
	}
	if (value->DEF_AxleWeightSet_weight == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->weight), &consinfo_weight)) < 0) return ret;
	}
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, ALIGN, 0);
	}
	return ret;
}
