int ASN1_PER_UNAlign_Data_Dec_AxleWeightSet(ASN1WorkSpace *workspace, AxleWeightSet *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_location = { ASN1_CONST64(0), ASN1_CONST64(255), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_weight = { ASN1_CONST64(0), ASN1_CONST64(64255), NULL, 0, CONS, 0, 0 };

	ASNBOOL extbit_AxleWeightSet;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_AxleWeightSet)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 2, &_optvalue)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_AxleWeightSet_location = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->location), &consinfo_location)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_AxleWeightSet_weight = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->weight), &consinfo_weight)) < 0) return ret;
	}
	if (extbit_AxleWeightSet == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, UNALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, UNALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
