/********************************************************
*J1939DataItems                                         *
********************************************************/
int ASN1_Print_J1939DataItems(J1939DataItems *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("J1939DataItems");
	if (value->DEF_J1939DataItems_tires == 1)
	{ /*OPTIONAL start */
		// Type Reference TireDataList
		if (Compare_Letter(tab_value, "tires")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("tires = ");
		}
		if ((ret = ASN1_Print_TireDataList((TireDataList *)&(value->tires), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_J1939DataItems_axles == 1)
	{ /*OPTIONAL start */
		// Type Reference AxleWeightList
		if (Compare_Letter(tab_value, "axles")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("axles = ");
		}
		if ((ret = ASN1_Print_AxleWeightList((AxleWeightList *)&(value->axles), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_J1939DataItems_trailerWeight == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("TrailerWeight", &(value->trailerWeight))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_J1939DataItems_cargoWeight == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("CargoWeight", &(value->cargoWeight))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_J1939DataItems_steeringAxleTemperature == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("SteeringAxleTemperature", &(value->steeringAxleTemperature))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_J1939DataItems_driveAxleLocation == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DriveAxleLocation", &(value->driveAxleLocation))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_J1939DataItems_driveAxleLiftAirPressure == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DriveAxleLiftAirPressure", &(value->driveAxleLiftAirPressure))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_J1939DataItems_driveAxleTemperature == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DriveAxleTemperature", &(value->driveAxleTemperature))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_J1939DataItems_driveAxleLubePressure == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DriveAxleLubePressure", &(value->driveAxleLubePressure))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_J1939DataItems_steeringAxleLubePressure == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("SteeringAxleLubePressure", &(value->steeringAxleLubePressure))) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
