int ASN1_Print_VehicleStatus_weatherReport(VehicleStatus_weatherReport *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : default
	ASN1_Print_SEQ(" ");
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->isRaining)
	{
	case 1: if ((ret = ASN1_Print_ENUMERATED("EssPrecipYesNo", "precip", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("EssPrecipYesNo", "noPrecip", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("EssPrecipYesNo", "error", 3)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	if (value->DEF_VehicleStatus_weatherReport_rainRate == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("EssPrecipRate", &(value->rainRate))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_weatherReport_precipSituation == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->precipSituation)
		{
		case 1: if ((ret = ASN1_Print_ENUMERATED("EssPrecipSituation", "other", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("EssPrecipSituation", "unknown", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("EssPrecipSituation", "noPrecipitation", 3)) < 0) return ret; break;
		case 4: if ((ret = ASN1_Print_ENUMERATED("EssPrecipSituation", "unidentifiedSlight", 4)) < 0) return ret; break;
		case 5: if ((ret = ASN1_Print_ENUMERATED("EssPrecipSituation", "unidentifiedModerate", 5)) < 0) return ret; break;
		case 6: if ((ret = ASN1_Print_ENUMERATED("EssPrecipSituation", "unidentifiedHeavy", 6)) < 0) return ret; break;
		case 7: if ((ret = ASN1_Print_ENUMERATED("EssPrecipSituation", "snowSlight", 7)) < 0) return ret; break;
		case 8: if ((ret = ASN1_Print_ENUMERATED("EssPrecipSituation", "snowModerate", 8)) < 0) return ret; break;
		case 9: if ((ret = ASN1_Print_ENUMERATED("EssPrecipSituation", "snowHeavy", 9)) < 0) return ret; break;
		case 10: if ((ret = ASN1_Print_ENUMERATED("EssPrecipSituation", "rainSlight", 10)) < 0) return ret; break;
		case 11: if ((ret = ASN1_Print_ENUMERATED("EssPrecipSituation", "rainModerate", 11)) < 0) return ret; break;
		case 12: if ((ret = ASN1_Print_ENUMERATED("EssPrecipSituation", "rainHeavy", 12)) < 0) return ret; break;
		case 13: if ((ret = ASN1_Print_ENUMERATED("EssPrecipSituation", "frozenPrecipitationSlight", 13)) < 0) return ret; break;
		case 14: if ((ret = ASN1_Print_ENUMERATED("EssPrecipSituation", "frozenPrecipitationModerate", 14)) < 0) return ret; break;
		case 15: if ((ret = ASN1_Print_ENUMERATED("EssPrecipSituation", "frozenPrecipitationHeavy", 15)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_weatherReport_solarRadiation == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("EssSolarRadiation", &(value->solarRadiation))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_weatherReport_friction == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("EssMobileFriction", &(value->friction))) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
