extern int ASN1_CHECK_VehicleStatus_weatherReport(VehicleStatus_weatherReport *value);
int ASN1_CHECK_VehicleStatus(VehicleStatus *value)
{
	int ret = 0;

	unsigned char checkinfo_lights[] = { 
		0x02,0x09,0x09,0xCC,0x00
	};
	unsigned char checkinfo_lightBar[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_wipers[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_brakeStatus[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_brakePressure[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_roadFriction[] = { 
		0x02,0x00,0x32,0x00
	};
	unsigned char checkinfo_sunData[] = { 
		0x02,0x00,0x82,0x03,0xE8,0x00
	};
	unsigned char checkinfo_rainData[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_airTemp[] = { 
		0x02,0x00,0x82,0x00,0xBF,0x00
	};
	unsigned char checkinfo_airPres[] = { 
		0x02,0x00,0x82,0x00,0xFF,0x00
	};
	unsigned char checkinfo_steering[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_accelSets[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_object[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_fullPos[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_throttlePos[] = { 
		0x02,0x00,0x82,0x00,0xC8,0x00
	};
	unsigned char checkinfo_speedHeadC[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_speedC[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_vehicleData[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_vehicleIdent[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_j1939data[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_weatherReport[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_gnssStatus[] = { 
		0x02,0x08,0x08,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_VehicleStatus_lights == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BITSTRING(&(value->lights), checkinfo_lights)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_lightBar == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->lightBar), checkinfo_lightBar)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_wipers == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_WiperSet(value->wipers)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_brakeStatus == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BrakeSystemStatus(value->brakeStatus)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_brakePressure == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->brakePressure), checkinfo_brakePressure)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_roadFriction == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->roadFriction), checkinfo_roadFriction)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_sunData == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->sunData), checkinfo_sunData)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_rainData == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->rainData), checkinfo_rainData)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_airTemp == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->airTemp), checkinfo_airTemp)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_airPres == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->airPres), checkinfo_airPres)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_steering == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_VehicleStatus_steering(value->steering)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_accelSets == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_VehicleStatus_accelSets(value->accelSets)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_object == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_VehicleStatus_object(value->object)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_fullPos == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_FullPositionVector(value->fullPos)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_throttlePos == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->throttlePos), checkinfo_throttlePos)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_speedHeadC == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_SpeedandHeadingandThrottleConfidence(value->speedHeadC)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_speedC == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->speedC), checkinfo_speedC)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_vehicleData == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_VehicleStatus_vehicleData(value->vehicleData)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_vehicleIdent == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_VehicleIdent(value->vehicleIdent)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_j1939data == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_J1939DataItems(value->j1939data)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_weatherReport == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_VehicleStatus_weatherReport(value->weatherReport)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleStatus_gnssStatus == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BITSTRING(&(value->gnssStatus), checkinfo_gnssStatus)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
