int ASN1_Print_Snapshot(Snapshot *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("Snapshot");
	// Type Reference FullPositionVector
	if (Compare_Letter(tab_value, "thePosition")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("thePosition = ");
	}
	if ((ret = ASN1_Print_FullPositionVector((FullPositionVector *)value->thePosition, tab_value + 1)) < 0) return ret;
	if (value->DEF_Snapshot_safetyExt == 1)
	{ /*OPTIONAL start */
		// Type Reference VehicleSafetyExtensions
		if (Compare_Letter(tab_value, "safetyExt")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("safetyExt = ");
		}
		if ((ret = ASN1_Print_VehicleSafetyExtensions((VehicleSafetyExtensions *)value->safetyExt, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_Snapshot_dataSet == 1)
	{ /*OPTIONAL start */
		// Type Reference VehicleStatus
		if (Compare_Letter(tab_value, "dataSet")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("dataSet = ");
		}
		if ((ret = ASN1_Print_VehicleStatus((VehicleStatus *)value->dataSet, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
