extern int ASN1_CHECK_FullPositionVector(FullPositionVector *value);
extern int ASN1_CHECK_VehicleSafetyExtensions(VehicleSafetyExtensions *value);
extern int ASN1_CHECK_VehicleStatus(VehicleStatus *value);
int ASN1_CHECK_Snapshot(Snapshot *value)
{
	int ret = 0;

	unsigned char checkinfo_thePosition[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_safetyExt[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_dataSet[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_FullPositionVector(value->thePosition)) < 0) return ret;
	if (value->DEF_Snapshot_safetyExt == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_VehicleSafetyExtensions(value->safetyExt)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_Snapshot_dataSet == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_VehicleStatus(value->dataSet)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_FullPositionVector(ASN1WorkSpace *workspace, FullPositionVector *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_VehicleSafetyExtensions(ASN1WorkSpace *workspace, VehicleSafetyExtensions *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_VehicleStatus(ASN1WorkSpace *workspace, VehicleStatus *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_Snapshot(ASN1WorkSpace *workspace, Snapshot *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_FullPositionVector(workspace, value->thePosition, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (value->DEF_Snapshot_safetyExt == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_VehicleSafetyExtensions(workspace, value->safetyExt, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_Snapshot_dataSet == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_VehicleStatus(workspace, value->dataSet, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_Snapshot(Snapshot *value);
extern int ASN1_BER_Data_Enc_Snapshot(ASN1WorkSpace *workspace, Snapshot *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_Snapshot(ASN1WorkSpace *workspace, Snapshot *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_Snapshot(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_Snapshot(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_FullPositionVector(ASN1WorkSpace *workspace, FullPositionVector *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_VehicleSafetyExtensions(ASN1WorkSpace *workspace, VehicleSafetyExtensions *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_VehicleStatus(ASN1WorkSpace *workspace, VehicleStatus *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_Snapshot(ASN1WorkSpace *workspace, Snapshot *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	value->thePosition = (FullPositionVector *)mpool_malloc(workspace->Pmemory, sizeof(FullPositionVector));
	memset(value->thePosition, 0, sizeof(FullPositionVector));
	value->safetyExt = (VehicleSafetyExtensions *)mpool_malloc(workspace->Pmemory, sizeof(VehicleSafetyExtensions));
	memset(value->safetyExt, 0, sizeof(VehicleSafetyExtensions));
	value->dataSet = (VehicleStatus *)mpool_malloc(workspace->Pmemory, sizeof(VehicleStatus));
	memset(value->dataSet, 0, sizeof(VehicleStatus));
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_FullPositionVector(workspace, value->thePosition, len, ASN1IMPL)) < 0) return ret;
	if (IfFixedLength(len) == -1)
	{
		if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_CONS | 1))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_VehicleSafetyExtensions(workspace, value->safetyExt, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->DEF_Snapshot_safetyExt = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_CONS | 2))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_VehicleStatus(workspace, value->dataSet, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->DEF_Snapshot_dataSet = 1;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_Snapshot(Snapshot *value);
extern int ASN1_BER_Data_Dec_Snapshot(ASN1WorkSpace *workspace, Snapshot *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_Snapshot(ASN1WorkSpace *workspace, Snapshot *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_Snapshot(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_Snapshot(value)) < 0) return ret;
	return ret;
}
