int ASN1_PER_Align_Data_Enc_Snapshot(ASN1WorkSpace *workspace, Snapshot *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_thePosition = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_safetyExt = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_dataSet = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };

	ASNINT32 all_bit;
	ASNUINT16 all_pointer;
	if ((ret = ASN1_PER_Enc_extbit(workspace, value->E)) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_Snapshot_safetyExt == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_Snapshot_dataSet == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Align_Enc_FullPositionVector(workspace, value->thePosition)) < 0) return ret;
	if (value->DEF_Snapshot_safetyExt == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_VehicleSafetyExtensions(workspace, value->safetyExt)) < 0) return ret;
	}
	if (value->DEF_Snapshot_dataSet == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_VehicleStatus(workspace, value->dataSet)) < 0) return ret;
	}
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, ALIGN, 0);
	}
	return ret;
}
