extern int ASN1_PER_Align_Data_Dec_VehicleSafetyExtensions(ASN1WorkSpace *workspace, VehicleSafetyExtensions *value);
extern int ASN1_PER_Align_Data_Dec_VehicleStatus(ASN1WorkSpace *workspace, VehicleStatus *value);
int ASN1_PER_Align_Data_Dec_Snapshot(ASN1WorkSpace *workspace, Snapshot *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_thePosition = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_safetyExt = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_dataSet = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };

	ASNBOOL extbit_Snapshot;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_Snapshot)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 2, &_optvalue)) < 0) return ret;
	value->thePosition = (FullPositionVector *)mpool_malloc(workspace->Pmemory, sizeof(FullPositionVector));
	memset(value->thePosition, 0, sizeof(FullPositionVector));
	value->safetyExt = (VehicleSafetyExtensions *)mpool_malloc(workspace->Pmemory, sizeof(VehicleSafetyExtensions));
	memset(value->safetyExt, 0, sizeof(VehicleSafetyExtensions));
	value->dataSet = (VehicleStatus *)mpool_malloc(workspace->Pmemory, sizeof(VehicleStatus));
	memset(value->dataSet, 0, sizeof(VehicleStatus));
	if ((ret = ASN1_PER_Align_Dec_FullPositionVector(workspace, value->thePosition)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_Snapshot_safetyExt = 1;
		if ((ret = ASN1_PER_Align_Dec_VehicleSafetyExtensions(workspace, value->safetyExt)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_Snapshot_dataSet = 1;
		if ((ret = ASN1_PER_Align_Dec_VehicleStatus(workspace, value->dataSet)) < 0) return ret;
	}
	if (extbit_Snapshot == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, ALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, ALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
extern int ASN1_CHECK_Snapshot(Snapshot *value);
extern int ASN1_PER_Align_Data_Dec_Snapshot(ASN1WorkSpace *workspace, Snapshot *value);
