/********************************************************
*ProbeVehicleData                                       *
********************************************************/
int ASN1_Print_ProbeVehicleData(ProbeVehicleData *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("ProbeVehicleData");
	if (value->DEF_ProbeVehicleData_timeStamp == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("MinuteOfTheYear", &(value->timeStamp))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ProbeVehicleData_segNum == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("ProbeSegmentNumber", &(value->segNum))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ProbeVehicleData_probeID == 1)
	{ /*OPTIONAL start */
		// Type Reference VehicleIdent
		if (Compare_Letter(tab_value, "probeID")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("probeID = ");
		}
		if ((ret = ASN1_Print_VehicleIdent((VehicleIdent *)value->probeID, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	// Type Reference FullPositionVector
	if (Compare_Letter(tab_value, "startVector")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("startVector = ");
	}
	if ((ret = ASN1_Print_FullPositionVector((FullPositionVector *)value->startVector, tab_value + 1)) < 0) return ret;
	// Type Reference VehicleClassification
	if (Compare_Letter(tab_value, "vehicleType")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("vehicleType = ");
	}
	if ((ret = ASN1_Print_VehicleClassification((VehicleClassification *)value->vehicleType, tab_value + 1)) < 0) return ret;
	// Type Reference ProbeVehicleData_snapshots
	if (Compare_Letter(tab_value, "snapshots")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("snapshots = ");
	}
	if ((ret = ASN1_Print_ProbeVehicleData_snapshots((ProbeVehicleData_snapshots *)&(value->snapshots), tab_value + 1)) < 0) return ret;
	if (value->DEF_ProbeVehicleData_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference ProbeVehicleData_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_ProbeVehicleData_regional((ProbeVehicleData_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
