extern int ASN1_CHECK_VehicleIdent(VehicleIdent *value);
extern int ASN1_CHECK_FullPositionVector(FullPositionVector *value);
extern int ASN1_CHECK_VehicleClassification(VehicleClassification *value);
extern int ASN1_CHECK_ProbeVehicleData_snapshots(ProbeVehicleData_snapshots *value);
extern int ASN1_CHECK_ProbeVehicleData_regional(ProbeVehicleData_regional *value);
int ASN1_CHECK_ProbeVehicleData(ProbeVehicleData *value)
{
	int ret = 0;

	unsigned char checkinfo_timeStamp[] = { 
		0x02,0x00,0x83,0x08,0x0A,0xC0,0x00
	};
	unsigned char checkinfo_segNum[] = { 
		0x02,0x00,0x82,0x7F,0xFF,0x00
	};
	unsigned char checkinfo_probeID[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_startVector[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_vehicleType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_snapshots[] = { 
		0x02,0x01,0x20,0x00
	};
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_ProbeVehicleData_timeStamp == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->timeStamp), checkinfo_timeStamp)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ProbeVehicleData_segNum == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->segNum), checkinfo_segNum)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ProbeVehicleData_probeID == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_VehicleIdent(value->probeID)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_FullPositionVector(value->startVector)) < 0) return ret;
	if ((ret = ASN1_CHECK_VehicleClassification(value->vehicleType)) < 0) return ret;
	if ((ret = ASN1_CHECK_ProbeVehicleData_snapshots(&(value->snapshots))) < 0) return ret;
	if (value->DEF_ProbeVehicleData_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ProbeVehicleData_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
