extern int ASN1_BER_Data_Enc_ProbeSegmentNumber(ASN1WorkSpace *workspace, ProbeSegmentNumber *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_VehicleIdent(ASN1WorkSpace *workspace, VehicleIdent *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_FullPositionVector(ASN1WorkSpace *workspace, FullPositionVector *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_VehicleClassification(ASN1WorkSpace *workspace, VehicleClassification *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_ProbeVehicleData_snapshots(ASN1WorkSpace *workspace, ProbeVehicleData_snapshots *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_ProbeVehicleData_regional(ASN1WorkSpace *workspace, ProbeVehicleData_regional *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_ProbeVehicleData(ASN1WorkSpace *workspace, ProbeVehicleData *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if (value->DEF_ProbeVehicleData_timeStamp == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_MinuteOfTheYear(workspace, &(value->timeStamp), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_ProbeVehicleData_segNum == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_ProbeSegmentNumber(workspace, &(value->segNum), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_ProbeVehicleData_probeID == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_VehicleIdent(workspace, value->probeID, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 3)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_FullPositionVector(workspace, value->startVector, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 4)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_VehicleClassification(workspace, value->vehicleType, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 16)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_ProbeVehicleData_snapshots(workspace, &(value->snapshots), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (value->DEF_ProbeVehicleData_regional == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 16)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_ProbeVehicleData_regional(workspace, &(value->regional), ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
