int ASN1_CHECK_Sample(Sample *value)
{
	int ret = 0;

	unsigned char checkinfo_sampleStart[] = { 
		0x02,0x00,0x82,0x00,0xFF,0x00
	};
	unsigned char checkinfo_sampleEnd[] = { 
		0x02,0x00,0x82,0x00,0xFF,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->sampleStart), checkinfo_sampleStart)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->sampleEnd), checkinfo_sampleEnd)) < 0) return ret;
	return ret;
}
int ASN1_BER_Data_Enc_Sample(ASN1WorkSpace *workspace, Sample *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_INTEGER(workspace, &(value->sampleStart), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_INTEGER(workspace, &(value->sampleEnd), ASN1IMPL)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_Sample(Sample *value);
extern int ASN1_BER_Data_Enc_Sample(ASN1WorkSpace *workspace, Sample *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_Sample(ASN1WorkSpace *workspace, Sample *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_Sample(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_Sample(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
int ASN1_BER_Data_Dec_Sample(ASN1WorkSpace *workspace, Sample *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Dec_INTEGER(workspace, &value->sampleStart, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Dec_INTEGER(workspace, &value->sampleEnd, len, ASN1IMPL)) < 0) return ret;
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_Sample(Sample *value);
extern int ASN1_BER_Data_Dec_Sample(ASN1WorkSpace *workspace, Sample *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_Sample(ASN1WorkSpace *workspace, Sample *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_Sample(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_Sample(value)) < 0) return ret;
	return ret;
}
