int ASN1_CHECK_SnapshotTime(SnapshotTime *value)
{
	int ret = 0;

	unsigned char checkinfo_speed1[] = { 
		0x02,0x00,0x1F,0x00
	};
	unsigned char checkinfo_time1[] = { 
		0x02,0x00,0x3D,0x00
	};
	unsigned char checkinfo_speed2[] = { 
		0x02,0x00,0x1F,0x00
	};
	unsigned char checkinfo_time2[] = { 
		0x02,0x00,0x3D,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->speed1), checkinfo_speed1)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->time1), checkinfo_time1)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->speed2), checkinfo_speed2)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->time2), checkinfo_time2)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Enc_GrossSpeed(ASN1WorkSpace *workspace, GrossSpeed *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_SecondOfTime(ASN1WorkSpace *workspace, SecondOfTime *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_GrossSpeed(ASN1WorkSpace *workspace, GrossSpeed *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_SecondOfTime(ASN1WorkSpace *workspace, SecondOfTime *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_SnapshotTime(ASN1WorkSpace *workspace, SnapshotTime *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_GrossSpeed(workspace, &(value->speed1), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_SecondOfTime(workspace, &(value->time1), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_GrossSpeed(workspace, &(value->speed2), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_SecondOfTime(workspace, &(value->time2), ASN1IMPL)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_SnapshotTime(SnapshotTime *value);
extern int ASN1_BER_Data_Enc_SnapshotTime(ASN1WorkSpace *workspace, SnapshotTime *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_SnapshotTime(ASN1WorkSpace *workspace, SnapshotTime *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_SnapshotTime(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_SnapshotTime(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_GrossSpeed(ASN1WorkSpace *workspace, GrossSpeed *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_SecondOfTime(ASN1WorkSpace *workspace, SecondOfTime *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_GrossSpeed(ASN1WorkSpace *workspace, GrossSpeed *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_SecondOfTime(ASN1WorkSpace *workspace, SecondOfTime *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_SnapshotTime(ASN1WorkSpace *workspace, SnapshotTime *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_GrossSpeed(workspace, &value->speed1, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_SecondOfTime(workspace, &value->time1, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_GrossSpeed(workspace, &value->speed2, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_SecondOfTime(workspace, &value->time2, len, ASN1IMPL)) < 0) return ret;
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_SnapshotTime(SnapshotTime *value);
extern int ASN1_BER_Data_Dec_SnapshotTime(ASN1WorkSpace *workspace, SnapshotTime *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_SnapshotTime(ASN1WorkSpace *workspace, SnapshotTime *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_SnapshotTime(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_SnapshotTime(value)) < 0) return ret;
	return ret;
}
