/********************************************************
*ProbeDataManagement_snapshot                           *
********************************************************/
int ASN1_Print_ProbeDataManagement_snapshot(ProbeDataManagement_snapshot *value, int tab_value)
{
	int ret = 0;
	// CHOICE : default
	ASN1_Print_CHOICE(" ");
	if (value == NULL) return -1;
	switch (value->M) {
	case DEF_ProbeDataManagement_snapshot_snapshotTime:
		// Type Reference SnapshotTime
		if (Compare_Letter(tab_value, "snapshotTime")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("snapshotTime = ");
		}
		if ((ret = ASN1_Print_SnapshotTime((SnapshotTime *)value->elements.snapshotTime, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_ProbeDataManagement_snapshot_snapshotDistance:
		// Type Reference SnapshotDistance
		if (Compare_Letter(tab_value, "snapshotDistance")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("snapshotDistance = ");
		}
		if ((ret = ASN1_Print_SnapshotDistance((SnapshotDistance *)value->elements.snapshotDistance, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	default: return -1;
}
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_ProbeDataManagement_snapshot_snapshotTime(ASN1WorkSpace *workspace, ProbeDataManagement_snapshot *value, SnapshotTime *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->elements.snapshotTime = (SnapshotTime *)mpool_malloc(workspace->Pmemory, sizeof(SnapshotTime));
	memset(value->elements.snapshotTime, 0, sizeof(SnapshotTime));
	value->M = DEF_ProbeDataManagement_snapshot_snapshotTime;
	memmove(value->elements.snapshotTime, user_value, sizeof(SnapshotTime));
	return ret;
}
