/********************************************************
*ProbeDataManagement                                    *
********************************************************/
int ASN1_Print_ProbeDataManagement(ProbeDataManagement *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("ProbeDataManagement");
	if (value->DEF_ProbeDataManagement_timeStamp == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("MinuteOfTheYear", &(value->timeStamp))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Reference Sample
	if (Compare_Letter(tab_value, "sample")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("sample = ");
	}
	if ((ret = ASN1_Print_Sample((Sample *)value->sample, tab_value + 1)) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BITSTRING("HeadingSlice", &(value->directions))) < 0) return ret;
	// Type Reference ProbeDataManagement_term
	if (Compare_Letter(tab_value, "term")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("term = ");
	}
	if ((ret = ASN1_Print_ProbeDataManagement_term((ProbeDataManagement_term *)value->term, tab_value + 1)) < 0) return ret;
	// Type Reference ProbeDataManagement_snapshot
	if (Compare_Letter(tab_value, "snapshot")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("snapshot = ");
	}
	if ((ret = ASN1_Print_ProbeDataManagement_snapshot((ProbeDataManagement_snapshot *)value->snapshot, tab_value + 1)) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("SecondOfTime", &(value->txInterval))) < 0) return ret;
	if (value->DEF_ProbeDataManagement_dataElements == 1)
	{ /*OPTIONAL start */
		// Type Reference VehicleStatusRequestList
		if (Compare_Letter(tab_value, "dataElements")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("dataElements = ");
		}
		if ((ret = ASN1_Print_VehicleStatusRequestList((VehicleStatusRequestList *)&(value->dataElements), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ProbeDataManagement_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference ProbeDataManagement_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_ProbeDataManagement_regional((ProbeDataManagement_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
