extern int ASN1_PER_UNAlign_Data_Enc_ProbeDataManagement_regional(ASN1WorkSpace *workspace, ProbeDataManagement_regional *value);
int ASN1_PER_UNAlign_Data_Enc_ProbeDataManagement(ASN1WorkSpace *workspace, ProbeDataManagement *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_timeStamp = { ASN1_CONST64(0), ASN1_CONST64(527040), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_sample = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_directions = { ASN1_CONST64(16), ASN1_CONST64(16), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_term = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_snapshot = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_txInterval = { ASN1_CONST64(0), ASN1_CONST64(61), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_dataElements = { ASN1_CONST64(1), ASN1_CONST64(32), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNINT32 all_bit;
	ASNUINT16 all_pointer;
	if ((ret = ASN1_PER_Enc_extbit(workspace, value->E)) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_ProbeDataManagement_timeStamp == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_ProbeDataManagement_dataElements == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_ProbeDataManagement_regional == 1 ? 1 : 0) )) < 0) return ret;
	if (value->DEF_ProbeDataManagement_timeStamp == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_INTEGER(workspace, &(value->timeStamp), &consinfo_timeStamp)) < 0) return ret;
	}
	if ((ret = ASN1_PER_UNAlign_Enc_Sample(workspace, value->sample)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Enc_BITSTRING(workspace, &(value->directions), &consinfo_directions)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Enc_ProbeDataManagement_term(workspace, value->term)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Enc_ProbeDataManagement_snapshot(workspace, value->snapshot)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Enc_INTEGER(workspace, &(value->txInterval), &consinfo_txInterval)) < 0) return ret;
	if (value->DEF_ProbeDataManagement_dataElements == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_VehicleStatusRequestList(workspace, &(value->dataElements))) < 0) return ret;
	}
	if (value->DEF_ProbeDataManagement_regional == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_ProbeDataManagement_regional(workspace, &(value->regional))) < 0) return ret;
	}
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, UNALIGN, 0);
	}
	return ret;
}
