extern int ASN1_PER_UNAlign_Data_Dec_ProbeDataManagement_regional(ASN1WorkSpace *workspace, ProbeDataManagement_regional *value);
int ASN1_PER_UNAlign_Data_Dec_ProbeDataManagement(ASN1WorkSpace *workspace, ProbeDataManagement *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_timeStamp = { ASN1_CONST64(0), ASN1_CONST64(527040), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_sample = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_directions = { ASN1_CONST64(16), ASN1_CONST64(16), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_term = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_snapshot = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_txInterval = { ASN1_CONST64(0), ASN1_CONST64(61), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_dataElements = { ASN1_CONST64(1), ASN1_CONST64(32), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNBOOL extbit_ProbeDataManagement;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_ProbeDataManagement)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 3, &_optvalue)) < 0) return ret;
	value->sample = (Sample *)mpool_malloc(workspace->Pmemory, sizeof(Sample));
	memset(value->sample, 0, sizeof(Sample));
	value->term = (ProbeDataManagement_term *)mpool_malloc(workspace->Pmemory, sizeof(ProbeDataManagement_term));
	memset(value->term, 0, sizeof(ProbeDataManagement_term));
	value->snapshot = (ProbeDataManagement_snapshot *)mpool_malloc(workspace->Pmemory, sizeof(ProbeDataManagement_snapshot));
	memset(value->snapshot, 0, sizeof(ProbeDataManagement_snapshot));
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_ProbeDataManagement_timeStamp = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->timeStamp), &consinfo_timeStamp)) < 0) return ret;
	}
	if ((ret = ASN1_PER_UNAlign_Dec_Sample(workspace, value->sample)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Dec_BITSTRING(workspace, &(value->directions), &consinfo_directions)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Dec_ProbeDataManagement_term(workspace, value->term)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Dec_ProbeDataManagement_snapshot(workspace, value->snapshot)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->txInterval), &consinfo_txInterval)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_ProbeDataManagement_dataElements = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_VehicleStatusRequestList(workspace, &(value->dataElements))) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 3) == 1)
	{
		value->DEF_ProbeDataManagement_regional = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_ProbeDataManagement_regional(workspace, &(value->regional))) < 0) return ret;
	}
	if (extbit_ProbeDataManagement == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, UNALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, UNALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
extern int ASN1_CHECK_ProbeDataManagement(ProbeDataManagement *value);
extern int ASN1_PER_UNAlign_Data_Dec_ProbeDataManagement(ASN1WorkSpace *workspace, ProbeDataManagement *value);
int ASN1_PER_UNAlign_Dec_ProbeDataManagement(ASN1WorkSpace *workspace, ProbeDataManagement *value)
{
	int ret = 0;
	if ((ret = ASN1_PER_UNAlign_Data_Dec_ProbeDataManagement(workspace,value)) < 0) return ret;
	if ((ret = ASN1_CHECK_ProbeDataManagement(value)) < 0) return ret;
	return ret;
}

/********************************************************
*RoadSignID                                             *
********************************************************/
int ASN1_Print_RoadSignID(RoadSignID *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("RoadSignID");
	// Type Reference Position3D
	if (Compare_Letter(tab_value, "position")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("position = ");
	}
	if ((ret = ASN1_Print_Position3D((Position3D *)value->position, tab_value + 1)) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BITSTRING("HeadingSlice", &(value->viewAngle))) < 0) return ret;
	if (value->DEF_RoadSignID_mutcdCode == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->mutcdCode)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("MUTCDCode", "none", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("MUTCDCode", "regulatory", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("MUTCDCode", "warning", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("MUTCDCode", "maintenance", 3)) < 0) return ret; break;
		case 4: if ((ret = ASN1_Print_ENUMERATED("MUTCDCode", "motoristService", 4)) < 0) return ret; break;
		case 5: if ((ret = ASN1_Print_ENUMERATED("MUTCDCode", "guide", 5)) < 0) return ret; break;
		case 6: if ((ret = ASN1_Print_ENUMERATED("MUTCDCode", "rec", 6)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	if (value->DEF_RoadSignID_crc == 1)
	{ /*OPTIONAL start */
		// Type OCTET STRING
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_OCTETSTRING("MsgCRC", &(value->crc), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
