extern int ASN1_CHECK_Position3D(Position3D *value);
int ASN1_CHECK_RoadSignID(RoadSignID *value)
{
	int ret = 0;

	unsigned char checkinfo_position[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_viewAngle[] = { 
		0x02,0x10,0x10,0x00
	};
	unsigned char checkinfo_mutcdCode[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_crc[] = { 
		0x02,0x02,0x02,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_Position3D(value->position)) < 0) return ret;
	if ((ret = ASN1_CHECK_BITSTRING(&(value->viewAngle), checkinfo_viewAngle)) < 0) return ret;
	if (value->DEF_RoadSignID_mutcdCode == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->mutcdCode), checkinfo_mutcdCode)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSignID_crc == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_OCTETSTRING(&(value->crc), checkinfo_crc)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_Position3D(ASN1WorkSpace *workspace, Position3D *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_HeadingSlice(ASN1WorkSpace *workspace, HeadingSlice *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_MUTCDCode(ASN1WorkSpace *workspace, MUTCDCode *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_MsgCRC(ASN1WorkSpace *workspace, MsgCRC *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_RoadSignID(ASN1WorkSpace *workspace, RoadSignID *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_Position3D(workspace, value->position, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_HeadingSlice(workspace, &(value->viewAngle), ASN1IMPL)) < 0) return ret;
	if (value->DEF_RoadSignID_mutcdCode == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_MUTCDCode(workspace, &(value->mutcdCode), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_RoadSignID_crc == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_MsgCRC(workspace, &(value->crc), ASN1IMPL)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_RoadSignID(RoadSignID *value);
extern int ASN1_BER_Data_Enc_RoadSignID(ASN1WorkSpace *workspace, RoadSignID *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_RoadSignID(ASN1WorkSpace *workspace, RoadSignID *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_RoadSignID(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_RoadSignID(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_Position3D(ASN1WorkSpace *workspace, Position3D *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_HeadingSlice(ASN1WorkSpace *workspace, HeadingSlice *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_MUTCDCode(ASN1WorkSpace *workspace, MUTCDCode *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_MsgCRC(ASN1WorkSpace *workspace, MsgCRC *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_RoadSignID(ASN1WorkSpace *workspace, RoadSignID *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	value->position = (Position3D *)mpool_malloc(workspace->Pmemory, sizeof(Position3D));
	memset(value->position, 0, sizeof(Position3D));
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_Position3D(workspace, value->position, len, ASN1IMPL)) < 0) return ret;
	if (IfFixedLength(len) == -1)
	{
		if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
	}
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_HeadingSlice(workspace, &value->viewAngle, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 2))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_MUTCDCode(workspace, &value->mutcdCode, len, ASN1IMPL)) < 0) return ret;
		value->DEF_RoadSignID_mutcdCode = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 3))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_MsgCRC(workspace, &value->crc, len, ASN1IMPL)) < 0) return ret;
		value->DEF_RoadSignID_crc = 1;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
