int ASN1_Print_NodeOffsetPointLL(NodeOffsetPointLL *value, int tab_value)
{
	int ret = 0;
	// CHOICE : t->tempIdentifier is Upper Letter
	ASN1_Print_CHOICE("NodeOffsetPointLL");
	if (value == NULL) return -1;
	switch (value->M) {
	case DEF_NodeOffsetPointLL_node_LL1:
		// Type Reference Node_LL_24B
		if (Compare_Letter(tab_value, "node-LL1")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("node-LL1 = ");
		}
		if ((ret = ASN1_Print_Node_LL_24B((Node_LL_24B *)value->elements.node_LL1, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_NodeOffsetPointLL_node_LL2:
		// Type Reference Node_LL_28B
		if (Compare_Letter(tab_value, "node-LL2")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("node-LL2 = ");
		}
		if ((ret = ASN1_Print_Node_LL_28B((Node_LL_28B *)value->elements.node_LL2, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_NodeOffsetPointLL_node_LL3:
		// Type Reference Node_LL_32B
		if (Compare_Letter(tab_value, "node-LL3")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("node-LL3 = ");
		}
		if ((ret = ASN1_Print_Node_LL_32B((Node_LL_32B *)value->elements.node_LL3, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_NodeOffsetPointLL_node_LL4:
		// Type Reference Node_LL_36B
		if (Compare_Letter(tab_value, "node-LL4")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("node-LL4 = ");
		}
		if ((ret = ASN1_Print_Node_LL_36B((Node_LL_36B *)value->elements.node_LL4, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_NodeOffsetPointLL_node_LL5:
		// Type Reference Node_LL_44B
		if (Compare_Letter(tab_value, "node-LL5")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("node-LL5 = ");
		}
		if ((ret = ASN1_Print_Node_LL_44B((Node_LL_44B *)value->elements.node_LL5, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_NodeOffsetPointLL_node_LL6:
		// Type Reference Node_LL_48B
		if (Compare_Letter(tab_value, "node-LL6")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("node-LL6 = ");
		}
		if ((ret = ASN1_Print_Node_LL_48B((Node_LL_48B *)value->elements.node_LL6, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_NodeOffsetPointLL_node_LatLon:
		// Type Reference Node_LLmD_64b
		if (Compare_Letter(tab_value, "node-LatLon")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("node-LatLon = ");
		}
		if ((ret = ASN1_Print_Node_LLmD_64b((Node_LLmD_64b *)value->elements.node_LatLon, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_NodeOffsetPointLL_regional:
		// Type Reference RegionalExtension
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_RegionalExtension((RegionalExtension *)value->elements.regional, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	default: return -1;
}
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
