/********************************************************
*NodeAttributeLLList                                    *
********************************************************/
int ASN1_Print_NodeAttributeLLList(NodeAttributeLLList *value, int tab_value)
{
	int ret = 0;
	int count;
	ASN1ListNode *pnode;
	if (value == NULL) return -1;
	count = value->count;
	pnode = value->head->next;
	// SEQUENCE OF : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ_OF("NodeAttributeLLList");
	while(count) {
		// Type Reference NodeAttributeLL
		if ((ret = ASN1_Print_NodeAttributeLL((NodeAttributeLL *)pnode->data, tab_value + 1)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}

	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_CHECK_NodeAttributeLLList(NodeAttributeLLList *value)
{
	int ret = 0;

	unsigned char checkinfo_NodeAttributeLLList[] = { 
		0x02,0x01,0x08,0x00
	};
	unsigned char checkinfo_NodeAttributeLLList_pdata[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	int count;
	ASN1ListNode* pnode;
	if (value == NULL) return -1;
	if (value->head == NULL) return -1;
	if (value->count < 0) return -1;
	pnode = value->head->next;
	count = value->count;
	while (count) {
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)pnode->data, checkinfo_NodeAttributeLLList_pdata)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}
	return ret;
}
