int ASN1_Print_NodeAttributeSetLL(NodeAttributeSetLL *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("NodeAttributeSetLL");
	if (value->DEF_NodeAttributeSetLL_localNode == 1)
	{ /*OPTIONAL start */
		// Type Reference NodeAttributeLLList
		if (Compare_Letter(tab_value, "localNode")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("localNode = ");
		}
		if ((ret = ASN1_Print_NodeAttributeLLList((NodeAttributeLLList *)&(value->localNode), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_NodeAttributeSetLL_disabled == 1)
	{ /*OPTIONAL start */
		// Type Reference SegmentAttributeLLList
		if (Compare_Letter(tab_value, "disabled")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("disabled = ");
		}
		if ((ret = ASN1_Print_SegmentAttributeLLList((SegmentAttributeLLList *)&(value->disabled), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_NodeAttributeSetLL_enabled == 1)
	{ /*OPTIONAL start */
		// Type Reference SegmentAttributeLLList
		if (Compare_Letter(tab_value, "enabled")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("enabled = ");
		}
		if ((ret = ASN1_Print_SegmentAttributeLLList((SegmentAttributeLLList *)&(value->enabled), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_NodeAttributeSetLL_data == 1)
	{ /*OPTIONAL start */
		// Type Reference LaneDataAttributeList
		if (Compare_Letter(tab_value, "data")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("data = ");
		}
		if ((ret = ASN1_Print_LaneDataAttributeList((LaneDataAttributeList *)&(value->data), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_NodeAttributeSetLL_dWidth == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("Offset_B10", &(value->dWidth))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_NodeAttributeSetLL_dElevation == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("Offset_B10", &(value->dElevation))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_NodeAttributeSetLL_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference NodeAttributeSetLL_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_NodeAttributeSetLL_regional((NodeAttributeSetLL_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
