extern int ASN1_CHECK_LaneDataAttributeList(LaneDataAttributeList *value);
extern int ASN1_CHECK_NodeAttributeSetLL_regional(NodeAttributeSetLL_regional *value);
int ASN1_CHECK_NodeAttributeSetLL(NodeAttributeSetLL *value)
{
	int ret = 0;

	unsigned char checkinfo_localNode[] = { 
		0x02,0x01,0x08,0x00
	};
	unsigned char checkinfo_disabled[] = { 
		0x02,0x01,0x08,0x00
	};
	unsigned char checkinfo_enabled[] = { 
		0x02,0x01,0x08,0x00
	};
	unsigned char checkinfo_data[] = { 
		0x02,0x01,0x08,0x00
	};
	unsigned char checkinfo_dWidth[] = { 
		0x02,0x82,0xFE,0x00,0x82,0x01,0xFF,0x00
	};
	unsigned char checkinfo_dElevation[] = { 
		0x02,0x82,0xFE,0x00,0x82,0x01,0xFF,0x00
	};
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_NodeAttributeSetLL_localNode == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_NodeAttributeLLList(&(value->localNode))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_NodeAttributeSetLL_disabled == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_SegmentAttributeLLList(&(value->disabled))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_NodeAttributeSetLL_enabled == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_SegmentAttributeLLList(&(value->enabled))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_NodeAttributeSetLL_data == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_LaneDataAttributeList(&(value->data))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_NodeAttributeSetLL_dWidth == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->dWidth), checkinfo_dWidth)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_NodeAttributeSetLL_dElevation == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->dElevation), checkinfo_dElevation)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_NodeAttributeSetLL_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_NodeAttributeSetLL_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
