int ASN1_Print_NodeLL(NodeLL *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("NodeLL");
	// Type Reference NodeOffsetPointLL
	if (Compare_Letter(tab_value, "delta")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("delta = ");
	}
	if ((ret = ASN1_Print_NodeOffsetPointLL((NodeOffsetPointLL *)value->delta, tab_value + 1)) < 0) return ret;
	if (value->DEF_NodeLL_attributes == 1)
	{ /*OPTIONAL start */
		// Type Reference NodeAttributeSetLL
		if (Compare_Letter(tab_value, "attributes")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("attributes = ");
		}
		if ((ret = ASN1_Print_NodeAttributeSetLL((NodeAttributeSetLL *)value->attributes, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_NodeLL_delta(ASN1WorkSpace *workspace, NodeLL *value, NodeOffsetPointLL *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->delta = (NodeOffsetPointLL *)mpool_malloc(workspace->Pmemory, sizeof(NodeOffsetPointLL));
	memset(value->delta, 0, sizeof(NodeOffsetPointLL));
	memmove(value->delta, user_value, sizeof(NodeOffsetPointLL));
	return ret;
}
int ASN1_SET_NodeLL_attributes(ASN1WorkSpace *workspace, NodeLL *value, NodeAttributeSetLL *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->attributes = (NodeAttributeSetLL *)mpool_malloc(workspace->Pmemory, sizeof(NodeAttributeSetLL));
	memset(value->attributes, 0, sizeof(NodeAttributeSetLL));
	value->DEF_NodeLL_attributes = 1;
	memmove(value->attributes, user_value, sizeof(NodeAttributeSetLL));
	return ret;
}
int ASN1_GET_NodeLL_delta(ASN1WorkSpace *workspace, NodeLL *value, NodeOffsetPointLL **user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	*user_value = value->delta;
	return ret;
}
int ASN1_GET_NodeLL_attributes(ASN1WorkSpace *workspace, NodeLL *value, NodeAttributeSetLL **user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if (value->DEF_NodeLL_attributes == 1)
	{
		*user_value = value->attributes;
	}
	else return -2;
	return ret;
}
extern int ASN1_CHECK_NodeOffsetPointLL(NodeOffsetPointLL *value);
