int ASN1_CHECK_NodeLL(NodeLL *value)
{
	int ret = 0;

	unsigned char checkinfo_delta[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_attributes[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_NodeOffsetPointLL(value->delta)) < 0) return ret;
	if (value->DEF_NodeLL_attributes == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_NodeAttributeSetLL(value->attributes)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_NodeOffsetPointLL(ASN1WorkSpace *workspace, NodeOffsetPointLL *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_NodeAttributeSetLL(ASN1WorkSpace *workspace, NodeAttributeSetLL *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_NodeLL(ASN1WorkSpace *workspace, NodeLL *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_NodeOffsetPointLL(workspace, value->delta, ASN1EXPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (value->DEF_NodeLL_attributes == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_NodeAttributeSetLL(workspace, value->attributes, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
