extern int ASN1_BER_Data_Dec_NodeOffsetPointLL(ASN1WorkSpace *workspace, NodeOffsetPointLL *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_NodeAttributeSetLL(ASN1WorkSpace *workspace, NodeAttributeSetLL *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_NodeLL(ASN1WorkSpace *workspace, NodeLL *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	value->delta = (NodeOffsetPointLL *)mpool_malloc(workspace->Pmemory, sizeof(NodeOffsetPointLL));
	memset(value->delta, 0, sizeof(NodeOffsetPointLL));
	value->attributes = (NodeAttributeSetLL *)mpool_malloc(workspace->Pmemory, sizeof(NodeAttributeSetLL));
	memset(value->attributes, 0, sizeof(NodeAttributeSetLL));
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_NodeOffsetPointLL(workspace, value->delta, len, ASN1EXPL)) < 0) return ret;
	if (IfFixedLength(len) == -1)
	{
		if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_CONS | 1))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_NodeAttributeSetLL(workspace, value->attributes, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->DEF_NodeLL_attributes = 1;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_NodeLL(NodeLL *value);
extern int ASN1_BER_Data_Dec_NodeLL(ASN1WorkSpace *workspace, NodeLL *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_NodeLL(ASN1WorkSpace *workspace, NodeLL *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_NodeLL(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_NodeLL(value)) < 0) return ret;
	return ret;
}
