extern int ASN1_BER_Data_Dec_NodeSetLL(ASN1WorkSpace *workspace, NodeSetLL *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_NodeListLL(ASN1WorkSpace *workspace, NodeListLL *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	value->M = 0;
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	switch(tag)
	{
	case ITS_ASN_CONT | ITS_ASN_CONS | 0:
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_NodeSetLL(workspace, &value->elements.nodes, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->M = DEF_NodeListLL_nodes;
		break;
	}
	return ret;
}
