extern int ASN1_PER_Align_Data_Dec_OffsetSystem_offset(ASN1WorkSpace *workspace, OffsetSystem_offset *value);
int ASN1_PER_Align_Data_Dec_OffsetSystem(ASN1WorkSpace *workspace, OffsetSystem *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_scale = { ASN1_CONST64(0), ASN1_CONST64(15), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_offset = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };

	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 1, &_optvalue)) < 0) return ret;
	value->offset = (OffsetSystem_offset *)mpool_malloc(workspace->Pmemory, sizeof(OffsetSystem_offset));
	memset(value->offset, 0, sizeof(OffsetSystem_offset));
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_OffsetSystem_scale = 1;
		if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->scale), &consinfo_scale)) < 0) return ret;
	}
	if ((ret = ASN1_PER_Align_Dec_OffsetSystem_offset(workspace, value->offset)) < 0) return ret;
	return ret;
}
extern int ASN1_CHECK_OffsetSystem(OffsetSystem *value);
