/********************************************************
*Circle                                                 *
********************************************************/
int ASN1_Print_Circle(Circle *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("Circle");
	// Type Reference Position3D
	if (Compare_Letter(tab_value, "center")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("center = ");
	}
	if ((ret = ASN1_Print_Position3D((Position3D *)value->center, tab_value + 1)) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("Radius_B12", &(value->radius))) < 0) return ret;
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->units)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("DistanceUnits", "centimeter", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("DistanceUnits", "cm2-5", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("DistanceUnits", "decimeter", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("DistanceUnits", "meter", 3)) < 0) return ret; break;
	case 4: if ((ret = ASN1_Print_ENUMERATED("DistanceUnits", "kilometer", 4)) < 0) return ret; break;
	case 5: if ((ret = ASN1_Print_ENUMERATED("DistanceUnits", "foot", 5)) < 0) return ret; break;
	case 6: if ((ret = ASN1_Print_ENUMERATED("DistanceUnits", "yard", 6)) < 0) return ret; break;
	case 7: if ((ret = ASN1_Print_ENUMERATED("DistanceUnits", "mile", 7)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_Circle_center(ASN1WorkSpace *workspace, Circle *value, Position3D *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->center = (Position3D *)mpool_malloc(workspace->Pmemory, sizeof(Position3D));
	memset(value->center, 0, sizeof(Position3D));
	memmove(value->center, user_value, sizeof(Position3D));
	return ret;
}
