{
	int ret = 0;
	if ((ret = ASN1_CHECK_GeometricProjection_regional(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_GeometricProjection_regional(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_RegionalExtension(ASN1WorkSpace *workspace, RegionalExtension *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_GeometricProjection_regional(ASN1WorkSpace *workspace, GeometricProjection_regional *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	RegionalExtension *pdata;
	ASNUINT8 *p = workspace->buffer.current;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	if ((ret = ASN1_Creat_Init_List(workspace, value)) < 0) return ret;
	while (ASN1_BER_Dec_Isloop(workspace, p, length))
	{
		pdata = (RegionalExtension *)mpool_malloc(GetMemPool(workspace), sizeof(RegionalExtension));
		memset(pdata, 0, sizeof(RegionalExtension));
		if ((ret = ASN1_BER_Data_Dec_RegionalExtension(workspace, pdata, len, ASN1EXPL)) < 0) return ret;
		if ((ret = ASN1_Insert_Node(workspace, value,(void*)pdata)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
