extern int ASN1_CHECK_Circle(Circle *value);
extern int ASN1_CHECK_GeometricProjection_regional(GeometricProjection_regional *value);
int ASN1_CHECK_GeometricProjection(GeometricProjection *value)
{
	int ret = 0;

	unsigned char checkinfo_direction[] = { 
		0x02,0x10,0x10,0x00
	};
	unsigned char checkinfo_extent[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_laneWidth[] = { 
		0x02,0x00,0x82,0x7F,0xFF,0x00
	};
	unsigned char checkinfo_circle[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_BITSTRING(&(value->direction), checkinfo_direction)) < 0) return ret;
	if (value->DEF_GeometricProjection_extent == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->extent), checkinfo_extent)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_GeometricProjection_laneWidth == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->laneWidth), checkinfo_laneWidth)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_Circle(value->circle)) < 0) return ret;
	if (value->DEF_GeometricProjection_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_GeometricProjection_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_HeadingSlice(ASN1WorkSpace *workspace, HeadingSlice *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_Extent(ASN1WorkSpace *workspace, Extent *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_LaneWidth(ASN1WorkSpace *workspace, LaneWidth *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_Circle(ASN1WorkSpace *workspace, Circle *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_GeometricProjection_regional(ASN1WorkSpace *workspace, GeometricProjection_regional *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_GeometricProjection(ASN1WorkSpace *workspace, GeometricProjection *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_HeadingSlice(workspace, &(value->direction), ASN1IMPL)) < 0) return ret;
	if (value->DEF_GeometricProjection_extent == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_Extent(workspace, &(value->extent), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_GeometricProjection_laneWidth == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_LaneWidth(workspace, &(value->laneWidth), ASN1IMPL)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 3)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_Circle(workspace, value->circle, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (value->DEF_GeometricProjection_regional == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 16)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_GeometricProjection_regional(workspace, &(value->regional), ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_GeometricProjection(GeometricProjection *value);
extern int ASN1_BER_Data_Enc_GeometricProjection(ASN1WorkSpace *workspace, GeometricProjection *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_GeometricProjection(ASN1WorkSpace *workspace, GeometricProjection *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_GeometricProjection(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_GeometricProjection(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_HeadingSlice(ASN1WorkSpace *workspace, HeadingSlice *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_Extent(ASN1WorkSpace *workspace, Extent *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_LaneWidth(ASN1WorkSpace *workspace, LaneWidth *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_Circle(ASN1WorkSpace *workspace, Circle *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_GeometricProjection_regional(ASN1WorkSpace *workspace, GeometricProjection_regional *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_GeometricProjection(ASN1WorkSpace *workspace, GeometricProjection *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	value->circle = (Circle *)mpool_malloc(workspace->Pmemory, sizeof(Circle));
	memset(value->circle, 0, sizeof(Circle));
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_HeadingSlice(workspace, &value->direction, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 1))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_Extent(workspace, &value->extent, len, ASN1IMPL)) < 0) return ret;
		value->DEF_GeometricProjection_extent = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 2))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_LaneWidth(workspace, &value->laneWidth, len, ASN1IMPL)) < 0) return ret;
		value->DEF_GeometricProjection_laneWidth = 1;
	}
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 3)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_Circle(workspace, value->circle, len, ASN1IMPL)) < 0) return ret;
	if (IfFixedLength(len) == -1)
	{
		if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_CONS | 16))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_GeometricProjection_regional(workspace, &value->regional, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->DEF_GeometricProjection_regional = 1;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_GeometricProjection(GeometricProjection *value);
extern int ASN1_BER_Data_Dec_GeometricProjection(ASN1WorkSpace *workspace, GeometricProjection *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_GeometricProjection(ASN1WorkSpace *workspace, GeometricProjection *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_GeometricProjection(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_GeometricProjection(value)) < 0) return ret;
	return ret;
}
extern int ASN1_PER_Align_Data_Enc_Circle(ASN1WorkSpace *workspace, Circle *value);
extern int ASN1_PER_Align_Data_Enc_GeometricProjection_regional(ASN1WorkSpace *workspace, GeometricProjection_regional *value);
int ASN1_PER_Align_Data_Enc_GeometricProjection(ASN1WorkSpace *workspace, GeometricProjection *value)
{
	int ret = 0;
	ASNINT32 ui_extent;
	struct Asn1ConsInfo consinfo_direction = { ASN1_CONST64(16), ASN1_CONST64(16), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_extent = { ASN1_CONST64(0), ASN1_CONST64(15), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_laneWidth = { ASN1_CONST64(0), ASN1_CONST64(32767), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_circle = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNINT32 all_bit;
	ASNUINT16 all_pointer;
	if ((ret = ASN1_PER_Enc_extbit(workspace, value->E)) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_GeometricProjection_extent == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_GeometricProjection_laneWidth == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_GeometricProjection_regional == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Align_Enc_BITSTRING(workspace, &(value->direction), &consinfo_direction)) < 0) return ret;
	if (value->DEF_GeometricProjection_extent == 1)
	{
		switch(value->extent)
		{
		case Extent_useInstantlyOnly: ui_extent = 0; consinfo_extent.enumextbit = 0; break;
		case Extent_useFor3meters: ui_extent = 1; consinfo_extent.enumextbit = 0; break;
		case Extent_useFor10meters: ui_extent = 2; consinfo_extent.enumextbit = 0; break;
		case Extent_useFor50meters: ui_extent = 3; consinfo_extent.enumextbit = 0; break;
		case Extent_useFor100meters: ui_extent = 4; consinfo_extent.enumextbit = 0; break;
		case Extent_useFor500meters: ui_extent = 5; consinfo_extent.enumextbit = 0; break;
		case Extent_useFor1000meters: ui_extent = 6; consinfo_extent.enumextbit = 0; break;
		case Extent_useFor5000meters: ui_extent = 7; consinfo_extent.enumextbit = 0; break;
		case Extent_useFor10000meters: ui_extent = 8; consinfo_extent.enumextbit = 0; break;
		case Extent_useFor50000meters: ui_extent = 9; consinfo_extent.enumextbit = 0; break;
		case Extent_useFor100000meters: ui_extent = 10; consinfo_extent.enumextbit = 0; break;
		case Extent_useFor500000meters: ui_extent = 11; consinfo_extent.enumextbit = 0; break;
		case Extent_useFor1000000meters: ui_extent = 12; consinfo_extent.enumextbit = 0; break;
		case Extent_useFor5000000meters: ui_extent = 13; consinfo_extent.enumextbit = 0; break;
		case Extent_useFor10000000meters: ui_extent = 14; consinfo_extent.enumextbit = 0; break;
		case Extent_forever: ui_extent = 15; consinfo_extent.enumextbit = 0; break;
		default: ui_extent = value->extent; consinfo_extent.enumextbit = 0;break;
		}
		if ((ret = ASN1_PER_Align_Enc_ENUMERATED(workspace, ui_extent, &consinfo_extent)) < 0) return ret;
	}
	if (value->DEF_GeometricProjection_laneWidth == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->laneWidth), &consinfo_laneWidth)) < 0) return ret;
	}
	if ((ret = ASN1_PER_Align_Enc_Circle(workspace, value->circle)) < 0) return ret;
	if (value->DEF_GeometricProjection_regional == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_GeometricProjection_regional(workspace, &(value->regional))) < 0) return ret;
	}
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, ALIGN, 0);
	}
	return ret;
}
extern int ASN1_CHECK_GeometricProjection(GeometricProjection *value);
extern int ASN1_PER_Align_Data_Enc_GeometricProjection(ASN1WorkSpace *workspace, GeometricProjection *value);
int ASN1_PER_Align_Enc_GeometricProjection(ASN1WorkSpace *workspace, GeometricProjection *value)
{ // ASN1_PER_Extern_Encode 
	int ret = 0;
	if ((ret = ASN1_CHECK_GeometricProjection(value)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Data_Enc_GeometricProjection(workspace,value)) < 0) return ret;
	return ret;
}
extern int ASN1_PER_Align_Data_Dec_Circle(ASN1WorkSpace *workspace, Circle *value);
extern int ASN1_PER_Align_Data_Dec_GeometricProjection_regional(ASN1WorkSpace *workspace, GeometricProjection_regional *value);
int ASN1_PER_Align_Data_Dec_GeometricProjection(ASN1WorkSpace *workspace, GeometricProjection *value)
{
	int ret = 0;
	ASNINT32 ui_extent;
	struct Asn1ConsInfo consinfo_direction = { ASN1_CONST64(16), ASN1_CONST64(16), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_extent = { ASN1_CONST64(0), ASN1_CONST64(15), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_laneWidth = { ASN1_CONST64(0), ASN1_CONST64(32767), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_circle = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNBOOL extbit_GeometricProjection;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_GeometricProjection)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 3, &_optvalue)) < 0) return ret;
	value->circle = (Circle *)mpool_malloc(workspace->Pmemory, sizeof(Circle));
	memset(value->circle, 0, sizeof(Circle));
	if ((ret = ASN1_PER_Align_Dec_BITSTRING(workspace, &(value->direction), &consinfo_direction)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_GeometricProjection_extent = 1;
		if ((ret = ASN1_PER_Align_Dec_ENUMERATED(workspace, &ui_extent, &consinfo_extent)) < 0) return ret;
		if (consinfo_extent.enumextbit == 0)
		{
			switch(ui_extent)
			{
			case 0: value->extent = Extent_useInstantlyOnly; break;
			case 1: value->extent = Extent_useFor3meters; break;
			case 2: value->extent = Extent_useFor10meters; break;
			case 3: value->extent = Extent_useFor50meters; break;
			case 4: value->extent = Extent_useFor100meters; break;
			case 5: value->extent = Extent_useFor500meters; break;
			case 6: value->extent = Extent_useFor1000meters; break;
			case 7: value->extent = Extent_useFor5000meters; break;
			case 8: value->extent = Extent_useFor10000meters; break;
			case 9: value->extent = Extent_useFor50000meters; break;
			case 10: value->extent = Extent_useFor100000meters; break;
			case 11: value->extent = Extent_useFor500000meters; break;
			case 12: value->extent = Extent_useFor1000000meters; break;
			case 13: value->extent = Extent_useFor5000000meters; break;
			case 14: value->extent = Extent_useFor10000000meters; break;
			case 15: value->extent = Extent_forever; break;
			default: value->extent = ui_extent; break;
			}
		}
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_GeometricProjection_laneWidth = 1;
		if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->laneWidth), &consinfo_laneWidth)) < 0) return ret;
	}
	if ((ret = ASN1_PER_Align_Dec_Circle(workspace, value->circle)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 3) == 1)
	{
		value->DEF_GeometricProjection_regional = 1;
		if ((ret = ASN1_PER_Align_Dec_GeometricProjection_regional(workspace, &(value->regional))) < 0) return ret;
	}
	if (extbit_GeometricProjection == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, ALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, ALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
