/********************************************************
*RegionOffsets                                          *
********************************************************/
int ASN1_Print_RegionOffsets(RegionOffsets *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("RegionOffsets");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("OffsetLL_B16", &(value->xOffset))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("OffsetLL_B16", &(value->yOffset))) < 0) return ret;
	if (value->DEF_RegionOffsets_zOffset == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("OffsetLL_B16", &(value->zOffset))) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_RegionOffsets_xOffset(ASN1WorkSpace *workspace, RegionOffsets *value, INTEGER user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if ((ret = ASN1_SET_INTEGER(workspace, &value->xOffset, user_value)) < 0) return ret;
	return ret;
}
