extern int ASN1_CHECK_Position3D(Position3D *value);
extern int ASN1_CHECK_RegionList(RegionList *value);
int ASN1_CHECK_RegionPointSet(RegionPointSet *value)
{
	int ret = 0;

	unsigned char checkinfo_anchor[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_scale[] = { 
		0x02,0x00,0x0F,0x00
	};
	unsigned char checkinfo_nodeList[] = { 
		0x02,0x01,0x40,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_RegionPointSet_anchor == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_Position3D(value->anchor)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RegionPointSet_scale == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->scale), checkinfo_scale)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_RegionList(&(value->nodeList))) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Enc_Position3D(ASN1WorkSpace *workspace, Position3D *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_Zoom(ASN1WorkSpace *workspace, Zoom *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_RegionList(ASN1WorkSpace *workspace, RegionList *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_RegionPointSet(ASN1WorkSpace *workspace, RegionPointSet *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if (value->DEF_RegionPointSet_anchor == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_Position3D(workspace, value->anchor, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_RegionPointSet_scale == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_Zoom(workspace, &(value->scale), ASN1IMPL)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_RegionList(workspace, &(value->nodeList), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
