extern int ASN1_BER_Data_Dec_Position3D(ASN1WorkSpace *workspace, Position3D *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_Zoom(ASN1WorkSpace *workspace, Zoom *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_RegionList(ASN1WorkSpace *workspace, RegionList *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_RegionPointSet(ASN1WorkSpace *workspace, RegionPointSet *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	value->anchor = (Position3D *)mpool_malloc(workspace->Pmemory, sizeof(Position3D));
	memset(value->anchor, 0, sizeof(Position3D));
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_CONS | 0))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_Position3D(workspace, value->anchor, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->DEF_RegionPointSet_anchor = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 1))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_Zoom(workspace, &value->scale, len, ASN1IMPL)) < 0) return ret;
		value->DEF_RegionPointSet_scale = 1;
	}
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_RegionList(workspace, &value->nodeList, len, ASN1IMPL)) < 0) return ret;
	if (IfFixedLength(len) == -1)
	{
		if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_RegionPointSet(RegionPointSet *value);
extern int ASN1_BER_Data_Dec_RegionPointSet(ASN1WorkSpace *workspace, RegionPointSet *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_RegionPointSet(ASN1WorkSpace *workspace, RegionPointSet *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_RegionPointSet(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_RegionPointSet(value)) < 0) return ret;
	return ret;
}
