int ASN1_Print_GeographicalPath_description(GeographicalPath_description *value, int tab_value)
{
	int ret = 0;
	// CHOICE : default
	ASN1_Print_CHOICE(" ");
	if (value == NULL) return -1;
	switch (value->M) {
	case DEF_GeographicalPath_description_path:
		// Type Reference OffsetSystem
		if (Compare_Letter(tab_value, "path")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("path = ");
		}
		if ((ret = ASN1_Print_OffsetSystem((OffsetSystem *)value->elements.path, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_GeographicalPath_description_geometry:
		// Type Reference GeometricProjection
		if (Compare_Letter(tab_value, "geometry")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("geometry = ");
		}
		if ((ret = ASN1_Print_GeometricProjection((GeometricProjection *)value->elements.geometry, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_GeographicalPath_description_oldRegion:
		// Type Reference ValidRegion
		if (Compare_Letter(tab_value, "oldRegion")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("oldRegion = ");
		}
		if ((ret = ASN1_Print_ValidRegion((ValidRegion *)value->elements.oldRegion, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	default: return -1;
}
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
