int ASN1_PER_UNAlign_Enc_GeographicalPath_description(ASN1WorkSpace *workspace, GeographicalPath_description *value)
{ // ASN1_PER_Extern_Encode 
	int ret = 0;
	if ((ret = ASN1_CHECK_GeographicalPath_description(value)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Data_Enc_GeographicalPath_description(workspace,value)) < 0) return ret;
	return ret;
}
extern int ASN1_PER_UNAlign_Data_Dec_OffsetSystem(ASN1WorkSpace *workspace, OffsetSystem *value);
extern int ASN1_PER_UNAlign_Data_Dec_GeometricProjection(ASN1WorkSpace *workspace, GeometricProjection *value);
extern int ASN1_PER_UNAlign_Data_Dec_ValidRegion(ASN1WorkSpace *workspace, ValidRegion *value);
int ASN1_PER_UNAlign_Data_Dec_GeographicalPath_description(ASN1WorkSpace *workspace, GeographicalPath_description *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_path = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_geometry = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_oldRegion = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };

	ASNINT32 index;
	ASNINT64 ui;
	ASNBOOL extbit;
	if ((ret = ASN1_PER_UNAlign_Dec_Choice_ENUMERATED(workspace, &ui, &extbit, 1, 3)) < 0) return ret;

	if (extbit == 0)
	{
		switch(ui)
		{
		case 0: index = DEF_GeographicalPath_description_path;
			value->elements.path = (OffsetSystem *)mpool_malloc(workspace->Pmemory, sizeof(OffsetSystem));
			memset(value->elements.path, 0, sizeof(OffsetSystem));
			break;
		case 1: index = DEF_GeographicalPath_description_geometry;
			value->elements.geometry = (GeometricProjection *)mpool_malloc(workspace->Pmemory, sizeof(GeometricProjection));
			memset(value->elements.geometry, 0, sizeof(GeometricProjection));
			break;
		case 2: index = DEF_GeographicalPath_description_oldRegion;
			value->elements.oldRegion = (ValidRegion *)mpool_malloc(workspace->Pmemory, sizeof(ValidRegion));
			memset(value->elements.oldRegion, 0, sizeof(ValidRegion));
			break;
		default: break;
		}
	}
	else
	{
		switch(ui)
		{
		default: break;
		}
	}
	if ((ret = ASN1_GetM(&value->M, index)) < 0) return ret;
	switch(index)
	{
	case DEF_GeographicalPath_description_path:
		if ((ret = ASN1_PER_UNAlign_Dec_OffsetSystem(workspace, value->elements.path)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_GeographicalPath_description_geometry:
		if ((ret = ASN1_PER_UNAlign_Dec_GeometricProjection(workspace, value->elements.geometry)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_GeographicalPath_description_oldRegion:
		if ((ret = ASN1_PER_UNAlign_Dec_ValidRegion(workspace, value->elements.oldRegion)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	default: ret = ASN1_PER_Dec_unKnown(workspace, UNALIGN); break;
	}
	return ret;
}
extern int ASN1_CHECK_GeographicalPath_description(GeographicalPath_description *value);
extern int ASN1_PER_UNAlign_Data_Dec_GeographicalPath_description(ASN1WorkSpace *workspace, GeographicalPath_description *value);
int ASN1_PER_UNAlign_Dec_GeographicalPath_description(ASN1WorkSpace *workspace, GeographicalPath_description *value)
{
	int ret = 0;
	if ((ret = ASN1_PER_UNAlign_Data_Dec_GeographicalPath_description(workspace,value)) < 0) return ret;
	if ((ret = ASN1_CHECK_GeographicalPath_description(value)) < 0) return ret;
	return ret;
}

/********************************************************
*GeographicalPath_regional                              *
********************************************************/
int ASN1_Print_GeographicalPath_regional(GeographicalPath_regional *value, int tab_value)
{
	int ret = 0;
	int count;
	ASN1ListNode *pnode;
	if (value == NULL) return -1;
	count = value->count;
	pnode = value->head->next;
	// SEQUENCE OF : default
	ASN1_Print_SEQ_OF(" ");
	while(count) {
		// Type Reference RegionalExtension
		ASN_Print_TAB(tab_value + 1);
		if ((ret = ASN1_Print_RegionalExtension((RegionalExtension *)pnode->data, tab_value + 1)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}

	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
extern int ASN1_CHECK_RegionalExtension(RegionalExtension *value);
int ASN1_CHECK_GeographicalPath_regional(GeographicalPath_regional *value)
{
	int ret = 0;

	unsigned char checkinfo_GeographicalPath_regional[] = { 
		0x02,0x01,0x04,0x00
	};
	unsigned char checkinfo_GeographicalPath_regional_pdata[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	int count;
	ASN1ListNode* pnode;
	if (value == NULL) return -1;
	if (value->head == NULL) return -1;
	if (value->count < 0) return -1;
	pnode = value->head->next;
	count = value->count;
	while (count) {
		if ((ret = ASN1_CHECK_RegionalExtension(pnode->data)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}
	return ret;
}
extern int ASN1_BER_Data_Enc_RegionalExtension(ASN1WorkSpace *workspace, RegionalExtension *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_GeographicalPath_regional(ASN1WorkSpace *workspace, GeographicalPath_regional *value, ASN1TagType tagFlag)
{
	int ret = 0;
	ASN1ListNode *pnode;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	pnode = value->head->next;
	while (NULL != pnode)
	{
		if ((ret = ASN1_BER_Data_Enc_RegionalExtension(workspace, pnode->data, ASN1EXPL)) < 0) return ret;
		pnode = pnode->next;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_GeographicalPath_regional(GeographicalPath_regional *value);
extern int ASN1_BER_Data_Enc_GeographicalPath_regional(ASN1WorkSpace *workspace, GeographicalPath_regional *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_GeographicalPath_regional(ASN1WorkSpace *workspace, GeographicalPath_regional *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_GeographicalPath_regional(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_GeographicalPath_regional(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_RegionalExtension(ASN1WorkSpace *workspace, RegionalExtension *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_GeographicalPath_regional(ASN1WorkSpace *workspace, GeographicalPath_regional *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	RegionalExtension *pdata;
	ASNUINT8 *p = workspace->buffer.current;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	if ((ret = ASN1_Creat_Init_List(workspace, value)) < 0) return ret;
	while (ASN1_BER_Dec_Isloop(workspace, p, length))
	{
		pdata = (RegionalExtension *)mpool_malloc(GetMemPool(workspace), sizeof(RegionalExtension));
		memset(pdata, 0, sizeof(RegionalExtension));
		if ((ret = ASN1_BER_Data_Dec_RegionalExtension(workspace, pdata, len, ASN1EXPL)) < 0) return ret;
		if ((ret = ASN1_Insert_Node(workspace, value,(void*)pdata)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_GeographicalPath_regional(GeographicalPath_regional *value);
extern int ASN1_BER_Data_Dec_GeographicalPath_regional(ASN1WorkSpace *workspace, GeographicalPath_regional *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_GeographicalPath_regional(ASN1WorkSpace *workspace, GeographicalPath_regional *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_GeographicalPath_regional(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_GeographicalPath_regional(value)) < 0) return ret;
	return ret;
}
extern int ASN1_PER_Align_Data_Enc_RegionalExtension(ASN1WorkSpace *workspace, RegionalExtension *value);
int ASN1_PER_Align_Data_Enc_GeographicalPath_regional(ASN1WorkSpace *workspace, GeographicalPath_regional *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_GeographicalPath_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_GeographicalPath_regional_pdata = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	ASNINT32 loop_set = 1;
	ASNINT32 all_length = value->count;
	ASNINT32 process_length = 0;
	ASNINT32 i = 0;
	ASN1ListNode *pnode = value->head->next;
	while(loop_set)
	{
		loop_set = ASN1_PER_Align_Enc_Set_Seq_Of_Length(workspace, &all_length, &process_length, &consinfo_GeographicalPath_regional);
		for(i = 0; i < process_length; i++)
		{
			if ((ret = ASN1_PER_Align_Enc_RegionalExtension(workspace, pnode->data)) < 0) return ret;
			pnode = pnode->next;
		}
	}
	if (value->count != 0 && value->count % 16384 == 0)
	{
		if ((ret = ASN1_PER_Align_WirteBuffer(workspace)) < 0) return ret;
	}
	return ret;
}
