extern int ASN1_CHECK_RoadSegmentReferenceID(RoadSegmentReferenceID *value);
extern int ASN1_CHECK_Position3D(Position3D *value);
extern int ASN1_CHECK_GeographicalPath_description(GeographicalPath_description *value);
extern int ASN1_CHECK_GeographicalPath_regional(GeographicalPath_regional *value);
int ASN1_CHECK_GeographicalPath(GeographicalPath *value)
{
	int ret = 0;

	unsigned char checkinfo_name[] = { 
		0x02,0x01,0x3F,0x00
	};
	unsigned char checkinfo_id[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_anchor[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_laneWidth[] = { 
		0x02,0x00,0x82,0x7F,0xFF,0x00
	};
	unsigned char checkinfo_directionality[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_closedPath[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_direction[] = { 
		0x02,0x10,0x10,0x00
	};
	unsigned char checkinfo_description[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_GeographicalPath_name == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_IA5String(&(value->name), checkinfo_name)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_GeographicalPath_id == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_RoadSegmentReferenceID(value->id)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_GeographicalPath_anchor == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_Position3D(value->anchor)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_GeographicalPath_laneWidth == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->laneWidth), checkinfo_laneWidth)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_GeographicalPath_directionality == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->directionality), checkinfo_directionality)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_GeographicalPath_closedPath == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BOOLEAN(&(value->closedPath), checkinfo_closedPath)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_GeographicalPath_direction == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BITSTRING(&(value->direction), checkinfo_direction)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_GeographicalPath_description == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_GeographicalPath_description(value->description)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_GeographicalPath_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_GeographicalPath_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
