/********************************************************
*ITIScodesAndText_element_item                          *
********************************************************/
int ASN1_Print_ITIScodesAndText_element_item(ITIScodesAndText_element_item *value, int tab_value)
{
	int ret = 0;
	// CHOICE : default
	ASN1_Print_CHOICE(" ");
	if (value == NULL) return -1;
	switch (value->M) {
	case DEF_ITIScodesAndText_element_item_itis:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("ITIScodes", &value->elements.itis)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_ITIScodesAndText_element_item_text:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_IA5String("ITIStext", &value->elements.text)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	default: return -1;
}
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_ITIScodesAndText_element_item_itis(ASN1WorkSpace *workspace, ITIScodesAndText_element_item *value, INTEGER user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	value->M = DEF_ITIScodesAndText_element_item_itis;
	if ((ret = ASN1_SET_INTEGER(workspace, &value->elements.itis, user_value)) < 0) return ret;
	return ret;
}
int ASN1_SET_ITIScodesAndText_element_item_text(ASN1WorkSpace *workspace, ITIScodesAndText_element_item *value, ASNUINT8 *user_value, ASNUINT32 user_value_length)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->M = DEF_ITIScodesAndText_element_item_text;
	if ((ret = ASN1_SET_IA5String(workspace, &value->elements.text, user_value, user_value_length)) < 0) return ret;
	return ret;
}
int ASN1_GET_ITIScodesAndText_element_item_itis(ASN1WorkSpace *workspace, ITIScodesAndText_element_item *value, INTEGER *user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if (value->M == DEF_ITIScodesAndText_element_item_itis)
	{
		if ((ret = ASN1_GET_INTEGER(workspace, &value->elements.itis, user_value)) < 0) return ret;
	}
	else return -2;
	return ret;
}
int ASN1_GET_ITIScodesAndText_element_item_text(ASN1WorkSpace *workspace, ITIScodesAndText_element_item *value, ASNUINT8 **user_value, ASNUINT32 *user_value_length)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if (value->M == DEF_ITIScodesAndText_element_item_text)
	{
		if ((ret = ASN1_GET_IA5String(workspace, &value->elements.text, user_value, user_value_length)) < 0) return ret;
	}
	else return -2;
	return ret;
}
int ASN1_CHECK_ITIScodesAndText_element_item(ITIScodesAndText_element_item *value)
{
	int ret = 0;

	unsigned char checkinfo_itis[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};
	unsigned char checkinfo_text[] = { 
		0x02,0x01,0x82,0x01,0xF4,0x00
	};

	if (value == NULL) return -1;
	switch (value->M)
	{
	case DEF_ITIScodesAndText_element_item_itis:
		if ((ret = ASN1_CHECK_INTEGER(&value->elements.itis, checkinfo_itis)) < 0) return ret;
		break;
	case DEF_ITIScodesAndText_element_item_text:
		if ((ret = ASN1_CHECK_IA5String(&value->elements.text, checkinfo_text)) < 0) return ret;
		break;
	default: break;
	}
	return ret;
}
