int ASN1_BER_Data_Dec_ITIScodesAndText_element_item(ASN1WorkSpace *workspace, ITIScodesAndText_element_item *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	value->M = 0;
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	switch(tag)
	{
	case ITS_ASN_CONT | ITS_ASN_PRIM | 0:
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_ITIScodes(workspace, &value->elements.itis, len, ASN1IMPL)) < 0) return ret;
		value->M = DEF_ITIScodesAndText_element_item_itis;
		break;
	case ITS_ASN_CONT | ITS_ASN_PRIM | 1:
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_ITIStext(workspace, &value->elements.text, len, ASN1IMPL)) < 0) return ret;
		value->M = DEF_ITIScodesAndText_element_item_text;
		break;
	}
	return ret;
}
