int ASN1_Print_GenericSignage_element(GenericSignage_element *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier == NULL
	ASN1_Print_SEQ(" ");
	// Type Reference GenericSignage_element_item
	if (Compare_Letter(tab_value, "item")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("item = ");
	}
	if ((ret = ASN1_Print_GenericSignage_element_item((GenericSignage_element_item *)value->item, tab_value + 1)) < 0) return ret;
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_GenericSignage_element_item(ASN1WorkSpace *workspace, GenericSignage_element *value, GenericSignage_element_item *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->item = (GenericSignage_element_item *)mpool_malloc(workspace->Pmemory, sizeof(GenericSignage_element_item));
	memset(value->item, 0, sizeof(GenericSignage_element_item));
	memmove(value->item, user_value, sizeof(GenericSignage_element_item));
	return ret;
}
int ASN1_GET_GenericSignage_element_item(ASN1WorkSpace *workspace, GenericSignage_element *value, GenericSignage_element_item **user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	*user_value = value->item;
	return ret;
}
extern int ASN1_CHECK_GenericSignage_element_item(GenericSignage_element_item *value);
int ASN1_CHECK_GenericSignage_element(GenericSignage_element *value)
{
	int ret = 0;

	unsigned char checkinfo_item[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_GenericSignage_element_item(value->item)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Enc_GenericSignage_element_item(ASN1WorkSpace *workspace, GenericSignage_element_item *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_GenericSignage_element(ASN1WorkSpace *workspace, GenericSignage_element *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_GenericSignage_element_item(workspace, value->item, ASN1EXPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
