/********************************************************
*GenericSignage                                         *
********************************************************/
int ASN1_Print_GenericSignage(GenericSignage *value, int tab_value)
{
	int ret = 0;
	int count;
	ASN1ListNode *pnode;
	if (value == NULL) return -1;
	count = value->count;
	pnode = value->head->next;
	// SEQUENCE OF : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ_OF("GenericSignage");
	while(count) {
		// Type Reference GenericSignage_element
		ASN_Print_TAB(tab_value + 1);
		if ((ret = ASN1_Print_GenericSignage_element((GenericSignage_element *)pnode->data, tab_value + 1)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}

	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
extern int ASN1_CHECK_GenericSignage_element(GenericSignage_element *value);
int ASN1_CHECK_GenericSignage(GenericSignage *value)
{
	int ret = 0;

	unsigned char checkinfo_GenericSignage[] = { 
		0x02,0x01,0x10,0x00
	};
	unsigned char checkinfo_GenericSignage_pdata[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	int count;
	ASN1ListNode* pnode;
	if (value == NULL) return -1;
	if (value->head == NULL) return -1;
	if (value->count < 0) return -1;
	pnode = value->head->next;
	count = value->count;
	while (count) {
		if ((ret = ASN1_CHECK_GenericSignage_element(pnode->data)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}
	return ret;
}
extern int ASN1_BER_Data_Enc_GenericSignage_element(ASN1WorkSpace *workspace, GenericSignage_element *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_GenericSignage(ASN1WorkSpace *workspace, GenericSignage *value, ASN1TagType tagFlag)
{
	int ret = 0;
	ASN1ListNode *pnode;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	pnode = value->head->next;
	while (NULL != pnode)
	{
		if ((ret = ASN1_BER_Data_Enc_GenericSignage_element(workspace, pnode->data, ASN1EXPL)) < 0) return ret;
		pnode = pnode->next;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
