int ASN1_Print_ExitService_element_item(ExitService_element_item *value, int tab_value)
{
	int ret = 0;
	// CHOICE : default
	ASN1_Print_CHOICE(" ");
	if (value == NULL) return -1;
	switch (value->M) {
	case DEF_ExitService_element_item_itis:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("ITIScodes", &value->elements.itis)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_ExitService_element_item_text:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_IA5String("ITIStextPhrase", &value->elements.text)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	default: return -1;
}
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
