int ASN1_Print_TravelerDataFrame_content(TravelerDataFrame_content *value, int tab_value)
{
	int ret = 0;
	// CHOICE : default
	ASN1_Print_CHOICE(" ");
	if (value == NULL) return -1;
	switch (value->M) {
	case DEF_TravelerDataFrame_content_advisory:
		// Type Reference ITIScodesAndText
		if (Compare_Letter(tab_value, "advisory")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("advisory = ");
		}
		if ((ret = ASN1_Print_ITIScodesAndText((ITIScodesAndText *)&value->elements.advisory, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_TravelerDataFrame_content_workZone:
		// Type Reference WorkZone
		if (Compare_Letter(tab_value, "workZone")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("workZone = ");
		}
		if ((ret = ASN1_Print_WorkZone((WorkZone *)&value->elements.workZone, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_TravelerDataFrame_content_genericSign:
		// Type Reference GenericSignage
		if (Compare_Letter(tab_value, "genericSign")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("genericSign = ");
		}
		if ((ret = ASN1_Print_GenericSignage((GenericSignage *)&value->elements.genericSign, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_TravelerDataFrame_content_speedLimit:
		// Type Reference SpeedLimit
		if (Compare_Letter(tab_value, "speedLimit")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("speedLimit = ");
		}
		if ((ret = ASN1_Print_SpeedLimit((SpeedLimit *)&value->elements.speedLimit, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_TravelerDataFrame_content_exitService:
		// Type Reference ExitService
		if (Compare_Letter(tab_value, "exitService")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("exitService = ");
		}
		if ((ret = ASN1_Print_ExitService((ExitService *)&value->elements.exitService, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	default: return -1;
}
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
