/********************************************************
*TravelerDataFrame                                      *
********************************************************/
int ASN1_Print_TravelerDataFrame(TravelerDataFrame *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("TravelerDataFrame");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("SSPindex", &(value->notUsed))) < 0) return ret;
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->frameType)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("TravelerInfoType", "unknown", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("TravelerInfoType", "advisory", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("TravelerInfoType", "roadSignage", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("TravelerInfoType", "commercialSignage", 3)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	// Type Reference TravelerDataFrame_msgId
	if (Compare_Letter(tab_value, "msgId")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("msgId = ");
	}
	if ((ret = ASN1_Print_TravelerDataFrame_msgId((TravelerDataFrame_msgId *)value->msgId, tab_value + 1)) < 0) return ret;
	if (value->DEF_TravelerDataFrame_startYear == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DYear", &(value->startYear))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("MinuteOfTheYear", &(value->startTime))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("MinutesDuration", &(value->durationTime))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("SignPriority", &(value->priority))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("SSPindex", &(value->notUsed1))) < 0) return ret;
	// Type Reference TravelerDataFrame_regions
	if (Compare_Letter(tab_value, "regions")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("regions = ");
	}
	if ((ret = ASN1_Print_TravelerDataFrame_regions((TravelerDataFrame_regions *)&(value->regions), tab_value + 1)) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("SSPindex", &(value->notUsed2))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("SSPindex", &(value->notUsed3))) < 0) return ret;
	// Type Reference TravelerDataFrame_content
	if (Compare_Letter(tab_value, "content")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("content = ");
	}
	if ((ret = ASN1_Print_TravelerDataFrame_content((TravelerDataFrame_content *)value->content, tab_value + 1)) < 0) return ret;
	if (value->DEF_TravelerDataFrame_url == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_IA5String("URL_Short", &(value->url))) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
