extern int ASN1_CHECK_TravelerDataFrame_regions(TravelerDataFrame_regions *value);
extern int ASN1_CHECK_TravelerDataFrame_content(TravelerDataFrame_content *value);
int ASN1_CHECK_TravelerDataFrame(TravelerDataFrame *value)
{
	int ret = 0;

	unsigned char checkinfo_notUsed[] = { 
		0x02,0x00,0x1F,0x00
	};
	unsigned char checkinfo_frameType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_msgId[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_startYear[] = { 
		0x02,0x00,0x82,0x0F,0xFF,0x00
	};
	unsigned char checkinfo_startTime[] = { 
		0x02,0x00,0x83,0x08,0x0A,0xC0,0x00
	};
	unsigned char checkinfo_durationTime[] = { 
		0x02,0x00,0x82,0x7D,0x00,0x00
	};
	unsigned char checkinfo_priority[] = { 
		0x02,0x00,0x07,0x00
	};
	unsigned char checkinfo_notUsed1[] = { 
		0x02,0x00,0x1F,0x00
	};
	unsigned char checkinfo_regions[] = { 
		0x02,0x01,0x10,0x00
	};
	unsigned char checkinfo_notUsed2[] = { 
		0x02,0x00,0x1F,0x00
	};
	unsigned char checkinfo_notUsed3[] = { 
		0x02,0x00,0x1F,0x00
	};
	unsigned char checkinfo_content[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_url[] = { 
		0x02,0x01,0x0F,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->notUsed), checkinfo_notUsed)) < 0) return ret;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->frameType), checkinfo_frameType)) < 0) return ret;
	if ((ret = ASN1_CHECK_TravelerDataFrame_msgId(value->msgId)) < 0) return ret;
	if (value->DEF_TravelerDataFrame_startYear == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->startYear), checkinfo_startYear)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_INTEGER(&(value->startTime), checkinfo_startTime)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->durationTime), checkinfo_durationTime)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->priority), checkinfo_priority)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->notUsed1), checkinfo_notUsed1)) < 0) return ret;
	if ((ret = ASN1_CHECK_TravelerDataFrame_regions(&(value->regions))) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->notUsed2), checkinfo_notUsed2)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->notUsed3), checkinfo_notUsed3)) < 0) return ret;
	if ((ret = ASN1_CHECK_TravelerDataFrame_content(value->content)) < 0) return ret;
	if (value->DEF_TravelerDataFrame_url == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_IA5String(&(value->url), checkinfo_url)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
