/********************************************************
*TravelerDataFrameList                                  *
********************************************************/
int ASN1_Print_TravelerDataFrameList(TravelerDataFrameList *value, int tab_value)
{
	int ret = 0;
	int count;
	ASN1ListNode *pnode;
	if (value == NULL) return -1;
	count = value->count;
	pnode = value->head->next;
	// SEQUENCE OF : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ_OF("TravelerDataFrameList");
	while(count) {
		// Type Reference TravelerDataFrame
		ASN_Print_TAB(tab_value + 1);
		if ((ret = ASN1_Print_TravelerDataFrame((TravelerDataFrame *)pnode->data, tab_value + 1)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}

	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
