int ASN1_Print_TravelerInformation(TravelerInformation *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("TravelerInformation");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("MsgCount", &(value->msgCnt))) < 0) return ret;
	if (value->DEF_TravelerInformation_timeStamp == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("MinuteOfTheYear", &(value->timeStamp))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TravelerInformation_packetID == 1)
	{ /*OPTIONAL start */
		// Type OCTET STRING
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_OCTETSTRING("UniqueMSGID", &(value->packetID), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TravelerInformation_urlB == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_IA5String("URL_Base", &(value->urlB))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Reference TravelerDataFrameList
	if (Compare_Letter(tab_value, "dataFrames")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("dataFrames = ");
	}
	if ((ret = ASN1_Print_TravelerDataFrameList((TravelerDataFrameList *)&(value->dataFrames), tab_value + 1)) < 0) return ret;
	if (value->DEF_TravelerInformation_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference TravelerInformation_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_TravelerInformation_regional((TravelerInformation_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
