{
	int ret = 0;

	unsigned char checkinfo_msgCnt[] = { 
		0x02,0x00,0x7F,0x00
	};
	unsigned char checkinfo_timeStamp[] = { 
		0x02,0x00,0x83,0x08,0x0A,0xC0,0x00
	};
	unsigned char checkinfo_packetID[] = { 
		0x02,0x09,0x09,0x00
	};
	unsigned char checkinfo_urlB[] = { 
		0x02,0x01,0x2D,0x00
	};
	unsigned char checkinfo_dataFrames[] = { 
		0x02,0x01,0x08,0x00
	};
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->msgCnt), checkinfo_msgCnt)) < 0) return ret;
	if (value->DEF_TravelerInformation_timeStamp == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->timeStamp), checkinfo_timeStamp)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TravelerInformation_packetID == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_OCTETSTRING(&(value->packetID), checkinfo_packetID)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TravelerInformation_urlB == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_IA5String(&(value->urlB), checkinfo_urlB)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_TravelerDataFrameList(&(value->dataFrames))) < 0) return ret;
	if (value->DEF_TravelerInformation_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_TravelerInformation_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
