/********************************************************
*RoadSideAlert_description                              *
********************************************************/
int ASN1_Print_RoadSideAlert_description(RoadSideAlert_description *value, int tab_value)
{
	int ret = 0;
	int count;
	ASN1ListNode *pnode;
	if (value == NULL) return -1;
	count = value->count;
	pnode = value->head->next;
	// SEQUENCE OF : default
	ASN1_Print_SEQ_OF(" ");
	while(count) {
		// Type Reference ITIScodes
		if ((ret = ASN1_Print_ITIScodes((ITIScodes *)pnode->data, tab_value + 1)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}

	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_CHECK_RoadSideAlert_description(RoadSideAlert_description *value)
{
	int ret = 0;

	unsigned char checkinfo_RoadSideAlert_description[] = { 
		0x02,0x01,0x08,0x00
	};
	unsigned char checkinfo_RoadSideAlert_description_pdata[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};
	int count;
	ASN1ListNode* pnode;
	if (value == NULL) return -1;
	if (value->head == NULL) return -1;
	if (value->count < 0) return -1;
	pnode = value->head->next;
	count = value->count;
	while (count) {
		if ((ret = ASN1_CHECK_INTEGER(pnode->data, checkinfo_RoadSideAlert_description_pdata)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}
	return ret;
}
extern int ASN1_BER_Data_Enc_ITIScodes(ASN1WorkSpace *workspace, ITIScodes *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_RoadSideAlert_description(ASN1WorkSpace *workspace, RoadSideAlert_description *value, ASN1TagType tagFlag)
{
	int ret = 0;
	ASN1ListNode *pnode;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	pnode = value->head->next;
	while (NULL != pnode)
	{
		if ((ret = ASN1_BER_Data_Enc_ITIScodes(workspace, pnode->data, ASN1EXPL)) < 0) return ret;
		pnode = pnode->next;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_RoadSideAlert_description(RoadSideAlert_description *value);
