{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_RoadSideAlert_description(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_RoadSideAlert_description(value)) < 0) return ret;
	return ret;
}
