/********************************************************
*RoadSideAlert                                          *
********************************************************/
int ASN1_Print_RoadSideAlert(RoadSideAlert *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("RoadSideAlert");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("MsgCount", &(value->msgCnt))) < 0) return ret;
	if (value->DEF_RoadSideAlert_timeStamp == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("MinuteOfTheYear", &(value->timeStamp))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("ITIScodes", &(value->typeEvent))) < 0) return ret;
	if (value->DEF_RoadSideAlert_description == 1)
	{ /*OPTIONAL start */
		// Type Reference RoadSideAlert_description
		if (Compare_Letter(tab_value, "description")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("description = ");
		}
		if ((ret = ASN1_Print_RoadSideAlert_description((RoadSideAlert_description *)&(value->description), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSideAlert_priority == 1)
	{ /*OPTIONAL start */
		// Type OCTET STRING
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_OCTETSTRING("Priority", &(value->priority), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSideAlert_heading == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("HeadingSlice", &(value->heading))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSideAlert_extent == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->extent)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("Extent", "useInstantlyOnly", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("Extent", "useFor3meters", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("Extent", "useFor10meters", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("Extent", "useFor50meters", 3)) < 0) return ret; break;
		case 4: if ((ret = ASN1_Print_ENUMERATED("Extent", "useFor100meters", 4)) < 0) return ret; break;
		case 5: if ((ret = ASN1_Print_ENUMERATED("Extent", "useFor500meters", 5)) < 0) return ret; break;
		case 6: if ((ret = ASN1_Print_ENUMERATED("Extent", "useFor1000meters", 6)) < 0) return ret; break;
		case 7: if ((ret = ASN1_Print_ENUMERATED("Extent", "useFor5000meters", 7)) < 0) return ret; break;
		case 8: if ((ret = ASN1_Print_ENUMERATED("Extent", "useFor10000meters", 8)) < 0) return ret; break;
		case 9: if ((ret = ASN1_Print_ENUMERATED("Extent", "useFor50000meters", 9)) < 0) return ret; break;
		case 10: if ((ret = ASN1_Print_ENUMERATED("Extent", "useFor100000meters", 10)) < 0) return ret; break;
		case 11: if ((ret = ASN1_Print_ENUMERATED("Extent", "useFor500000meters", 11)) < 0) return ret; break;
		case 12: if ((ret = ASN1_Print_ENUMERATED("Extent", "useFor1000000meters", 12)) < 0) return ret; break;
		case 13: if ((ret = ASN1_Print_ENUMERATED("Extent", "useFor5000000meters", 13)) < 0) return ret; break;
		case 14: if ((ret = ASN1_Print_ENUMERATED("Extent", "useFor10000000meters", 14)) < 0) return ret; break;
		case 15: if ((ret = ASN1_Print_ENUMERATED("Extent", "forever", 15)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	if (value->DEF_RoadSideAlert_position == 1)
	{ /*OPTIONAL start */
		// Type Reference FullPositionVector
		if (Compare_Letter(tab_value, "position")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("position = ");
		}
		if ((ret = ASN1_Print_FullPositionVector((FullPositionVector *)value->position, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSideAlert_furtherInfoID == 1)
	{ /*OPTIONAL start */
		// Type OCTET STRING
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_OCTETSTRING("FurtherInfoID", &(value->furtherInfoID), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSideAlert_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference RoadSideAlert_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_RoadSideAlert_regional((RoadSideAlert_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
