extern int ASN1_CHECK_FullPositionVector(FullPositionVector *value);
extern int ASN1_CHECK_RoadSideAlert_regional(RoadSideAlert_regional *value);
int ASN1_CHECK_RoadSideAlert(RoadSideAlert *value)
{
	int ret = 0;

	unsigned char checkinfo_msgCnt[] = { 
		0x02,0x00,0x7F,0x00
	};
	unsigned char checkinfo_timeStamp[] = { 
		0x02,0x00,0x83,0x08,0x0A,0xC0,0x00
	};
	unsigned char checkinfo_typeEvent[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};
	unsigned char checkinfo_description[] = { 
		0x02,0x01,0x08,0x00
	};
	unsigned char checkinfo_priority[] = { 
		0x02,0x01,0x01,0x00
	};
	unsigned char checkinfo_heading[] = { 
		0x02,0x10,0x10,0x00
	};
	unsigned char checkinfo_extent[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_position[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_furtherInfoID[] = { 
		0x02,0x02,0x02,0x00
	};
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->msgCnt), checkinfo_msgCnt)) < 0) return ret;
	if (value->DEF_RoadSideAlert_timeStamp == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->timeStamp), checkinfo_timeStamp)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_INTEGER(&(value->typeEvent), checkinfo_typeEvent)) < 0) return ret;
	if (value->DEF_RoadSideAlert_description == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_RoadSideAlert_description(&(value->description))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSideAlert_priority == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_OCTETSTRING(&(value->priority), checkinfo_priority)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSideAlert_heading == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BITSTRING(&(value->heading), checkinfo_heading)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSideAlert_extent == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->extent), checkinfo_extent)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSideAlert_position == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_FullPositionVector(value->position)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSideAlert_furtherInfoID == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_OCTETSTRING(&(value->furtherInfoID), checkinfo_furtherInfoID)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSideAlert_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_RoadSideAlert_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
