	if ((ret = ASN1_BER_Data_Enc_ITIScodes(workspace, &(value->typeEvent), ASN1IMPL)) < 0) return ret;
	if (value->DEF_RoadSideAlert_description == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 16)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_RoadSideAlert_description(workspace, &(value->description), ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_RoadSideAlert_priority == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 4)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_Priority(workspace, &(value->priority), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_RoadSideAlert_heading == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 5)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_HeadingSlice(workspace, &(value->heading), ASN1IMPL)) < 0) return ret;
	}
