	{
		if ((ret = ASN1_PER_Align_Enc_EventDescription_regional(workspace, &(value->regional))) < 0) return ret;
	}
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, ALIGN, 0);
	}
