extern int ASN1_PER_Align_Data_Dec_EventDescription_description(ASN1WorkSpace *workspace, EventDescription_description *value);
extern int ASN1_PER_Align_Data_Dec_EventDescription_regional(ASN1WorkSpace *workspace, EventDescription_regional *value);
int ASN1_PER_Align_Data_Dec_EventDescription(ASN1WorkSpace *workspace, EventDescription *value)
{
	int ret = 0;
	ASNINT32 ui_extent;
	struct Asn1ConsInfo consinfo_typeEvent = { ASN1_CONST64(0), ASN1_CONST64(65535), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_description = { ASN1_CONST64(1), ASN1_CONST64(8), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_priority = { ASN1_CONST64(1), ASN1_CONST64(1), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_heading = { ASN1_CONST64(16), ASN1_CONST64(16), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_extent = { ASN1_CONST64(0), ASN1_CONST64(15), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNBOOL extbit_EventDescription;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_EventDescription)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 5, &_optvalue)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->typeEvent), &consinfo_typeEvent)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_EventDescription_description = 1;
		if ((ret = ASN1_PER_Align_Dec_EventDescription_description(workspace, &(value->description))) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_EventDescription_priority = 1;
		if ((ret = ASN1_PER_Align_Dec_OCTETSTRING(workspace, &(value->priority), &consinfo_priority)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 3) == 1)
	{
		value->DEF_EventDescription_heading = 1;
		if ((ret = ASN1_PER_Align_Dec_BITSTRING(workspace, &(value->heading), &consinfo_heading)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 4) == 1)
	{
		value->DEF_EventDescription_extent = 1;
		if ((ret = ASN1_PER_Align_Dec_ENUMERATED(workspace, &ui_extent, &consinfo_extent)) < 0) return ret;
		if (consinfo_extent.enumextbit == 0)
		{
			switch(ui_extent)
			{
			case 0: value->extent = Extent_useInstantlyOnly; break;
			case 1: value->extent = Extent_useFor3meters; break;
			case 2: value->extent = Extent_useFor10meters; break;
			case 3: value->extent = Extent_useFor50meters; break;
			case 4: value->extent = Extent_useFor100meters; break;
			case 5: value->extent = Extent_useFor500meters; break;
			case 6: value->extent = Extent_useFor1000meters; break;
			case 7: value->extent = Extent_useFor5000meters; break;
			case 8: value->extent = Extent_useFor10000meters; break;
			case 9: value->extent = Extent_useFor50000meters; break;
			case 10: value->extent = Extent_useFor100000meters; break;
			case 11: value->extent = Extent_useFor500000meters; break;
			case 12: value->extent = Extent_useFor1000000meters; break;
			case 13: value->extent = Extent_useFor5000000meters; break;
			case 14: value->extent = Extent_useFor10000000meters; break;
			case 15: value->extent = Extent_forever; break;
			default: value->extent = ui_extent; break;
			}
		}
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 5) == 1)
	{
		value->DEF_EventDescription_regional = 1;
		if ((ret = ASN1_PER_Align_Dec_EventDescription_regional(workspace, &(value->regional))) < 0) return ret;
	}
	if (extbit_EventDescription == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, ALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, ALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
