int ASN1_CHECK_PivotPointDescription(PivotPointDescription *value)
{
	int ret = 0;

	unsigned char checkinfo_pivotOffset[] = { 
		0x02,0x82,0xFC,0x00,0x82,0x03,0xFF,0x00
	};
	unsigned char checkinfo_pivotAngle[] = { 
		0x02,0x00,0x82,0x70,0x80,0x00
	};
	unsigned char checkinfo_pivots[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->pivotOffset), checkinfo_pivotOffset)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->pivotAngle), checkinfo_pivotAngle)) < 0) return ret;
	if ((ret = ASN1_CHECK_BOOLEAN(&(value->pivots), checkinfo_pivots)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Enc_Offset_B11(ASN1WorkSpace *workspace, Offset_B11 *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_Angle(ASN1WorkSpace *workspace, Angle *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_PivotingAllowed(ASN1WorkSpace *workspace, PivotingAllowed *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_PivotPointDescription(ASN1WorkSpace *workspace, PivotPointDescription *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_Offset_B11(workspace, &(value->pivotOffset), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_Angle(workspace, &(value->pivotAngle), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_PivotingAllowed(workspace, &(value->pivots), ASN1IMPL)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_PivotPointDescription(PivotPointDescription *value);
