int ASN1_PER_Align_Data_Dec_PivotPointDescription(ASN1WorkSpace *workspace, PivotPointDescription *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_pivotOffset = { ASN1_CONST64(-1024), ASN1_CONST64(1023), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_pivotAngle = { ASN1_CONST64(0), ASN1_CONST64(28800), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_pivots = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };

	ASNBOOL extbit_PivotPointDescription;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_PivotPointDescription)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->pivotOffset), &consinfo_pivotOffset)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->pivotAngle), &consinfo_pivotAngle)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Dec_BOOLEAN(workspace, &(value->pivots), &consinfo_pivots)) < 0) return ret;
	if (extbit_PivotPointDescription == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, ALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, ALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
