/********************************************************
*TrailerUnitDescription                                 *
********************************************************/
int ASN1_Print_TrailerUnitDescription(TrailerUnitDescription *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("TrailerUnitDescription");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BOOLEAN("IsDolly", &(value->isDolly))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("VehicleWidth", &(value->width))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("VehicleLength", &(value->length))) < 0) return ret;
	if (value->DEF_TrailerUnitDescription_height == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("VehicleHeight", &(value->height))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TrailerUnitDescription_mass == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("TrailerMass", &(value->mass))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TrailerUnitDescription_bumperHeights == 1)
	{ /*OPTIONAL start */
		// Type Reference BumperHeights
		if (Compare_Letter(tab_value, "bumperHeights")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("bumperHeights = ");
		}
		if ((ret = ASN1_Print_BumperHeights((BumperHeights *)value->bumperHeights, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TrailerUnitDescription_centerOfGravity == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("VehicleHeight", &(value->centerOfGravity))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Reference PivotPointDescription
	if (Compare_Letter(tab_value, "frontPivot")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("frontPivot = ");
	}
	if ((ret = ASN1_Print_PivotPointDescription((PivotPointDescription *)value->frontPivot, tab_value + 1)) < 0) return ret;
	if (value->DEF_TrailerUnitDescription_rearPivot == 1)
	{ /*OPTIONAL start */
		// Type Reference PivotPointDescription
		if (Compare_Letter(tab_value, "rearPivot")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("rearPivot = ");
		}
		if ((ret = ASN1_Print_PivotPointDescription((PivotPointDescription *)value->rearPivot, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TrailerUnitDescription_rearWheelOffset == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("Offset_B12", &(value->rearWheelOffset))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Reference Node_XY_24b
	if (Compare_Letter(tab_value, "positionOffset")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("positionOffset = ");
	}
	if ((ret = ASN1_Print_Node_XY_24b((Node_XY_24b *)value->positionOffset, tab_value + 1)) < 0) return ret;
	if (value->DEF_TrailerUnitDescription_elevationOffset == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("VertOffset_B07", &(value->elevationOffset))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TrailerUnitDescription_crumbData == 1)
	{ /*OPTIONAL start */
		// Type Reference TrailerHistoryPointList
		if (Compare_Letter(tab_value, "crumbData")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("crumbData = ");
		}
		if ((ret = ASN1_Print_TrailerHistoryPointList((TrailerHistoryPointList *)&(value->crumbData), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
