/********************************************************
*TrailerData                                            *
********************************************************/
int ASN1_Print_TrailerData(TrailerData *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("TrailerData");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("SSPindex", &(value->doNotUse))) < 0) return ret;
	// Type Reference PivotPointDescription
	if (Compare_Letter(tab_value, "connection")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("connection = ");
	}
	if ((ret = ASN1_Print_PivotPointDescription((PivotPointDescription *)value->connection, tab_value + 1)) < 0) return ret;
	// Type Reference TrailerUnitDescriptionList
	if (Compare_Letter(tab_value, "units")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("units = ");
	}
	if ((ret = ASN1_Print_TrailerUnitDescriptionList((TrailerUnitDescriptionList *)&(value->units), tab_value + 1)) < 0) return ret;
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_TrailerData_doNotUse(ASN1WorkSpace *workspace, TrailerData *value, INTEGER user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if ((ret = ASN1_SET_INTEGER(workspace, &value->doNotUse, user_value)) < 0) return ret;
	return ret;
}
int ASN1_SET_TrailerData_connection(ASN1WorkSpace *workspace, TrailerData *value, PivotPointDescription *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->connection = (PivotPointDescription *)mpool_malloc(workspace->Pmemory, sizeof(PivotPointDescription));
	memset(value->connection, 0, sizeof(PivotPointDescription));
	memmove(value->connection, user_value, sizeof(PivotPointDescription));
	return ret;
}
int ASN1_SET_TrailerData_units(ASN1WorkSpace *workspace, TrailerData *value, TrailerUnitDescriptionList *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	memmove(&value->units, user_value, sizeof(TrailerUnitDescriptionList));
	return ret;
}
