extern int ASN1_BER_Data_Dec_SSPindex(ASN1WorkSpace *workspace, SSPindex *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_PivotPointDescription(ASN1WorkSpace *workspace, PivotPointDescription *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_TrailerUnitDescriptionList(ASN1WorkSpace *workspace, TrailerUnitDescriptionList *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_TrailerData(ASN1WorkSpace *workspace, TrailerData *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT8 *_cpointer;
	value->connection = (PivotPointDescription *)mpool_malloc(workspace->Pmemory, sizeof(PivotPointDescription));
	memset(value->connection, 0, sizeof(PivotPointDescription));
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_SSPindex(workspace, &value->doNotUse, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_PivotPointDescription(workspace, value->connection, len, ASN1IMPL)) < 0) return ret;
	if (IfFixedLength(len) == -1)
	{
		if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
	}
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_TrailerUnitDescriptionList(workspace, &value->units, len, ASN1IMPL)) < 0) return ret;
	if (IfFixedLength(len) == -1)
	{
		if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_TrailerData(TrailerData *value);
extern int ASN1_BER_Data_Dec_TrailerData(ASN1WorkSpace *workspace, TrailerData *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_TrailerData(ASN1WorkSpace *workspace, TrailerData *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_TrailerData(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_TrailerData(value)) < 0) return ret;
	return ret;
}
