extern int ASN1_PER_Align_Data_Enc_TrailerUnitDescriptionList(ASN1WorkSpace *workspace, TrailerUnitDescriptionList *value);
int ASN1_PER_Align_Data_Enc_TrailerData(ASN1WorkSpace *workspace, TrailerData *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_doNotUse = { ASN1_CONST64(0), ASN1_CONST64(31), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_connection = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_units = { ASN1_CONST64(1), ASN1_CONST64(8), NULL, 0, CONS, 0, 0 };

	ASNINT32 all_bit;
	ASNUINT16 all_pointer;
	if ((ret = ASN1_PER_Enc_extbit(workspace, value->E)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->doNotUse), &consinfo_doNotUse)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Enc_PivotPointDescription(workspace, value->connection)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Enc_TrailerUnitDescriptionList(workspace, &(value->units))) < 0) return ret;
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, ALIGN, 0);
	}
	return ret;
}
