extern int ASN1_PER_Align_Data_Dec_TrailerUnitDescriptionList(ASN1WorkSpace *workspace, TrailerUnitDescriptionList *value);
int ASN1_PER_Align_Data_Dec_TrailerData(ASN1WorkSpace *workspace, TrailerData *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_doNotUse = { ASN1_CONST64(0), ASN1_CONST64(31), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_connection = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_units = { ASN1_CONST64(1), ASN1_CONST64(8), NULL, 0, CONS, 0, 0 };

	ASNBOOL extbit_TrailerData;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_TrailerData)) < 0) return ret;
	value->connection = (PivotPointDescription *)mpool_malloc(workspace->Pmemory, sizeof(PivotPointDescription));
	memset(value->connection, 0, sizeof(PivotPointDescription));
	if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->doNotUse), &consinfo_doNotUse)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Dec_PivotPointDescription(workspace, value->connection)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Dec_TrailerUnitDescriptionList(workspace, &(value->units))) < 0) return ret;
	if (extbit_TrailerData == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, ALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, ALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
