/********************************************************
*SpecialVehicleExtensions                               *
********************************************************/
int ASN1_Print_SpecialVehicleExtensions(SpecialVehicleExtensions *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("SpecialVehicleExtensions");
	if (value->DEF_SpecialVehicleExtensions_vehicleAlerts == 1)
	{ /*OPTIONAL start */
		// Type Reference EmergencyDetails
		if (Compare_Letter(tab_value, "vehicleAlerts")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("vehicleAlerts = ");
		}
		if ((ret = ASN1_Print_EmergencyDetails((EmergencyDetails *)value->vehicleAlerts, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SpecialVehicleExtensions_description == 1)
	{ /*OPTIONAL start */
		// Type Reference EventDescription
		if (Compare_Letter(tab_value, "description")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("description = ");
		}
		if ((ret = ASN1_Print_EventDescription((EventDescription *)value->description, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SpecialVehicleExtensions_trailers == 1)
	{ /*OPTIONAL start */
		// Type Reference TrailerData
		if (Compare_Letter(tab_value, "trailers")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("trailers = ");
		}
		if ((ret = ASN1_Print_TrailerData((TrailerData *)value->trailers, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_SpecialVehicleExtensions_vehicleAlerts(ASN1WorkSpace *workspace, SpecialVehicleExtensions *value, EmergencyDetails *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->vehicleAlerts = (EmergencyDetails *)mpool_malloc(workspace->Pmemory, sizeof(EmergencyDetails));
	memset(value->vehicleAlerts, 0, sizeof(EmergencyDetails));
	value->DEF_SpecialVehicleExtensions_vehicleAlerts = 1;
	memmove(value->vehicleAlerts, user_value, sizeof(EmergencyDetails));
	return ret;
}
