int ASN1_CHECK_SpecialVehicleExtensions(SpecialVehicleExtensions *value)
{
	int ret = 0;

	unsigned char checkinfo_vehicleAlerts[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_description[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_trailers[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if (value->DEF_SpecialVehicleExtensions_vehicleAlerts == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_EmergencyDetails(value->vehicleAlerts)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SpecialVehicleExtensions_description == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_EventDescription(value->description)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SpecialVehicleExtensions_trailers == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_TrailerData(value->trailers)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
