int ASN1_PER_Align_Data_Enc_SpecialVehicleExtensions(ASN1WorkSpace *workspace, SpecialVehicleExtensions *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_vehicleAlerts = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_description = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_trailers = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };

	ASNINT32 all_bit;
	ASNUINT16 all_pointer;
	if ((ret = ASN1_PER_Enc_extbit(workspace, value->E)) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_SpecialVehicleExtensions_vehicleAlerts == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_SpecialVehicleExtensions_description == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_SpecialVehicleExtensions_trailers == 1 ? 1 : 0) )) < 0) return ret;
	if (value->DEF_SpecialVehicleExtensions_vehicleAlerts == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_EmergencyDetails(workspace, value->vehicleAlerts)) < 0) return ret;
	}
	if (value->DEF_SpecialVehicleExtensions_description == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_EventDescription(workspace, value->description)) < 0) return ret;
	}
	if (value->DEF_SpecialVehicleExtensions_trailers == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_TrailerData(workspace, value->trailers)) < 0) return ret;
	}
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, ALIGN, 0);
	}
	return ret;
}
