/********************************************************
*VehicleData                                            *
********************************************************/
int ASN1_Print_VehicleData(VehicleData *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("VehicleData");
	if (value->DEF_VehicleData_height == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("VehicleHeight", &(value->height))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleData_bumpers == 1)
	{ /*OPTIONAL start */
		// Type Reference BumperHeights
		if (Compare_Letter(tab_value, "bumpers")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("bumpers = ");
		}
		if ((ret = ASN1_Print_BumperHeights((BumperHeights *)value->bumpers, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleData_mass == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("VehicleMass", &(value->mass))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleData_trailerWeight == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("TrailerWeight", &(value->trailerWeight))) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
