extern int ASN1_CHECK_BumperHeights(BumperHeights *value);
int ASN1_CHECK_VehicleData(VehicleData *value)
{
	int ret = 0;

	unsigned char checkinfo_height[] = { 
		0x02,0x00,0x7F,0x00
	};
	unsigned char checkinfo_bumpers[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_mass[] = { 
		0x02,0x00,0x82,0x00,0xFF,0x00
	};
	unsigned char checkinfo_trailerWeight[] = { 
		0x02,0x00,0x83,0x00,0xFA,0xFF,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_VehicleData_height == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->height), checkinfo_height)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleData_bumpers == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BumperHeights(value->bumpers)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleData_mass == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->mass), checkinfo_mass)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleData_trailerWeight == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->trailerWeight), checkinfo_trailerWeight)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_VehicleHeight(ASN1WorkSpace *workspace, VehicleHeight *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_BumperHeights(ASN1WorkSpace *workspace, BumperHeights *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_VehicleMass(ASN1WorkSpace *workspace, VehicleMass *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_TrailerWeight(ASN1WorkSpace *workspace, TrailerWeight *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_VehicleData(ASN1WorkSpace *workspace, VehicleData *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if (value->DEF_VehicleData_height == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_VehicleHeight(workspace, &(value->height), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_VehicleData_bumpers == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_BumperHeights(workspace, value->bumpers, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_VehicleData_mass == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_VehicleMass(workspace, &(value->mass), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_VehicleData_trailerWeight == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_TrailerWeight(workspace, &(value->trailerWeight), ASN1IMPL)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_VehicleData(VehicleData *value);
extern int ASN1_BER_Data_Enc_VehicleData(ASN1WorkSpace *workspace, VehicleData *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_VehicleData(ASN1WorkSpace *workspace, VehicleData *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_VehicleData(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_VehicleData(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_VehicleHeight(ASN1WorkSpace *workspace, VehicleHeight *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_BumperHeights(ASN1WorkSpace *workspace, BumperHeights *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_VehicleMass(ASN1WorkSpace *workspace, VehicleMass *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_TrailerWeight(ASN1WorkSpace *workspace, TrailerWeight *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_VehicleData(ASN1WorkSpace *workspace, VehicleData *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	value->bumpers = (BumperHeights *)mpool_malloc(workspace->Pmemory, sizeof(BumperHeights));
	memset(value->bumpers, 0, sizeof(BumperHeights));
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 0))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_VehicleHeight(workspace, &value->height, len, ASN1IMPL)) < 0) return ret;
		value->DEF_VehicleData_height = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_CONS | 1))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_BumperHeights(workspace, value->bumpers, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->DEF_VehicleData_bumpers = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 2))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_VehicleMass(workspace, &value->mass, len, ASN1IMPL)) < 0) return ret;
		value->DEF_VehicleData_mass = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 3))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_TrailerWeight(workspace, &value->trailerWeight, len, ASN1IMPL)) < 0) return ret;
		value->DEF_VehicleData_trailerWeight = 1;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_VehicleData(VehicleData *value);
extern int ASN1_BER_Data_Dec_VehicleData(ASN1WorkSpace *workspace, VehicleData *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_VehicleData(ASN1WorkSpace *workspace, VehicleData *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_VehicleData(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_VehicleData(value)) < 0) return ret;
	return ret;
}
extern int ASN1_PER_Align_Data_Enc_BumperHeights(ASN1WorkSpace *workspace, BumperHeights *value);
int ASN1_PER_Align_Data_Enc_VehicleData(ASN1WorkSpace *workspace, VehicleData *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_height = { ASN1_CONST64(0), ASN1_CONST64(127), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_bumpers = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_mass = { ASN1_CONST64(0), ASN1_CONST64(255), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_trailerWeight = { ASN1_CONST64(0), ASN1_CONST64(64255), NULL, 0, CONS, 0, 0 };

	ASNINT32 all_bit;
	ASNUINT16 all_pointer;
	if ((ret = ASN1_PER_Enc_extbit(workspace, value->E)) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_VehicleData_height == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_VehicleData_bumpers == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_VehicleData_mass == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_VehicleData_trailerWeight == 1 ? 1 : 0) )) < 0) return ret;
	if (value->DEF_VehicleData_height == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->height), &consinfo_height)) < 0) return ret;
	}
	if (value->DEF_VehicleData_bumpers == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_BumperHeights(workspace, value->bumpers)) < 0) return ret;
	}
	if (value->DEF_VehicleData_mass == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->mass), &consinfo_mass)) < 0) return ret;
	}
	if (value->DEF_VehicleData_trailerWeight == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->trailerWeight), &consinfo_trailerWeight)) < 0) return ret;
	}
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, ALIGN, 0);
	}
	return ret;
}
