extern int ASN1_PER_Align_Data_Dec_BumperHeights(ASN1WorkSpace *workspace, BumperHeights *value);
int ASN1_PER_Align_Data_Dec_VehicleData(ASN1WorkSpace *workspace, VehicleData *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_height = { ASN1_CONST64(0), ASN1_CONST64(127), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_bumpers = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_mass = { ASN1_CONST64(0), ASN1_CONST64(255), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_trailerWeight = { ASN1_CONST64(0), ASN1_CONST64(64255), NULL, 0, CONS, 0, 0 };

	ASNBOOL extbit_VehicleData;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_VehicleData)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 4, &_optvalue)) < 0) return ret;
	value->bumpers = (BumperHeights *)mpool_malloc(workspace->Pmemory, sizeof(BumperHeights));
	memset(value->bumpers, 0, sizeof(BumperHeights));
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_VehicleData_height = 1;
		if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->height), &consinfo_height)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_VehicleData_bumpers = 1;
		if ((ret = ASN1_PER_Align_Dec_BumperHeights(workspace, value->bumpers)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 3) == 1)
	{
		value->DEF_VehicleData_mass = 1;
		if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->mass), &consinfo_mass)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 4) == 1)
	{
		value->DEF_VehicleData_trailerWeight = 1;
		if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->trailerWeight), &consinfo_trailerWeight)) < 0) return ret;
	}
	if (extbit_VehicleData == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, ALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, ALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
