int ASN1_CHECK_WeatherReport(WeatherReport *value)
{
	int ret = 0;

	unsigned char checkinfo_isRaining[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_rainRate[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};
	unsigned char checkinfo_precipSituation[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_solarRadiation[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};
	unsigned char checkinfo_friction[] = { 
		0x02,0x00,0x65,0x00
	};
	unsigned char checkinfo_roadFriction[] = { 
		0x02,0x00,0x32,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->isRaining), checkinfo_isRaining)) < 0) return ret;
	if (value->DEF_WeatherReport_rainRate == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->rainRate), checkinfo_rainRate)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_WeatherReport_precipSituation == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->precipSituation), checkinfo_precipSituation)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_WeatherReport_solarRadiation == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->solarRadiation), checkinfo_solarRadiation)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_WeatherReport_friction == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->friction), checkinfo_friction)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_WeatherReport_roadFriction == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->roadFriction), checkinfo_roadFriction)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
