int ASN1_BER_Data_Enc_WeatherReport(ASN1WorkSpace *workspace, WeatherReport *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_EssPrecipYesNo(workspace, &(value->isRaining), ASN1IMPL)) < 0) return ret;
	if (value->DEF_WeatherReport_rainRate == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_EssPrecipRate(workspace, &(value->rainRate), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_WeatherReport_precipSituation == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_EssPrecipSituation(workspace, &(value->precipSituation), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_WeatherReport_solarRadiation == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_EssSolarRadiation(workspace, &(value->solarRadiation), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_WeatherReport_friction == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 4)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_EssMobileFriction(workspace, &(value->friction), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_WeatherReport_roadFriction == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 5)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_CoefficientOfFriction(workspace, &(value->roadFriction), ASN1IMPL)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
