			case 4: value->precipSituation = EssPrecipSituation_unidentifiedModerate; break;
			case 5: value->precipSituation = EssPrecipSituation_unidentifiedHeavy; break;
			case 6: value->precipSituation = EssPrecipSituation_snowSlight; break;
			case 7: value->precipSituation = EssPrecipSituation_snowModerate; break;
			case 8: value->precipSituation = EssPrecipSituation_snowHeavy; break;
			case 9: value->precipSituation = EssPrecipSituation_rainSlight; break;
			case 10: value->precipSituation = EssPrecipSituation_rainModerate; break;
			case 11: value->precipSituation = EssPrecipSituation_rainHeavy; break;
			case 12: value->precipSituation = EssPrecipSituation_frozenPrecipitationSlight; break;
			case 13: value->precipSituation = EssPrecipSituation_frozenPrecipitationModerate; break;
			case 14: value->precipSituation = EssPrecipSituation_frozenPrecipitationHeavy; break;
			default: value->precipSituation = ui_precipSituation; break;
