/********************************************************
*WeatherProbe                                           *
********************************************************/
int ASN1_Print_WeatherProbe(WeatherProbe *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("WeatherProbe");
	if (value->DEF_WeatherProbe_airTemp == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("AmbientAirTemperature", &(value->airTemp))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_WeatherProbe_airPressure == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("AmbientAirPressure", &(value->airPressure))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_WeatherProbe_rainRates == 1)
	{ /*OPTIONAL start */
		// Type Reference WiperSet
		if (Compare_Letter(tab_value, "rainRates")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("rainRates = ");
		}
		if ((ret = ASN1_Print_WiperSet((WiperSet *)value->rainRates, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_WeatherProbe_airTemp(ASN1WorkSpace *workspace, WeatherProbe *value, INTEGER user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	value->DEF_WeatherProbe_airTemp = 1;
	if ((ret = ASN1_SET_INTEGER(workspace, &value->airTemp, user_value)) < 0) return ret;
	return ret;
}
int ASN1_SET_WeatherProbe_airPressure(ASN1WorkSpace *workspace, WeatherProbe *value, INTEGER user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	value->DEF_WeatherProbe_airPressure = 1;
	if ((ret = ASN1_SET_INTEGER(workspace, &value->airPressure, user_value)) < 0) return ret;
	return ret;
}
int ASN1_SET_WeatherProbe_rainRates(ASN1WorkSpace *workspace, WeatherProbe *value, WiperSet *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->rainRates = (WiperSet *)mpool_malloc(workspace->Pmemory, sizeof(WiperSet));
	memset(value->rainRates, 0, sizeof(WiperSet));
	value->DEF_WeatherProbe_rainRates = 1;
	memmove(value->rainRates, user_value, sizeof(WiperSet));
	return ret;
}
int ASN1_GET_WeatherProbe_airTemp(ASN1WorkSpace *workspace, WeatherProbe *value, INTEGER *user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if (value->DEF_WeatherProbe_airTemp == 1)
	{
		if ((ret = ASN1_GET_INTEGER(workspace, &value->airTemp, user_value)) < 0) return ret;
	}
	else return -2;
	return ret;
}
int ASN1_GET_WeatherProbe_airPressure(ASN1WorkSpace *workspace, WeatherProbe *value, INTEGER *user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if (value->DEF_WeatherProbe_airPressure == 1)
	{
		if ((ret = ASN1_GET_INTEGER(workspace, &value->airPressure, user_value)) < 0) return ret;
	}
	else return -2;
	return ret;
}
int ASN1_GET_WeatherProbe_rainRates(ASN1WorkSpace *workspace, WeatherProbe *value, WiperSet **user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if (value->DEF_WeatherProbe_rainRates == 1)
	{
		*user_value = value->rainRates;
	}
	else return -2;
	return ret;
}
extern int ASN1_CHECK_WiperSet(WiperSet *value);
int ASN1_CHECK_WeatherProbe(WeatherProbe *value)
{
	int ret = 0;

	unsigned char checkinfo_airTemp[] = { 
		0x02,0x00,0x82,0x00,0xBF,0x00
	};
	unsigned char checkinfo_airPressure[] = { 
		0x02,0x00,0x82,0x00,0xFF,0x00
	};
	unsigned char checkinfo_rainRates[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if (value->DEF_WeatherProbe_airTemp == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->airTemp), checkinfo_airTemp)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_WeatherProbe_airPressure == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->airPressure), checkinfo_airPressure)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_WeatherProbe_rainRates == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_WiperSet(value->rainRates)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_AmbientAirTemperature(ASN1WorkSpace *workspace, AmbientAirTemperature *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_AmbientAirPressure(ASN1WorkSpace *workspace, AmbientAirPressure *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_WiperSet(ASN1WorkSpace *workspace, WiperSet *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_WeatherProbe(ASN1WorkSpace *workspace, WeatherProbe *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if (value->DEF_WeatherProbe_airTemp == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_AmbientAirTemperature(workspace, &(value->airTemp), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_WeatherProbe_airPressure == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_AmbientAirPressure(workspace, &(value->airPressure), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_WeatherProbe_rainRates == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_WiperSet(workspace, value->rainRates, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_WeatherProbe(WeatherProbe *value);
extern int ASN1_BER_Data_Enc_WeatherProbe(ASN1WorkSpace *workspace, WeatherProbe *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_WeatherProbe(ASN1WorkSpace *workspace, WeatherProbe *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_WeatherProbe(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_WeatherProbe(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_AmbientAirTemperature(ASN1WorkSpace *workspace, AmbientAirTemperature *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_AmbientAirPressure(ASN1WorkSpace *workspace, AmbientAirPressure *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_WiperSet(ASN1WorkSpace *workspace, WiperSet *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_WeatherProbe(ASN1WorkSpace *workspace, WeatherProbe *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	value->rainRates = (WiperSet *)mpool_malloc(workspace->Pmemory, sizeof(WiperSet));
	memset(value->rainRates, 0, sizeof(WiperSet));
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 0))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_AmbientAirTemperature(workspace, &value->airTemp, len, ASN1IMPL)) < 0) return ret;
		value->DEF_WeatherProbe_airTemp = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 1))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_AmbientAirPressure(workspace, &value->airPressure, len, ASN1IMPL)) < 0) return ret;
		value->DEF_WeatherProbe_airPressure = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_CONS | 2))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_WiperSet(workspace, value->rainRates, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->DEF_WeatherProbe_rainRates = 1;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_WeatherProbe(WeatherProbe *value);
extern int ASN1_BER_Data_Dec_WeatherProbe(ASN1WorkSpace *workspace, WeatherProbe *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_WeatherProbe(ASN1WorkSpace *workspace, WeatherProbe *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_WeatherProbe(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_WeatherProbe(value)) < 0) return ret;
	return ret;
}
