extern int ASN1_BER_Data_Enc_RTCMheader(ASN1WorkSpace *workspace, RTCMheader *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_RTCMmessageList(ASN1WorkSpace *workspace, RTCMmessageList *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_RTCMPackage(ASN1WorkSpace *workspace, RTCMPackage *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if (value->DEF_RTCMPackage_rtcmHeader == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_RTCMheader(workspace, value->rtcmHeader, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_RTCMmessageList(workspace, &(value->msgs), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
