extern int ASN1_BER_Data_Dec_RTCMheader(ASN1WorkSpace *workspace, RTCMheader *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_RTCMmessageList(ASN1WorkSpace *workspace, RTCMmessageList *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_RTCMPackage(ASN1WorkSpace *workspace, RTCMPackage *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	value->rtcmHeader = (RTCMheader *)mpool_malloc(workspace->Pmemory, sizeof(RTCMheader));
	memset(value->rtcmHeader, 0, sizeof(RTCMheader));
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_CONS | 0))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_RTCMheader(workspace, value->rtcmHeader, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->DEF_RTCMPackage_rtcmHeader = 1;
	}
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_RTCMmessageList(workspace, &value->msgs, len, ASN1IMPL)) < 0) return ret;
	if (IfFixedLength(len) == -1)
	{
		if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_RTCMPackage(RTCMPackage *value);
extern int ASN1_BER_Data_Dec_RTCMPackage(ASN1WorkSpace *workspace, RTCMPackage *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_RTCMPackage(ASN1WorkSpace *workspace, RTCMPackage *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_RTCMPackage(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_RTCMPackage(value)) < 0) return ret;
	return ret;
}
