int ASN1_PER_Align_Data_Dec_RTCMPackage(ASN1WorkSpace *workspace, RTCMPackage *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_rtcmHeader = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_msgs = { ASN1_CONST64(1), ASN1_CONST64(5), NULL, 0, CONS, 0, 0 };

	ASNBOOL extbit_RTCMPackage;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_RTCMPackage)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 1, &_optvalue)) < 0) return ret;
	value->rtcmHeader = (RTCMheader *)mpool_malloc(workspace->Pmemory, sizeof(RTCMheader));
	memset(value->rtcmHeader, 0, sizeof(RTCMheader));
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_RTCMPackage_rtcmHeader = 1;
		if ((ret = ASN1_PER_Align_Dec_RTCMheader(workspace, value->rtcmHeader)) < 0) return ret;
	}
	if ((ret = ASN1_PER_Align_Dec_RTCMmessageList(workspace, &(value->msgs))) < 0) return ret;
	if (extbit_RTCMPackage == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, ALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, ALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
