/********************************************************
*SupplementalVehicleExtensions                          *
********************************************************/
int ASN1_Print_SupplementalVehicleExtensions(SupplementalVehicleExtensions *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("SupplementalVehicleExtensions");
	if (value->DEF_SupplementalVehicleExtensions_classification == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("BasicVehicleClass", &(value->classification))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_classDetails == 1)
	{ /*OPTIONAL start */
		// Type Reference VehicleClassification
		if (Compare_Letter(tab_value, "classDetails")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("classDetails = ");
		}
		if ((ret = ASN1_Print_VehicleClassification((VehicleClassification *)value->classDetails, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_vehicleData == 1)
	{ /*OPTIONAL start */
		// Type Reference VehicleData
		if (Compare_Letter(tab_value, "vehicleData")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("vehicleData = ");
		}
		if ((ret = ASN1_Print_VehicleData((VehicleData *)value->vehicleData, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_weatherReport == 1)
	{ /*OPTIONAL start */
		// Type Reference WeatherReport
		if (Compare_Letter(tab_value, "weatherReport")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("weatherReport = ");
		}
		if ((ret = ASN1_Print_WeatherReport((WeatherReport *)value->weatherReport, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_weatherProbe == 1)
	{ /*OPTIONAL start */
		// Type Reference WeatherProbe
		if (Compare_Letter(tab_value, "weatherProbe")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("weatherProbe = ");
		}
		if ((ret = ASN1_Print_WeatherProbe((WeatherProbe *)value->weatherProbe, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_obstacle == 1)
	{ /*OPTIONAL start */
		// Type Reference ObstacleDetection
		if (Compare_Letter(tab_value, "obstacle")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("obstacle = ");
		}
		if ((ret = ASN1_Print_ObstacleDetection((ObstacleDetection *)value->obstacle, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_status == 1)
	{ /*OPTIONAL start */
		// Type Reference DisabledVehicle
		if (Compare_Letter(tab_value, "status")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("status = ");
		}
		if ((ret = ASN1_Print_DisabledVehicle((DisabledVehicle *)value->status, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_speedProfile == 1)
	{ /*OPTIONAL start */
		// Type Reference SpeedProfile
		if (Compare_Letter(tab_value, "speedProfile")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("speedProfile = ");
		}
		if ((ret = ASN1_Print_SpeedProfile((SpeedProfile *)value->speedProfile, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_theRTCM == 1)
	{ /*OPTIONAL start */
		// Type Reference RTCMPackage
		if (Compare_Letter(tab_value, "theRTCM")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("theRTCM = ");
		}
		if ((ret = ASN1_Print_RTCMPackage((RTCMPackage *)value->theRTCM, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference SupplementalVehicleExtensions_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_SupplementalVehicleExtensions_regional((SupplementalVehicleExtensions_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
