extern int ASN1_CHECK_VehicleClassification(VehicleClassification *value);
extern int ASN1_CHECK_VehicleData(VehicleData *value);
extern int ASN1_CHECK_WeatherReport(WeatherReport *value);
extern int ASN1_CHECK_WeatherProbe(WeatherProbe *value);
extern int ASN1_CHECK_ObstacleDetection(ObstacleDetection *value);
extern int ASN1_CHECK_DisabledVehicle(DisabledVehicle *value);
extern int ASN1_CHECK_SpeedProfile(SpeedProfile *value);
extern int ASN1_CHECK_RTCMPackage(RTCMPackage *value);
extern int ASN1_CHECK_SupplementalVehicleExtensions_regional(SupplementalVehicleExtensions_regional *value);
int ASN1_CHECK_SupplementalVehicleExtensions(SupplementalVehicleExtensions *value)
{
	int ret = 0;

	unsigned char checkinfo_classification[] = { 
		0x02,0x00,0x82,0x00,0xFF,0x00
	};
	unsigned char checkinfo_classDetails[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_vehicleData[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_weatherReport[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_weatherProbe[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_obstacle[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_status[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_speedProfile[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_theRTCM[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_SupplementalVehicleExtensions_classification == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->classification), checkinfo_classification)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_classDetails == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_VehicleClassification(value->classDetails)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_vehicleData == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_VehicleData(value->vehicleData)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_weatherReport == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_WeatherReport(value->weatherReport)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_weatherProbe == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_WeatherProbe(value->weatherProbe)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_obstacle == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ObstacleDetection(value->obstacle)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_status == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_DisabledVehicle(value->status)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_speedProfile == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_SpeedProfile(value->speedProfile)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_theRTCM == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_RTCMPackage(value->theRTCM)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SupplementalVehicleExtensions_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_SupplementalVehicleExtensions_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
