int ASN1_Print_IntersectionAccessPoint(IntersectionAccessPoint *value, int tab_value)
{
	int ret = 0;
	// CHOICE : t->tempIdentifier is Upper Letter
	ASN1_Print_CHOICE("IntersectionAccessPoint");
	if (value == NULL) return -1;
	switch (value->M) {
	case DEF_IntersectionAccessPoint_lane:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("LaneID", &value->elements.lane)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_IntersectionAccessPoint_approach:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("ApproachID", &value->elements.approach)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_IntersectionAccessPoint_connection:
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("LaneConnectionID", &value->elements.connection)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	default: return -1;
}
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
