int ASN1_CHECK_IntersectionAccessPoint(IntersectionAccessPoint *value)
{
	int ret = 0;

	unsigned char checkinfo_lane[] = { 
		0x02,0x00,0x82,0x00,0xFF,0x00
	};
	unsigned char checkinfo_approach[] = { 
		0x02,0x00,0x0F,0x00
	};
	unsigned char checkinfo_connection[] = { 
		0x02,0x00,0x82,0x00,0xFF,0x00
	};

	if (value == NULL) return -1;
	switch (value->M)
	{
	case DEF_IntersectionAccessPoint_lane:
		if ((ret = ASN1_CHECK_INTEGER(&value->elements.lane, checkinfo_lane)) < 0) return ret;
		break;
	case DEF_IntersectionAccessPoint_approach:
		if ((ret = ASN1_CHECK_INTEGER(&value->elements.approach, checkinfo_approach)) < 0) return ret;
		break;
	case DEF_IntersectionAccessPoint_connection:
		if ((ret = ASN1_CHECK_INTEGER(&value->elements.connection, checkinfo_connection)) < 0) return ret;
		break;
	default: break;
	}
	return ret;
}
extern int ASN1_BER_Data_Enc_LaneID(ASN1WorkSpace *workspace, LaneID *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_ApproachID(ASN1WorkSpace *workspace, ApproachID *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_LaneConnectionID(ASN1WorkSpace *workspace, LaneConnectionID *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_IntersectionAccessPoint(ASN1WorkSpace *workspace, IntersectionAccessPoint *value, ASN1TagType tagFlag)
{
	int ret = 0;
	switch(value->M)
	{
	case DEF_IntersectionAccessPoint_lane:
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_LaneID(workspace, &(value->elements.lane), ASN1IMPL)) < 0) return ret;
		break;
	case DEF_IntersectionAccessPoint_approach:
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_ApproachID(workspace, &(value->elements.approach), ASN1IMPL)) < 0) return ret;
		break;
	case DEF_IntersectionAccessPoint_connection:
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_LaneConnectionID(workspace, &(value->elements.connection), ASN1IMPL)) < 0) return ret;
		break;
	}
	return ret;
}
extern int ASN1_CHECK_IntersectionAccessPoint(IntersectionAccessPoint *value);
extern int ASN1_BER_Data_Enc_IntersectionAccessPoint(ASN1WorkSpace *workspace, IntersectionAccessPoint *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_IntersectionAccessPoint(ASN1WorkSpace *workspace, IntersectionAccessPoint *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_IntersectionAccessPoint(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_IntersectionAccessPoint(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_LaneID(ASN1WorkSpace *workspace, LaneID *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_ApproachID(ASN1WorkSpace *workspace, ApproachID *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_LaneConnectionID(ASN1WorkSpace *workspace, LaneConnectionID *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_IntersectionAccessPoint(ASN1WorkSpace *workspace, IntersectionAccessPoint *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	value->M = 0;
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	switch(tag)
	{
	case ITS_ASN_CONT | ITS_ASN_PRIM | 0:
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_LaneID(workspace, &value->elements.lane, len, ASN1IMPL)) < 0) return ret;
		value->M = DEF_IntersectionAccessPoint_lane;
		break;
	case ITS_ASN_CONT | ITS_ASN_PRIM | 1:
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_ApproachID(workspace, &value->elements.approach, len, ASN1IMPL)) < 0) return ret;
		value->M = DEF_IntersectionAccessPoint_approach;
		break;
	case ITS_ASN_CONT | ITS_ASN_PRIM | 2:
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_LaneConnectionID(workspace, &value->elements.connection, len, ASN1IMPL)) < 0) return ret;
		value->M = DEF_IntersectionAccessPoint_connection;
		break;
	}
	return ret;
}
extern int ASN1_CHECK_IntersectionAccessPoint(IntersectionAccessPoint *value);
extern int ASN1_BER_Data_Dec_IntersectionAccessPoint(ASN1WorkSpace *workspace, IntersectionAccessPoint *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_IntersectionAccessPoint(ASN1WorkSpace *workspace, IntersectionAccessPoint *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_IntersectionAccessPoint(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_IntersectionAccessPoint(value)) < 0) return ret;
	return ret;
}
