/********************************************************
*RequestorPositionVector                                *
********************************************************/
int ASN1_Print_RequestorPositionVector(RequestorPositionVector *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("RequestorPositionVector");
	// Type Reference Position3D
	if (Compare_Letter(tab_value, "position")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("position = ");
	}
	if ((ret = ASN1_Print_Position3D((Position3D *)value->position, tab_value + 1)) < 0) return ret;
	if (value->DEF_RequestorPositionVector_heading == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("Angle", &(value->heading))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RequestorPositionVector_speed == 1)
	{ /*OPTIONAL start */
		// Type Reference TransmissionAndSpeed
		if (Compare_Letter(tab_value, "speed")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("speed = ");
		}
		if ((ret = ASN1_Print_TransmissionAndSpeed((TransmissionAndSpeed *)value->speed, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
