extern int ASN1_BER_Data_Dec_Position3D(ASN1WorkSpace *workspace, Position3D *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_Angle(ASN1WorkSpace *workspace, Angle *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_TransmissionAndSpeed(ASN1WorkSpace *workspace, TransmissionAndSpeed *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_RequestorPositionVector(ASN1WorkSpace *workspace, RequestorPositionVector *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	value->position = (Position3D *)mpool_malloc(workspace->Pmemory, sizeof(Position3D));
	memset(value->position, 0, sizeof(Position3D));
	value->speed = (TransmissionAndSpeed *)mpool_malloc(workspace->Pmemory, sizeof(TransmissionAndSpeed));
	memset(value->speed, 0, sizeof(TransmissionAndSpeed));
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_Position3D(workspace, value->position, len, ASN1IMPL)) < 0) return ret;
	if (IfFixedLength(len) == -1)
	{
		if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 1))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_Angle(workspace, &value->heading, len, ASN1IMPL)) < 0) return ret;
		value->DEF_RequestorPositionVector_heading = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_CONS | 2))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_TransmissionAndSpeed(workspace, value->speed, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->DEF_RequestorPositionVector_speed = 1;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
