/********************************************************
*RequestorDescription                                   *
********************************************************/
int ASN1_Print_RequestorDescription(RequestorDescription *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("RequestorDescription");
	// Type Reference VehicleID
	if (Compare_Letter(tab_value, "id")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("id = ");
	}
	if ((ret = ASN1_Print_VehicleID((VehicleID *)value->id, tab_value + 1)) < 0) return ret;
	if (value->DEF_RequestorDescription_type == 1)
	{ /*OPTIONAL start */
		// Type Reference RequestorType
		if (Compare_Letter(tab_value, "type")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("type = ");
		}
		if ((ret = ASN1_Print_RequestorType((RequestorType *)value->type, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RequestorDescription_position == 1)
	{ /*OPTIONAL start */
		// Type Reference RequestorPositionVector
		if (Compare_Letter(tab_value, "position")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("position = ");
		}
		if ((ret = ASN1_Print_RequestorPositionVector((RequestorPositionVector *)value->position, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RequestorDescription_name == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_IA5String("DescriptiveName", &(value->name))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RequestorDescription_routeName == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_IA5String("DescriptiveName", &(value->routeName))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RequestorDescription_transitStatus == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("TransitVehicleStatus", &(value->transitStatus))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RequestorDescription_transitOccupancy == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->transitOccupancy)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("TransitVehicleOccupancy", "occupancyUnknown", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("TransitVehicleOccupancy", "occupancyEmpty", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("TransitVehicleOccupancy", "occupancyVeryLow", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("TransitVehicleOccupancy", "occupancyLow", 3)) < 0) return ret; break;
		case 4: if ((ret = ASN1_Print_ENUMERATED("TransitVehicleOccupancy", "occupancyMed", 4)) < 0) return ret; break;
		case 5: if ((ret = ASN1_Print_ENUMERATED("TransitVehicleOccupancy", "occupancyHigh", 5)) < 0) return ret; break;
		case 6: if ((ret = ASN1_Print_ENUMERATED("TransitVehicleOccupancy", "occupancyNearlyFull", 6)) < 0) return ret; break;
		case 7: if ((ret = ASN1_Print_ENUMERATED("TransitVehicleOccupancy", "occupancyFull", 7)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	if (value->DEF_RequestorDescription_transitSchedule == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DeltaTime", &(value->transitSchedule))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RequestorDescription_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference RequestorDescription_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_RequestorDescription_regional((RequestorDescription_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_RequestorDescription_id(ASN1WorkSpace *workspace, RequestorDescription *value, VehicleID *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->id = (VehicleID *)mpool_malloc(workspace->Pmemory, sizeof(VehicleID));
	memset(value->id, 0, sizeof(VehicleID));
	memmove(value->id, user_value, sizeof(VehicleID));
	return ret;
}
