int ASN1_CHECK_RequestorDescription(RequestorDescription *value)
{
	int ret = 0;

	unsigned char checkinfo_id[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_type[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_position[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_name[] = { 
		0x02,0x01,0x3F,0x00
	};
	unsigned char checkinfo_routeName[] = { 
		0x02,0x01,0x3F,0x00
	};
	unsigned char checkinfo_transitStatus[] = { 
		0x02,0x08,0x08,0x00
	};
	unsigned char checkinfo_transitOccupancy[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_transitSchedule[] = { 
		0x02,0x81,0x86,0x79,0x00
	};
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_VehicleID(value->id)) < 0) return ret;
	if (value->DEF_RequestorDescription_type == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_RequestorType(value->type)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RequestorDescription_position == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_RequestorPositionVector(value->position)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RequestorDescription_name == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_IA5String(&(value->name), checkinfo_name)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RequestorDescription_routeName == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_IA5String(&(value->routeName), checkinfo_routeName)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RequestorDescription_transitStatus == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BITSTRING(&(value->transitStatus), checkinfo_transitStatus)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RequestorDescription_transitOccupancy == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->transitOccupancy), checkinfo_transitOccupancy)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RequestorDescription_transitSchedule == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->transitSchedule), checkinfo_transitSchedule)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RequestorDescription_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_RequestorDescription_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
