extern int ASN1_BER_Data_Enc_RequestorDescription_regional(ASN1WorkSpace *workspace, RequestorDescription_regional *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_RequestorDescription(ASN1WorkSpace *workspace, RequestorDescription *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_VehicleID(workspace, value->id, ASN1EXPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (value->DEF_RequestorDescription_type == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_RequestorType(workspace, value->type, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_RequestorDescription_position == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_RequestorPositionVector(workspace, value->position, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_RequestorDescription_name == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_DescriptiveName(workspace, &(value->name), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_RequestorDescription_routeName == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 4)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_DescriptiveName(workspace, &(value->routeName), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_RequestorDescription_transitStatus == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 5)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_TransitVehicleStatus(workspace, &(value->transitStatus), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_RequestorDescription_transitOccupancy == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 6)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_TransitVehicleOccupancy(workspace, &(value->transitOccupancy), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_RequestorDescription_transitSchedule == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 7)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_DeltaTime(workspace, &(value->transitSchedule), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_RequestorDescription_regional == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 16)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_RequestorDescription_regional(workspace, &(value->regional), ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_RequestorDescription(RequestorDescription *value);
extern int ASN1_BER_Data_Enc_RequestorDescription(ASN1WorkSpace *workspace, RequestorDescription *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_RequestorDescription(ASN1WorkSpace *workspace, RequestorDescription *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_RequestorDescription(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_RequestorDescription(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_VehicleID(ASN1WorkSpace *workspace, VehicleID *value, int length, ASN1TagType tagFlag);
