extern int ASN1_BER_Data_Dec_TransitVehicleOccupancy(ASN1WorkSpace *workspace, TransitVehicleOccupancy *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_DeltaTime(ASN1WorkSpace *workspace, DeltaTime *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_RequestorDescription_regional(ASN1WorkSpace *workspace, RequestorDescription_regional *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_RequestorDescription(ASN1WorkSpace *workspace, RequestorDescription *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	value->id = (VehicleID *)mpool_malloc(workspace->Pmemory, sizeof(VehicleID));
	memset(value->id, 0, sizeof(VehicleID));
	value->type = (RequestorType *)mpool_malloc(workspace->Pmemory, sizeof(RequestorType));
	memset(value->type, 0, sizeof(RequestorType));
	value->position = (RequestorPositionVector *)mpool_malloc(workspace->Pmemory, sizeof(RequestorPositionVector));
	memset(value->position, 0, sizeof(RequestorPositionVector));
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_VehicleID(workspace, value->id, len, ASN1EXPL)) < 0) return ret;
	if (IfFixedLength(len) == -1)
	{
		if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_CONS | 1))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_RequestorType(workspace, value->type, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->DEF_RequestorDescription_type = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_CONS | 2))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_RequestorPositionVector(workspace, value->position, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->DEF_RequestorDescription_position = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 3))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 3)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_DescriptiveName(workspace, &value->name, len, ASN1IMPL)) < 0) return ret;
		value->DEF_RequestorDescription_name = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 4))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 4)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_DescriptiveName(workspace, &value->routeName, len, ASN1IMPL)) < 0) return ret;
		value->DEF_RequestorDescription_routeName = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 5))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 5)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_TransitVehicleStatus(workspace, &value->transitStatus, len, ASN1IMPL)) < 0) return ret;
		value->DEF_RequestorDescription_transitStatus = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 6))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 6)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_TransitVehicleOccupancy(workspace, &value->transitOccupancy, len, ASN1IMPL)) < 0) return ret;
		value->DEF_RequestorDescription_transitOccupancy = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 7))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 7)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_DeltaTime(workspace, &value->transitSchedule, len, ASN1IMPL)) < 0) return ret;
		value->DEF_RequestorDescription_transitSchedule = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_CONS | 16))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_RequestorDescription_regional(workspace, &value->regional, len, ASN1IMPL)) < 0) return ret;
		if (IfFixedLength(len) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
		value->DEF_RequestorDescription_regional = 1;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_RequestorDescription(RequestorDescription *value);
extern int ASN1_BER_Data_Dec_RequestorDescription(ASN1WorkSpace *workspace, RequestorDescription *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_RequestorDescription(ASN1WorkSpace *workspace, RequestorDescription *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_RequestorDescription(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_RequestorDescription(value)) < 0) return ret;
	return ret;
}
extern int ASN1_PER_Align_Data_Enc_VehicleID(ASN1WorkSpace *workspace, VehicleID *value);
extern int ASN1_PER_Align_Data_Enc_RequestorType(ASN1WorkSpace *workspace, RequestorType *value);
extern int ASN1_PER_Align_Data_Enc_RequestorPositionVector(ASN1WorkSpace *workspace, RequestorPositionVector *value);
extern int ASN1_PER_Align_Data_Enc_RequestorDescription_regional(ASN1WorkSpace *workspace, RequestorDescription_regional *value);
int ASN1_PER_Align_Data_Enc_RequestorDescription(ASN1WorkSpace *workspace, RequestorDescription *value)
{
	int ret = 0;
	ASNINT32 ui_transitOccupancy;
	struct Asn1ConsInfo consinfo_id = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_type = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_position = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_name = { ASN1_CONST64(1), ASN1_CONST64(63), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_routeName = { ASN1_CONST64(1), ASN1_CONST64(63), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_transitStatus = { ASN1_CONST64(8), ASN1_CONST64(8), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_transitOccupancy = { ASN1_CONST64(0), ASN1_CONST64(7), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_transitSchedule = { ASN1_CONST64(-122), ASN1_CONST64(121), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNINT32 all_bit;
	ASNUINT16 all_pointer;
	if ((ret = ASN1_PER_Enc_extbit(workspace, value->E)) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_RequestorDescription_type == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_RequestorDescription_position == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_RequestorDescription_name == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_RequestorDescription_routeName == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_RequestorDescription_transitStatus == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_RequestorDescription_transitOccupancy == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_RequestorDescription_transitSchedule == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_RequestorDescription_regional == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Align_Enc_VehicleID(workspace, value->id)) < 0) return ret;
	if (value->DEF_RequestorDescription_type == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_RequestorType(workspace, value->type)) < 0) return ret;
	}
	if (value->DEF_RequestorDescription_position == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_RequestorPositionVector(workspace, value->position)) < 0) return ret;
	}
	if (value->DEF_RequestorDescription_name == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_IA5String(workspace, &(value->name), &consinfo_name)) < 0) return ret;
	}
	if (value->DEF_RequestorDescription_routeName == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_IA5String(workspace, &(value->routeName), &consinfo_routeName)) < 0) return ret;
	}
	if (value->DEF_RequestorDescription_transitStatus == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_BITSTRING(workspace, &(value->transitStatus), &consinfo_transitStatus)) < 0) return ret;
	}
	if (value->DEF_RequestorDescription_transitOccupancy == 1)
	{
		switch(value->transitOccupancy)
		{
		case TransitVehicleOccupancy_occupancyUnknown: ui_transitOccupancy = 0; consinfo_transitOccupancy.enumextbit = 0; break;
		case TransitVehicleOccupancy_occupancyEmpty: ui_transitOccupancy = 1; consinfo_transitOccupancy.enumextbit = 0; break;
		case TransitVehicleOccupancy_occupancyVeryLow: ui_transitOccupancy = 2; consinfo_transitOccupancy.enumextbit = 0; break;
		case TransitVehicleOccupancy_occupancyLow: ui_transitOccupancy = 3; consinfo_transitOccupancy.enumextbit = 0; break;
		case TransitVehicleOccupancy_occupancyMed: ui_transitOccupancy = 4; consinfo_transitOccupancy.enumextbit = 0; break;
		case TransitVehicleOccupancy_occupancyHigh: ui_transitOccupancy = 5; consinfo_transitOccupancy.enumextbit = 0; break;
		case TransitVehicleOccupancy_occupancyNearlyFull: ui_transitOccupancy = 6; consinfo_transitOccupancy.enumextbit = 0; break;
		case TransitVehicleOccupancy_occupancyFull: ui_transitOccupancy = 7; consinfo_transitOccupancy.enumextbit = 0; break;
		default: ui_transitOccupancy = value->transitOccupancy; consinfo_transitOccupancy.enumextbit = 0;break;
		}
		if ((ret = ASN1_PER_Align_Enc_ENUMERATED(workspace, ui_transitOccupancy, &consinfo_transitOccupancy)) < 0) return ret;
	}
	if (value->DEF_RequestorDescription_transitSchedule == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_INTEGER(workspace, &(value->transitSchedule), &consinfo_transitSchedule)) < 0) return ret;
	}
	if (value->DEF_RequestorDescription_regional == 1)
	{
		if ((ret = ASN1_PER_Align_Enc_RequestorDescription_regional(workspace, &(value->regional))) < 0) return ret;
	}
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, ALIGN, 0);
	}
	return ret;
}
