extern int ASN1_PER_Align_Data_Dec_RequestorDescription_regional(ASN1WorkSpace *workspace, RequestorDescription_regional *value);
int ASN1_PER_Align_Data_Dec_RequestorDescription(ASN1WorkSpace *workspace, RequestorDescription *value)
{
	int ret = 0;
	ASNINT32 ui_transitOccupancy;
	struct Asn1ConsInfo consinfo_id = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_type = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_position = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_name = { ASN1_CONST64(1), ASN1_CONST64(63), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_routeName = { ASN1_CONST64(1), ASN1_CONST64(63), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_transitStatus = { ASN1_CONST64(8), ASN1_CONST64(8), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_transitOccupancy = { ASN1_CONST64(0), ASN1_CONST64(7), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_transitSchedule = { ASN1_CONST64(-122), ASN1_CONST64(121), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNBOOL extbit_RequestorDescription;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_RequestorDescription)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 8, &_optvalue)) < 0) return ret;
	value->id = (VehicleID *)mpool_malloc(workspace->Pmemory, sizeof(VehicleID));
	memset(value->id, 0, sizeof(VehicleID));
	value->type = (RequestorType *)mpool_malloc(workspace->Pmemory, sizeof(RequestorType));
	memset(value->type, 0, sizeof(RequestorType));
	value->position = (RequestorPositionVector *)mpool_malloc(workspace->Pmemory, sizeof(RequestorPositionVector));
	memset(value->position, 0, sizeof(RequestorPositionVector));
	if ((ret = ASN1_PER_Align_Dec_VehicleID(workspace, value->id)) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_RequestorDescription_type = 1;
		if ((ret = ASN1_PER_Align_Dec_RequestorType(workspace, value->type)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_RequestorDescription_position = 1;
		if ((ret = ASN1_PER_Align_Dec_RequestorPositionVector(workspace, value->position)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 3) == 1)
	{
		value->DEF_RequestorDescription_name = 1;
		if ((ret = ASN1_PER_Align_Dec_IA5String(workspace, &(value->name), &consinfo_name)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 4) == 1)
	{
		value->DEF_RequestorDescription_routeName = 1;
		if ((ret = ASN1_PER_Align_Dec_IA5String(workspace, &(value->routeName), &consinfo_routeName)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 5) == 1)
	{
		value->DEF_RequestorDescription_transitStatus = 1;
		if ((ret = ASN1_PER_Align_Dec_BITSTRING(workspace, &(value->transitStatus), &consinfo_transitStatus)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 6) == 1)
	{
		value->DEF_RequestorDescription_transitOccupancy = 1;
		if ((ret = ASN1_PER_Align_Dec_ENUMERATED(workspace, &ui_transitOccupancy, &consinfo_transitOccupancy)) < 0) return ret;
		if (consinfo_transitOccupancy.enumextbit == 0)
		{
			switch(ui_transitOccupancy)
			{
			case 0: value->transitOccupancy = TransitVehicleOccupancy_occupancyUnknown; break;
			case 1: value->transitOccupancy = TransitVehicleOccupancy_occupancyEmpty; break;
			case 2: value->transitOccupancy = TransitVehicleOccupancy_occupancyVeryLow; break;
			case 3: value->transitOccupancy = TransitVehicleOccupancy_occupancyLow; break;
			case 4: value->transitOccupancy = TransitVehicleOccupancy_occupancyMed; break;
			case 5: value->transitOccupancy = TransitVehicleOccupancy_occupancyHigh; break;
			case 6: value->transitOccupancy = TransitVehicleOccupancy_occupancyNearlyFull; break;
			case 7: value->transitOccupancy = TransitVehicleOccupancy_occupancyFull; break;
			default: value->transitOccupancy = ui_transitOccupancy; break;
			}
		}
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 7) == 1)
	{
		value->DEF_RequestorDescription_transitSchedule = 1;
		if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->transitSchedule), &consinfo_transitSchedule)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 8) == 1)
	{
		value->DEF_RequestorDescription_regional = 1;
		if ((ret = ASN1_PER_Align_Dec_RequestorDescription_regional(workspace, &(value->regional))) < 0) return ret;
	}
	if (extbit_RequestorDescription == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, ALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, ALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
