extern int ASN1_CHECK_SignalRequesterInfo(SignalRequesterInfo *value);
extern int ASN1_CHECK_IntersectionAccessPoint(IntersectionAccessPoint *value);
extern int ASN1_CHECK_IntersectionAccessPoint(IntersectionAccessPoint *value);
extern int ASN1_CHECK_SignalStatusPackage_regional(SignalStatusPackage_regional *value);
int ASN1_CHECK_SignalStatusPackage(SignalStatusPackage *value)
{
	int ret = 0;

	unsigned char checkinfo_requester[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_inboundOn[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_outboundOn[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_minute[] = { 
		0x02,0x00,0x83,0x08,0x0A,0xC0,0x00
	};
	unsigned char checkinfo_second[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};
	unsigned char checkinfo_duration[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};
	unsigned char checkinfo_status[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_SignalStatusPackage_requester == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_SignalRequesterInfo(value->requester)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_IntersectionAccessPoint(value->inboundOn)) < 0) return ret;
	if (value->DEF_SignalStatusPackage_outboundOn == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_IntersectionAccessPoint(value->outboundOn)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SignalStatusPackage_minute == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->minute), checkinfo_minute)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SignalStatusPackage_second == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->second), checkinfo_second)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SignalStatusPackage_duration == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->duration), checkinfo_duration)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->status), checkinfo_status)) < 0) return ret;
	if (value->DEF_SignalStatusPackage_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_SignalStatusPackage_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
