/********************************************************
*SignalStatus                                           *
********************************************************/
int ASN1_Print_SignalStatus(SignalStatus *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("SignalStatus");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("MsgCount", &(value->sequenceNumber))) < 0) return ret;
	// Type Reference IntersectionReferenceID
	if (Compare_Letter(tab_value, "id")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("id = ");
	}
	if ((ret = ASN1_Print_IntersectionReferenceID((IntersectionReferenceID *)value->id, tab_value + 1)) < 0) return ret;
	// Type Reference SignalStatusPackageList
	if (Compare_Letter(tab_value, "sigStatus")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("sigStatus = ");
	}
	if ((ret = ASN1_Print_SignalStatusPackageList((SignalStatusPackageList *)&(value->sigStatus), tab_value + 1)) < 0) return ret;
	if (value->DEF_SignalStatus_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference SignalStatus_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_SignalStatus_regional((SignalStatus_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_SignalStatus_sequenceNumber(ASN1WorkSpace *workspace, SignalStatus *value, INTEGER user_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	if ((ret = ASN1_SET_INTEGER(workspace, &value->sequenceNumber, user_value)) < 0) return ret;
	return ret;
}
int ASN1_SET_SignalStatus_id(ASN1WorkSpace *workspace, SignalStatus *value, IntersectionReferenceID *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->id = (IntersectionReferenceID *)mpool_malloc(workspace->Pmemory, sizeof(IntersectionReferenceID));
	memset(value->id, 0, sizeof(IntersectionReferenceID));
	memmove(value->id, user_value, sizeof(IntersectionReferenceID));
	return ret;
}
int ASN1_SET_SignalStatus_sigStatus(ASN1WorkSpace *workspace, SignalStatus *value, SignalStatusPackageList *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	memmove(&value->sigStatus, user_value, sizeof(SignalStatusPackageList));
	return ret;
}
int ASN1_SET_SignalStatus_regional(ASN1WorkSpace *workspace, SignalStatus *value, SignalStatus_regional *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->DEF_SignalStatus_regional = 1;
	memmove(&value->regional, user_value, sizeof(SignalStatus_regional));
	return ret;
}
