{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	*user_value = value->id;
	return ret;
}
int ASN1_GET_SignalStatus_sigStatus(ASN1WorkSpace *workspace, SignalStatus *value, SignalStatusPackageList **user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	*user_value = &value->sigStatus;
	return ret;
}
int ASN1_GET_SignalStatus_regional(ASN1WorkSpace *workspace, SignalStatus *value, SignalStatus_regional **user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if (value->DEF_SignalStatus_regional == 1)
	{
		*user_value = &value->regional;
	}
	else return -2;
	return ret;
}
extern int ASN1_CHECK_IntersectionReferenceID(IntersectionReferenceID *value);
extern int ASN1_CHECK_SignalStatusPackageList(SignalStatusPackageList *value);
extern int ASN1_CHECK_SignalStatus_regional(SignalStatus_regional *value);
int ASN1_CHECK_SignalStatus(SignalStatus *value)
{
	int ret = 0;

	unsigned char checkinfo_sequenceNumber[] = { 
		0x02,0x00,0x7F,0x00
	};
	unsigned char checkinfo_id[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_sigStatus[] = { 
		0x02,0x01,0x20,0x00
	};
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->sequenceNumber), checkinfo_sequenceNumber)) < 0) return ret;
	if ((ret = ASN1_CHECK_IntersectionReferenceID(value->id)) < 0) return ret;
	if ((ret = ASN1_CHECK_SignalStatusPackageList(&(value->sigStatus))) < 0) return ret;
	if (value->DEF_SignalStatus_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_SignalStatus_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_MsgCount(ASN1WorkSpace *workspace, MsgCount *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_IntersectionReferenceID(ASN1WorkSpace *workspace, IntersectionReferenceID *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_SignalStatusPackageList(ASN1WorkSpace *workspace, SignalStatusPackageList *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_SignalStatus_regional(ASN1WorkSpace *workspace, SignalStatus_regional *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_SignalStatus(ASN1WorkSpace *workspace, SignalStatus *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_MsgCount(workspace, &(value->sequenceNumber), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_IntersectionReferenceID(workspace, value->id, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_SignalStatusPackageList(workspace, &(value->sigStatus), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (value->DEF_SignalStatus_regional == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 16)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_SignalStatus_regional(workspace, &(value->regional), ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_SignalStatus(SignalStatus *value);
extern int ASN1_BER_Data_Enc_SignalStatus(ASN1WorkSpace *workspace, SignalStatus *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_SignalStatus(ASN1WorkSpace *workspace, SignalStatus *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_SignalStatus(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_SignalStatus(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
