extern int ASN1_PER_Align_Data_Dec_SignalStatusPackageList(ASN1WorkSpace *workspace, SignalStatusPackageList *value);
extern int ASN1_PER_Align_Data_Dec_SignalStatus_regional(ASN1WorkSpace *workspace, SignalStatus_regional *value);
int ASN1_PER_Align_Data_Dec_SignalStatus(ASN1WorkSpace *workspace, SignalStatus *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_sequenceNumber = { ASN1_CONST64(0), ASN1_CONST64(127), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_id = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_sigStatus = { ASN1_CONST64(1), ASN1_CONST64(32), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_regional = { ASN1_CONST64(1), ASN1_CONST64(4), NULL, 0, CONS, 0, 0 };

	ASNBOOL extbit_SignalStatus;
	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_extbit(workspace, &extbit_SignalStatus)) < 0) return ret;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 1, &_optvalue)) < 0) return ret;
	value->id = (IntersectionReferenceID *)mpool_malloc(workspace->Pmemory, sizeof(IntersectionReferenceID));
	memset(value->id, 0, sizeof(IntersectionReferenceID));
	if ((ret = ASN1_PER_Align_Dec_INTEGER(workspace, &(value->sequenceNumber), &consinfo_sequenceNumber)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Dec_IntersectionReferenceID(workspace, value->id)) < 0) return ret;
	if ((ret = ASN1_PER_Align_Dec_SignalStatusPackageList(workspace, &(value->sigStatus))) < 0) return ret;
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_SignalStatus_regional = 1;
		if ((ret = ASN1_PER_Align_Dec_SignalStatus_regional(workspace, &(value->regional))) < 0) return ret;
	}
	if (extbit_SignalStatus == 1)
	{ /* EXT_DEC_start */
		ASNINT32 _ext_count = 0;
		ASNINT32 _ext_x_count = 0;
		ASNUINT8 *extvalue;
		ASNINT32 ret_exp=0;
		if ((ret_exp = ASN1_PER_Dec_extOption(workspace, ALIGN, &_ext_count, &extvalue)) < 0) return ret_exp;
		_ext_x_count = _ext_count;
		_ext_x_count = _ext_x_count - _ext_count+1;
		for (;_ext_count > 0; _ext_count--)
		{
			if (ASN1_PER_CheckExtBit(extvalue, _ext_x_count) == 1)
			{
				if ((ret = ASN1_PER_Dec_unKnown(workspace, ALIGN)) != 0) return -1;
			}
			_ext_x_count++;
		}
	} /* EXT_DEC_end */

	return ret;
}
