/********************************************************
*SignalRequestPackage                                   *
********************************************************/
int ASN1_Print_SignalRequestPackage(SignalRequestPackage *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("SignalRequestPackage");
	// Type Reference SignalRequest
	if (Compare_Letter(tab_value, "request")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("request = ");
	}
	if ((ret = ASN1_Print_SignalRequest((SignalRequest *)value->request, tab_value + 1)) < 0) return ret;
	if (value->DEF_SignalRequestPackage_minute == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("MinuteOfTheYear", &(value->minute))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SignalRequestPackage_second == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DSecond", &(value->second))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SignalRequestPackage_duration == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DSecond", &(value->duration))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SignalRequestPackage_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference SignalRequestPackage_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_SignalRequestPackage_regional((SignalRequestPackage_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_SignalRequestPackage_request(ASN1WorkSpace *workspace, SignalRequestPackage *value, SignalRequest *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->request = (SignalRequest *)mpool_malloc(workspace->Pmemory, sizeof(SignalRequest));
	memset(value->request, 0, sizeof(SignalRequest));
	memmove(value->request, user_value, sizeof(SignalRequest));
	return ret;
}
