int ASN1_Print_PropelledInformation(PropelledInformation *value, int tab_value)
{
	int ret = 0;
	// CHOICE : t->tempIdentifier is Upper Letter
	ASN1_Print_CHOICE("PropelledInformation");
	if (value == NULL) return -1;
	switch (value->M) {
	case DEF_PropelledInformation_human:
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->elements.human)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("HumanPropelledType", "unavailable", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("HumanPropelledType", "otherTypes", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("HumanPropelledType", "onFoot", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("HumanPropelledType", "skateboard", 3)) < 0) return ret; break;
		case 4: if ((ret = ASN1_Print_ENUMERATED("HumanPropelledType", "pushOrKickScooter", 4)) < 0) return ret; break;
		case 5: if ((ret = ASN1_Print_ENUMERATED("HumanPropelledType", "wheelchair", 5)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
		if (ret != 0) return -1;
		break;
	case DEF_PropelledInformation_animal:
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->elements.animal)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("AnimalPropelledType", "unavailable", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("AnimalPropelledType", "otherTypes", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("AnimalPropelledType", "animalMounted", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("AnimalPropelledType", "animalDrawnCarriage", 3)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
		if (ret != 0) return -1;
		break;
	case DEF_PropelledInformation_motor:
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->elements.motor)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("MotorizedPropelledType", "unavailable", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("MotorizedPropelledType", "otherTypes", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("MotorizedPropelledType", "wheelChair", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("MotorizedPropelledType", "bicycle", 3)) < 0) return ret; break;
		case 4: if ((ret = ASN1_Print_ENUMERATED("MotorizedPropelledType", "scooter", 4)) < 0) return ret; break;
		case 5: if ((ret = ASN1_Print_ENUMERATED("MotorizedPropelledType", "selfBalancingDevice", 5)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
		if (ret != 0) return -1;
		break;
	default: return -1;
}
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
