int ASN1_CHECK_PropelledInformation(PropelledInformation *value)
{
	int ret = 0;

	unsigned char checkinfo_human[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_animal[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_motor[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	switch (value->M)
	{
	case DEF_PropelledInformation_human:
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&value->elements.human, checkinfo_human)) < 0) return ret;
		break;
	case DEF_PropelledInformation_animal:
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&value->elements.animal, checkinfo_animal)) < 0) return ret;
		break;
	case DEF_PropelledInformation_motor:
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&value->elements.motor, checkinfo_motor)) < 0) return ret;
		break;
	default: break;
	}
	return ret;
}
extern int ASN1_BER_Data_Enc_HumanPropelledType(ASN1WorkSpace *workspace, HumanPropelledType *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_AnimalPropelledType(ASN1WorkSpace *workspace, AnimalPropelledType *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_MotorizedPropelledType(ASN1WorkSpace *workspace, MotorizedPropelledType *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_PropelledInformation(ASN1WorkSpace *workspace, PropelledInformation *value, ASN1TagType tagFlag)
{
	int ret = 0;
	switch(value->M)
	{
	case DEF_PropelledInformation_human:
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_HumanPropelledType(workspace, &(value->elements.human), ASN1IMPL)) < 0) return ret;
		break;
	case DEF_PropelledInformation_animal:
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_AnimalPropelledType(workspace, &(value->elements.animal), ASN1IMPL)) < 0) return ret;
		break;
	case DEF_PropelledInformation_motor:
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_MotorizedPropelledType(workspace, &(value->elements.motor), ASN1IMPL)) < 0) return ret;
		break;
	}
	return ret;
}
