int ASN1_PER_UNAlign_Data_Dec_PropelledInformation(ASN1WorkSpace *workspace, PropelledInformation *value)
{
	int ret = 0;
	ASNINT32 ui_human;
	ASNINT32 ui_animal;
	ASNINT32 ui_motor;
	struct Asn1ConsInfo consinfo_human = { ASN1_CONST64(0), ASN1_CONST64(5), NULL, 1, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_animal = { ASN1_CONST64(0), ASN1_CONST64(3), NULL, 1, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_motor = { ASN1_CONST64(0), ASN1_CONST64(5), NULL, 1, CONS, 0, 0 };

	ASNINT32 index;
	ASNINT64 ui;
	ASNBOOL extbit;
	if ((ret = ASN1_PER_UNAlign_Dec_Choice_ENUMERATED(workspace, &ui, &extbit, 1, 3)) < 0) return ret;

	if (extbit == 0)
	{
		switch(ui)
		{
		case 0: index = DEF_PropelledInformation_human;
			break;
		case 1: index = DEF_PropelledInformation_animal;
			break;
		case 2: index = DEF_PropelledInformation_motor;
			break;
		default: break;
		}
	}
	else
	{
		switch(ui)
		{
		default: break;
		}
	}
	if ((ret = ASN1_GetM(&value->M, index)) < 0) return ret;
	switch(index)
	{
	case DEF_PropelledInformation_human:
		if ((ret = ASN1_PER_UNAlign_Dec_ENUMERATED(workspace, &ui_human, &consinfo_human)) < 0) return ret;
		if (consinfo_human.enumextbit == 0)
		{
			switch(ui_human)
			{
			case 0: value->elements.human = HumanPropelledType_unavailable; break;
			case 1: value->elements.human = HumanPropelledType_otherTypes; break;
			case 2: value->elements.human = HumanPropelledType_onFoot; break;
			case 3: value->elements.human = HumanPropelledType_skateboard; break;
			case 4: value->elements.human = HumanPropelledType_pushOrKickScooter; break;
			case 5: value->elements.human = HumanPropelledType_wheelchair; break;
			default: break;
			}
		}
		else
		{
			switch(ui_human)
			{
			default: value->elements.human = ui_human; break;
			}
		}
		if (ret != 0) return -1;
		break;
	case DEF_PropelledInformation_animal:
		if ((ret = ASN1_PER_UNAlign_Dec_ENUMERATED(workspace, &ui_animal, &consinfo_animal)) < 0) return ret;
		if (consinfo_animal.enumextbit == 0)
		{
			switch(ui_animal)
			{
			case 0: value->elements.animal = AnimalPropelledType_unavailable; break;
			case 1: value->elements.animal = AnimalPropelledType_otherTypes; break;
			case 2: value->elements.animal = AnimalPropelledType_animalMounted; break;
			case 3: value->elements.animal = AnimalPropelledType_animalDrawnCarriage; break;
			default: break;
			}
		}
		else
		{
			switch(ui_animal)
			{
			default: value->elements.animal = ui_animal; break;
			}
		}
		if (ret != 0) return -1;
		break;
	case DEF_PropelledInformation_motor:
		if ((ret = ASN1_PER_UNAlign_Dec_ENUMERATED(workspace, &ui_motor, &consinfo_motor)) < 0) return ret;
		if (consinfo_motor.enumextbit == 0)
		{
			switch(ui_motor)
			{
			case 0: value->elements.motor = MotorizedPropelledType_unavailable; break;
			case 1: value->elements.motor = MotorizedPropelledType_otherTypes; break;
			case 2: value->elements.motor = MotorizedPropelledType_wheelChair; break;
			case 3: value->elements.motor = MotorizedPropelledType_bicycle; break;
			case 4: value->elements.motor = MotorizedPropelledType_scooter; break;
			case 5: value->elements.motor = MotorizedPropelledType_selfBalancingDevice; break;
			default: break;
			}
		}
		else
		{
			switch(ui_motor)
			{
			default: value->elements.motor = ui_motor; break;
			}
		}
		if (ret != 0) return -1;
		break;
	default: ret = ASN1_PER_Dec_unKnown(workspace, UNALIGN); break;
	}
	return ret;
}
