/********************************************************
*SignalRequestMessage                                   *
********************************************************/
int ASN1_Print_SignalRequestMessage(SignalRequestMessage *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("SignalRequestMessage");
	if (value->DEF_SignalRequestMessage_timeStamp == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("MinuteOfTheYear", &(value->timeStamp))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("DSecond", &(value->second))) < 0) return ret;
	if (value->DEF_SignalRequestMessage_sequenceNumber == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("MsgCount", &(value->sequenceNumber))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SignalRequestMessage_requests == 1)
	{ /*OPTIONAL start */
		// Type Reference SignalRequestList
		if (Compare_Letter(tab_value, "requests")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("requests = ");
		}
		if ((ret = ASN1_Print_SignalRequestList((SignalRequestList *)&(value->requests), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	// Type Reference RequestorDescription
	if (Compare_Letter(tab_value, "requestor")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("requestor = ");
	}
	if ((ret = ASN1_Print_RequestorDescription((RequestorDescription *)value->requestor, tab_value + 1)) < 0) return ret;
	if (value->DEF_SignalRequestMessage_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference SignalRequestMessage_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_SignalRequestMessage_regional((SignalRequestMessage_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
