extern int ASN1_CHECK_SignalRequestList(SignalRequestList *value);
extern int ASN1_CHECK_RequestorDescription(RequestorDescription *value);
extern int ASN1_CHECK_SignalRequestMessage_regional(SignalRequestMessage_regional *value);
int ASN1_CHECK_SignalRequestMessage(SignalRequestMessage *value)
{
	int ret = 0;

	unsigned char checkinfo_timeStamp[] = { 
		0x02,0x00,0x83,0x08,0x0A,0xC0,0x00
	};
	unsigned char checkinfo_second[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};
	unsigned char checkinfo_sequenceNumber[] = { 
		0x02,0x00,0x7F,0x00
	};
	unsigned char checkinfo_requests[] = { 
		0x02,0x01,0x20,0x00
	};
	unsigned char checkinfo_requestor[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_SignalRequestMessage_timeStamp == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->timeStamp), checkinfo_timeStamp)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_INTEGER(&(value->second), checkinfo_second)) < 0) return ret;
	if (value->DEF_SignalRequestMessage_sequenceNumber == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->sequenceNumber), checkinfo_sequenceNumber)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SignalRequestMessage_requests == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_SignalRequestList(&(value->requests))) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_RequestorDescription(value->requestor)) < 0) return ret;
	if (value->DEF_SignalRequestMessage_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_SignalRequestMessage_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_MinuteOfTheYear(ASN1WorkSpace *workspace, MinuteOfTheYear *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_DSecond(ASN1WorkSpace *workspace, DSecond *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_MsgCount(ASN1WorkSpace *workspace, MsgCount *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_SignalRequestList(ASN1WorkSpace *workspace, SignalRequestList *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_RequestorDescription(ASN1WorkSpace *workspace, RequestorDescription *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_SignalRequestMessage_regional(ASN1WorkSpace *workspace, SignalRequestMessage_regional *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_SignalRequestMessage(ASN1WorkSpace *workspace, SignalRequestMessage *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if (value->DEF_SignalRequestMessage_timeStamp == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_MinuteOfTheYear(workspace, &(value->timeStamp), ASN1IMPL)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_DSecond(workspace, &(value->second), ASN1IMPL)) < 0) return ret;
	if (value->DEF_SignalRequestMessage_sequenceNumber == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_MsgCount(workspace, &(value->sequenceNumber), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_SignalRequestMessage_requests == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 3)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_SignalRequestList(workspace, &(value->requests), ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 4)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_RequestorDescription(workspace, value->requestor, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (value->DEF_SignalRequestMessage_regional == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 16)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_SignalRequestMessage_regional(workspace, &(value->regional), ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
