int ASN1_Print_SignalStatusMessage(SignalStatusMessage *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("SignalStatusMessage");
	if (value->DEF_SignalStatusMessage_timeStamp == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("MinuteOfTheYear", &(value->timeStamp))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("DSecond", &(value->second))) < 0) return ret;
	if (value->DEF_SignalStatusMessage_sequenceNumber == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("MsgCount", &(value->sequenceNumber))) < 0) return ret;
	} /* OPTIONAL end */
	// Type Reference SignalStatusList
	if (Compare_Letter(tab_value, "status")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("status = ");
	}
	if ((ret = ASN1_Print_SignalStatusList((SignalStatusList *)&(value->status), tab_value + 1)) < 0) return ret;
	if (value->DEF_SignalStatusMessage_regional == 1)
	{ /*OPTIONAL start */
		// Type Reference SignalStatusMessage_regional
		if (Compare_Letter(tab_value, "regional")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regional = ");
		}
		if ((ret = ASN1_Print_SignalStatusMessage_regional((SignalStatusMessage_regional *)&(value->regional), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
