extern int ASN1_CHECK_RoadSideAlert(RoadSideAlert *value);
extern int ASN1_CHECK_EmergencyDetails(EmergencyDetails *value);
extern int ASN1_CHECK_EmergencyVehicleAlert_regional(EmergencyVehicleAlert_regional *value);
int ASN1_CHECK_EmergencyVehicleAlert(EmergencyVehicleAlert *value)
{
	int ret = 0;

	unsigned char checkinfo_timeStamp[] = { 
		0x02,0x00,0x83,0x08,0x0A,0xC0,0x00
	};
	unsigned char checkinfo_id[] = { 
		0x02,0x04,0x04,0x00
	};
	unsigned char checkinfo_rsaMsg[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_responseType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_details[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_mass[] = { 
		0x02,0x00,0x82,0x00,0xFF,0x00
	};
	unsigned char checkinfo_basicType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_vehicleType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_responseEquip[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_responderType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_EmergencyVehicleAlert_timeStamp == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->timeStamp), checkinfo_timeStamp)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_EmergencyVehicleAlert_id == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_OCTETSTRING(&(value->id), checkinfo_id)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_RoadSideAlert(value->rsaMsg)) < 0) return ret;
	if (value->DEF_EmergencyVehicleAlert_responseType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->responseType), checkinfo_responseType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_EmergencyVehicleAlert_details == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_EmergencyDetails(value->details)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_EmergencyVehicleAlert_mass == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->mass), checkinfo_mass)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_EmergencyVehicleAlert_basicType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->basicType), checkinfo_basicType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_EmergencyVehicleAlert_vehicleType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->vehicleType), checkinfo_vehicleType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_EmergencyVehicleAlert_responseEquip == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->responseEquip), checkinfo_responseEquip)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_EmergencyVehicleAlert_responderType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->responderType), checkinfo_responderType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_EmergencyVehicleAlert_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_EmergencyVehicleAlert_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
