extern int ASN1_CHECK_Position3D(Position3D *value);
extern int ASN1_CHECK_PositionalAccuracy(PositionalAccuracy *value);
extern int ASN1_CHECK_AccelerationSet4Way(AccelerationSet4Way *value);
extern int ASN1_CHECK_PathHistory(PathHistory *value);
extern int ASN1_CHECK_PathPrediction(PathPrediction *value);
extern int ASN1_CHECK_PropelledInformation(PropelledInformation *value);
extern int ASN1_CHECK_PersonalSafetyMessage_regional(PersonalSafetyMessage_regional *value);
int ASN1_CHECK_PersonalSafetyMessage(PersonalSafetyMessage *value)
{
	int ret = 0;

	unsigned char checkinfo_basicType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_secMark[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};
	unsigned char checkinfo_msgCnt[] = { 
		0x02,0x00,0x7F,0x00
	};
	unsigned char checkinfo_id[] = { 
		0x02,0x04,0x04,0x00
	};
	unsigned char checkinfo_position[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_accuracy[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_speed[] = { 
		0x02,0x00,0x82,0x1F,0xFF,0x00
	};
	unsigned char checkinfo_heading[] = { 
		0x02,0x00,0x82,0x70,0x80,0x00
	};
	unsigned char checkinfo_accelSet[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_pathHistory[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_pathPrediction[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_propulsion[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_useState[] = { 
		0x02,0x09,0x09,0xCC,0x00
	};
	unsigned char checkinfo_crossRequest[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_crossState[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_clusterSize[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_clusterRadius[] = { 
		0x02,0x00,0x64,0x00
	};
	unsigned char checkinfo_eventResponderType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_activityType[] = { 
		0x02,0x06,0x06,0xCC,0x00
	};
	unsigned char checkinfo_activitySubType[] = { 
		0x02,0x07,0x07,0xCC,0x00
	};
	unsigned char checkinfo_assistType[] = { 
		0x02,0x06,0x06,0xCC,0x00
	};
	unsigned char checkinfo_sizing[] = { 
		0x02,0x05,0x05,0xCC,0x00
	};
	unsigned char checkinfo_attachment[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_attachmentRadius[] = { 
		0x02,0x00,0x82,0x00,0xC8,0x00
	};
	unsigned char checkinfo_animalType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_regional[] = { 
		0x02,0x01,0x04,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->basicType), checkinfo_basicType)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->secMark), checkinfo_secMark)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->msgCnt), checkinfo_msgCnt)) < 0) return ret;
	if ((ret = ASN1_CHECK_OCTETSTRING(&(value->id), checkinfo_id)) < 0) return ret;
	if ((ret = ASN1_CHECK_Position3D(value->position)) < 0) return ret;
	if ((ret = ASN1_CHECK_PositionalAccuracy(value->accuracy)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->speed), checkinfo_speed)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->heading), checkinfo_heading)) < 0) return ret;
	if (value->DEF_PersonalSafetyMessage_accelSet == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_AccelerationSet4Way(value->accelSet)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_pathHistory == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_PathHistory(value->pathHistory)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_pathPrediction == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_PathPrediction(value->pathPrediction)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_propulsion == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_PropelledInformation(value->propulsion)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_useState == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BITSTRING(&(value->useState), checkinfo_useState)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_crossRequest == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BOOLEAN(&(value->crossRequest), checkinfo_crossRequest)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_crossState == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BOOLEAN(&(value->crossState), checkinfo_crossState)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_clusterSize == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->clusterSize), checkinfo_clusterSize)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_clusterRadius == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->clusterRadius), checkinfo_clusterRadius)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_eventResponderType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->eventResponderType), checkinfo_eventResponderType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_activityType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BITSTRING(&(value->activityType), checkinfo_activityType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_activitySubType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BITSTRING(&(value->activitySubType), checkinfo_activitySubType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_assistType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BITSTRING(&(value->assistType), checkinfo_assistType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_sizing == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_BITSTRING(&(value->sizing), checkinfo_sizing)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_attachment == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->attachment), checkinfo_attachment)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_attachmentRadius == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->attachmentRadius), checkinfo_attachmentRadius)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_animalType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->animalType), checkinfo_animalType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_PersonalSafetyMessage_regional == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_PersonalSafetyMessage_regional(&(value->regional))) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
