		case 4: value->event = ADASEventType_motors; break;
		case 5: value->event = ADASEventType_special; break;
		case 6: value->event = ADASEventType_bicycle; break;
		case 7: value->event = ADASEventType_pedestrian; break;
		case 8: value->event = ADASEventType_pothole; break;
		case 9: value->event = ADASEventType_rubbercon; break;
