	{
		switch(ui_event)
		{
		default: value->event = ui_event; break;
		}
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_CITSADAS_KOR_distance = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->distance), &consinfo_distance)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_CITSADAS_KOR_time = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->time), &consinfo_time)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 3) == 1)
	{
		value->DEF_CITSADAS_KOR_lon = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->lon), &consinfo_lon)) < 0) return ret;
	}
