			case 1: value->confidence = PositionConfidence_a500m; break;
			case 2: value->confidence = PositionConfidence_a200m; break;
			case 3: value->confidence = PositionConfidence_a100m; break;
			case 4: value->confidence = PositionConfidence_a50m; break;
			case 5: value->confidence = PositionConfidence_a20m; break;
			case 6: value->confidence = PositionConfidence_a10m; break;
			case 7: value->confidence = PositionConfidence_a5m; break;
			case 8: value->confidence = PositionConfidence_a2m; break;
			case 9: value->confidence = PositionConfidence_a1m; break;
			case 10: value->confidence = PositionConfidence_a50cm; break;
			case 11: value->confidence = PositionConfidence_a20cm; break;
			case 12: value->confidence = PositionConfidence_a10cm; break;
			case 13: value->confidence = PositionConfidence_a5cm; break;
			case 14: value->confidence = PositionConfidence_a2cm; break;
			case 15: value->confidence = PositionConfidence_a1cm; break;
			default: value->confidence = ui_confidence; break;
