int ASN1_Print_BasicSafetyMessage_KOR_adas(BasicSafetyMessage_KOR_adas *value, int tab_value)
{
	int ret = 0;
	int count;
	ASN1ListNode *pnode;
	if (value == NULL) return -1;
	count = value->count;
	pnode = value->head->next;
	// SEQUENCE OF : default
	ASN1_Print_SEQ_OF(" ");
	while(count) {
		// Type Reference CITSADAS_KOR
		ASN_Print_TAB(tab_value + 1);
		if ((ret = ASN1_Print_CITSADAS_KOR((CITSADAS_KOR *)pnode->data, tab_value + 1)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}

	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
