extern int ASN1_BER_Data_Enc_ITISCodes_KOR(ASN1WorkSpace *workspace, ITISCodes_KOR *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_EventDescription_KOR(ASN1WorkSpace *workspace, EventDescription_KOR *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_ITISCodes_KOR(workspace, &(value->eventType), ASN1IMPL)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
