	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_SupplementalVehicleExtensions_KOR(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_SupplementalVehicleExtensions_KOR(value)) < 0) return ret;
