int ASN1_Print_EventOrSvcInfo_KOR(EventOrSvcInfo_KOR *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("EventOrSvcInfo-KOR");
	if (value->DEF_EventOrSvcInfo_KOR_typeEvent == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("ITISCodes_KOR", &(value->typeEvent))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_EventOrSvcInfo_KOR_description == 1)
	{ /*OPTIONAL start */
		// Type Reference ITIScodesAndText
		if (Compare_Letter(tab_value, "description")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("description = ");
		}
		if ((ret = ASN1_Print_ITIScodesAndText((ITIScodesAndText *)&(value->description), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_EventOrSvcInfo_KOR_text == 1)
	{ /*OPTIONAL start */
		// Type Reference EventOrSvcInfo_KOR_text
		if (Compare_Letter(tab_value, "text")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("text = ");
		}
		if ((ret = ASN1_Print_EventOrSvcInfo_KOR_text((EventOrSvcInfo_KOR_text *)&(value->text), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_EventOrSvcInfo_KOR_subtext == 1)
	{ /*OPTIONAL start */
		// Type Reference EventOrSvcInfo_KOR_subtext
		if (Compare_Letter(tab_value, "subtext")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("subtext = ");
		}
		if ((ret = ASN1_Print_EventOrSvcInfo_KOR_subtext((EventOrSvcInfo_KOR_subtext *)&(value->subtext), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
