int ASN1_Print_FuelStatus_KOR(FuelStatus_KOR *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("FuelStatus-KOR");
	if (value->DEF_FuelStatus_KOR_efficiency == 1)
	{ /*OPTIONAL start */
		// Type Reference FuelEfficiency_KOR
		if (Compare_Letter(tab_value, "efficiency")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("efficiency = ");
		}
		if ((ret = ASN1_Print_FuelEfficiency_KOR((FuelEfficiency_KOR *)value->efficiency, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_FuelStatus_KOR_residualQuantity == 1)
	{ /*OPTIONAL start */
		// Type Reference FuelResidualQuantity_KOR
		if (Compare_Letter(tab_value, "residualQuantity")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("residualQuantity = ");
		}
		if ((ret = ASN1_Print_FuelResidualQuantity_KOR((FuelResidualQuantity_KOR *)value->residualQuantity, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_FuelStatus_KOR_tankCapacity == 1)
	{ /*OPTIONAL start */
		// Type Reference FuelTankCapacity_KOR
		if (Compare_Letter(tab_value, "tankCapacity")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("tankCapacity = ");
		}
		if ((ret = ASN1_Print_FuelTankCapacity_KOR((FuelTankCapacity_KOR *)value->tankCapacity, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
