extern int ASN1_CHECK_FuelTankCapacity_KOR(FuelTankCapacity_KOR *value);
int ASN1_CHECK_FuelStatus_KOR(FuelStatus_KOR *value)
{
	int ret = 0;

	unsigned char checkinfo_efficiency[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_residualQuantity[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_tankCapacity[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if (value->DEF_FuelStatus_KOR_efficiency == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_FuelEfficiency_KOR(value->efficiency)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_FuelStatus_KOR_residualQuantity == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_FuelResidualQuantity_KOR(value->residualQuantity)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_FuelStatus_KOR_tankCapacity == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_FuelTankCapacity_KOR(value->tankCapacity)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_FuelEfficiency_KOR(ASN1WorkSpace *workspace, FuelEfficiency_KOR *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_FuelResidualQuantity_KOR(ASN1WorkSpace *workspace, FuelResidualQuantity_KOR *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_FuelTankCapacity_KOR(ASN1WorkSpace *workspace, FuelTankCapacity_KOR *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_FuelStatus_KOR(ASN1WorkSpace *workspace, FuelStatus_KOR *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if (value->DEF_FuelStatus_KOR_efficiency == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_FuelEfficiency_KOR(workspace, value->efficiency, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_FuelStatus_KOR_residualQuantity == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_FuelResidualQuantity_KOR(workspace, value->residualQuantity, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_FuelStatus_KOR_tankCapacity == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_FuelTankCapacity_KOR(workspace, value->tankCapacity, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
