/********************************************************
*MsgLog_KOR                                             *
********************************************************/
int ASN1_Print_MsgLog_KOR(MsgLog_KOR *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("MsgLog-KOR");
	// Type OCTET STRING
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_OCTETSTRING("FurtherInfoID", &(value->furtherInfoID), tab_value + 1)) < 0) return ret;
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->msgType)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("MsgType-KOR", "bsm", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("MsgType-KOR", "spat", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("MsgType-KOR", "tls", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("MsgType-KOR", "map", 3)) < 0) return ret; break;
	case 4: if ((ret = ASN1_Print_ENUMERATED("MsgType-KOR", "nmeacorrections", 4)) < 0) return ret; break;
	case 5: if ((ret = ASN1_Print_ENUMERATED("MsgType-KOR", "rtcmcorrections", 5)) < 0) return ret; break;
	case 6: if ((ret = ASN1_Print_ENUMERATED("MsgType-KOR", "pvd", 6)) < 0) return ret; break;
	case 7: if ((ret = ASN1_Print_ENUMERATED("MsgType-KOR", "pdm", 7)) < 0) return ret; break;
	case 8: if ((ret = ASN1_Print_ENUMERATED("MsgType-KOR", "rsa", 8)) < 0) return ret; break;
	case 9: if ((ret = ASN1_Print_ENUMERATED("MsgType-KOR", "tim", 9)) < 0) return ret; break;
	case 10: if ((ret = ASN1_Print_ENUMERATED("MsgType-KOR", "adas", 10)) < 0) return ret; break;
	case 11: if ((ret = ASN1_Print_ENUMERATED("MsgType-KOR", "psm", 11)) < 0) return ret; break;
	case 12: if ((ret = ASN1_Print_ENUMERATED("MsgType-KOR", "drowsiness", 12)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	if (value->DEF_MsgLog_KOR_msgEvent == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("ITISCodes_KOR", &(value->msgEvent))) < 0) return ret;
	} /* OPTIONAL end */
	// Type OCTET STRING
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_OCTETSTRING("TemporaryID", &(value->msgID), tab_value + 1)) < 0) return ret;
	if (value->DEF_MsgLog_KOR_msgDate == 1)
	{ /*OPTIONAL start */
		// Type Reference DDateTime
		if (Compare_Letter(tab_value, "msgDate")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("msgDate = ");
		}
		if ((ret = ASN1_Print_DDateTime((DDateTime *)value->msgDate, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MsgLog_KOR_msgCommType == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->msgCommType)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("MsgCommType-KOR", "unavailable", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("MsgCommType-KOR", "wave", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("MsgCommType-KOR", "lte", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("MsgCommType-KOR", "g5", 3)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	if (value->DEF_MsgLog_KOR_msgChannel == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("MsgChannel_KOR", &(value->msgChannel))) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->msgDeviceType)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("MsgDeviceType-KOR", "other", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("MsgDeviceType-KOR", "communication", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("MsgDeviceType-KOR", "display", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("MsgDeviceType-KOR", "adas", 3)) < 0) return ret; break;
	case 4: if ((ret = ASN1_Print_ENUMERATED("MsgDeviceType-KOR", "drowsinessDetector", 4)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	if (value->DEF_MsgLog_KOR_msgDisplayLocation == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("MsgDisplayLocation_KOR", &(value->msgDisplayLocation))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MsgLog_KOR_msgDisplayTime == 1)
	{ /*OPTIONAL start */
		// Type Reference DDateTime
		if (Compare_Letter(tab_value, "msgDisplayTime")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("msgDisplayTime = ");
		}
		if ((ret = ASN1_Print_DDateTime((DDateTime *)value->msgDisplayTime, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
