int ASN1_CHECK_MsgLog_KOR(MsgLog_KOR *value)
{
	int ret = 0;

	unsigned char checkinfo_furtherInfoID[] = { 
		0x02,0x02,0x02,0x00
	};
	unsigned char checkinfo_msgType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_msgEvent[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};
	unsigned char checkinfo_msgID[] = { 
		0x02,0x04,0x04,0x00
	};
	unsigned char checkinfo_msgDate[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_msgCommType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_msgChannel[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};
	unsigned char checkinfo_msgDeviceType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_msgDisplayLocation[] = { 
		0x02,0x00,0x82,0x00,0x80,0x00
	};
	unsigned char checkinfo_msgDisplayTime[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_OCTETSTRING(&(value->furtherInfoID), checkinfo_furtherInfoID)) < 0) return ret;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->msgType), checkinfo_msgType)) < 0) return ret;
	if (value->DEF_MsgLog_KOR_msgEvent == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->msgEvent), checkinfo_msgEvent)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_OCTETSTRING(&(value->msgID), checkinfo_msgID)) < 0) return ret;
	if (value->DEF_MsgLog_KOR_msgDate == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_DDateTime(value->msgDate)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MsgLog_KOR_msgCommType == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->msgCommType), checkinfo_msgCommType)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MsgLog_KOR_msgChannel == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->msgChannel), checkinfo_msgChannel)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->msgDeviceType), checkinfo_msgDeviceType)) < 0) return ret;
	if (value->DEF_MsgLog_KOR_msgDisplayLocation == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->msgDisplayLocation), checkinfo_msgDisplayLocation)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_MsgLog_KOR_msgDisplayTime == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_DDateTime(value->msgDisplayTime)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
