int ASN1_Print_RoadWorkInfo_KOR(RoadWorkInfo_KOR *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("RoadWorkInfo-KOR");
	if (value->DEF_RoadWorkInfo_KOR_worklanes == 1)
	{ /*OPTIONAL start */
		// Type Reference RoadWorkInfo_KOR_worklanes
		if (Compare_Letter(tab_value, "worklanes")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("worklanes = ");
		}
		if ((ret = ASN1_Print_RoadWorkInfo_KOR_worklanes((RoadWorkInfo_KOR_worklanes *)&(value->worklanes), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadWorkInfo_KOR_workstart == 1)
	{ /*OPTIONAL start */
		// Type Reference DDateTime
		if (Compare_Letter(tab_value, "workstart")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("workstart = ");
		}
		if ((ret = ASN1_Print_DDateTime((DDateTime *)value->workstart, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadWorkInfo_KOR_workend == 1)
	{ /*OPTIONAL start */
		// Type Reference DDateTime
		if (Compare_Letter(tab_value, "workend")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("workend = ");
		}
		if ((ret = ASN1_Print_DDateTime((DDateTime *)value->workend, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
