/********************************************************
*VehicleControlInfo_KOR                                 *
********************************************************/
int ASN1_Print_VehicleControlInfo_KOR(VehicleControlInfo_KOR *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("VehicleControlInfo-KOR");
	if (value->DEF_VehicleControlInfo_KOR_mode == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->mode)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("VehicleControlMode-KOR", "manual", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("VehicleControlMode-KOR", "auto", 1)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	if (value->DEF_VehicleControlInfo_KOR_tunring == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->tunring)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("PossibleTurn-KOR", "non", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("PossibleTurn-KOR", "left-turn", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("PossibleTurn-KOR", "right-turn", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("PossibleTurn-KOR", "both-turn", 3)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	if (value->DEF_VehicleControlInfo_KOR_angle == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("DrivingWheelAngle", &(value->angle))) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
