{
	int ret = 0;

	unsigned char checkinfo_mode[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_tunring[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_angle[] = { 
		0x02,0x82,0xFF,0x80,0x7F,0x00
	};

	if (value == NULL) return -1;
	if (value->DEF_VehicleControlInfo_KOR_mode == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->mode), checkinfo_mode)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleControlInfo_KOR_tunring == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->tunring), checkinfo_tunring)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_VehicleControlInfo_KOR_angle == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->angle), checkinfo_angle)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
