extern int ASN1_BER_Data_Enc_PossibleTurn_KOR(ASN1WorkSpace *workspace, PossibleTurn_KOR *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_DrivingWheelAngle(ASN1WorkSpace *workspace, DrivingWheelAngle *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_VehicleControlInfo_KOR(ASN1WorkSpace *workspace, VehicleControlInfo_KOR *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if (value->DEF_VehicleControlInfo_KOR_mode == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_VehicleControlMode_KOR(workspace, &(value->mode), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_VehicleControlInfo_KOR_tunring == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_PossibleTurn_KOR(workspace, &(value->tunring), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_VehicleControlInfo_KOR_angle == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_DrivingWheelAngle(workspace, &(value->angle), ASN1IMPL)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
