/********************************************************
*SensorValuesRegardingDriving_KOR                       *
********************************************************/
int ASN1_Print_SensorValuesRegardingDriving_KOR(SensorValuesRegardingDriving_KOR *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("SensorValuesRegardingDriving-KOR");
	if (value->DEF_SensorValuesRegardingDriving_KOR_rpm == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("Rpm_KOR", &(value->rpm))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_SensorValuesRegardingDriving_KOR_gears == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->gears)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "neutral", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "park", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "forwardGears", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "reverseGears", 3)) < 0) return ret; break;
		case 4: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "reserved1", 4)) < 0) return ret; break;
		case 5: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "reserved2", 5)) < 0) return ret; break;
		case 6: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "reserved3", 6)) < 0) return ret; break;
		case 7: if ((ret = ASN1_Print_ENUMERATED("TransmissionState", "unavailable", 7)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	if (value->DEF_SensorValuesRegardingDriving_KOR_gyro == 1)
	{ /*OPTIONAL start */
		// Type Reference GyroscopeValue_KOR
		if (Compare_Letter(tab_value, "gyro")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("gyro = ");
		}
		if ((ret = ASN1_Print_GyroscopeValue_KOR((GyroscopeValue_KOR *)value->gyro, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
