int ASN1_PER_UNAlign_Data_Enc_RidingNotification_KOR(ASN1WorkSpace *workspace, RidingNotification_KOR *value)
{
	int ret = 0;
	struct Asn1ConsInfo consinfo_stopID = { ASN1_CONST64(1), ASN1_CONST64(128), NULL, 0, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_disabled = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_boarding = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };

	ASNINT32 all_bit;
	ASNUINT16 all_pointer;
	if ((ret = ASN1_PER_Enc_extbit(workspace, value->E)) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_RidingNotification_KOR_stopID == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_RidingNotification_KOR_disabled == 1 ? 1 : 0) )) < 0) return ret;
	if ((ret = ASN1_PER_Enc_bit(workspace, (ASNBOOL)(value->DEF_RidingNotification_KOR_boarding == 1 ? 1 : 0) )) < 0) return ret;
	if (value->DEF_RidingNotification_KOR_stopID == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_UTF8Str(workspace, &(value->stopID), &consinfo_stopID)) < 0) return ret;
	}
	if (value->DEF_RidingNotification_KOR_disabled == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_BOOLEAN(workspace, &(value->disabled), &consinfo_disabled)) < 0) return ret;
	}
	if (value->DEF_RidingNotification_KOR_boarding == 1)
	{
		if ((ret = ASN1_PER_UNAlign_Enc_BOOLEAN(workspace, &(value->boarding), &consinfo_boarding)) < 0) return ret;
	}
	ASN1_SaveCurrentPointer(workspace, &all_bit, &all_pointer);
	if (value->E != 0)
	{
		ASN1_PER_Enc_extOption(workspace, UNALIGN, 0);
	}
	return ret;
}
