int ASN1_Print_RoadSideAlert_KOR_regions(RoadSideAlert_KOR_regions *value, int tab_value)
{
	int ret = 0;
	int count;
	ASN1ListNode *pnode;
	if (value == NULL) return -1;
	count = value->count;
	pnode = value->head->next;
	// SEQUENCE OF : default
	ASN1_Print_SEQ_OF(" ");
	while(count) {
		// Type Reference RegionDescribedByID_KOR
		ASN_Print_TAB(tab_value + 1);
		if ((ret = ASN1_Print_RegionDescribedByID_KOR((RegionDescribedByID_KOR *)pnode->data, tab_value + 1)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}

	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
extern int ASN1_CHECK_RegionDescribedByID_KOR(RegionDescribedByID_KOR *value);
int ASN1_CHECK_RoadSideAlert_KOR_regions(RoadSideAlert_KOR_regions *value)
{
	int ret = 0;

	unsigned char checkinfo_RoadSideAlert_KOR_regions[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_RoadSideAlert_KOR_regions_pdata[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	int count;
	ASN1ListNode* pnode;
	if (value == NULL) return -1;
	if (value->head == NULL) return -1;
	if (value->count < 0) return -1;
	pnode = value->head->next;
	count = value->count;
	while (count) {
		if ((ret = ASN1_CHECK_RegionDescribedByID_KOR(pnode->data)) < 0) return ret;
		pnode = pnode->next;
		count--;
	}
	return ret;
}
