/********************************************************
*RoadSideAlert_KOR                                      *
********************************************************/
int ASN1_Print_RoadSideAlert_KOR(RoadSideAlert_KOR *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("RoadSideAlert-KOR");
	if (value->DEF_RoadSideAlert_KOR_msgID == 1)
	{ /*OPTIONAL start */
		// Type Default
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("msgID", &(value->msgID))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSideAlert_KOR_regions == 1)
	{ /*OPTIONAL start */
		// Type Reference RoadSideAlert_KOR_regions
		if (Compare_Letter(tab_value, "regions")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("regions = ");
		}
		if ((ret = ASN1_Print_RoadSideAlert_KOR_regions((RoadSideAlert_KOR_regions *)&(value->regions), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSideAlert_KOR_events == 1)
	{ /*OPTIONAL start */
		// Type Reference EventOrSvcInfo_KOR
		if (Compare_Letter(tab_value, "events")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("events = ");
		}
		if ((ret = ASN1_Print_EventOrSvcInfo_KOR((EventOrSvcInfo_KOR *)value->events, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSideAlert_KOR_state == 1)
	{ /*OPTIONAL start */
		// Type Reference MovementEvent
		if (Compare_Letter(tab_value, "state")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("state = ");
		}
		if ((ret = ASN1_Print_MovementEvent((MovementEvent *)value->state, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_RoadSideAlert_KOR_detectedObject == 1)
	{ /*OPTIONAL start */
		// Type Reference DetectedObjectInfo_KOR
		if (Compare_Letter(tab_value, "detectedObject")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("detectedObject = ");
		}
		if ((ret = ASN1_Print_DetectedObjectInfo_KOR((DetectedObjectInfo_KOR *)value->detectedObject, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
