int ASN1_Print_StationInformation_KOR(StationInformation_KOR *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("StationInformation-KOR");
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->type)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("FuelType-KOR", "gasoline", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("FuelType-KOR", "diesel", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("FuelType-KOR", "lpg", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("FuelType-KOR", "premium", 3)) < 0) return ret; break;
	case 4: if ((ret = ASN1_Print_ENUMERATED("FuelType-KOR", "hydrogen", 4)) < 0) return ret; break;
	case 5: if ((ret = ASN1_Print_ENUMERATED("FuelType-KOR", "normalCharging", 5)) < 0) return ret; break;
	case 6: if ((ret = ASN1_Print_ENUMERATED("FuelType-KOR", "quickCharging", 6)) < 0) return ret; break;
	case 7: if ((ret = ASN1_Print_ENUMERATED("FuelType-KOR", "superCharging", 7)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	if (value->DEF_StationInformation_KOR_capacity == 1)
	{ /*OPTIONAL start */
		// Type Default
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("capacity", &(value->capacity))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_StationInformation_KOR_maxcapacity == 1)
	{ /*OPTIONAL start */
		// Type Default
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("maxcapacity", &(value->maxcapacity))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_StationInformation_KOR_price == 1)
	{ /*OPTIONAL start */
		// Type Default
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("price", &(value->price))) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
