/********************************************************
*ServiceAreaInformation_KOR                             *
********************************************************/
int ASN1_Print_ServiceAreaInformation_KOR(ServiceAreaInformation_KOR *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("ServiceAreaInformation-KOR");
	// Type Default
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_UTF8Str("name", &(value->name))) < 0) return ret;
	// Type Default
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_UTF8Str("id", &(value->id))) < 0) return ret;
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->direction)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("HighwayDirection-KOR", "up", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("HighwayDirection-KOR", "down", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("HighwayDirection-KOR", "upAndDown", 2)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	if (value->DEF_ServiceAreaInformation_KOR_stationInfo == 1)
	{ /*OPTIONAL start */
		// Type Reference ServiceAreaInformation_KOR_stationInfo
		if (Compare_Letter(tab_value, "stationInfo")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("stationInfo = ");
		}
		if ((ret = ASN1_Print_ServiceAreaInformation_KOR_stationInfo((ServiceAreaInformation_KOR_stationInfo *)&(value->stationInfo), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_ServiceAreaInformation_KOR_parkingInfo == 1)
	{ /*OPTIONAL start */
		// Type Reference ServiceAreaInformation_KOR_parkingInfo
		if (Compare_Letter(tab_value, "parkingInfo")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("parkingInfo = ");
		}
		if ((ret = ASN1_Print_ServiceAreaInformation_KOR_parkingInfo((ServiceAreaInformation_KOR_parkingInfo *)&(value->parkingInfo), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
