int ASN1_Print_TollgateLaneInformation_KOR(TollgateLaneInformation_KOR *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("TollgateLaneInformation-KOR");
	if (value->DEF_TollgateLaneInformation_KOR_name == 1)
	{ /*OPTIONAL start */
		// Type Default
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_UTF8Str("name", &(value->name))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TollgateLaneInformation_KOR_heading == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->heading)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("HighwayDirection-KOR", "up", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("HighwayDirection-KOR", "down", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("HighwayDirection-KOR", "upAndDown", 2)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	if (value->DEF_TollgateLaneInformation_KOR_lanes == 1)
	{ /*OPTIONAL start */
		// Type Reference TollgateLaneInformation_KOR_lanes
		if (Compare_Letter(tab_value, "lanes")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("lanes = ");
		}
		if ((ret = ASN1_Print_TollgateLaneInformation_KOR_lanes((TollgateLaneInformation_KOR_lanes *)&(value->lanes), tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
