int ASN1_Print_WeatherInfo_KOR(WeatherInfo_KOR *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("WeatherInfo-KOR");
	if (value->DEF_WeatherInfo_KOR_temp == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("AmbientAirTemperature", &(value->temp))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_WeatherInfo_KOR_rainfall == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("EssPrecipRate", &(value->rainfall))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_WeatherInfo_KOR_humidity == 1)
	{ /*OPTIONAL start */
		// Type Default
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("humidity", &(value->humidity))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_WeatherInfo_KOR_windDir == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("HeadingSlice", &(value->windDir))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_WeatherInfo_KOR_windSpd == 1)
	{ /*OPTIONAL start */
		// Type Default
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("windSpd", &(value->windSpd))) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
