int ASN1_Print_TravelerDataFrameAdditionalInformation_KOR(TravelerDataFrameAdditionalInformation_KOR *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("TravelerDataFrameAdditionalInformation-KOR");
	// Type Default
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("dataFrameIndex", &(value->dataFrameIndex))) < 0) return ret;
	if (value->DEF_TravelerDataFrameAdditionalInformation_KOR_events == 1)
	{ /*OPTIONAL start */
		// Type Reference EventOrSvcInfo_KOR
		if (Compare_Letter(tab_value, "events")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("events = ");
		}
		if ((ret = ASN1_Print_EventOrSvcInfo_KOR((EventOrSvcInfo_KOR *)value->events, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TravelerDataFrameAdditionalInformation_KOR_vehicleRidingStatus == 1)
	{ /*OPTIONAL start */
		// Type Reference RidingNotification_KOR
		if (Compare_Letter(tab_value, "vehicleRidingStatus")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("vehicleRidingStatus = ");
		}
		if ((ret = ASN1_Print_RidingNotification_KOR((RidingNotification_KOR *)value->vehicleRidingStatus, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TravelerDataFrameAdditionalInformation_KOR_weatherInfo == 1)
	{ /*OPTIONAL start */
		// Type Reference WeatherInfo_KOR
		if (Compare_Letter(tab_value, "weatherInfo")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("weatherInfo = ");
		}
		if ((ret = ASN1_Print_WeatherInfo_KOR((WeatherInfo_KOR *)value->weatherInfo, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TravelerDataFrameAdditionalInformation_KOR_serviceArea == 1)
	{ /*OPTIONAL start */
		// Type Reference ServiceAreaInformation_KOR
		if (Compare_Letter(tab_value, "serviceArea")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("serviceArea = ");
		}
		if ((ret = ASN1_Print_ServiceAreaInformation_KOR((ServiceAreaInformation_KOR *)value->serviceArea, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TravelerDataFrameAdditionalInformation_KOR_tollgate == 1)
	{ /*OPTIONAL start */
		// Type Reference TollgateLaneInformation_KOR
		if (Compare_Letter(tab_value, "tollgate")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("tollgate = ");
		}
		if ((ret = ASN1_Print_TollgateLaneInformation_KOR((TollgateLaneInformation_KOR *)value->tollgate, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
