extern int ASN1_BER_Data_Enc_RidingNotification_KOR(ASN1WorkSpace *workspace, RidingNotification_KOR *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_WeatherInfo_KOR(ASN1WorkSpace *workspace, WeatherInfo_KOR *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_ServiceAreaInformation_KOR(ASN1WorkSpace *workspace, ServiceAreaInformation_KOR *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_TollgateLaneInformation_KOR(ASN1WorkSpace *workspace, TollgateLaneInformation_KOR *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_TravelerDataFrameAdditionalInformation_KOR(ASN1WorkSpace *workspace, TravelerDataFrameAdditionalInformation_KOR *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_INTEGER(workspace, &(value->dataFrameIndex), ASN1IMPL)) < 0) return ret;
	if (value->DEF_TravelerDataFrameAdditionalInformation_KOR_events == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_EventOrSvcInfo_KOR(workspace, value->events, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_TravelerDataFrameAdditionalInformation_KOR_vehicleRidingStatus == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 2)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_RidingNotification_KOR(workspace, value->vehicleRidingStatus, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_TravelerDataFrameAdditionalInformation_KOR_weatherInfo == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 3)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_WeatherInfo_KOR(workspace, value->weatherInfo, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_TravelerDataFrameAdditionalInformation_KOR_serviceArea == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 4)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_ServiceAreaInformation_KOR(workspace, value->serviceArea, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (value->DEF_TravelerDataFrameAdditionalInformation_KOR_tollgate == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 5)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_TollgateLaneInformation_KOR(workspace, value->tollgate, ASN1IMPL)) < 0) return ret;
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
