extern int ASN1_CHECK_PositionOffsetXYZ(PositionOffsetXYZ *value);
extern int ASN1_CHECK_PositionConfidenceSet(PositionConfidenceSet *value);
extern int ASN1_CHECK_AccelerationSet4Way(AccelerationSet4Way *value);
int ASN1_CHECK_DetectedObjectCommonData(DetectedObjectCommonData *value)
{
	int ret = 0;

	unsigned char checkinfo_objType[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_objTypeCfd[] = { 
		0x02,0x00,0x65,0x00
	};
	unsigned char checkinfo_objectID[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};
	unsigned char checkinfo_measurementTime[] = { 
		0x02,0x82,0xFA,0x24,0x82,0x05,0xDC,0x00
	};
	unsigned char checkinfo_timeConfidence[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_pos[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_posConfidence[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_speed[] = { 
		0x02,0x00,0x82,0x1F,0xFF,0x00
	};
	unsigned char checkinfo_speedConfidence[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_speedZ[] = { 
		0x02,0x00,0x82,0x1F,0xFF,0x00
	};
	unsigned char checkinfo_speedConfidenceZ[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_heading[] = { 
		0x02,0x00,0x82,0x70,0x80,0x00
	};
	unsigned char checkinfo_headingConf[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_accel4way[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_accCfdX[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_accCfdY[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_accCfdZ[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_accCfdYaw[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->objType), checkinfo_objType)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->objTypeCfd), checkinfo_objTypeCfd)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->objectID), checkinfo_objectID)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->measurementTime), checkinfo_measurementTime)) < 0) return ret;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->timeConfidence), checkinfo_timeConfidence)) < 0) return ret;
	if ((ret = ASN1_CHECK_PositionOffsetXYZ(value->pos)) < 0) return ret;
	if ((ret = ASN1_CHECK_PositionConfidenceSet(value->posConfidence)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->speed), checkinfo_speed)) < 0) return ret;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->speedConfidence), checkinfo_speedConfidence)) < 0) return ret;
	if (value->DEF_DetectedObjectCommonData_speedZ == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->speedZ), checkinfo_speedZ)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DetectedObjectCommonData_speedConfidenceZ == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->speedConfidenceZ), checkinfo_speedConfidenceZ)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_INTEGER(&(value->heading), checkinfo_heading)) < 0) return ret;
	if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->headingConf), checkinfo_headingConf)) < 0) return ret;
	if (value->DEF_DetectedObjectCommonData_accel4way == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_AccelerationSet4Way(value->accel4way)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DetectedObjectCommonData_accCfdX == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->accCfdX), checkinfo_accCfdX)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DetectedObjectCommonData_accCfdY == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->accCfdY), checkinfo_accCfdY)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DetectedObjectCommonData_accCfdZ == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->accCfdZ), checkinfo_accCfdZ)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DetectedObjectCommonData_accCfdYaw == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->accCfdYaw), checkinfo_accCfdYaw)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
