int ASN1_Print_AttitudeConfidence(AttitudeConfidence *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("AttitudeConfidence");
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->pitchConfidence)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "unavailable", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec10deg", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec05deg", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec01deg", 3)) < 0) return ret; break;
	case 4: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec0-1deg", 4)) < 0) return ret; break;
	case 5: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec0-05deg", 5)) < 0) return ret; break;
	case 6: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec0-01deg", 6)) < 0) return ret; break;
	case 7: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec0-0125deg", 7)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->rollConfidence)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "unavailable", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec10deg", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec05deg", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec01deg", 3)) < 0) return ret; break;
	case 4: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec0-1deg", 4)) < 0) return ret; break;
	case 5: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec0-05deg", 5)) < 0) return ret; break;
	case 6: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec0-01deg", 6)) < 0) return ret; break;
	case 7: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec0-0125deg", 7)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->yawConfidence)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "unavailable", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec10deg", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec05deg", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec01deg", 3)) < 0) return ret; break;
	case 4: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec0-1deg", 4)) < 0) return ret; break;
	case 5: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec0-05deg", 5)) < 0) return ret; break;
	case 6: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec0-01deg", 6)) < 0) return ret; break;
	case 7: if ((ret = ASN1_Print_ENUMERATED("HeadingConfidence", "prec0-0125deg", 7)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
