extern int ASN1_BER_Data_Enc_PitchRate(ASN1WorkSpace *workspace, PitchRate *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_RollRate(ASN1WorkSpace *workspace, RollRate *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_AngularVelocity(ASN1WorkSpace *workspace, AngularVelocity *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_PitchRate(workspace, &(value->pitchRate), ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_RollRate(workspace, &(value->rollRate), ASN1IMPL)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
