int ASN1_CHECK_AngularVelocityConfidence(AngularVelocityConfidence *value)
{
	int ret = 0;

	unsigned char checkinfo_pitchRateConfidence[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_rollRateConfidence[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if (value->DEF_AngularVelocityConfidence_pitchRateConfidence == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->pitchRateConfidence), checkinfo_pitchRateConfidence)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_AngularVelocityConfidence_rollRateConfidence == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_ENUMERATED((ASNINT32*)&(value->rollRateConfidence), checkinfo_rollRateConfidence)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
extern int ASN1_BER_Data_Enc_PitchRateConfidence(ASN1WorkSpace *workspace, PitchRateConfidence *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_RollRateConfidence(ASN1WorkSpace *workspace, RollRateConfidence *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_AngularVelocityConfidence(ASN1WorkSpace *workspace, AngularVelocityConfidence *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if (value->DEF_AngularVelocityConfidence_pitchRateConfidence == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_PitchRateConfidence(workspace, &(value->pitchRateConfidence), ASN1IMPL)) < 0) return ret;
	}
	if (value->DEF_AngularVelocityConfidence_rollRateConfidence == 1)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Enc_RollRateConfidence(workspace, &(value->rollRateConfidence), ASN1IMPL)) < 0) return ret;
	}
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_AngularVelocityConfidence(AngularVelocityConfidence *value);
extern int ASN1_BER_Data_Enc_AngularVelocityConfidence(ASN1WorkSpace *workspace, AngularVelocityConfidence *value, ASN1TagType tagFlag);
int ASN1_BER_Enc_AngularVelocityConfidence(ASN1WorkSpace *workspace, AngularVelocityConfidence *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = ASN1_CHECK_AngularVelocityConfidence(value)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_AngularVelocityConfidence(workspace, value, tagFlag)) < 0) return ret;
	return ret;
}
extern int ASN1_BER_Data_Dec_PitchRateConfidence(ASN1WorkSpace *workspace, PitchRateConfidence *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_RollRateConfidence(ASN1WorkSpace *workspace, RollRateConfidence *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_AngularVelocityConfidence(ASN1WorkSpace *workspace, AngularVelocityConfidence *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 0))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_PitchRateConfidence(workspace, &value->pitchRateConfidence, len, ASN1IMPL)) < 0) return ret;
		value->DEF_AngularVelocityConfidence_pitchRateConfidence = 1;
	}
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 1))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_RollRateConfidence(workspace, &value->rollRateConfidence, len, ASN1IMPL)) < 0) return ret;
		value->DEF_AngularVelocityConfidence_rollRateConfidence = 1;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
