int ASN1_Print_DetectedVehicleData(DetectedVehicleData *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("DetectedVehicleData");
	if (value->DEF_DetectedVehicleData_lights == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_BITSTRING("ExteriorLights", &(value->lights))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DetectedVehicleData_vehAttitude == 1)
	{ /*OPTIONAL start */
		// Type Reference Attitude
		if (Compare_Letter(tab_value, "vehAttitude")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("vehAttitude = ");
		}
		if ((ret = ASN1_Print_Attitude((Attitude *)value->vehAttitude, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DetectedVehicleData_vehAttitudeConfidence == 1)
	{ /*OPTIONAL start */
		// Type Reference AttitudeConfidence
		if (Compare_Letter(tab_value, "vehAttitudeConfidence")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("vehAttitudeConfidence = ");
		}
		if ((ret = ASN1_Print_AttitudeConfidence((AttitudeConfidence *)value->vehAttitudeConfidence, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DetectedVehicleData_vehAngVel == 1)
	{ /*OPTIONAL start */
		// Type Reference AngularVelocity
		if (Compare_Letter(tab_value, "vehAngVel")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("vehAngVel = ");
		}
		if ((ret = ASN1_Print_AngularVelocity((AngularVelocity *)value->vehAngVel, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DetectedVehicleData_vehAngVelConfidence == 1)
	{ /*OPTIONAL start */
		// Type Reference AngularVelocityConfidence
		if (Compare_Letter(tab_value, "vehAngVelConfidence")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("vehAngVelConfidence = ");
		}
		if ((ret = ASN1_Print_AngularVelocityConfidence((AngularVelocityConfidence *)value->vehAngVelConfidence, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DetectedVehicleData_size == 1)
	{ /*OPTIONAL start */
		// Type Reference VehicleSize
		if (Compare_Letter(tab_value, "size")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("size = ");
		}
		if ((ret = ASN1_Print_VehicleSize((VehicleSize *)value->size, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DetectedVehicleData_height == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("VehicleHeight", &(value->height))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DetectedVehicleData_vehicleSizeConfidence == 1)
	{ /*OPTIONAL start */
		// Type Reference VehicleSizeConfidence
		if (Compare_Letter(tab_value, "vehicleSizeConfidence")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("vehicleSizeConfidence = ");
		}
		if ((ret = ASN1_Print_VehicleSizeConfidence((VehicleSizeConfidence *)value->vehicleSizeConfidence, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DetectedVehicleData_vehicleClass == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("BasicVehicleClass", &(value->vehicleClass))) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_DetectedVehicleData_classConf == 1)
	{ /*OPTIONAL start */
		// Type Default
		// Type is Referenced
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		if ((ret = ASN1_Print_INTEGER("ClassificationConfidence", &(value->classConf))) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
