extern int ASN1_PER_UNAlign_Data_Enc_DetectedVRUData(ASN1WorkSpace *workspace, DetectedVRUData *value);
int ASN1_PER_UNAlign_Enc_DetectedVRUData(ASN1WorkSpace *workspace, DetectedVRUData *value)
{ // ASN1_PER_Extern_Encode 
	int ret = 0;
	if ((ret = ASN1_CHECK_DetectedVRUData(value)) < 0) return ret;
	if ((ret = ASN1_PER_UNAlign_Data_Enc_DetectedVRUData(workspace,value)) < 0) return ret;
	return ret;
}
extern int ASN1_PER_UNAlign_Data_Dec_PropelledInformation(ASN1WorkSpace *workspace, PropelledInformation *value);
int ASN1_PER_UNAlign_Data_Dec_DetectedVRUData(ASN1WorkSpace *workspace, DetectedVRUData *value)
{
	int ret = 0;
	ASNINT32 ui_basicType;
	ASNINT32 ui_attachment;
	struct Asn1ConsInfo consinfo_basicType = { ASN1_CONST64(0), ASN1_CONST64(4), NULL, 1, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_propulsion = { ASN1_CONST64(-9223372036854775807), ASN1_CONST64(9223372036854775807), NULL, 0, UNCONS, 0, 0 };
	struct Asn1ConsInfo consinfo_attachment = { ASN1_CONST64(0), ASN1_CONST64(6), NULL, 1, CONS, 0, 0 };
	struct Asn1ConsInfo consinfo_radius = { ASN1_CONST64(0), ASN1_CONST64(200), NULL, 0, CONS, 0, 0 };

	ASNUINT8 *_optvalue;
	if ((ret = ASN1_PER_Dec_Opt_Def_bit(workspace, 4, &_optvalue)) < 0) return ret;
	value->propulsion = (PropelledInformation *)mpool_malloc(workspace->Pmemory, sizeof(PropelledInformation));
	memset(value->propulsion, 0, sizeof(PropelledInformation));
	if (ASN1_PER_CheckExtBit(_optvalue, 1) == 1)
	{
		value->DEF_DetectedVRUData_basicType = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_ENUMERATED(workspace, &ui_basicType, &consinfo_basicType)) < 0) return ret;
		if (consinfo_basicType.enumextbit == 0)
		{
			switch(ui_basicType)
			{
			case 0: value->basicType = PersonalDeviceUserType_unavailable; break;
			case 1: value->basicType = PersonalDeviceUserType_aPedestrian; break;
			case 2: value->basicType = PersonalDeviceUserType_aPedalCyclist; break;
			case 3: value->basicType = PersonalDeviceUserType_aPublicSafetyWorker; break;
			case 4: value->basicType = PersonalDeviceUserType_anAnimal; break;
			default: break;
			}
		}
		else
		{
			switch(ui_basicType)
			{
			case 0: value->basicType = PersonalDeviceUserType_aWheelchair; break;
			case 1: value->basicType = PersonalDeviceUserType_aSelfBalancingDevice; break;
			case 2: value->basicType = PersonalDeviceUserType_aStandingScooter; break;
			case 3: value->basicType = PersonalDeviceUserType_aSeatedScooter; break;
			case 4: value->basicType = PersonalDeviceUserType_aSkates; break;
			case 5: value->basicType = PersonalDeviceUserType_anOneWheelTransporter; break;
			case 6: value->basicType = PersonalDeviceUserType_aCargoBike; break;
			case 7: value->basicType = PersonalDeviceUserType_aConstructionWorker; break;
			case 8: value->basicType = PersonalDeviceUserType_anOther; break;
			default: value->basicType = ui_basicType; break;
			}
		}
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 2) == 1)
	{
		value->DEF_DetectedVRUData_propulsion = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_PropelledInformation(workspace, value->propulsion)) < 0) return ret;
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 3) == 1)
	{
		value->DEF_DetectedVRUData_attachment = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_ENUMERATED(workspace, &ui_attachment, &consinfo_attachment)) < 0) return ret;
		if (consinfo_attachment.enumextbit == 0)
		{
			switch(ui_attachment)
			{
			case 0: value->attachment = Attachment_unavailable; break;
			case 1: value->attachment = Attachment_stroller; break;
			case 2: value->attachment = Attachment_bicycleTrailer; break;
			case 3: value->attachment = Attachment_cart; break;
			case 4: value->attachment = Attachment_wheelchair; break;
			case 5: value->attachment = Attachment_otherWalkAssistAttachments; break;
			case 6: value->attachment = Attachment_pet; break;
			default: break;
			}
		}
		else
		{
			switch(ui_attachment)
			{
			default: value->attachment = ui_attachment; break;
			}
		}
	}
	if (ASN1_PER_CheckExtBit(_optvalue, 4) == 1)
	{
		value->DEF_DetectedVRUData_radius = 1;
		if ((ret = ASN1_PER_UNAlign_Dec_INTEGER(workspace, &(value->radius), &consinfo_radius)) < 0) return ret;
	}
	return ret;
}
extern int ASN1_CHECK_DetectedVRUData(DetectedVRUData *value);
extern int ASN1_PER_UNAlign_Data_Dec_DetectedVRUData(ASN1WorkSpace *workspace, DetectedVRUData *value);
int ASN1_PER_UNAlign_Dec_DetectedVRUData(ASN1WorkSpace *workspace, DetectedVRUData *value)
{
	int ret = 0;
	if ((ret = ASN1_PER_UNAlign_Data_Dec_DetectedVRUData(workspace,value)) < 0) return ret;
	if ((ret = ASN1_CHECK_DetectedVRUData(value)) < 0) return ret;
	return ret;
}

