extern int ASN1_BER_Data_Dec_SizeValueConfidence(ASN1WorkSpace *workspace, SizeValueConfidence *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_SizeValueConfidence(ASN1WorkSpace *workspace, SizeValueConfidence *value, int length, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Dec_SizeValueConfidence(ASN1WorkSpace *workspace, SizeValueConfidence *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Data_Dec_ObstacleSizeConfidence(ASN1WorkSpace *workspace, ObstacleSizeConfidence *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	int len = length;
	ASNUINT32 tag;
	ASNUINT8 *_cpointer;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace,ITS_ASN_UNIV|ITS_ASN_CONS|16)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace,&length)) < 0) return ret;
	}
	ASN1_Save_Current_P(workspace, &_cpointer);
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 0)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_SizeValueConfidence(workspace, &value->widthConfidence, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 1)) < 0) return ret;
	if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_SizeValueConfidence(workspace, &value->lengthConfidence, len, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_GET_Tag(workspace, &tag)) < 0) return ret;
	if (tag == (ITS_ASN_CONT | ITS_ASN_PRIM | 2))
	{
		if ((ret = ASN1_BER_User_Dec_Tag(workspace, ITS_ASN_CONT | ITS_ASN_PRIM | 2)) < 0) return ret;
		if ((ret = ASN1_BER_User_Dec_Length(workspace, &len)) < 0) return ret;
		if ((ret = ASN1_BER_Data_Dec_SizeValueConfidence(workspace, &value->heightConfidence, len, ASN1IMPL)) < 0) return ret;
		value->DEF_ObstacleSizeConfidence_heightConfidence = 1;
	}
	ASN1_Dec_Seq_EXT_UNKnow(workspace, _cpointer, length);
	if (tagFlag == ASN1EXPL)
	{
		if( IfFixedLength(length) == -1)
		{
			if ((ret = ASN1_BER_Dec_StrmEOC(workspace)) < 0) return ret;
		}
	}
	return ret;
}
extern int ASN1_CHECK_ObstacleSizeConfidence(ObstacleSizeConfidence *value);
extern int ASN1_BER_Data_Dec_ObstacleSizeConfidence(ASN1WorkSpace *workspace, ObstacleSizeConfidence *value, int length, ASN1TagType tagFlag);
int ASN1_BER_Dec_ObstacleSizeConfidence(ASN1WorkSpace *workspace, ObstacleSizeConfidence *value, int length, ASN1TagType tagFlag)
{
	int ret = 0;
	if ((ret = _ASN1_BER_CHECK_Length(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Dec_ObstacleSizeConfidence(workspace,value,length,tagFlag)) < 0) return ret;
	if ((ret = ASN1_CHECK_ObstacleSizeConfidence(value)) < 0) return ret;
	return ret;
}
