extern int ASN1_BER_Data_Enc_ObstacleSize(ASN1WorkSpace *workspace, ObstacleSize *value, ASN1TagType tagFlag);
extern int ASN1_BER_Data_Enc_ObstacleSizeConfidence(ASN1WorkSpace *workspace, ObstacleSizeConfidence *value, ASN1TagType tagFlag);
int ASN1_BER_Data_Enc_DetectedObstacleData(ASN1WorkSpace *workspace, DetectedObstacleData *value, ASN1TagType tagFlag)
{
	int ret = 0;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_UNIV | ITS_ASN_CONS | 16)) < 0) return ret;
	}
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 0)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_ObstacleSize(workspace, value->obstSize, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_Tag_Indef(workspace, ITS_ASN_CONT | ITS_ASN_CONS | 1)) < 0) return ret;
	if ((ret = ASN1_BER_Data_Enc_ObstacleSizeConfidence(workspace, value->obstSizeConfidence, ASN1IMPL)) < 0) return ret;
	if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	if (tagFlag == ASN1EXPL)
	{
		if ((ret = ASN1_BER_Enc_StrmEOC(workspace)) < 0) return ret;
	}
	return ret;
}
