int ASN1_Print_DetectedObjectOptionalData(DetectedObjectOptionalData *value, int tab_value)
{
	int ret = 0;
	// CHOICE : t->tempIdentifier is Upper Letter
	ASN1_Print_CHOICE("DetectedObjectOptionalData");
	if (value == NULL) return -1;
	switch (value->M) {
	case DEF_DetectedObjectOptionalData_detVeh:
		// Type Reference DetectedVehicleData
		if (Compare_Letter(tab_value, "detVeh")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("detVeh = ");
		}
		if ((ret = ASN1_Print_DetectedVehicleData((DetectedVehicleData *)value->elements.detVeh, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_DetectedObjectOptionalData_detVRU:
		// Type Reference DetectedVRUData
		if (Compare_Letter(tab_value, "detVRU")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("detVRU = ");
		}
		if ((ret = ASN1_Print_DetectedVRUData((DetectedVRUData *)value->elements.detVRU, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	case DEF_DetectedObjectOptionalData_detObst:
		// Type Reference DetectedObstacleData
		if (Compare_Letter(tab_value, "detObst")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("detObst = ");
		}
		if ((ret = ASN1_Print_DetectedObstacleData((DetectedObstacleData *)value->elements.detObst, tab_value + 1)) < 0) return ret;
		if (ret != 0) return -1;
		break;
	default: return -1;
}
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
