/********************************************************
*DetectedObjectData                                     *
********************************************************/
int ASN1_Print_DetectedObjectData(DetectedObjectData *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("DetectedObjectData");
	// Type Reference DetectedObjectCommonData
	if (Compare_Letter(tab_value, "detObjCommon")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("detObjCommon = ");
	}
	if ((ret = ASN1_Print_DetectedObjectCommonData((DetectedObjectCommonData *)value->detObjCommon, tab_value + 1)) < 0) return ret;
	if (value->DEF_DetectedObjectData_detObjOptData == 1)
	{ /*OPTIONAL start */
		// Type Reference DetectedObjectOptionalData
		if (Compare_Letter(tab_value, "detObjOptData")) {
			ASN_Print_TAB(tab_value + 1);
			asn_printf("detObjOptData = ");
		}
		if ((ret = ASN1_Print_DetectedObjectOptionalData((DetectedObjectOptionalData *)value->detObjOptData, tab_value + 1)) < 0) return ret;
	} /* OPTIONAL end */
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
int ASN1_SET_DetectedObjectData_detObjCommon(ASN1WorkSpace *workspace, DetectedObjectData *value, DetectedObjectCommonData *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->detObjCommon = (DetectedObjectCommonData *)mpool_malloc(workspace->Pmemory, sizeof(DetectedObjectCommonData));
	memset(value->detObjCommon, 0, sizeof(DetectedObjectCommonData));
	memmove(value->detObjCommon, user_value, sizeof(DetectedObjectCommonData));
	return ret;
}
int ASN1_SET_DetectedObjectData_detObjOptData(ASN1WorkSpace *workspace, DetectedObjectData *value, DetectedObjectOptionalData *user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	value->detObjOptData = (DetectedObjectOptionalData *)mpool_malloc(workspace->Pmemory, sizeof(DetectedObjectOptionalData));
	memset(value->detObjOptData, 0, sizeof(DetectedObjectOptionalData));
	value->DEF_DetectedObjectData_detObjOptData = 1;
	memmove(value->detObjOptData, user_value, sizeof(DetectedObjectOptionalData));
	return ret;
}
int ASN1_GET_DetectedObjectData_detObjCommon(ASN1WorkSpace *workspace, DetectedObjectData *value, DetectedObjectCommonData **user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	*user_value = value->detObjCommon;
	return ret;
}
int ASN1_GET_DetectedObjectData_detObjOptData(ASN1WorkSpace *workspace, DetectedObjectData *value, DetectedObjectOptionalData **user_value)
{
	int ret = 0;
	if (value == NULL || user_value == NULL) return -1;
	if (value->DEF_DetectedObjectData_detObjOptData == 1)
	{
		*user_value = value->detObjOptData;
	}
	else return -2;
	return ret;
}
extern int ASN1_CHECK_DetectedObjectCommonData(DetectedObjectCommonData *value);
extern int ASN1_CHECK_DetectedObjectOptionalData(DetectedObjectOptionalData *value);
int ASN1_CHECK_DetectedObjectData(DetectedObjectData *value)
{
	int ret = 0;

	unsigned char checkinfo_detObjCommon[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_detObjOptData[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_DetectedObjectCommonData(value->detObjCommon)) < 0) return ret;
	if (value->DEF_DetectedObjectData_detObjOptData == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_DetectedObjectOptionalData(value->detObjOptData)) < 0) return ret;
	} /* OPTIONAL end */
	return ret;
}
