/********************************************************
*SensorDataSharingMessage                               *
********************************************************/
int ASN1_Print_SensorDataSharingMessage(SensorDataSharingMessage *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("SensorDataSharingMessage");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("MsgCount", &(value->msgCnt))) < 0) return ret;
	// Type OCTET STRING
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_OCTETSTRING("TemporaryID", &(value->sourceID), tab_value + 1)) < 0) return ret;
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->equipmentType)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("EquipmentType", "unknown", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("EquipmentType", "rsu", 1)) < 0) return ret; break;
	case 2: if ((ret = ASN1_Print_ENUMERATED("EquipmentType", "obu", 2)) < 0) return ret; break;
	case 3: if ((ret = ASN1_Print_ENUMERATED("EquipmentType", "vru", 3)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	// Type Reference DDateTime
	if (Compare_Letter(tab_value, "sDSMTimeStamp")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("sDSMTimeStamp = ");
	}
	if ((ret = ASN1_Print_DDateTime((DDateTime *)value->sDSMTimeStamp, tab_value + 1)) < 0) return ret;
	// Type Reference Position3D
	if (Compare_Letter(tab_value, "refPos")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("refPos = ");
	}
	if ((ret = ASN1_Print_Position3D((Position3D *)value->refPos, tab_value + 1)) < 0) return ret;
	// Type Reference PositionalAccuracy
	if (Compare_Letter(tab_value, "refPosXYConf")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("refPosXYConf = ");
	}
	if ((ret = ASN1_Print_PositionalAccuracy((PositionalAccuracy *)value->refPosXYConf, tab_value + 1)) < 0) return ret;
	if (value->DEF_SensorDataSharingMessage_refPosElConf == 1)
	{ /*OPTIONAL start */
		if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
		switch(value->refPosElConf)
		{
		case 0: if ((ret = ASN1_Print_ENUMERATED("ElevationConfidence", "unavailable", 0)) < 0) return ret; break;
		case 1: if ((ret = ASN1_Print_ENUMERATED("ElevationConfidence", "elev-500-00", 1)) < 0) return ret; break;
		case 2: if ((ret = ASN1_Print_ENUMERATED("ElevationConfidence", "elev-200-00", 2)) < 0) return ret; break;
		case 3: if ((ret = ASN1_Print_ENUMERATED("ElevationConfidence", "elev-100-00", 3)) < 0) return ret; break;
		case 4: if ((ret = ASN1_Print_ENUMERATED("ElevationConfidence", "elev-050-00", 4)) < 0) return ret; break;
		case 5: if ((ret = ASN1_Print_ENUMERATED("ElevationConfidence", "elev-020-00", 5)) < 0) return ret; break;
		case 6: if ((ret = ASN1_Print_ENUMERATED("ElevationConfidence", "elev-010-00", 6)) < 0) return ret; break;
		case 7: if ((ret = ASN1_Print_ENUMERATED("ElevationConfidence", "elev-005-00", 7)) < 0) return ret; break;
		case 8: if ((ret = ASN1_Print_ENUMERATED("ElevationConfidence", "elev-002-00", 8)) < 0) return ret; break;
		case 9: if ((ret = ASN1_Print_ENUMERATED("ElevationConfidence", "elev-001-00", 9)) < 0) return ret; break;
		case 10: if ((ret = ASN1_Print_ENUMERATED("ElevationConfidence", "elev-000-50", 10)) < 0) return ret; break;
		case 11: if ((ret = ASN1_Print_ENUMERATED("ElevationConfidence", "elev-000-20", 11)) < 0) return ret; break;
		case 12: if ((ret = ASN1_Print_ENUMERATED("ElevationConfidence", "elev-000-10", 12)) < 0) return ret; break;
		case 13: if ((ret = ASN1_Print_ENUMERATED("ElevationConfidence", "elev-000-05", 13)) < 0) return ret; break;
		case 14: if ((ret = ASN1_Print_ENUMERATED("ElevationConfidence", "elev-000-02", 14)) < 0) return ret; break;
		case 15: if ((ret = ASN1_Print_ENUMERATED("ElevationConfidence", "elev-000-01", 15)) < 0) return ret; break;
		default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
		};
	} /* OPTIONAL end */
	// Type Reference DetectedObjectList
	if (Compare_Letter(tab_value, "objects")) {
		ASN_Print_TAB(tab_value + 1);
		asn_printf("objects = ");
	}
	if ((ret = ASN1_Print_DetectedObjectList((DetectedObjectList *)&(value->objects), tab_value + 1)) < 0) return ret;
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
