int ASN1_Print_TrafficLightStatus_KOR(TrafficLightStatus_KOR *value, int tab_value)
{
	int ret = 0;
	if (value == NULL) return -1;
	// SEQUENCE : t->tempIdentifier is Upper Letter
	ASN1_Print_SEQ("TrafficLightStatus-KOR");
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("TrafficLightType_KOR", &(value->trafficLightType))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("ConsecutiveTrafficLight_KOR", &(value->consecutiveTrafficLight))) < 0) return ret;
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	switch(value->trafficLightIntervalType)
	{
	case 0: if ((ret = ASN1_Print_ENUMERATED("TrafficLightIntervalType-KOR", "static", 0)) < 0) return ret; break;
	case 1: if ((ret = ASN1_Print_ENUMERATED("TrafficLightIntervalType-KOR", "variable", 1)) < 0) return ret; break;
	default: ASN1_Enum_UNKNOWN(tab_value + 1); break;
	};
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BOOLEAN("PedestrianCall_KOR", &(value->pedestrianCall))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BOOLEAN("ActuatedInterval_KOR", &(value->actuatedinterval))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BOOLEAN("PermissiveNonProtected_KOR", &(value->permissiveNonProtected))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("TrafficLightingStatus_KOR", &(value->lightingStatus))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("TimeInSecond_B8_KOR", &(value->maxIntervalLength))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("TimeInSecond_B8_KOR", &(value->remainingTime))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_INTEGER("TrafficLightDirectionCode_KOR", &(value->directionCode))) < 0) return ret;
	// Type Default
	// Type is Referenced
	if ((ret = ASN_Print_TAB(tab_value + 1)) < 0) return ret;
	if ((ret = ASN1_Print_BOOLEAN("ReservedBit_KOR", &(value->reserved))) < 0) return ret;
	ASN_Print_TAB(tab_value); asn_printf("}\n");
	return ret;
}
