int ASN1_CHECK_TrafficLightStatusMessage(TrafficLightStatusMessage *value)
{
	int ret = 0;

	unsigned char checkinfo_traffiLightID[] = { 
		0x02,0x00,0x85,0x00,0xFF,0xFF,0xFF,0xFF,0x00
	};
	unsigned char checkinfo_lon[] = { 
		0x02,0x84,0x94,0xB6,0x2E,0x01,0x84,0x6B,0x49,0xD2,0x01,0x00
	};
	unsigned char checkinfo_lat[] = { 
		0x02,0x84,0xCA,0x5B,0x17,0x00,0x84,0x35,0xA4,0xE9,0x01,0x00
	};
	unsigned char checkinfo_operationStatus[] = { 
		0x02,0x08,0x08,0x00
	};
	unsigned char checkinfo_controllerStatus[] = { 
		0x02,0x08,0x08,0x00
	};
	unsigned char checkinfo_cycleCounter[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};
	unsigned char checkinfo_cycleTime[] = { 
		0x02,0x00,0x83,0x00,0xFF,0xFF,0x00
	};
	unsigned char checkinfo_currentTime[] = { 0x00, 0x00 }; /* 0x00 == t->consterminal.cons_type */
	unsigned char checkinfo_trafficLightStatus[] = { 
		0x02,0x01,0x82,0x00,0xFF,0x00
	};

	if (value == NULL) return -1;
	if ((ret = ASN1_CHECK_INTEGER(&(value->traffiLightID), checkinfo_traffiLightID)) < 0) return ret;
	if (value->DEF_TrafficLightStatusMessage_lon == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->lon), checkinfo_lon)) < 0) return ret;
	} /* OPTIONAL end */
	if (value->DEF_TrafficLightStatusMessage_lat == 1)
	{ /* OPTIONAL start */
		if ((ret = ASN1_CHECK_INTEGER(&(value->lat), checkinfo_lat)) < 0) return ret;
	} /* OPTIONAL end */
	if ((ret = ASN1_CHECK_BITSTRING(&(value->operationStatus), checkinfo_operationStatus)) < 0) return ret;
	if ((ret = ASN1_CHECK_BITSTRING(&(value->controllerStatus), checkinfo_controllerStatus)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->cycleCounter), checkinfo_cycleCounter)) < 0) return ret;
	if ((ret = ASN1_CHECK_INTEGER(&(value->cycleTime), checkinfo_cycleTime)) < 0) return ret;
	if ((ret = ASN1_CHECK_DDateTime(value->currentTime)) < 0) return ret;
	if ((ret = ASN1_CHECK_TrafficLightStatusList_KOR(&(value->trafficLightStatus))) < 0) return ret;
	return ret;
}
